local dialogues = {}
dialogues.npcs = {
    ["'Fraidy cat"] = {
        ["[To talk to cats, you need a catspeak amulet. You can get one from Tiny Zemouregal in New Varrock.]"] = "[Para hablar con los gatos, necesitas un amuleto de lengua de gato. Puedes conseguir uno de Tiny Zemouregal en New Varrock.]",
        ["[To talk to cats, you need to wear your catspeak amulet.]"] = "[Para hablar con los gatos, debes usar tu amuleto catspeak.]",
        ["Come on, kitty, time to move on."] = "Vamos, gatito, es hora de seguir adelante.",
        ["P-p-please don't shout at me. I'm s-s-scared of whatever's in that kennel."] = "P-p-por favor no me grites. Tengo mucho miedo de lo que sea que haya en esa perrera.",
        ["Oh, I'm sorry, I didn't mean to frighten you."] = "Oh, lo siento, no quise asustarte.",
        ["It's fine. I'm used to it. I once belonged to a w-w-witch. She didn't treat me too well."] = "Está bien. Estoy acostumbrado. Una vez pertenecí a una bruja. Ella no me trató muy bien.",
        ["B-b-but I did learn a lot."] = "P-p-pero aprendí mucho.",
        ["Well, if you did move on, you'd get away from that kennel."] = "Bueno, si siguieras adelante, te alejarías de esa perrera.",
        ["I th-th-think I need some courage. There's something that would h-h-help."] = "Creo que necesito algo de coraje. Hay algo que ayudaría.",
        ["Name it, and I'll see if I can get it for you."] = "Name y veré si puedo conseguírtelo.",
        ["There's a book - reading it was my only comfort, but it was s-s-stolen. It's hidden in the Zamorak temple, behind the black stone altar slab."] = "Hay un libro. Leerlo fue mi único consuelo, pero me lo robaron. Está escondido en el templo Zamorak, detrás de la losa del altar de piedra negra.",
        ["[As you look at the altar you notice a strange book hidden beneath it.]"] = "[Al mirar el altar, notas un extraño libro escondido debajo.]",
        ["You've found it - the book of power! You fool! At last, it is mine!"] = "Lo has encontrado: ¡el libro del poder! ¡Tonto! ¡Por fin es mío!",
        ["Before you can say anything, the cat snatches the book and confidently strides off in the direction of New Varrock's graveyard..."] = "Antes de que puedas decir algo, el gato agarra el libro y se aleja con confianza en dirección al cementerio de New Varrock...",
        ["You have made progress in the 'A Cat's Bane' Task. ([number]/4)"] = "Has progresado en la tarea \"La perdición de un gato\". ([número]/4)",
        ["I wonder why they all headed off towards the graveyard..."] = "Me pregunto por qué todos se dirigieron hacia el cementerio...",
        ["Poor Fluffs. I wonder what happened to your kittens."] = "Pobre Fluffs. Me pregunto qué pasó con tus gatitos.",
        ["Perhaps you are not such a fool, human. The Necrofelinominom is too powerful, and now in safer paws than mine - those of my new owner, Gertrude."] = "Quizás no seas tan tonto, humano. El Necrofelinominom es demasiado poderoso y ahora está en garras más seguras que las mías: las de mi nuevo dueño, Gertrude.",
    },
    ["Faceless Assassin"] = {
        ["What's all this about an Assassin's Contract list."] = "¿Qué es todo eso sobre la lista de contratos de asesino?",
        ["Keep your voice down, and perhaps I'll share my secrets with you."] = "Baja la voz y tal vez comparta mis secretos contigo.",
        ["The Assassin's Contract list is only something for the most worthy."] = "La lista de contratos de The Assassin es sólo algo para los más dignos.",
        ["Ask about.."] = "Pregunta sobre..",
        ["*(Only initially:)*"] = "*(Sólo inicialmente:)*",
        ["I'm worthy"] = "soy digno",
        ["I'm worthy. I'll prove it."] = "Soy digno. Lo probaré.",
        ["I see you've already got a copy of the Assassin's Contract list, take a look at the list and see if your skills are as good as you think!"] = "Veo que ya tienes una copia de la lista de contratos de the Assassin, ¡échale un vistazo a la lista y comprueba si tus habilidades son tan buenas como crees!",
        ["*(Returns to the previous questions.)*"] = "*(Vuelve a las preguntas anteriores.)*",
        ["*(Only after choosing some other option:)*"] = "*(Sólo después de elegir alguna otra opción:)*",
        ["How can I help?"] = "¿Cómo puedo ayudar?",
        ["*(As after the first question.)*"] = "*(Como después de la primera pregunta.)*",
        ["Assassin Contracts"] = "Asesino Contracts",
        ["Assassin's Contracts?"] = "¿Contracts del asesino?",
        ["There's a selection of contracts for aspiring assassins to undertake to test their skills and see if they're worthy."] = "Hay una selección de contracts para que los aspirantes a asesinos se comprometan a probar sus habilidades y ver si son dignos.",
        ["Anything from making antipoison and entering dangerous places, to assassinating specific targets with discretion."] = "Cualquier cosa, desde hacer antiveneno y entrar en lugares peligrosos, hasta asesinar objetivos específicos con discreción.",
        ["Ok, I'll see if my skills are a match for your contracts."] = "Ok, veré si mis habilidades coinciden con las de tu contracts.",
        ["Contagion mixture"] = "Mezcla de contagio",
        ["Contagion, isn't that dangerous?"] = "Contagio, ¿no es peligroso?",
        ["Not in itself, but when put together correctly... it can be lethal."] = "No en sí mismo, pero cuando se combina correctamente... puede ser letal.",
        ["If you can source the reagents I would be most impressed."] = "Si pudiera conseguir los reactivos, estaría muy impresionado.",
        ["What do you need?"] = "¿Qué necesitas?",
        ["This list is for your eyes only, it will require..."] = "Esta lista es sólo para sus ojos, requerirá...",
        ["*(Contagion Reagents book opens.)*"] = "*(Se abre el libro Reactivos de contagio.)*",
        ["Contagion list"] = "Lista de contagios",
        ["Can I see the list again?"] = "¿Puedo ver la lista nuevamente?",
        ["I've got some reagents"] = "tengo algunos reactivos",
        ["*(Without any missing reagents:)*"] = "*(Sin faltar reactivos:)*",
        ["Looks like we're still missing some reagents. See if you can do better."] = "Parece que todavía nos faltan algunos reactivos. Vea si puede hacerlo mejor.",
        ["*(With reagents:)*"] = "*(Con reactivos:)*",
        ["*(If the overload salve is carried:)*"] = "*(Si se lleva el ungüento de sobrecarga:)*",
        ["I've brought you an Overload salve."] = "Te he traído un ungüento para sobrecarga.",
        ["Good work getting that one. This will give the contagion the unstable properties it needs."] = "Buen trabajo consiguiendo ese. Esto le dará al contagio las propiedades inestables que necesita.",
        ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
        ["*(If the divine rocktail bubble is carried:)*"] = "*(Si se lleva la divina burbuja cola de roca:)*",
        ["I've brought you a Divine rocktail bubble."] = "Te he traído una burbuja divina de cola de roca.",
        ["Excellent job in acquiring this. The bubbles will help the contagion spread nicely."] = "Excelente trabajo al adquirir esto. Las burbujas ayudarán a que el contagio se propague bien.",
        ["*(If the empty bird's nest is carried:)*"] = "*(Si se lleva el nido de pájaro vacío:)*",
        ["I've brought you an empty bird's nest."] = "Te he traído un nido de pájaro vacío.",
        ["You've done well to source this. I can weave this into the mix."] = "Has hecho bien en conseguir esto. Puedo incorporar esto a la mezcla.",
        ["*(If the harmonic dust is carried:)*"] = "*(Si se transporta polvo armónico:)*",
        ["I've brought you 134 Harmonic Dust."] = "Te he traído 134 polvo armónico.",
        ["I'll hodl onto those. The contagion will really spread with this, With a bit of a ripple at first, building up in waves and into the ether."] = "Me centraré en . El contagio realmente se extenderá con esto, con como una pequeña onda al principio, acumulándose en ondas y hacia el éter.",
        ["*(If the basiliskbane ore is carried:)*"] = "*(Si se lleva el mineral azote de basilisco:)*",
        ["I've brought you some Basiliskbane ore"] = "Te he traído un poco de mineral Basiliskbane",
        ["Well, I am impressed. The power this will imbibe into the contagion will be perfect."] = "Bueno, estoy impresionado. El poder que esto imbuirá en el contagio será perfecto.",
        ["*(If the sack of onions is carried:)*"] = "*(Si se lleva el saco de cebollas:)*",
        ["I've brought you a sack of onions."] = "Te he traído un saco de cebollas.",
        ["I expected no less. This will add some potency."] = "No esperaba menos. Esto agregará algo de potencia.",
        ["*(If all the reagents have been delivered:)*"] = "*(Si se han entregado todos los reactivos:)*",
        ["You've acquired all the reagents for the Faceless Assasin to make the Contagion and completed one of your Assassin's Contracts."] = "Has adquirido todos los reactivos del Asesino sin rostro para crear el Contagio y has completado uno de tus Contracts de Asesino.",
        ["*(With the task completed:)*"] = "*(Con la tarea completada :)*",
        ["I believe we're done with the reagents for now."] = "Creo que por ahora hemos terminado con los reactivos.",
    },
    ["Factory Manager"] = {
        ["Don't bother me, can't you see I'm busy?"] = "No me molestes, ¿no ves que estoy ocupado?",
        ["No, I can't... can I go into the factory?"] = "No, no puedo... ¿puedo entrar a la fábrica?",
        ["You can go in. The Consortium, in their infinite wisdom, has decided to open up the factory to all and sundry."] = "Puedes entrar. El Consorcio, en su infinita sabiduría, ha decidido abrir la fábrica a todos.",
        ["How come?"] = "¿Cómo es eso?",
        ["We've built a new blast furnace and always have a shortage of people to work on it."] = "Hemos construido un nuevo alto horno y siempre nos falta gente para trabajar en él.",
        ["I'll have a look, thanks."] = "Echaré un vistazo, gracias.",
        ["Just don't go causing any trouble, I still run this factory!"] = "¡No vayas a causar problemas, todavía dirijo esta fábrica!",
    },
    ["Factory Worker"] = {
        ["*The dialogue shown depends on which Factory Worker is spoken to.*"] = "*El diálogo que se muestra depende de con qué Factory Worker se habla.*",
        ["What are you dwarves doing in this factory?"] = "¿Qué están haciendo ustedes, enanos, en esta fábrica?",
        ["Working of course, can't you see that?"] = "Funciona, por supuesto, ¿no lo ves?",
        ["But working on what?"] = "¿Pero trabajar en qué?",
        ["Refining the ore that is being brought into the factory, of course."] = "Refinar el mineral que se lleva a la fábrica, por supuesto.",
        ["And what does that mean?"] = "¿Y eso qué significa?",
        ["It means you should stop asking so many questions and get back to work!"] = "¡Significa que debes dejar de hacer tantas preguntas y volver al trabajo!",
        ["Who owns this factory?"] = "¿A quién pertenece esta fábrica?",
        ["The Consortium does and that's all you need to know."] = "El Consorcio sí lo hace y eso es todo lo que necesitas saber.",
        ["But what company? I thought there were all these different companies?"] = "¿Pero qué empresa? Pensé que había todas estas empresas diferentes.",
        ["Oh yes, all the major companies own this plant. It's too vital to be in the hands of one company alone."] = "Oh, sí, todas las empresas importantes son propietarias de esta planta. Es demasiado vital para estar en manos de una sola empresa.",
        ["And what exactly are you doing here?"] = "¿Y qué haces aquí exactamente?",
        ["I tire of these questions. Let me get back to work!"] = "Me canso de estas preguntas. ¡Déjame volver al trabajo!",
        ["I'm sorry, I'm looking for the blast furnace?"] = "Lo siento, ¿estoy buscando el alto horno?",
        ["Do I look like a guide to you?"] = "¿Te parezco una guía?",
        ["No, you look like a hard-working dwarf, but can you please tell me where the blast furnace is?"] = "No, pareces un enano trabajador, pero ¿podrías decirme dónde está el alto horno?",
        ["Alright, just head down the stairs, it's easy to find."] = "Muy bien, baja las escaleras, es fácil de encontrar.",
        ["Thanks."] = "Gracias.",
        ["Are you okay?"] = "¿Estás bien?",
        ["Don't I look okay?"] = "¿No me veo bien?",
        ["If you were any shorter you wouldn't exist."] = "Si fueras más bajo, no existirías.",
        ["Very funny, human."] = "Muy divertido, humano.",
    },
    ["Fadli"] = {
        ["Good day. How may I help you?"] = "Buenos días. ¿Cómo puedo ayudarte?",
        ["I'd Like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
        ["I'd like to check my PIN settings."] = "Me gustaría verificar la configuración de mi PIN.",
        ["I'd like to see my collection box."] = "Me gustaría ver mi caja de colección.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is a branch of the Bank of RuneScape. We have branches in many towns."] = "Esta es una sucursal del Banco de RuneScape. Disponemos de sucursales en muchas localidades.",
        ["And what do you do?"] = "¿Y tú qué haces?",
        ["We will look after your items and money for you. Leave your valuables with us if you want to keep them safe."] = "Nos ocuparemos de tus artículos y de tu dinero. Deje sus objetos de valor con nosotros si desea mantenerlos seguros.",
        ["Didn't you used to be called the Bank of Varrock?"] = "¿No te llamaban antes el Banco de Varrock?",
        ["Yes we did, but people kept on coming into our branches outside of Varrock and telling us that our signs were wrong. They acted as if we didn't know what town we were in or something."] = "Sí, lo hicimos, pero la gente seguía entrando a nuestras sucursales fuera de Varrock y diciéndonos que nuestros carteles estaban equivocados. Actuaron como si no supiéramos en qué ciudad estábamos o algo así.",
        ["What?"] = "¿Qué?",
        ["Before we go any further, I should inform you that you have items ready for collection from the Grand Exchange."] = "Antes de continuar, debo informarle que tiene artículos listos para ser recogidos en Grand Exchange.",
        ["**WHAT WOULD YOU LIKE TO SAY?**"] = "**¿QUÉ TE GUSTARÍA DECIR?**",
        ["What do you do?"] = "¿A qué te dedicas?",
        ["You can store your stuff here if you want. You can dump anything you don't want to carry while you're relaxing in the oasis and pick it up again on the way out."] = "Puedes guardar tus cosas aquí si quieres. Puedes tirar todo lo que no quieras llevar mientras te relajas en el oasis y recogerlo de nuevo al salir.",
        ["To be honest, I'm wasted here. But ever since the Duel Arena collapsed, I don't know where my fighting skills would be best placed."] = "Para ser honesto, estoy perdido aquí. Pero desde que el Duel Arena colapsó, no sé dónde estarían mejor ubicadas mis habilidades de lucha.",
        ["You could always try the Al Kharid security force!"] = "¡Siempre puedes probar la fuerza de seguridad Al Kharid!",
        ["No thanks."] = "No, gracias.",
        ["Do you visit the oasis?"] = "¿Visitas el oasis?",
        ["Do you ever visit the oasis?"] = "¿Alguna vez visitas el oasis?",
        ["When I can. As much as I miss the arena, the oasis is a nice change of scenery. And the crocodiles seem to enjoy the rotten fruit I throw to them. Wanna buy some?"] = "Cuando pueda. Por mucho que extraño la arena, el oasis es un agradable cambio de escenario. Y los cocodrilos parecen disfrutar de la fruta podrida que les tiro. ¿Quieres comprar algunos?",
        ["Yes, please."] = "Sí, por favor.",
        ["No, thanks."] = "No, gracias.",
        ["I'd like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
        ["I'd like to see my Collection box."] = "Me gustaría ver mi caja de Colección.",
        ["Would you like to trade?"] = "¿Le gustaría negociar?",
        ["I suppose so."] = "Supongo que sí.",
    },
    ["Fairy (echo)"] = {
        ["There was a moon - close to a lush-looking planet - whose tiny winged inhabitants opened portals to explore the wonders of the universe. This is their story."] = "Había una luna, cercana a un planeta de aspecto exuberante, cuyos diminutos habitantes alados abrían portales para explorar las maravillas del universo. Esta es su historia.",
        ["I discovered my first evidence of the race I would come to know as fairies in my exploration of the myriad nature worlds."] = "Descubrí mi primera evidencia de la raza que llegaría a conocer como hadas en mi exploración de los innumerables mundos de la naturaleza.",
        ["These were environments of wild diversity, prolific with the strangest of fauna and flora, where the strongest survived and the weak were food."] = "Eran entornos de diversidad salvaje, prolíficos con la fauna y la flora más extrañas, donde los más fuertes sobrevivían y los débiles eran alimento.",
        ["Much later, similar creatures were found on Gielinor, such as the jadinko and ganodermic beasts, but with an undeniably common origin."] = "Mucho más tarde, se encontraron criaturas similares en Gielinor, como el jadinko y las bestias ganodermicas, pero con un origen innegablemente común.",
        ["Were they, perhaps, the final products of a great experiment? Could the same hand have forged the Blade that I wielded?"] = "¿Fueron, quizás, los productos finales de un gran experimento? ¿Podría la misma mano haber forjado la espada que yo empuñé?",
        ["On one dark world, teeming with all manner of fungi in its humid jungles and moist swamps, I met with a race of surprisingly intellectual mushrooms."] = "En un mundo oscuro, repleto de todo tipo de hongos en sus selvas húmedas y pantanos húmedos, me encontré con una raza de hongos sorprendentemente intelectuales.",
        ["They lacked mobility, but travelled and reproduced by dispersing spores that fused with the nervous system of local animals, allowing them to control the host."] = "Carecían de movilidad, pero viajaban y se reproducían dispersando esporas que se fusionaban con el sistema nervioso de los animales locales, permitiéndoles controlar al huésped.",
        ["Bonding with me in this way, I was able to communicate with the myceloids. Friendly though they were, it took much persuasion to convince the symbiotic parasites to detach from my brain upon taking root."] = "Al unirme de esta manera, pude comunicarme con los micelios. Aunque eran amigables, fue necesaria mucha persuasión para convencer a los parásitos simbióticos de que se separaran de mi cerebro al echar raíces.",
        ["Another world teemed with insects. A culture of winged invertebrates that bore some resemblance to the fairies of Zanaris, but the swarms were mindless and tirelessly industrious."] = "Otro mundo lleno de insectos. Una cultura de invertebrados alados que guardaba cierto parecido con las hadas de Zanaris, pero los enjambres eran tontos e incansablemente trabajadores.",
        ["The migration of these insects - which was achieved through an innate ability to teleport over short distances - also seemed to have a direct impact on the local climate, for reasons I could not discern."] = "La migración de estos insectos, que se logró mediante una capacidad innata de teletransportarse en distancias cortas, también parecía tener un impacto directo en el clima local, por razones que no pude discernir.",
        ["This brings us to the moon of Zanaris, its dark magical forests, giant fungi and, as I discovered on a return visit, a network of fairy rings they had made from the World Gate I'd placed there."] = "Esto nos lleva a la luna de Zanaris, sus oscuros bosques mágicos, hongos gigantes y, como descubrí en una visita posterior, una red de anillos de hadas que habían hecho a partir de la Puerta del Mundo que había colocado allí.",
        ["The fairies of Zanaris, caretakers of the world below, obviously shared a common ancestry with the creatures I had encountered on the nature worlds."] = "Las hadas de Zanaris, cuidadoras del mundo inferior, obviamente compartían una ascendencia común con las criaturas que había encontrado en los mundos naturales.",
        ["However, they were changed, transcendent, inextricably bound to the abundant magical energy of Gielinor, in order to fulfil a specific purpose."] = "Sin embargo, fueron cambiados, trascendentes, indisolublemente ligados a la abundante energía mágica de Gielinor, para cumplir un propósito específico.",
        ["The fairies are an embodiment of magic - their life-force infused with anima."] = "Las hadas son una encarnación de la magia: su fuerza vital infundida con ánima.",
        ["It is why they work so tirelessly to maintain Gielinor's weather and seasons, for the planet's equilibrium is intrinsic to their own wellbeing."] = "Es por eso que trabajan tan incansablemente para mantener el clima y las estaciones de Gielinor, ya que el equilibrio del planeta es intrínseco a su propio bienestar.",
        ["They have no choice. It is now necessary for their very survival, but they perform their duty without complaint."] = "No tienen otra opción. Ahora es necesario para su supervivencia, pero cumplen con su deber sin quejarse.",
    },
