        ["Select an Option"] = "Selecciona una opción",
        ["I think I'll stay here a bit longer."] = "Creo que me quedaré aquí un poco más.",
        ["I think I'll stay down here a bit longer."] = "Creo que me quedaré aquí un poco más.",
        ["As you wish."] = "Como desees.",
        ["Yes, I'm ready to leave."] = "Sí, estoy listo para partir.",
        ["*(One of the following dialogues is played:)*"] = "*(Se reproduce uno de los siguientes diálogos:)*",
        ["*(Dialogue 1:)*"] = "*(Diálogo 1:)*",
        ["Err, hello. Do you have any idea what a Winter Fairy actually does?"] = "Err, hola. ¿Tienes alguna idea de lo que realmente hace un Winter Fairy?",
        ["No, no idea at all."] = "No, ni idea.",
        ["Oh, pity. Neither do I, but I'm supposed to be one this week."] = "Oh, lástima. Yo tampoco, pero se supone que lo seré esta semana.",
        ["*(Dialogue 2:)*"] = "*(Diálogo 2:)*",
        ["Have you got any idea where Burthorpe is? The co-ordinator says I need to go there and paint all the leaves yellow, but I've never heard of that place!"] = "¿Tienes alguna idea de dónde está Burthorpe? El coordinador dice que tengo que ir allí y pintar todas las hojas de amarillo, ¡pero nunca había oído hablar de ese lugar!",
        ["*(Dialogue 3:)*"] = "*(Diálogo 3:)*",
        ["Be careful when you pick mushrooms near the strange ruins to the south. Some of them will try to eat you!"] = "Ten cuidado al recoger setas cerca de las extrañas ruinas del sur. ¡Algunos de ellos intentarán comerte!",
        ["*(Dialogue 4:)*"] = "*(Diálogo 4:)*",
        ["I'm afraid I can't stop to chat. I've just been told to get ready to go to Etceteria for some reason or other!"] = "Me temo que no puedo parar a charlar. ¡Me acaban de decir que me prepare para ir a Etceteria por alguna razón u otra!",
        ["*(Dialogue 5:)*"] = "*(Diálogo 5:)*",
        ["Picking mushrooms near the forge will probably end quite badly for you. Not as bad as the ones by the strange ruins to the south though. They're much bigger."] = "Recoger setas cerca de la fragua probablemente terminará bastante mal para ti. Aunque no son tan malos como los de las extrañas ruinas del sur. Son mucho más grandes.",
        ["*(Dialogue 6:)*"] = "*(Diálogo 6:)*",
        ["Sorry, I can't talk I'm looking for Sarah-Jane!"] = "Lo siento, no puedo hablar. ¡Estoy buscando a Sarah-Jane!",
        ["*(Dialogue 7:)*"] = "*(Diálogo 7 :)*",
        ["Is your name Freddie, and are you losing your teeth?"] = "¿Te llamas Freddie y estás perdiendo los dientes?",
        ["Err, no. I'm afraid not."] = "Err, no. Me temo que no.",
        ["Oh, right. You don't have any idea where I can find him do you?"] = "Ah, claro. No tienes idea de dónde puedo encontrarlo, ¿verdad?",
        ["No, I don't know that either."] = "No, yo tampoco lo sé.",
        ["Oh, ok then. If you do find out please let me know. The co-ordinator has sent me to find him."] = "Oh, está bien entonces. Si lo averiguas por favor házmelo saber. El coordinador me ha enviado a buscarlo.",
    },
    ["Fairy (market exit)"] = {
        ["This fairy ring will take you out of Zanaris. It leads to the place known as Al Kharid in your realm. Once passed, you can not return this way. Before leaving, make sure that you have fully sampled the delights of our marketplace."] = "Este anillo de hadas te sacará de Zanaris. Conduce al lugar conocido como Al Kharid en tu reino. Una vez pasado, no se puede volver por este camino. Antes de partir, asegúrese de haber probado todas las delicias de nuestro mercado.",
        ["Select an Option"] = "Selecciona una opción",
        ["I think I'll stay here a bit longer."] = "Creo que me quedaré aquí un poco más.",
        ["I think I'll stay down here a bit longer."] = "Creo que me quedaré aquí un poco más.",
        ["As you wish."] = "Como desees.",
        ["Yes, I'm ready to leave."] = "Sí, estoy listo para partir.",
    },
    ["Fairy Aeryka"] = {
        ["Hello, my name is Player. Who are you?"] = "Hola, mi nombre es Player. ¿Quién eres?",
        ["Oh hello Player. I'm Aeryka. Aery for short."] = "Oh, hola Player. Soy Aeryka. Aery para abreviar.",
        ["Airy Fairy?"] = "¿Aireado Fairy?",
        ["That's right. What can I do for you?"] = "Así es. ¿Qué puedo hacer por ti?",
        ["What's that crop circle thing doing here?"] = "¿Qué hace ese círculo en las cosechas aquí?",
        ["Crop circle? Oh, you mean the Puromantic portal?"] = "¿Círculo de cultivos? Oh, ¿te refieres al portal Puromantic?",
        ["The pyromanic what?"] = "¿El pirománico qué?",
        ["The Puromantic portal. At least that's what we call them. It's the way the implings travel from Puro-Puro to other planes."] = "El portal Puromántico. Al menos así es como los llamamos. Es la forma en que los implings viajan de Puro-Puro a otros planos.",
        ["Puro-Puro?"] = "¿Puro-Puro?",
        ["The impling home. We call it Puro-Puro. The implings just call it home, I think."] = "El hogar implícito. Lo llamamos Puro-Puro. Creo que los implícitos simplemente lo llaman hogar.",
        ["It's still here."] = "Todavía está aquí.",
        ["Pardon?"] = "¿Perdón?",
        ["It's still here. The crop circle is still here."] = "Todavía está aquí. El círculo de las cosechas todavía está aquí.",
        ["Oh yes, thanks Aery. It didn't go anywhere in the meantime, then?"] = "Oh, sí, gracias Aery. ¿Entonces no llegó a ninguna parte mientras tanto?",
        ["Nope. It just sat there."] = "No. Simplemente se quedó allí.",
        ["Jolly good. I can come back and visit Puro-Puro whenever I want then. Brilliant!"] = "Muy bien. Entonces puedo volver a visitar Puro-Puro cuando quiera. ¡Brillante!",
        ["Is there anything else you want to ask?"] = "¿Hay algo más que quieras preguntar?",
        ["What's in Puro-Puro?"] = "¿Qué hay en Puro-Puro?",
        ["Implings...and wheat."] = "Implicaciones... y trigo.",
        ["Erm, anything else?"] = "Erm, ¿algo más?",
        ["Not really. Though I have noticed quite a lot of you humans travelling through the portal recently. I suppose you must like wheat."] = "En realidad, no. Aunque he notado que muchos de ustedes, humanos, viajan a través del portal recientemente. Supongo que te debe gustar el trigo.",
        ["Well, most of us prefer lobsters to be perfectly honest, but there must be something interesting there."] = "Bueno, para ser honesto, la mayoría de nosotros preferimos las langostas, pero debe haber algo interesante allí.",
        ["Oh, I did notice a very serious-looking gnome go into the portal. Maybe he knows what's going on."] = "Oh, noté que un gnomo de aspecto muy serio entró en el portal. Quizás él sepa lo que está pasando.",
        ["Do you remember what his name was?"] = "¿Recuerdas cómo se llamaba?",
        ["Errm, Egg-nog, or something like that."] = "Errm, ponche de huevo o algo así.",
        ["Right, thanks! I'll have a chat with him when I go. Maybe he'll know what's going on."] = "¡Bien, gracias! Charlaré con él cuando vaya. Quizás él sepa lo que está pasando.",
        ["So what are these implings then?"] = "Entonces, ¿cuáles son estas implicaciones?",
        ["Well, no-one knows for sure. The mischievous little creatures are probably related to imps. And they fly as well. Also, like imps, they love collecting things. I'm not sure why, though. They also seem to like being chased."] = "Bueno, nadie lo sabe con seguridad. Estas pequeñas y traviesas criaturas probablemente estén emparentadas con diablillos. Y también vuelan. Además, al igual que los diablillos, les encanta coleccionar cosas. Aunque no estoy seguro de por qué. También parece que les gusta que los persigan.",
        ["So how would I get hold of what they are carrying, then?"] = "Entonces, ¿cómo podría conseguir lo que llevan?",
        ["Catch them, I suppose. I don't know really. Why would you want to?"] = "Atrápalos, supongo. Realmente no lo sé. ¿Por qué querrías hacerlo?",
        ["Well, if they were carrying something useful. Maybe I could catch them with a big net - like butterflies."] = "Bueno, si llevaran algo útil. Tal vez podría atraparlas con una red grande, como mariposas.",
        ["Sounds a bit cruel to me, but I suppose that's possible."] = "Suena un poco cruel para mí, pero supongo que es posible.",
        ["I've heard I may find dragon equipment in Puro-Puro."] = "He oído que puedo encontrar equipo para dragones en Puro-Puro.",
        ["Really? You humans like that stuff a lot, don't you? I don't like really old stuff myself."] = "¿En serio? A los humanos les gustan mucho esas cosas, ¿no? A mí tampoco me gustan las cosas realmente viejas.",
        ["Old?"] = "¿Viejo?",
        ["Yes, dragon stuff feels really old."] = "Sí, las cosas de dragones parecen muy viejas.",
        ["How can you tell that?"] = "¿Cómo puedes saber eso?",
        ["From its magical aura, obviously. Oh, I forget you humans can't feel auras."] = "Por su aura mágica, obviamente. Oh, olvidé que los humanos no pueden sentir auras.",
        ["How old is old?"] = "¿Cuántos años tiene la edad?",
        ["Really, really, old."] = "De verdad, de verdad, viejo.",
        ["Can you be any more precise?"] = "¿Puedes ser más preciso?",
        ["Not really. Time doesn't really mean a lot round here. Hundreds, maybe thousands of your human lifespans, I suppose. Anyway, it would have to be old since it all comes from the Necrosyrtes."] = "En realidad, no. El tiempo realmente no significa mucho por aquí. Cientos, tal vez miles de vidas humanas, supongo. De todos modos tendría que ser antiguo ya que todo proviene de los Necrosyrtes.",
        ["Necrosyrtes? Who are they?"] = "¿Necrosirtes? ¿Quiénes son?",
        ["Old and powerful creatures. I don't think there have been any around here for aeons. I haven't seen one. I don't think they are very nice. Not like me. Anyway, this is all ancient history. Boooring!"] = "Criaturas viejas y poderosas. No creo que haya habido ninguno por aquí desde hace eones. No he visto ninguno. No creo que sean muy agradables. No como yo. De todos modos, todo esto es historia antigua. ¡Abucheos!",
        ["While I'm on the subject do you have any dragon stuff I can have?"] = "Ya que estoy en el tema, ¿tienes algo de dragón que pueda tener?",
        ["Oh, I did have loads, but I threw it away."] = "Oh, tenía un montón, pero lo tiré.",
        ["What?"] = "¿Qué?",
        ["Only joking. No, sorry, I can't help you there. You'll have to look for it yourself. Although, maybe if you find Necrosyrtes then they'll give you some. I heard they give dragon stuff away to people they like. Not fairies. We're too nice."] = "Sólo bromeo. No, lo siento, no puedo ayudarte en eso. Tendrás que buscarlo tú mismo. Aunque, tal vez si encuentras Necrosyrtes entonces te darán algunos. He oído que regalan cosas de dragones a la gente que les gusta. No hadas. Somos demasiado amables.",
        ["No, bye!"] = "¡No, adiós!",
        ["See you around!"] = "¡Nos vemos!",
    },
    ["Fairy Fixit"] = {
        ["Select an option"] = "Selecciona una opción",
        ["I want to buy a fairy enchantment."] = "Quiero comprar un encantamiento de hadas.",
        ["Here you go!"] = "¡Aquí tienes!",
        ["Talk about something else."] = "Habla de otra cosa.",
        ["Why are you carrying that toolbox?"] = "¿Por qué llevas esa caja de herramientas?",
        ["It's the fizgog! It's picking up cable again!"] = "¡Es el fizgog! ¡Está captando cable otra vez!",
        ["Uh, right. So is it safe to use the fairy rings then?"] = "Ah, claro. Entonces, ¿es seguro usar los anillos de hadas?",
        ["Sure, as long as you have been given permission to use them. You should just be aware that using the fairy rings sometimes has strange results - the locations that you have been to may affect the locations you are trying to reach. I could fix it by replacing the fizgog and the whosprangit; I've put in a request for some new parts, but they're pretty hard to get hold of it seems."] = "Claro, siempre y cuando se te haya dado permiso para usarlos. Sólo debes tener en cuenta que el uso de los anillos de hadas a veces tiene resultados extraños: los lugares en los que has estado pueden afectar los lugares a los que intentas llegar. Podría solucionarlo reemplazando el fizgog y el whosprangit; He solicitado algunas piezas nuevas, pero parece que es bastante difícil conseguirlas.",
    },
    ["Fairy Nuff"] = {
        ["Hello, can I help you at all?"] = "Hola, ¿puedo ayudarte en algo?",
        ["Select an Option"] = "Selecciona una opción",
        ["What do you do around here?"] = "¿Qué haces por aquí?",
        ["Oh, I'm the resident healer. My name is Nuff, Fairy Nuff. Who are you?"] = "Oh, soy el sanador residente. Mi nombre es Nuff, Fairy Nuff. ¿Quién eres?",
        ["My name is Player."] = "Mi nombre es Player.",
        ["Pleased to meet you, Player. As I was saying, I'm the healer in Zanaris. I graduated over 200 human years ago. Look, there's my Advanced Healing Certificate on the wall. I never go anywhere without it. It's my job to look after the sick, wounded or dying fairies around here. Of course, fairies being magical by nature, not many of them get hurt, so I don't normally have much to do."] = "Encantado de conocerte, Player. Como decía, soy el sanador de Zanaris. Me gradué hace más de 200 años humanos. Mira, ahí está mi Certificado de Curación Avanzada en la pared. Nunca voy a ningún lado sin él. Mi trabajo es cuidar de las hadas enfermas, heridas o moribundas de aquí. Por supuesto, como las hadas son mágicas por naturaleza, no muchas de ellas resultan heridas, así que normalmente no tengo mucho que hacer.",
        ["What about healing humans? Lots of adventurers must get hurt fighting the Otherworldly beings."] = "¿Qué pasa con la curación de humanos? Muchos aventureros deben resultar heridos luchando contra seres del Otro Mundo.",
        ["Yes, they do. Silly isn't it? I do use my healing magic on humans sometimes, but I don't like them attacking our other guests, so I charge them for the service."] = "Sí, lo hacen. Tonto ¿no? A veces uso mi magia curativa con humanos, pero no me gusta que ataquen a nuestros otros invitados, así que les cobro por el servicio.",
        ["How much do you charge to heal someone, then?"] = "¿Cuánto cobras por curar a alguien, entonces?",
        ["Well, the gold that you humans are so fond of has no real value in Zanaris, so I ask my patients to pay me in gems. I will heal 40 life points for an opal, 50 life points for either a sapphire or a piece of jade, 70 life points for an emerald or red topaz, 90 for a ruby and 110 for a diamond."] = "Bueno, el oro que tanto les gusta a los humanos no tiene valor real en Zanaris, así que les pido a mis pacientes que me paguen en gemas. Curaré 40 puntos de vida por un ópalo, 50 puntos de vida por un zafiro o un trozo de jade, 70 puntos de vida por una esmeralda o topacio rojo, 90 por un rubí y 110 por un diamante.",
        ["Only 110 life points for a diamond? Doesn't that seem a bit steep?"] = "¿Solo 110 puntos de vida por un diamante? ¿No parece un poco caro?",
        ["Maybe to you, but you'd be surprised how many adventurers are willing to pay those prices."] = "Quizás para ti, pero te sorprendería saber cuántos aventureros están dispuestos a pagar esos precios.",
        ["No thanks. Just looking around."] = "No, gracias. Sólo mirando a mi alrededor.",
        ["Okay. If you want to know anything, just ask."] = "Está bien. Si quieres saber algo, sólo pregunta.",
        ["Hello Player, do you need any assistance?"] = "Hola Player, ¿necesitas ayuda?",
        ["Yes, please. I need healing."] = "Sí, por favor. Necesito curación.",
        ["Sure, how many life points would you like me to heal?"] = "Claro, ¿cuántos puntos de vida te gustaría que sane?",
        ["40 Life points."] = "40 puntos de vida.",
        ["That will cost you 1 opal."] = "Eso te costará 1 ópalo.",
        ["All right."] = "Muy bien.",
        ["You don't have to pay me!"] = "¡No tienes que pagarme!",
        ["Whoops, sorry."] = "Vaya, lo siento.",
        ["On second thoughts, no thanks."] = "Pensándolo bien, no, gracias.",
        ["Okay, suit yourself."] = "Está bien, haz lo que quieras.",
        ["50 Life points."] = "50 puntos de vida.",
        ["That will cost you 1 sapphire or 1 piece of jade."] = "Eso te costará 1 zafiro o 1 pieza de jade.",
        ["You don't have a sapphire or a piece of jade with you!"] = "¡No llevas ni un zafiro ni un trozo de jade contigo!",
        ["70 Life points."] = "70 puntos de vida.",
        ["That will cost you 1 emerald or 1 red topaz."] = "Eso te costará 1 esmeralda o 1 topacio rojo.",
        ["You don't have an emerald or a red topaz to pay me with!"] = "¡No tienes una esmeralda o un topacio rojo para pagarme!",
        ["90 Life points."] = "90 puntos de vida.",
        ["That will cost you 1 ruby."] = "Eso te costará 1 rubí.",
        ["You don't have a ruby to pay me!"] = "¡No tienes ni un rubí para pagarme!",
        ["110 Life points."] = "110 puntos de vida.",
        ["That will cost you 1 diamond."] = "Eso te costará 1 diamante.",
        ["You don't have a diamond to pay me!"] = "¡No tienes un diamante para pagarme!",
        ["Thank you so much for all you've done for us, Player."] = "Muchas gracias por todo lo que has hecho por nosotros, Player.",
        ["Oh, Player, thanks so much for your help! You're a true friend to us fairies!"] = "Oh, Player, ¡muchas gracias por tu ayuda! ¡Eres un verdadero amigo para nosotras las hadas!",
        ["I have a puzzle for you!"] = "¡Tengo un rompecabezas para ti!",
        ["[Fairy Nuff has given you a puzzle box!]"] = "[¡Fairy Nuff te ha regalado una caja de rompecabezas!]",
        ["Is that your best attempt? You'll have to try harder."] = "¿Es ese tu mejor intento? Tendrás que esforzarte más.",
        ["[Fairy Nuff has given you another clue scroll!]"] = "[¡Fairy Nuff te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["There you go!"] = "¡Ahí lo tienes!",
    },
    ["Fairy Queen"] = {
        ["Select an option"] = "Selecciona una opción",
        ["How do crops and such survive down here?"] = "¿Cómo sobreviven los cultivos y demás aquí abajo?",
        ["How do crops and such survive down here? Surely they need a bit of sunlight?"] = "¿Cómo sobreviven los cultivos y demás aquí abajo? ¿Seguramente necesitan un poco de luz solar?",
        ["Clearly you come from a plane dependent on sunlight. Down here, the plants grow in the aura of faerie."] = "Claramente vienes de un plano que depende de la luz solar. Aquí abajo, las plantas crecen en un aura de hadas.",
        ["What's so good about this place?"] = "¿Qué tiene de bueno este lugar?",
        ["Zanaris is a meeting point of cultures. Those from many worlds converge here to exchange knowledge and goods."] = "Zanaris es un punto de encuentro de culturas. Personas de muchos mundos convergen aquí para intercambiar conocimientos y bienes.",
        ["Have you managed to work out a plan yet?"] = "¿Ya has logrado elaborar un plan?",
        ["Not yet, Player, but it looks like we'll need to ask you for your help again, I'm afraid. I'll be able to tell you more once we have finished making our battle plans."] = "Todavía no, Player, pero parece que tendremos que pedirte ayuda nuevamente, me temo. Podré contarles más una vez que hayamos terminado de hacer nuestros planes de batalla.",
        ["I've lost my magic watering can."] = "He perdido mi regadera mágica.",
        ["Oh, what a nuisance! Have another."] = "¡Oh, qué molestia! Toma otro.",
        ["[The Fairy Queen gives you a magic watering can.]"] = "[El Fairy Queen te ofrece una regadera mágica.]",
        ["Don't fret Player! My farming advisors tell me you added it to your tool belt!"] = "¡No te preocupes Player! ¡Mis asesores agrícolas me dicen que lo agregaste a tu cinturón de herramientas!",
        ["Oh, great! Thanks!"] = "¡Oh, genial! ¡Gracias!",
        ["How's everything in Zanaris?"] = "¿Cómo va todo en Zanaris?",
        ["All seems to be going pretty well now that the Fairy Godfather has been sorted out. Thanks so much for your help with that little problem."] = "Todo parece ir bastante bien ahora que se ha solucionado el padrino de Fairy. Muchas gracias por tu ayuda con ese pequeño problema.",
        ["My pleasure. If you get any other issues you need sorting out, just let me know."] = "Es un placer. Si tienes algún otro problema que necesites solucionar, házmelo saber.",
    },
    ["Fairy chef"] = {
        ["Ello, sugar. I'm afraid I can't gossip right now, I've got a cake in the oven."] = "Hola, cariño. Me temo que ahora no puedo cotillear, tengo un pastel en el horno.",
        ["Oi you! Did you think I didn't see that? That's my chocolate bar, that is!"] = "¡Oye tú! ¿Pensaste que no vi eso? ¡Esa es mi barra de chocolate, eso es!",
        ["Oh, sorry. I didn't realise it belonged to anybody."] = "Oh, lo siento. No me di cuenta de que pertenecía a nadie.",
        ["That's alright, honey. You look a bit thin anyway. Take it if you need it."] = "Está bien, cariño. Te ves un poco delgada de todos modos. Tómalo si lo necesitas.",
    },
    ["Fairy shop assistant"] = {
        ["Can I help you at all?"] = "¿Puedo ayudarte en algo?",
        ["Select an option"] = "Seleccione una opción",
        ["Yes, please. What are you selling?"] = "Sí, por favor. ¿Qué estás vendiendo?",
        ["How should I use your shop?"] = "¿Cómo debo utilizar su tienda?",
        ["I'm glad you ask! You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "¡Me alegra que lo preguntes! Puede comprar tantos artículos almacenados como desee. También puedes vender la mayoría de los artículos en la tienda.",
        ["No, thanks."] = "No, gracias.",
    },
    ["Fairy shopkeeper"] = {
        ["*When talking to the Fairy shopkeeper in Zanaris.*"] = "*Al hablar con Fairy shopkeeper en Zanaris.*",
        ["Can I help you at all?"] = "¿Puedo ayudarte en algo?",
        ["Select an option"] = "Seleccione una opción",
        ["Yes, please. What are you selling?"] = "Sí, por favor. ¿Qué estás vendiendo?",
        ["How should I use your shop?"] = "¿Cómo debo utilizar su tienda?",
        ["I'm glad you ask! You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "¡Me alegra que lo preguntes! Puede comprar tantos artículos almacenados como desee. También puedes vender la mayoría de los artículos en la tienda.",
        ["No, thanks."] = "No, gracias.",
    },
    ["Fairy trader"] = {
        ["You need to be a level 113 thief to steal from this target."] = "Debes ser un ladrón de nivel 113 para robarle a este objetivo.",
        ["You cannot keep pickpocketing as you have a full inventory."] = "No puedes seguir robando carteras porque tienes un inventario completo.",
        ["You pick the target's pocket."] = "Escoges el bolsillo del objetivo.",
        ["[number] coins have been added to your money pouch."] = "[número] coins se han agregado a su bolsa de dinero.",
    },
    ["Faisal the Barman"] = {
        ["Hello there."] = "Hola.",
        ["Good day. Can I help you with anything?"] = "Buenos días. ¿Puedo ayudarte con algo?",
        ["Select an option"] = "Selecciona una opción",
        ["Yes, I'd like a drink please."] = "Sí, me gustaría un trago por favor.",
        ["What's going on in town?"] = "¿Qué está pasando en la ciudad?",
        ["Well since you gave the two gangs a good kicking, things have improved hugely. Both gangs seem to be spending all their gold here drowning their sorrows."] = "Bueno, desde que les diste una buena patada a las dos pandillas, las cosas han mejorado enormemente. Ambas bandas parecen estar gastando todo su oro aquí ahogando sus penas.",
        ["That's great! So do I get a cut in the profits?"] = "¡Eso es genial! Entonces, ¿recibo una parte de las ganancias?",
        ["Get out of here, you cheeky rascal. A cut in my profits? As if!"] = "Sal de aquí, bribón descarado. ¿Un recorte en mis ganancias? ¡Como si!",
        ["Nothing much really, the same as you would expect of any border town on the edge of the desert."] = "Nada realmente, lo mismo que se esperaría de cualquier ciudad fronteriza al borde del desierto.",
        ["So can you tell me anything about those two gangs in the town?"] = "Entonces, ¿puedes contarme algo sobre esas dos pandillas en la ciudad?",
        ["Nothing much to really say about them. They're all paying customers so I won't rock the boat if you don't mind."] = "No hay mucho que decir sobre ellos. Todos son clientes que pagan, así que no haré problemas si no te importa.",
        ["Is there anything else I can help you with?"] = "¿Hay algo más en lo que pueda ayudarte?",
        ["No thanks I'm ok."] = "No gracias estoy bien.",
        ["No thanks I'm ok. Thanks for your time."] = "No, gracias, estoy bien. Gracias por tu tiempo.",
        ["Yes, I'd like to talk about something else."] = "Sí, me gustaría hablar de otra cosa.",
        ["The 'Asp and Snake'? What a strange name for a bar."] = "¿El 'Áspide y la Serpiente'? Qué nombre más extraño para un bar.",
        ["I know what you're thinking, asps are a type of snake, right?"] = "Sé lo que estás pensando, los áspides son un tipo de serpiente, ¿verdad?",
        ["I admit it is a little confusing, but neither 'The Asp' nor 'The Snake' have quite the same ring to them."] = "Admito que es un poco confuso, pero ni 'The Asp' ni 'The Snake' suenan igual.",
        ["I get your point. I quite like the name."] = "Entiendo tu punto. Me gusta bastante el nombre.",
        ["*(After The Feud:)* Could you tell Traitorous Hesham that someone has poisoned his drink."] = "*(Después de The Feud:)* ¿Podrías decirle al traidor Hesham que alguien ha envenenado su bebida?",
        ["Could you tell Traitorous Hesham that someone has poisoned his drink."] = "¿Podrías decirle al traidor Hesham que alguien ha envenenado su bebida?",
        ["What! Drink being poisoned in my bar! My reputation could be destroyed if someone died here. Thank you adventurer."] = "¡Qué! ¡Bebe siendo envenenado en mi bar! Mi reputación podría destruirse si alguien muriera aquí. Gracias aventurero.",
        ["No problem at all."] = "No hay ningún problema.",
        ["Here have a beer - it's on the house."] = "Toma una cerveza, la invita la casa.",
        ["Thanks!"] = "¡Gracias!",
        ["Faisal the barman gives you a beer."] = "Faisal the barman te regala una cerveza.",
        ["Congratulations! You have completed: 'Free Beer Here' - Tell Faisal the Barman that Traitorous Hesham's drink was poisoned."] = "¡Felicitaciones! Has completado: 'Cerveza gratis aquí' - Dile a Faisal the Barman que la bebida del Traidor Hesham fue envenenada.",
        ["Thanks but no thanks, I don't drink."] = "Gracias pero no gracias, no bebo.",
        ["Don't say that around here too loud please, it may catch and then I'd be out of business."] = "No digas eso por aquí demasiado alto, por favor, puede sonar y entonces me quedaría sin negocio.",
        ["You could always open up a non alcoholic fruit juice bar. You'd have less problems with drunken customers."] = "Siempre puedes abrir una barra de jugos de frutas sin alcohol. Tendrías menos problemas con clientes borrachos.",
        ["You might be onto something there, but then what would I do with the drunken sailor?"] = "Puede que tengas algo ahí, pero entonces, ¿qué haría con el drunken sailor?",
        ["Who?"] = "¿Quién?",
        ["Jalal the Drunk. Oh never mind its a long story."] = "Jalal the Drunk. Oh, no importa, es una larga historia.",
        ["Yuck! I don't like beer."] = "¡Qué asco! No me gusta la cerveza.",
        ["Fine, no need to insult me then."] = "Bien, entonces no necesitas insultarme.",
    },
    ["Faiza"] = {
        ["Woo woo."] = "Guau, guau.",
        ["If only there was an item I could wear that would help me communicate with you..."] = "Si tan solo hubiera un artículo que pudiera usar y que me ayudara a comunicarme con ustedes...",
        ["Woo woo wooo. (You can't make out the words but you sense whatever she's saying is laced with sarcasm)"] = "Woo woo wooo. (No puedes distinguir las palabras pero sientes que todo lo que dice está lleno de sarcasmo)",
        ["So your journey has finally led you here, Slayer!"] = "¡Así que tu viaje finalmente te ha llevado hasta aquí, Slayer!",
        ["Who's there?"] = "¿Quién está ahí?",
        ["Ah, I am but a spirit now. Bound forever to this place to preserve everything we hold sacred."] = "Ah, ahora no soy más que un espíritu. Unidos para siempre a este lugar para preservar todo lo que consideramos sagrado.",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is where it all began. Where I, one of the seven original Slayer Masters, placed my sword down and swore that I would forever more be dedicated to the deliverance of souls to the afterlife. Welcome to the Order of the Slayers. This is the origin of everything you have trained for. My life ended long ago but little did I know my promise truly meant forever. And you are here because it is time for you to begin your journey to becoming a Slayer Master."] = "Aquí es donde empezó todo. Donde yo, uno de los siete Slayer Masters originales, puse mi espada y juré que siempre estaría dedicado a la liberación de almas al más allá. Bienvenidos a la Orden de los Cazadores. Este es el origen de todo para lo que te has entrenado. Mi vida terminó hace mucho tiempo, pero no sabía que mi promesa realmente significaba para siempre. Y usted está aquí porque es hora de que comience su viaje para convertirse en Slayer Master.",
        ["Yes, if you accept, over time I will teach you everything there is to know about our Order. So, do you wish to begin?"] = "Sí, si aceptas, con el tiempo te enseñaré todo lo que hay que saber sobre nuestra Orden. Entonces, ¿quieres empezar?",
        ["Start training to become a Slayer Master?"] = "¿Empezar a entrenar para convertirte en un Slayer Master?",
        ["Yes."] = "Sí.",
        ["Excellent."] = "Excelente.",
        ["So what do I need to do?"] = "Entonces, ¿qué debo hacer?",
        ["We need to go back to the start. All the monsters you have fought and killed so far have developed your combat skills against them, but that is not enough. Now it is time to understand them. Every creature has a soul - that spark within them that is the basis for everything that they are. As part of your training to become a Slayer Master, I request your assistance. The Order is in ruins covered in a magic that has locked away the secrets of our past. You must capture these souls and deliver them back here. Each soul gathered will weaken the spell that we placed over the Order all those years ago. And in return I will offer you further training."] = "Necesitamos volver al principio. Todos los monstruos con los que has luchado y matado hasta ahora han desarrollado tus habilidades de combate contra ellos, pero eso no es suficiente. Ahora es el momento de entenderlos. Cada criatura tiene un alma, esa chispa dentro de ellas que es la base de todo lo que son. Como parte de tu formación para convertirte en Slayer Master, solicito tu ayuda. La Orden está en ruinas cubierta por una magia que ha encerrado los secretos de nuestro pasado. Debes capturar estas almas y devolverlas aquí. Cada alma reunida debilitará el hechizo que colocamos sobre la Orden hace tantos años. Y a cambio te ofreceré más formación.",
        ["I have to capture the soul of every Slayer creature?"] = "¿Tengo que capturar el alma de cada criatura Slayer?",
        ["I never said the journey was going to be easy. If you wish to give up, you may leave now. I have waited this long, I can wait more if required."] = "Nunca dije que el viaje iba a ser fácil. Si deseas rendirte, puedes irte ahora. He esperado tanto tiempo, puedo esperar más si es necesario.",
        ["I'm ready."] = "Estoy listo.",
        ["*(If you don't have two empty inventory slots:)*"] = "*(Si no tienes dos espacios de inventario vacíos:)*",
        ["You need 2 free inventory spaces for the next step of your training."] = "Necesitas 2 espacios de inventario gratuitos para el siguiente paso de tu capacitación.",
        ["*(Dialogue terminates. After clearing inventory, the dialogue begins again at **Faiza:** Excellent.)*"] = "*(El diálogo termina. Después de limpiar el inventario, el diálogo comienza nuevamente en **Faiza:** Excelente.)*",
        ["*(If you have two empty inventory slots:)*"] = "*(Si tienes dos espacios de inventario vacíos:)*",
        ["*Faiza gives you some empty ushtabi and a Slayer Codex.*"] = "*Faiza te ofrece algunos ushtabi vacíos y un códice Slayer.*",
        ["These ushabti are vessels that can contain the soul of a Slayer monster. Simply kill a monster with one of these with you and it has a chance of capturing the creature's soul. Bring it back here and you can deliver the soul in return for greater understanding and take another step on your way to becoming a Slayer Master. The Codex in turn will allow you to track your progress. As you capture each monster it will be marked in the Codex, this will lead to a greater understanding which in turn comes with its own rewards."] = "Estos ushabti son recipientes que pueden contener el alma de un monstruo Slayer. Simplemente mata a un monstruo con uno de estos contigo y tendrás la posibilidad de capturar el alma de la criatura. Tráelo de vuelta aquí y podrás entregar el alma a cambio de una mayor comprensión y dar un paso más en tu camino para convertirte en un Slayer Master. El Codex, a su vez, te permitirá seguir tu progreso. A medida que captures cada monstruo, se marcará en el Códice, lo que conducirá a una mayor comprensión que a su vez viene con sus propias recompensas.",
        ["*You can now purchase more ushabti from the Slayer Masters around the world.*"] = "*Ahora puedes comprar más ushabti de Slayer Masters en todo el mundo.*",
        ["*(Continues with normal dialogue below.)*"] = "*(Continúa con el diálogo normal a continuación.)*",
        ["Sorry, but I have better things to do!"] = "Lo siento, ¡pero tengo mejores cosas que hacer!",
        ["*(Dialogue terminates. After returning, the dialogue begins again at **Faiza:** Excellent.)*"] = "*(El diálogo termina. Después de regresar, el diálogo comienza nuevamente en **Faiza:** Excelente.)*",
        ["A disappointing answer, however if this is your desire I cannot interfere. However the offer remains; you are welcome to return at any time and begin your training."] = "Una respuesta decepcionante, sin embargo, si este es tu deseo, no puedo interferir. Sin embargo la oferta permanece; Eres bienvenido a regresar en cualquier momento y comenzar tu entrenamiento.",
        ["Welcome back, Slayer."] = "Bienvenido de nuevo, Slayer.",
        ["*(If you are eligible for a free ushtabi (given for each Slayer level above 99):*"] = "*(Si eres elegible para recibir un ushtabi gratis (otorgado por cada nivel de Slayer superior a 99):*",
        ["*Faiza gives you an empty ushtabi.*"] = "*Faiza te da un ushtabi vacío.*",
        ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
        ["*(If you have lost Slayer Codex:)*"] = "*(Si has perdido el Códice Slayer:)*",
        ["It seems you have lost your Slayer Codex. Would you like another?"] = "Parece que has perdido tu códice Slayer. ¿Quieres otro?",
        ["Select an option"] = "Seleccione una opción",
        ["Faiza gives you a Slayer Codex."] = "Faiza te ofrece un códice Slayer.",
        ["*(Continues with normal dialogue.)*"] = "*(Continúa con el diálogo normal.)*",
        ["Can you explain what I need to do?"] = "¿Puedes explicar lo que tengo que hacer?",
        ["We need to go back to the start. All the monsters you have fought against and killed so far have developed your combat skills against them but that is not enough. Now it is time to understand them. Every creature has a soul - that spark within them that is the basis for everything that they are. As part of your training to become a Slayer Master, I request your assistance. The Order is in ruins covered in magic that has locked away the secrets of our past. You must capture these souls and deliver them back here. Each soul gathered will weaken the spell that we placed over the Order all those years ago. And in return, I will offer you further training."] = "Necesitamos volver al principio. Todos los monstruos contra los que has luchado y matado hasta ahora han desarrollado tus habilidades de combate contra ellos, pero eso no es suficiente. Ahora es el momento de entenderlos. Cada criatura tiene un alma, esa chispa dentro de ellas que es la base de todo lo que son. Como parte de tu formación para convertirte en Slayer Master, solicito tu ayuda. La Orden está en ruinas cubierta de magia que ha encerrado los secretos de nuestro pasado. Debes capturar estas almas y devolverlas aquí. Cada alma reunida debilitará el hechizo que colocamos sobre la Orden hace tantos años. Y a cambio te ofreceré más formación.",
        ["I have to capture the soul of every slayer creature?"] = "¿Tengo que capturar el alma de cada criatura asesina?",
        ["I never said the journey was going to be easy. These ushtabi are vessels that can contain the soul of a Slayer monster. Simple kill a monster with one of these with you and it has a chance of capturing the creature's soul. Bring it back here and you can deliver the soul in return for greater understanding and take another step on your way to becoming a Slayer Master."] = "Nunca dije que el viaje iba a ser fácil. Estos ushtabi son recipientes que pueden contener el alma de un monstruo Slayer. Simplemente mata a un monstruo con uno de estos contigo y tendrás la posibilidad de capturar el alma de la criatura. Tráelo de vuelta aquí y podrás entregar el alma a cambio de una mayor comprensión y dar un paso más en tu camino para convertirte en un Slayer Master.",
        ["You can purchase more ushtabi from Slayer Masters around the world."] = "Puedes comprar más ushtabi en Slayer Masters en todo el mundo.",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["What is the best way to catch a soul?"] = "¿Cuál es la mejor manera de atrapar un alma?",
        ["As your understanding of Slayer increases, the chance of catching a soul significantly increases. Additionally, being on a Slayer task increases your chance of capturing the soul."] = "A medida que aumenta su comprensión de Slayer, la posibilidad de atrapar un alma aumenta significativamente. Además, estar en una tarea Slayer aumenta tus posibilidades de capturar el alma.",
        ["What else can I do with these souls?"] = "¿Qué más puedo hacer con estas almas?",
        ["If understanding is not enough you can also capture these souls and bring them here. Within these walls, the soul remains in stasis unable to move to the afterlife. You may wish to release a soul in one of the rooms ahead. There they will stay, under your command, allowing you to kill them over and over again. You may find this useful if you are on a Slayer task. There are others that have also found this place and they too wish to learn the secrets of the Order. If you meet one of those people, perhaps they would allow you to witness the spirits they have captured."] = "Si la comprensión no es suficiente, también puedes capturar estas almas y traerlas aquí. Dentro de estos muros, el alma permanece en estasis incapaz de pasar al más allá. Es posible que desees liberar un alma en una de las habitaciones más adelante. Allí permanecerán, bajo tu mando, permitiéndote matarlos una y otra vez. Puede que esto le resulte útil si se encuentra en una tarea Slayer. Hay otros que también han encontrado este lugar y también desean conocer los secretos de la Orden. Si conoces a una de esas personas, tal vez te permitan presenciar los espíritus que han capturado.",
        ["What can you tell me about the Order?"] = "¿Qué me puedes contar sobre la Orden?",
        ["That can wait. First capture some souls and begin your journey of understanding."] = "Eso puede esperar. Primero captura algunas almas y comienza tu viaje de comprensión.",
        ["I have to go now."] = "Tengo que irme ahora.",
        ["Farewell."] = "Adiós.",
        ["For both meeting Morvran's Platinum Rush of Blood challenge and completing the Slayer Codex, you have unlocked the title "] = "Tanto para superar el desafío Platinum Rush of Blood de Morvran como para completar el Códice Slayer, has desbloqueado el título ",
    },
    ["Faizan Augour"] = {
        ["Welcome, welcome! It's wonderful to see a fresh face. You'll need to speak to Orla to get a rundown of our research before I can help you."] = "¡Bienvenido, bienvenido! Es maravilloso ver una cara nueva. Tendrás que hablar con Orla para obtener un resumen de nuestra investigación antes de que pueda ayudarte.",
        ["Ah, excellent - a new volunteer! You're already on your way, but I have plenty to share with you. Shall we get started?"] = "Ah, excelente, ¡un nuevo voluntario! Ya estás en camino, pero tengo mucho que compartir contigo. ¿Empezamos?",
        ["Select an option"] = "Selecciona una opción",
        ["Yes, please."] = "Sí, por favor.",
        ["First, we will learn how to make portents. These varied items can be held in your inventory for different effects. Why don't you try and make one?"] = "Primero, aprenderemos a hacer portentos. Estos variados elementos se pueden guardar en su inventario para lograr diferentes efectos. ¿Por qué no intentas hacer uno?",
        ["Not at the moment, thanks."] = "Por el momento no, gracias.",
        ["*After creating a portent:*"] = "*Después de crear un presagio:*",
        ["I have much more to show you! Would you like to continue with my lessons?"] = "¡Tengo mucho más que mostrarte! ¿Te gustaría continuar con mis lecciones?",
        ["Select an otpion"] = "Selecciona una opción",
        ["Yes!"] = "¡Sí!",
        ["You've made a portent, so it's time for something more advanced. Why not try your hand at a divine location?"] = "Has hecho un presagio, así que es hora de algo más avanzado. ¿Por qué no probar suerte en un lugar divino?",
        ["*After creating a divine location:*"] = "*Después de crear una ubicación divina:*",
        ["You are proving to be an excellent pupil! Would you like to learn more?"] = "¡Estás demostrando ser un excelente alumno! ¿Quieres saber más?",
        ["Well the next logical step seems to be to learn about signs. These useful little items can be worn in your pocket slot for various effects! Make one, and see what benefit it gives you."] = "Bueno, el siguiente paso lógico parece ser aprender sobre las señales. ¡Estos pequeños y útiles objetos se pueden llevar en la ranura de tu bolsillo para conseguir diversos efectos! Haga uno y vea qué beneficio le brinda.",
        ["*After creating a sign and with Divination level 10 or higher:*"] = "*Después de crear un letrero y con Divination nivel 10 o superior:*",
        ["This is my very latest discovery. Would you like me to share it with you?"] = "Este es mi último descubrimiento. ¿Quieres que lo comparta contigo?",
        ["As you increase your skill in divination, you'll find yourself moving on to more complex wisps. It just so happens I've discovered something useful for that very situation! With a large amount of divine energy of the correct tier, you will be able to make a boon. This means you will be more effective when converting memories of the tier for which your boon was made, giving you a greater return! Why don't you give it a go?"] = "A medida que aumentes tu habilidad en adivinación, te encontrarás pasando a mechones más complejos. ¡Da la casualidad de que descubrí algo útil para esa misma situación! Con una gran cantidad de energía divina del nivel correcto, podrás realizar una bendición. Esto significa que serás más efectivo al convertir recuerdos del nivel para el cual se creó tu bendición, ¡lo que te brindará un mayor retorno! ¿Por qué no lo intentas?",
        ["I'm afraid my lessons are slightly too advanced for you at the moment. When you've increased your experience in divination, though, please do come and see me."] = "Me temo que mis lecciones son demasiado avanzadas para ti en este momento. Sin embargo, cuando hayas aumentado tu experiencia en adivinación, por favor ven a verme.",
        ["You need Divination level <13> to continue with Faizan's lessons."] = "Necesitas el nivel Divination <13> para continuar con las lecciones de Faizan.",
        ["*After creating a boon:*"] = "*Después de crear una bendición:*",
        ["Your knowledge of divination currently equals my own. Orla tells me she's discovered something new, though. Perhaps you should speak to her!"] = "Tu conocimiento de adivinación actualmente es igual al mío. Sin embargo, Orla me dice que ha descubierto algo nuevo. ¡Quizás deberías hablar con ella!",
        ["Ok, I'll speak to Orla."] = "Ok, hablaré con Orla.",
        ["I'd like to ask about portents."] = "Me gustaría preguntar sobre los presagios.",
        ["How do I make portents?"] = "¿Cómo hago portentos?",
        ["**Faizan Augour:** First, you'll need to find out what ingredients you need to make your chosen portent. All portents require some tier of divine energy and a secondary ingredient. Then, simply weave the divine energy to make your portent. This can be done straight from your backpack - no need for any tools."] = "**Faizan Augour:** Primero, necesitarás averiguar qué ingredientes necesitas para hacer el portento elegido. Todos los portentos requieren algún nivel de energía divina y un ingrediente secundario. Luego, simplemente entreteje la energía divina para hacer tu portento. Esto se puede hacer directamente desde su backpack, sin necesidad de herramientas.",
        ["How do I use portents?"] = "¿Cómo uso los portentos?",
        ["How do I make signs?"] = "¿Cómo hago carteles?",
        ["How do I use signs?"] = "¿Cómo uso los signos?",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["**Faizan Augour:** When a portent has been created, it can be kept in your inventory. Its effect will kick in automatically when needed - without you having to activate it!"] = "**Faizan Augour:** Cuando se ha creado un portento, se puede guardar en su inventario. Su efecto se activará automáticamente cuando sea necesario, ¡sin que tengas que activarlo!",
        ["How do you make portents?"] = "¿Cómo se hacen presagios?",
        ["How do you make signs?"] = "¿Cómo se hacen los carteles?",
        ["How do you use signs?"] = "¿Cómo se utilizan los signos?",
        ["I'd like to ask about divine locations."] = "Me gustaría preguntar sobre lugares divinos.",
        ["How do I make divine locations?"] = "¿Cómo hago lugares divinos?",
        ["**Faizan Augour:** Well first you'll need the ingredients. All divine locations require some tier of divine energy and a secondary ingredient. The secondary ingredient will most likely be a sample of what you would expect to get from your divine location. For example, if you're making a divine bronze rock, you'll need either copper or tin ore. Be aware that you may need a large amount of that secondary ingredient. When you've got your ingredients, you just need to weave the divine energy. Remember that you can do this anywhere, and you don't need any tools."] = "**Faizan Augour:** Bueno, primero necesitarás los ingredientes. Todos los lugares divinos requieren algún nivel de energía divina y un ingrediente secundario. Lo más probable es que el ingrediente secundario sea una muestra de lo que esperarías obtener de tu ubicación divina. Por ejemplo, si estás haciendo una roca de bronce divina, necesitarás mineral de cobre o estaño. Tenga en cuenta que es posible que necesite una gran cantidad de ese ingrediente secundario. Cuando tengas tus ingredientes, sólo necesitas tejer la energía divina. Recuerda que puedes hacer esto en cualquier lugar y no necesitas ninguna herramienta.",
        ["How do you use divine locations?"] = "¿Cómo se utilizan las ubicaciones divinas?",
        ["How do I use divine locations?"] = "¿Cómo uso ubicaciones divinas?",
        ["**Faizan Augour:** When you've made a divine location, you can place it and use it much like anywhere you would gather resources normally, for example a tree, or an ore rock. It's beneficial to place them in busy areas, as others can use your location too. When they do, there's a chance that you'll get additional resources."] = "**Faizan Augour:** Cuando hayas creado una ubicación divina, puedes colocarla y usarla como en cualquier lugar donde normalmente recolectarías recursos, por ejemplo, un árbol o una roca mineral. Es beneficioso colocarlos en áreas concurridas, ya que otros también pueden usar su ubicación. Cuando lo hagan, existe la posibilidad de que obtenga recursos adicionales.",
        ["How do you make divine locations?"] = "¿Cómo se crean lugares divinos?",
        ["I'd like to ask about signs."] = "Me gustaría preguntar sobre las señales.",
        ["**Faizan Augour:** Much like portents, you just need some divine energy of the correct tier and a secondary ingredient. Weave the divine energy straight from your backpack to make your chosen sign, no tools required."] = "**Faizan Augour:** Al igual que los portentos, solo necesitas algo de energía divina del nivel correcto y un ingrediente secundario. Entreteje la energía divina directamente desde tu backpack para hacer el letrero que elijas, sin necesidad de herramientas.",
        ["To use a sign, you simply need to equip it! It will then sit in your pocket, dormant, until it is triggered. The point at which it is triggered depends on the purpose of the sign, of course."] = "¡Para usar un letrero, simplemente necesitas equiparlo! Luego permanecerá en su bolsillo, inactivo, hasta que se active. El momento en el que se activa depende, por supuesto, del propósito del signo.",
        ["How do you use portents?"] = "¿Cómo se utilizan los portentos?",
        ["I'd like to ask about boons."] = "Me gustaría preguntar sobre las bendiciones.",
        ["Ah, boons are particularly interesting. To make one, you will need a large amount of divine energy of the correct tier. Weave the divine energy to make your selected boon. As before, this can be done anywhere - straight from your backpack - and doesn't require any tools. The boon will be automatically applied to you, giving you a permanent, passive benefit. Then, when converting memories of the same tier as that boon, you will receive additional experience or divine energy."] = "Ah, las bendiciones son particularmente interesantes. Para hacer uno, necesitarás una gran cantidad de energía divina del nivel correcto. Teje la energía divina para hacer tu bendición seleccionada. Como antes, esto se puede hacer en cualquier lugar, directamente desde su backpack, y no requiere ninguna herramienta. La bendición se le aplicará automáticamente, brindándole un beneficio pasivo permanente. Luego, al convertir recuerdos del mismo nivel que esa bendición, recibirás experiencia adicional o energía divina.",
        ["Thanks for the explanation."] = "Gracias por la explicación.",
        ["I have made one further discovery. Would you like me to share it with you?"] = "He hecho un descubrimiento más. ¿Quieres que lo comparta contigo?",
        ["I have discovered you can use divine energy to change one item into another! Just take the correct tier and amount of divine energy, along with a secondary ingredient, and you are able to produce a higher quality object. You should try it!"] = "¡He descubierto que puedes usar energía divina para transformar un objeto en otro! Simplemente tome el nivel y la cantidad correctos de energía divina, junto con un ingrediente secundario, y podrá producir un objeto de mayor calidad. ¡Deberías probarlo!",
        ["Ah, my favourite volunteer! You should speak to Orla; she has something to congratulate you on your achievement in divination so far."] = "¡Ah, mi voluntario favorito! Deberías hablar con Orla; Ella tiene algo para felicitarte por tus logros en adivinación hasta ahora.",
        ["Ah, my favourite volunteer! What can I do for you?"] = "¡Ah, mi voluntario favorito! ¿Qué puedo hacer por ti?",
        ["I'd like to ask about signs and portents."] = "Me gustaría preguntar sobre señales y presagios.",
        ["I'd like to ask about transmutation."] = "Me gustaría preguntar sobre la transmutación.",
        ["Transmutation is a most interesting application of divine energy. It seems you can take an item, combine it with divine energy and transform it into a greater one!"] = "La transmutación es una aplicación muy interesante de la energía divina. ¡Parece que puedes tomar un objeto, combinarlo con energía divina y transformarlo en uno mayor!",
        ["For example, we can transmute logs into oak logs; iron ore into silver ore... The possibilities are tremendous!"] = "Por ejemplo, podemos transmutar logs en oak logs; mineral de hierro en mineral de plata... ¡Las posibilidades son tremendas!",
        ["To do this, you will need an amount of divine energy of the correct tier, and a secondary ingredient. It seems that some of the secondary ingredient is destroyed in the process, so it is likely that you will need a good amount."] = "Para hacer esto, necesitarás una cantidad de energía divina del nivel correcto y un ingrediente secundario. Parece que parte del ingrediente secundario se destruye en el proceso, por lo que es probable que necesites una buena cantidad.",
        ["When you have your ingredients, weave your divine energy and conduct your transmutation!"] = "¡Cuando tengas tus ingredientes, teje tu energía divina y lleva a cabo tu transmutación!",
        ["Thanks."] = "Gracias.",
        ["No, thanks."] = "No, gracias.",
    },
    ["Falador White Knight"] = {
        ["Greetings! Duke Horacio has called for aid, and Falador answers! While we'd love to help our fellow Saradominists battle the evil forces of Zamorak, our primary duty is to protect the citizens of Lumbridge. Fear not, we shall protect you from any Zamorakian scum that decides to wander out of the crater!"] = "¡Saludos! ¡Duke Horacio ha pedido ayuda y Falador responde! Si bien nos encantaría ayudar a nuestros compañeros saradoministas a luchar contra las fuerzas malignas de Zamorak, nuestro deber principal es proteger a los ciudadanos de Lumbridge. ¡No temas, te protegeremos de cualquier escoria zamorakiana que decida salir del cráter!",
    },
    ["Falador representative"] = {
        ["Not gonna' introduce ya'self then?"] = "¿No te vas a presentar entonces?",
    },
    ["Fallen Nihil"] = {
        ["Thank you for heeding my call, human."] = "Gracias por atender mi llamado, humano.",
        ["It's hard to ignore a demon stepping out of a bonfire."] = "Es difícil ignorar a un demonio que sale de una hoguera.",
        ["I have been sent as an emissary of the Queen of Ashes, and require any and all help."] = "Me han enviado como emisario de la Reina de las Cenizas y necesito toda la ayuda.",
        ["What is it you need?"] = "¿Qué es lo que necesitas?",
        ["Many interesting embers have been turning up in this world, and my Queen wishes to analyse their properties. Collect as many burning embers as possible and bring them back to me."] = "Muchas brasas interesantes han ido apareciendo en este mundo, y mi Reina desea analizar sus propiedades. Recoge tantas brasas encendidas como puedas y tráemelas.",
        ["Sounds simple enough."] = "Suena bastante simple.",
        ["What are you?"] = "¿Qué eres?",
        ["A failed experiment. Considered unworthy. Incredibly angry. Redeemed by Fire."] = "Un experimento fallido. Considerado indigno. Increíblemente enojado. Redimidos por el fuego.",
        ["It sounds like you've got a pretty large grudge against someone."] = "Parece que tienes un gran rencor contra alguien.",
        ["That's not even the half of it."] = "Eso no es ni la mitad.",
        ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
        ["What do you plan to do with these Burning Embers?"] = "¿Qué planeas hacer con estas brasas ardientes?",
        ["Some questions are best left unanswered, human."] = "Es mejor dejar algunas preguntas sin respuesta, humano.",
        ["Like 'What's your relationship with Zaros'?"] = "Como '¿Cuál es tu relación con Zaros'?",
        ["Yes, like that one."] = "Sí, como ese.",
        ["How did you get here?"] = "¿Cómo llegaste aquí?",
        ["My Queen noticed this world appear in the heavens as if it had been revealed from behind a curtain. Last year she felt an increase in fire energy in this location. She had her pyradins spend a year preparing to use that energy. With it, she could bring me through the planes, in the hopes that the energy would build up once more."] = "Mi Reina notó que este mundo aparecía en los cielos como si hubiera sido revelado detrás de una cortina. El año pasado sintió un aumento en la energía del fuego en este lugar. Hizo que sus piradins pasaran un año preparándose para usar esa energía. Con él, podría llevarme a través de los planos, con la esperanza de que la energía se acumulara una vez más.",
        ["You worked an entire year in the hope that the energy might return?"] = "¿Trabajaste un año entero con la esperanza de que la energía regresara?",
        ["I did not personally; my task is to act as scout and herald for my Queen; to seek worlds that are ready for her Enlightenment, and deliver messages between those who are already Enlightened."] = "Yo personalmente no; mi tarea es actuar como explorador y heraldo de mi Reina; buscar mundos que estén listos para su Iluminación y entregar mensajes entre aquellos que ya están Iluminados.",
        ["How long will you be around for?"] = "¿Cuánto tiempo estarás aquí?",
        ["Without a continuous source, all fire comes to an end. I can only last here for the amount of time my Queen's strength allows me. Be sure to collect my embers quickly!"] = "Sin una fuente continua, todo fuego llega a su fin. Sólo puedo durar aquí el tiempo que me permita la fuerza de mi Reina. ¡Asegúrate de recoger mis brasas rápidamente!",
        ["*(Only after asking one of the latter two questions:)*"] = "*(Sólo después de hacer una de las dos últimas preguntas :)*",
        ["Who is the Queen of Ashes?"] = "¿Quién es la Reina de las Cenizas?",
        ["A redeemer, and life-giver. My queen accepted me for what I was, and gave me a second chance in life. Soon, Gielinor will feel the same redemption."] = "Un redentor y dador de vida. Mi reina me aceptó tal como era y me dio una segunda oportunidad en la vida. Pronto, Gielinor sentirá la misma redención.",
        ["How soon is 'soon'?"] = "¿Qué tan pronto es \"pronto\"?",
        ["The Queen of Ashes rushes nothing, small one. She is biding her time and will arrive when she feels this world is ready."] = "La Reina de las Cenizas no se apresura, pequeña. Ella está esperando su momento y llegará cuando sienta que este mundo está listo.",
        ["So... soon?"] = "Entonces... ¿pronto?",
        ["Yes, soon."] = "Sí, pronto.",
        ["Thank you for helping me collect these particular burning embers. I still have some time here to thank you for your efforts. Soon I will depart, but rest assured you will be hearing from my Queen in the near future."] = "Gracias por ayudarme a recolectar estas brasas ardientes en particular. Todavía tengo algo de tiempo aquí para agradecerles por sus esfuerzos. Pronto partiré, pero ten por seguro que tendrás noticias de mi Reina en un futuro próximo.",
        ["*(As during the event.)*"] = "*(Como durante el evento.)*",
        ["*(Only after asking something else:)*"] = "*(Solo después de preguntar algo más :)*",
        ["*(If a reward isn't unlocked:)*"] = "*(Si una recompensa no está desbloqueada:)*",
        ["I require more offerings before I can reward you."] = "Necesito más ofertas antes de poder recompensarte.",
        ["*(If a reward is unlocked:)*"] = "*(Si se desbloquea una recompensa:)*",
        ["There you are!"] = "¡Ahí estás!",
        ["*(Without rewards to claim and none claimed:)*"] = "*(Sin recompensas para reclamar y ninguna reclamada:)*",
        ["You'll need to help me some more before I can offer you any rewards."] = "Tendrás que ayudarme un poco más antes de poder ofrecerte alguna recompensa.",
        ["*(Without rewards to claim and some claimed:)*"] = "*(Sin recompensas que reclamar y algunas reclamadas:)*",
        ["*(Without all rewards claimed:)*"] = "*(Sin todas las recompensas reclamadas :)*",
        ["You've already claimed all of the rewards I have to offer."] = "Ya has reclamado todas las recompensas que tengo para ofrecer.",
    },
    ["Fame"] = {
        ["Tell me about the Drop: 15th Anniversary Edition."] = "Háblame de Drop: Edición del 15.º aniversario.",
        ["*If the player completed Deathcon II*"] = "*Si el player completó Deathcon II*",
        ["Hello again sugar, my clever friend who completed the puzzle book."] = "Hola de nuevo, cariño, mi inteligente amiga que completó el libro de rompecabezas.",
        ["I'm back, by popular demand. For the 15th Aniversary celebrations they've asked me to host a special edition of The Drop. We've hand-picked questions all about the history of RuneScape. If you get them all right, you'll get a new title and a huge prismatic star! I'm sure you'll be a winner in no time, you can't keep talent down."] = "Estoy de regreso, por demanda popular. Para las celebraciones del 15º aniversario me pidieron que presentara una edición especial de The Drop. Hemos seleccionado preguntas sobre la historia de RuneScape. ¡Si los haces bien, obtendrás un nuevo título y una enorme estrella prismática! Estoy seguro de que serás un ganador en poco tiempo, no puedes reprimir el talento.",
        ["Enter The Drop: 15th Anniversary Edition."] = "Ingrese The Drop: Edición del 15º aniversario.",
        ["*If The Drop has not started*"] = "*Si The Drop no ha comenzado*",
        ["The Drop: 15th Anniversary Edition starts in X minutes."] = "The Drop: Edición del 15.º aniversario comienza en X minutos.",
        ["What are the rewards?"] = "¿Cuáles son las recompensas?",
        ["If you get all the answers correct sweetie, you can get the limited edition title, 'the Historian' and a huge bonus XP star! You've got to get them all right in one go though to get them, so keep trying! Then you'll get a star for the star you are. Break a leg, sweetie!"] = "Si obtienes todas las respuestas correctas, cariño, ¡puedes obtener el título de edición limitada, 'el Historiador' y una enorme estrella de XP adicional! Tienes que hacerlos bien de una sola vez para conseguirlos, ¡así que sigue intentándolo! Entonces obtendrás una estrella por la estrella que eres. ¡Rómpete una pierna, cariño!",
        ["Farewell."] = "Adiós.",
        ["Good to see you sweetie!"] = "¡Qué bueno verte, cariño!",
        ["You're looking well as always, Fame."] = "Te ves bien como siempre, Fame.",
        ["Select an option"] = "Seleccione una opción",
        ["Why did you move the statues?"] = "¿Por qué moviste las estatuas?",
        ["I loved the garden that Pete and I made for the fifteenth anniversary celebrations, and I wanted to make sure that it was preserved. It was so gorgeous, and the world deserves to keep beauty like that. And, there was the lovely serendipity of the Arc, and all of these new islands, so I knew just what I had to do. I claimed one as my own and got the statues shipped over here. So they can spend the rest of time in this glorious atmosphere and so everyone can enjoy them. Don't they look lovely?"] = "Me encantó el jardín que Pete y yo hicimos para las celebraciones del decimoquinto aniversario y quería asegurarme de que se conservara. Era tan hermoso y el mundo merece mantener una belleza así. Y estaba la encantadora casualidad del Arco y todas estas nuevas islas, así que sabía exactamente lo que tenía que hacer. Reclamé una como mía y envié las estatuas aquí. Para que puedan pasar el resto del tiempo en este glorioso ambiente y para que todos puedan disfrutar de ellos. ¿No se ven preciosos?",
        ["Absolutely. It's quite the setting for them."] = "Absolutamente. Es todo un escenario para ellos.",
        ["Why are you here?"] = "¿Por qué estás aquí?",
        ["Well, darling, why wouldn't I be? Don't you just love the atmosphere? Every star has to have their bolt-hole, their little piece of tranquillity where they can truly be themselves. This is that place for me. My little haven."] = "Bueno, cariño, ¿por qué no lo estaría? ¿No te encanta el ambiente? Cada estrella tiene que tener su refugio, su pedacito de tranquilidad donde poder ser verdaderamente ella misma. Este es ese lugar para mí. Mi pequeño refugio.",
        ["So you're staying here?"] = "¿Entonces te quedarás aquí?",
        ["Well, if my public calls for me, I will of course answer them, it's only right. But for now, this is my home."] = "Bueno, si mi público me llama, por supuesto les responderé, es lo correcto. Pero por ahora esta es mi casa.",
        ["What are you planning to do next?"] = "¿Qué planeas hacer a continuación?",
        ["It's tiring having so much talent, so I'm taking this time to recuperate so I can come back at full capacity. Feel free to visit me from time to time, sweetie, your company is always welcome. But, yes, I shall be here until I am completely reinvigorated."] = "Es agotador tener tanto talento, así que me estoy tomando este tiempo para recuperarme y poder regresar a plena capacidad. No dudes en visitarme de vez en cuando, cariño, tu compañía siempre es bienvenida. Pero sí, estaré aquí hasta que esté completamente revitalizado.",
        ["Bye."] = "Adiós.",
        ["Break a leg, sweetie!"] = "¡Rómpete una pierna, cariño!",
    },
    ["Famine"] = {
        ["You've unlocked the next step."] = "Has desbloqueado el siguiente paso.",
        ["Really?"] = "¿En serio?",
        ["Yes."] = "Sí.",
        ["Like really though? This is the next step?"] = "¿Te gusta realmente? ¿Este es el siguiente paso?",
        ["Why not? I know Mazcab lore."] = "¿Por qué no? Conozco la tradición Mazcab.",
        ["But but..."] = "Pero pero...",
        ["HAHAHAHAHAHAHAHAHAHAHAHAHA. I'm joking. But I've been asked to give you a message from a hooded stranger... It reads... 'Mod Raven woz ere."] = "JAJAJAJAJAJAJAJAJAJAJAJAJAJA. Estoy bromeando. Pero me han pedido que te dé un mensaje de un extraño encapuchado... Dice... 'Mod Raven woz ere'.",
        ["Famine does not acknowledge you. She releases a heavy sigh."] = "Famine no te reconoce. Ella lanza un profundo suspiro.",
        ["Famine is not amused by your antics."] = "A Famine no le divierten tus payasadas.",
        ["Congratulations! You have completed: 'The Feast and the Famine' - Attempt to be funny and show a primal feast to someone who won't appreciate it at Stormguard."] = "¡Felicitaciones! Has completado: 'The Feast and the Famine': intenta ser gracioso y mostrar un festín primitivo a alguien que no lo apreciará en Stormguard.",
    },
    ["Fancy Dan"] = {
        ["Arr!"] = "¡Arr!",
        ["Is there something I can help ye with?"] = "¿Hay algo en lo que pueda ayudarte?",
        ["Select an option"] = "Seleccione una opción",
        ["I would like to join your crew."] = "Me gustaría unirme a tu equipo.",
        ["Of course you would!"] = "¡Por supuesto que sí!",
        ["Arr, well we'll get you sorted out with a team hat right away."] = "Arr, bueno, te solucionaremos el problema con una gorra de equipo de inmediato.",
        ["Go wait in the waiting room, I'll call you when we are ready to begin."] = "Ve a esperar en la sala de espera, te llamaré cuando estemos listos para comenzar.",
        ["If wearing hat or helmet"] = "Si usa sombrero o casco",
        ["However, I don't let anyone on the team if they are wearing a hat or a helmet."] = "Sin embargo, no dejo a nadie en el equipo si lleva gorra o casco.",
        ["You can go and store it in the deposit box next to Jimmy's stall."] = "Puedes ir y guardarlo en la caja de depósito al lado del puesto de Jimmy.",
        ["Why not?"] = "¿Por qué no?",
        ["Well, in order to tell my crew from San Fan's I will need to give you a hat like mine."] = "Bueno, para decírselo a mi equipo de San Fan's tendré que regalarles un sombrero como el mío.",
        ["If you are wearing a hat it might get lost when I give you my crew's hat."] = "Si llevas sombrero, es posible que se pierda cuando te entregue el sombrero de mi equipo.",
        ["You wouldn't want that would you?"] = "No querrías eso, ¿verdad?",
        ["No, that sounds very reasonable in fact."] = "No, de hecho, eso suena muy razonable.",
        ["If you do not have an empty inventory"] = "Si no tienes un inventario vacío",
        ["Well, I'll be glad to have you aboard, but you will need to go and store all of your gear first."] = "Bueno, me alegrará tenerte a bordo, pero primero tendrás que ir a guardar todo tu equipo.",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["Well, you will need all of your inventory space for the ingredients, and all of the other things I'll need you to haul about."] = "Bueno, necesitarás todo el espacio de tu inventario para los ingredientes y todas las demás cosas que necesitaré que cargues.",
        ["There is a bank deposit box next to Jimmy's stall if you need it. Come and see me when you have a fully empty inventory."] = "Hay una caja de depósito bancaria al lado del puesto de Jimmy si la necesitas. Ven a verme cuando tengas el inventario completamente vacío.",
        ["Who are you, and what is this place?"] = "¿Quién eres y qué es este lugar?",
        ["Arrharrharr!"] = "¡Arrarra!",
        ["Do you not recognise me? I am the famous dandy pirate 'Fancy' Dan!"] = "¿No me reconoces? ¡Soy el famoso pirata dandy 'Fancy' Dan!",
        ["Yes, of course, any pirate knows who you are."] = "Sí, por supuesto, cualquier pirata sabe quién eres.",
        ["But of course."] = "Pero claro.",
        ["As for what this place is, it is my glorious still, producing the best quality 'rum' this side of Braindeath Island."] = "En cuanto a lo que es este lugar, es mi glorioso alambique, que produce el 'ron' de mejor calidad de este lado de Braindeath Island.",
        ["Oh, and the run-down swill-producing ditch that San Fan over there calls a still."] = "Ah, y la zanja deteriorada que produce basura y que San Fan llama alambique.",
        ["So with two stills you have plenty of 'rum' right?"] = "Entonces con dos fotogramas tienes mucho 'ron', ¿verdad?",
        ["Well we would do, if that hatchet-faced harridan wouldn't keep trying to torch the place!"] = "¡Bueno, lo haríamos si esa bruja con cara de hacha no siguiera intentando incendiar el lugar!",
        ["I say!"] = "¡Yo digo!",
        ["A little while ago we had some real problems getting rum to the island, hence the two stills."] = "Hace poco tuvimos verdaderos problemas para llevar ron a la isla, de ahí los dos alambiques.",
        ["However, after a little misunderstanding involving San's still and a barrel of gunpowder our relationship seems to have become a little strained."] = "Sin embargo, después de un pequeño malentendido que involucró al alambique de San y un barril de pólvora, nuestra relación parece haberse vuelto un poco tensa.",
        ["Apparently it is perfectly within the pirate code to burn each others stills, so long as nobody directly attacks the other person's crew, so run production has taken a slight dip of late."] = "Aparentemente está perfectamente dentro del código pirata quemar imágenes fijas unos de otros, siempre y cuando nadie ataque directamente a la tripulación de la otra persona, por lo que la producción ha disminuido ligeramente últimamente.",
        ["Can I help out?"] = "¿Puedo ayudar?",
        ["Yes, probably. I have a bunch of jobs that need doing, if you feel up to it."] = "Sí, probablemente. Tengo un montón de trabajos que hacer, si te sientes con ganas.",
        ["What would you like to know about?"] = "¿Qué te gustaría saber?",
        ["Brewing 'Rum"] = "Elaborar ron",
        ["How do I help you brew 'Rum'?"] = "¿Cómo te ayudo a preparar 'ron'?",
        ["Well the stills we have set up are based on the ones on Braindeath Island... well roughly at any rate."] = "Bueno, las imágenes fijas que hemos creado se basan en las de Braindeath Island... bueno, más o menos, en cualquier caso.",
        ["All you have to do is help put the ingredients into the hopper and keep the boilers burning."] = "Todo lo que tienes que hacer es ayudar a poner los ingredientes en la tolva y mantener las calderas encendidas.",
        ["If you add enough ingredients to the hopper's then you have the ability to pick up a single bottle of rum when it brews."] = "Si agregas suficientes ingredientes a la tolva, podrás recoger una sola botella de ron cuando se prepare.",
        ["So, if ye add 5 buckets of water to the hopper's, then ye get access to one bottle. If you add 3 bowls of coloured water you get access to one bottle, and if you add one of anything else you get access to one bottle."] = "Entonces, si agregas 5 cubos de agua a la tolva, tendrás acceso a una botella. Si agregas 3 tazones de agua coloreada, tendrás acceso a una botella, y si agregas uno de cualquier otra cosa, tendrás acceso a una botella.",
        ["This is cumulative, meaning that if you add (for example ) 10 buckets of water, 3 sweetgrubs and 6 bowls of coloured water, then you have a chance to collect 7 bottles of rum for the team."] = "Esto es acumulativo, lo que significa que si agregas (por ejemplo) 10 cubos de agua, 3 larvas dulces y 6 tazones de agua coloreada, tendrás la oportunidad de recolectar 7 botellas de ron para el equipo.",
        ["The boilers are easy as pie to sort out. You just put some logs in, light them with a tinderbox, and then keep putting logs in until they are good and hot."] = "Las calderas son muy fáciles de clasificar. Simplemente pones un poco de logs, los enciendes con un yesquero y luego sigues poniendo logs hasta que estén bien y calientes.",
        ["Three logs should do it, but it's best to keep heaping them in just in case."] = "Tres logs deberían ser suficientes, pero es mejor seguir amontonándolos por si acaso.",
        ["The ingredients are; Bitternuts, Scrapey Tree Bark, Sweetgrubs, Buckets of Water and some Coloured Water."] = "Los ingredientes son; Nueces amargas, corteza de árbol raspada, larvas dulces, cubos de agua y un poco de agua coloreada.",
        ["Where can I get Bitternuts?"] = "¿Dónde puedo conseguir Bitternuts?",
        ["There are plenty of Bitternut trees inside this walled off area. The problem is that the trees are too tricky for a human to climb."] = "Hay muchos árboles Bitternut dentro de esta área amurallada. El problema es que los árboles son demasiado complicados para que un humano los trepe.",
        ["You will need to catch a monkey and send it up the tree to get the nut for you."] = "Tendrás que atrapar un mono y enviarlo al árbol para que te consiga la nuez.",
        ["Send it up the tree? How does that work?"] = "¿Enviarlo al árbol? ¿Cómo funciona eso?",
        ["Well, if you were a monkey, and some random person grabbed you, dumped some dye in your fur and shoved you up a tree, you would hurl the closest heavy object at them too."] = "Bueno, si fueras un mono y una persona al azar te agarrara, te arrojara un poco de dye en tu pelaje y te empujara hacia un árbol, también les arrojarías el objeto pesado más cercano.",
        ["Wait a second, dye?"] = "Espera un segundo, ¿dye?",
        ["Yes, you'll need to get a bowl of coloured water and pour it on the monkey. Otherwise you won't be able to tell which team the monkey belongs to."] = "Sí, necesitarás conseguir un recipiente con agua coloreada y verterlo sobre el mono. De lo contrario no podrás saber a qué equipo pertenece el mono.",
        ["That makes sense...I think..."] = "Eso tiene sentido... Creo...",
        ["Anything else?"] = "¿Algo más?",
        ["Where can I get Scrapey Tree Bark?"] = "¿Dónde puedo conseguir la corteza de árbol Scrapey?",
        ["Where can I get Scrapey tree bark...and why do I get the feeling I won't like the answer?"] = "¿Dónde puedo conseguir corteza de árbol Scrapey... y por qué tengo la sensación de que no me gustará la respuesta?",
        ["Inside this walled area there are a few Scrapey trees. They are the big, ill looking ones, you can't miss them."] = "Dentro de esta zona amurallada hay algunos árboles Scrapey. Son los grandes y feos, no te los puedes perder.",
        ["Basically, you cut them down and then carve the bark off with a knife."] = "Básicamente, los cortas y luego les cortas la corteza con un cuchillo.",
        ["It's pretty simple, except the sap tends so make people feel kind of ill if they get any on themselves."] = "Es bastante simple, excepto que la savia tiende a hacer que las personas se sientan un poco enfermas si se manchan.",
        ["How ill?"] = "¿Qué tan enfermo?",
        ["Don't worry, we aren't talking deadly ill or anything."] = "No te preocupes, no estamos hablando de una enfermedad mortal ni nada por el estilo.",
        ["It's more like you'll feel quite dizzy and weak for a bit."] = "Es más como si te sintieras bastante mareado y débil por un tiempo.",
        ["Joy..."] = "Alegría...",
        ["Where can I get Sweetgrubs?"] = "¿Dónde puedo conseguir larvas dulces?",
        ["Sweetgrubs? What are they?"] = "¿Larvas dulces? ¿Cuáles son?",
        ["Well, lacking any sluglings in the area, we add these little grubs called Sweetgrubs. If you ignore the gag-inducing aftertaste, they are quite sweet."] = "Bueno, a falta de babosas en el área, agregamos estas pequeñas larvas llamadas Sweetgrubs. Si ignoras el regusto que provoca náuseas, son bastante dulces.",
        ["How... how can you drink the stuff?"] = "¿Cómo... cómo puedes beber esa cosa?",
        ["Quite easily!"] = "¡Muy fácil!",
        ["Pirates are renowned as being tough for a reason."] = "Los piratas tienen fama de ser duros por una razón.",
        ["So where do I get these grubs from anyway?"] = "Entonces, ¿de dónde obtengo estas larvas?",
        ["Well, there are a few sweetgrub mounds inside there. We have a handful of rat meat that you can use on the mounds to draw the grubs to the surface."] = "Bueno, hay algunos montículos de larvas dulces ahí dentro. Tenemos un puñado de carne de rata que puedes usar en los montículos para atraer las larvas a la superficie.",
        ["Mind your fingers though, they are voracious little things."] = "Pero ten cuidado con los dedos, son cositas voraces.",
        ["And here was me thinking that nothing could be more disgusting than Braindeath 'Rum'."] = "Y aquí estaba yo pensando que nada podría ser más repugnante que Braindeath 'Rum'.",
        ["Arr, that's where ye'd be wrong lad, 'cos new, improved Braindeath 'Rum' Classic is now 200% more disgustin' then any leadin' competitor!"] = "Arr, ahí es donde te equivocarías muchacho, porque el nuevo y mejorado Braindeath 'Rum' Classic es ahora un 200% más repugnante que cualquier competidor líder.",
        ["Legal disclaimer; the dangerous amount of disgustin' in new Braindeath 'Rum' Classic be too much for pregnant women, donkeys and anyone with more than seven letters in their last name."] = "Aviso legal; La peligrosa cantidad de asco del nuevo Braindeath 'Rum' Classic es demasiado para las mujeres embarazadas, los burros y cualquier persona con más de siete letras en su apellido.",
        ["What was that?"] = "¿Qué fue eso?",
        ["What was what?"] = "¿Qué fue qué?",
        ["Is there anything else?"] = "¿Hay algo más?",
        ["Where can I get buckets of water?"] = "¿Dónde puedo conseguir baldes de agua?",
        ["How do I get..."] = "¿Cómo consigo...?",
        ["Wait, no, that question makes me sound like I haven't a clue what I'm doing."] = "Espera, no, esa pregunta me hace parecer como si no tuviera ni idea de lo que estoy haciendo.",
        ["Where can I get buckets in there?"] = "¿Dónde puedo conseguir cubos allí?",
        ["There are a few lying about. Help yourself."] = "Hay algunos por ahí. Ayudar a sí mismo.",
        ["There is a pump in the still, so long as it's working you should have almost unlimited water."] = "Hay una bomba en el alambique, mientras esté funcionando deberías tener agua casi ilimitada.",
        ["Hold on, do I have to add anything disgusting and/or potential lethal to the water before I pour it in?"] = "Espera, ¿tengo que agregar algo repugnante y/o potencialmente letal al agua antes de verterla?",
        ["Perish the thought!"] = "¡Maldito pensamiento!",
        ["Ok, just checking."] = "Ok, solo estoy comprobando.",
        ["Where can I get coloured water?"] = "¿Dónde puedo conseguir agua coloreada?",
        ["What sort of coloured water are we talking about here?"] = "¿De qué tipo de agua coloreada estamos hablando aquí?",
        ["Well, the other still has an area of waste ground with a flower growing on it. If you go and grab one of the flowers and jam it in the kettle, the water will boil out the colour."] = "Bueno, el otro todavía tiene un terreno baldío con una flor creciendo en él. Si vas y agarras una de las flores y la metes en la tetera, el agua perderá el color.",
        ["We use the colour to keep our rum easily identifiable."] = "Usamos el color para que nuestro ron sea fácilmente identificable.",
        ["So I just empty the kettle into the hopper, right?"] = "Así que simplemente vacío el hervidor en la tolva, ¿verdad?",
        ["No, no, you'll need to take an empty bowl and fill it from the kettle."] = "No, no, tendrás que coger un recipiente vacío y llenarlo con la tetera.",
        ["That way you can use the stuff on a monkey if you need to."] = "De esa manera puedes usar las cosas en un mono si es necesario.",
        ["Use it on a monkey...of course."] = "Úselo en un mono... por supuesto.",
        ["Repairing the Still"] = "Reparando el alambique",
        ["How do I repair the still?"] = "¿Cómo reparo el alambique?",
        ["Well, assuming those scurvy dogs have managed to set any of it on fire, then you will need to tip a bucket of water on it before you can repair it."] = "Bueno, suponiendo que esos perros con escorbuto hayan logrado prenderle fuego a algo, entonces tendrás que echarle un balde de agua antes de poder repararlo.",
        ["Then, it all comes down to what part of it was damaged."] = "Luego, todo se reduce a qué parte resultó dañada.",
        ["How do I repair Hoppers?"] = "¿Cómo reparo las tolvas?",
        ["How can I repair hoppers?"] = "¿Cómo puedo reparar las tolvas?",
        ["Well, assuming that they are not on fire, all you need to do is use the heavy lumber patches. They are big enough to cover most holes."] = "Bueno, suponiendo que no estén en llamas, todo lo que necesitas hacer es usar los parches de madera pesados. Son lo suficientemente grandes como para cubrir la mayoría de los agujeros.",
        ["Will I need a hammer?"] = "¿Necesitaré un martillo?",
        ["No, just shove it into place and whack it until it lines up."] = "No, simplemente empújalo en su lugar y golpéalo hasta que quede alineado.",
        ["How do I repair Pipes and the pump?"] = "¿Cómo reparo las tuberías y la bomba?",
        ["How do I repair pipes and the pump?"] = "¿Cómo reparo las tuberías y la bomba?",
        ["Well, if you use a pipe section on the damaged part you should be able to replace it easily."] = "Bueno, si usas una sección de tubería en la parte dañada deberías poder reemplazarla fácilmente.",
        ["No, likely you'll just need to whack the old one out and slot the new one in with your hands."] = "No, probablemente solo tendrás que sacar el viejo y colocar el nuevo con las manos.",
        ["How do I repair Bridges?"] = "¿Cómo reparo puentes?",
        ["How do I repair bridges?"] = "¿Cómo reparo puentes?",
        ["Well, we have these handy bridge sections you can use to repair the bridges."] = "Bueno, tenemos estas prácticas secciones de puentes que puedes usar para reparar los puentes.",
        ["The main problem is, while a still will keep working if a bit of it is only damaged, the bridges are completely out of commission if they are even slightly damaged."] = "El problema principal es que, mientras que un alambique seguirá funcionando si solo se daña una parte, los puentes quedan completamente fuera de servicio si se dañan aunque sea ligeramente.",
        ["Is that going to be a problem? I mean, I can jump across I think."] = "¿Eso va a ser un problema? Quiero decir, creo que puedo saltar.",
        ["Don't try that! Our lawyers tell us we aren't covered for injuries sustained while jumping over burned bridges."] = "¡No intentes eso! Nuestros abogados nos dicen que no estamos cubiertos por las lesiones sufridas al saltar sobre puentes quemados.",
        ["Seriously, just keep off the bridges until they are fixed."] = "En serio, mantente alejado de los puentes hasta que estén reparados.",
        ["How do I get repair items?"] = "¿Cómo obtengo artículos de reparación?",
        ["Where do I get all this stuff anyway?"] = "¿De dónde consigo todas estas cosas?",
        ["We have a load of items already on a table inside the still. You can also make new ones if you grab some logs."] = "Ya tenemos un montón de artículos en una mesa dentro del alambique. También puedes crear otros nuevos si compras logs.",
        ["How does that work?"] = "¿Cómo funciona eso?",
        ["We have a worktable set up in the still. If you use the logs in it can craft up a handy replacement for part of the still."] = "Tenemos una mesa de trabajo instalada en el alambique. Si usa el logs, puede crear un reemplazo útil para parte del alambique.",
        ["Don't worry about them fitting, the things are held together by nails, replacement parts and soot by now."] = "No te preocupes por que encajen, las cosas se mantienen juntas gracias a nails, las piezas de repuesto y el hollín.",
        ["Well...how sanitary..."] = "Bueno... qué sanitario...",
        ["Ok, I think I've heard enough"] = "Ok, creo que ya he escuchado suficiente.",
        ["Ok, I think I've heard enough."] = "Ok, creo que ya he escuchado suficiente.",
        ["Fine. Glad I could help."] = "Bien. Me alegra poder ayudar.",
        ["Sabotaging San's Still"] = "Saboteando el alambique de San",
        ["So...how would I go about sabotaging the enemy still?"] = "Entonces... ¿cómo haría para seguir saboteando al enemigo?",
        ["Ok, here's what you need to do."] = "Ok, esto es lo que debes hacer.",
        ["The wood around here is really dry and flammable, so take one of the torches, light it up, and then go and attack the enemy still with it."] = "La madera que hay por aquí está muy seca e inflamable, así que toma una de las antorchas, enciéndela y luego ataca al enemigo que todavía la tiene.",
        ["That's it?"] = "¿Eso es todo?",
        ["Most of their still is soaked in 'alcohol' and made from tinder dry wood."] = "La mayor parte de su alambique está empapado en 'alcohol' y hecho de yesca de madera seca.",
        ["Essentially, if it isn't ours, try using a torch on it and see what happens."] = "Básicamente, si no es nuestro, intente usar una antorcha y vea qué sucede.",
        ["Ok, I get you."] = "Ok, te entiendo.",
        ["What will you pay me?"] = "¿Qué me pagarás?",
        ["So what will you give me for helping out?"] = "Entonces, ¿qué me darás por ayudar?",
        ["Hahahaha! What a mercenary attitude! You'll do fine here."] = "¡Jajajaja! ¡Qué actitud tan mercenaria! Te irá bien aquí.",
        ["Well, for each bottle that your team produces, I'll give you one piece of eight."] = "Bueno, por cada botella que produzca tu equipo, te daré una pieza de ocho.",
        ["If you managed to set something on fire then I'll toss in another, same for repairing the still."] = "Si lograste prender fuego a algo, arrojaré otro, lo mismo para reparar el alambique.",
        ["What can I use these pieces of eight for?"] = "¿Para qué puedo utilizar estos ocho?",
        ["See Honest Jimmy there? He will trade you some pretty nice stuff for them."] = "¿Ves Honest Jimmy allí? Te cambiará algunas cosas muy bonitas por ellas.",
        ["Great!"] = "¡Genial!",
        ["Category:NPC dialogue"] = "Categoría: Diálogo NPC",
    },
    ["Fancy-dress shop owner"] = {
        ["Now you look like someone who goes to a lot of fancy dress parties."] = "Ahora pareces alguien que va a muchas fiestas de disfraces.",
        ["Errr...what are you saying exactly?"] = "Errr... ¿qué estás diciendo exactamente?",
        ["I'm just saying that perhaps you would like to peruse my selection of garments."] = "Sólo digo que quizás te gustaría examinar mi selección de prendas.",
        ["Or, if that doesn't interest you, then maybe you have something else to offer? I'm always on the lookout for interesting or unusual new materials."] = "O, si eso no te interesa, ¿quizás tengas algo más que ofrecer? Siempre estoy buscando materiales nuevos, interesantes o inusuales.",
        ["Select an option"] = "Selecciona una opción",
        ["Okay, let's see what you've got, then."] = "Bien, entonces veamos qué tienes.",
        ["*(After Eagles' Peak:)* Could you make another bird costume for me?"] = "*(Después de Eagles' Peak:)* ¿Podrías hacerme otro disfraz de pájaro?",
        ["Could you make another eagle costume for me?"] = "¿Podrías hacerme otro disfraz de águila?",
        ["Certainly, if you can supply the materials. I'll need appropriate feathers, swamp tar and some yellow dye. It'll also cost you 25 gold pieces."] = "Por supuesto, si puedes proporcionar los materiales. Necesitaré plumas apropiadas, alquitrán de pantano y algo de yellow dye. También te costará 25 piezas de oro.",
        ["I'll see what I can do."] = "Veré qué puedo hacer.",
        ["Okay, here are the materials. Eagle me up."] = "Bien, aquí están los materiales. Águilame.",
        ["I'm afraid I don't have that much money with me."] = "Me temo que no tengo tanto dinero conmigo.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["There we go, one eagle costume. You should be the envy of the entire party wearing that."] = "Ahí vamos, un disfraz de águila. Deberías ser la envidia de todo el grupo usando eso.",
        ["Thanks."] = "Gracias.",
        ["On second thoughts, that's too expensive."] = "Pensándolo bien, eso es demasiado caro.",
        ["Well, feel free to come back if you change your mind."] = "Bueno, no dudes en volver si cambias de opinión.",
        ["I think I might just leave the perusing for now thanks."] = "Creo que podría dejar la lectura por ahora, gracias.",
        ["I think I might just leave the perusing for now, thanks."] = "Creo que podría dejar la lectura por ahora, gracias.",
        ["*(If you do not have suitable fur in your inventory:)* Can you make clothing suitable for hunting in?"] = "*(Si no tienes pieles adecuadas en tu inventario:)* ¿Puedes hacer ropa adecuada para cazar?",
        ["Can you make clothing suitable for hunting?"] = "¿Puedes hacer ropa adecuada para cazar?",
        ["Certainly. Take a look at my range of made-to-order items. If you can supply the furs, I'll gladly make any of these for you."] = "Por supuesto. Echa un vistazo a mi gama de artículos hechos a medida. Si puedes proporcionarme las pieles, con mucho gusto te haré cualquiera de estas.",
        ["*(If you have fur in your inventory:)* Could you make anything out of this fur that I got from hunting?"] = "*(Si tienes pelaje en tu inventario:)* ¿Podrías hacer algo con este pelaje que obtuve cazando?",
        ["Could you make anything out of this fur that I got from hunting?"] = "¿Podrías hacer algo con este pelaje que obtuve cazando?",
        ["What sort of unusual materials did you have in mind?"] = "¿Qué tipo de materiales inusuales tenías en mente?",
        ["Well, some more colourful feathers might be useful. For some surreal reason, all I normally seem to get offered are large quantities of rather beaten-up looking chicken feathers."] = "Bueno, algunas plumas más coloridas podrían ser útiles. Por alguna razón surrealista, lo único que normalmente me ofrecen son grandes cantidades de plumas de pollo de aspecto bastante desgastado.",
        ["People must have some very strange pastimes around these parts, that's all I can say."] = "La gente debe tener pasatiempos muy extraños por estos lares, eso es todo lo que puedo decir.",
        ["Ok, let's see what you've got then."] = "Ok, veamos qué tienes entonces.",
    },
    ["Fandon"] = {
        ["Are you a surface-dweller?"] = "¿Eres un habitante de la superficie?",
        ["Yes..."] = "Sí...",
        ["Haha! You look funny! All tall and skinny with tiny eyes!"] = "¡Jaja! ¡Te ves gracioso! ¡Todo alto y delgado con ojos diminutos!",
        ["Are you Player? Did you help Zanik save the city?"] = "¿Eres Player? ¿Ayudaste a Zanik a salvar la ciudad?",
        ["Yes, that was me!"] = "¡Sí, ese era yo!",
        ["When I'm older I'm going to be an adventurer, just like Zanik!"] = "Cuando sea mayor seré un aventurero, ¡como Zanik!",
        ["Sorry, I'm not meant to talk to strangers."] = "Lo siento, no debo hablar con extraños.",
        ["Shh! Don't tell anyone!"] = "¡Shh! ¡No se lo digas a nadie!",
        ["Don't tell anyone what?"] = "¿No decirle a nadie qué?",
        ["SHHH!"] = "¡SHHH!",
        ["Help! Help! The surface people are attacking!"] = "¡Ayuda! ¡Ayuda! ¡La gente de la superficie está atacando!",
        ["It's alright, I'm friendly!"] = "¡Está bien, soy amigable!",
    },
    ["Fanellaman"] = {
        ["Hello there...thanks for helping out Trufitus commune with the gods Bwana. We've been able to return to the village thanks to your help."] = "Hola... gracias por ayudar a Trufitus a comunicarse con los dioses Bwana. Hemos podido regresar al pueblo gracias a vuestra ayuda.",
        ["Select an Option"] = "Selecciona una opción",
        ["What do you do here?"] = "¿Qué haces aquí?",
        ["Ha, well I'm retired now, but in my heyday I was quite the expert fisherman! These days I just help out around the village where I can, my old bones don't allow me to do any more than that."] = "Ja, bueno, ahora estoy retirado, ¡pero en mi apogeo era un pescador bastante experto! Actualmente sólo ayudo en el pueblo donde puedo, mis viejos huesos no me permiten hacer más que eso.",
        ["Is there anything interesting to do here?"] = "¿Hay algo interesante que hacer aquí?",
        ["Bwana, if anyone else asks me that question today, I'll explode! Go and ask Murcaily!"] = "Bwana, si alguien más me hace esa pregunta hoy, ¡explotaré! ¡Ve y pregúntale a Murcaily!",
        ["I'm just enjoying the sunshine, Bwana. Try asking Murcaily."] = "Solo estoy disfrutando del sol, Bwana. Intente preguntarle a Murcaily.",
        ["Well, I think that there's some work to be done...perhaps Murcaily can help you. He usually tends to the hardwood grove to the east of Trufitus' hut."] = "Bueno, creo que hay trabajo por hacer... tal vez Murcaily pueda ayudarte. Por lo general, atiende el bosquecillo de madera al este de la cabaña de Trufitus.",
        ["Sorry Bwana, I'm already busy, why not go and talk to Murcaily! He's around the village somewhere."] = "Lo siento Bwana, ya estoy ocupado, ¿por qué no vas y hablas con Murcaily? Está en alguna parte del pueblo.",
        ["I've been doing some work around the village."] = "He estado trabajando en el pueblo.",
        ["Hey, I've seen you working around the village. You've been doing a lot of good work around here for us. Let me give you something for your trouble."] = "Oye, te he visto trabajando en el pueblo. Has estado haciendo un muy buen trabajo aquí para nosotros. Déjame darte algo por tu molestia.",
        ["I've already given you some trading sticks and I don't have any more on me at the moment. Why not go and talk to some of the other villagers and get some contributions?"] = "Ya te he dado algunos palitos de intercambio y no tengo ninguno más en este momento. ¿Por qué no vas y hablas con algunos de los otros aldeanos y consigues algunas contribuciones?",
        ["Ok, thanks."] = "Vale, gracias.",
        ["Ahhhhhhhh - Get away from me you beast!"] = "Ahhhhhhhh - ¡Aléjate de mí, bestia!",
        ["Ahhhhhhhh!"] = "¡Ahhhhhhhh!",
        ["Ahhhhhhhh - It's a monster!"] = "Ahhhhhhhh - ¡Es un monstruo!",
        ["Waahhhhh! - It's da evil broodoo beast come ta eat my very soul!"] = "¡Waahhhhh! - ¡Es una bestia malvada que viene a comerse mi alma!",
        ["What's the problem... oh, I'm wearing this big scary mask! I'd better take it off before I start talking to the natives."] = "¿Cuál es el problema? ¡Oh, estoy usando esta gran máscara aterradora! Será mejor que me lo quite antes de empezar a hablar con los nativos.",
    },
    ["Farhad"] = {
        ["Is it chilly out here, or is it just me?"] = "¿Hace frío aquí afuera o soy solo yo?",
        ["Maybe put on a shirt."] = "Tal vez ponerte una camisa.",
    },
    ["Farid Morrisane (ores)"] = {
        ["Hello."] = "Hola.",
        ["**Farid Morrisane (ores):** Hmmm, a new trader. I suggest you speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance for a lesson. Brugsen will give an interesting and complete lesson and the Tutor will give a smaller, plain lesson."] = "**Farid Morrisane (ores):** Hmmm, un nuevo comerciante. Te sugiero que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada para recibir una lección. Brugsen dará una lección interesante y completa y el Tutor dará una lección más breve y sencilla.",
        ["Hello, little boy."] = "Hola, pequeño.",
        ["I would appreciate it if you didn't talk to me in such a manner. I'll have you know I'm an accomplished merchant."] = "Le agradecería que no me hablara de esa manera. Le haré saber que soy un comerciante consumado.",
        ["Select an Option"] = "Selecciona una opción",
        ["Calm down, junior."] = "Cálmate, joven.",
        ["Don't tell me to calm down! And don't call me 'junior'."] = "¡No me digas que me calme! Y no me llames 'junior'.",
        ["I'll have you know I am Farid Morrisane, son of Ali Morrisane, the world's greatest merchant!"] = "Para que sepas, soy Farid Morrisane, hijo de Ali Morrisane, ¡el comerciante más grande del mundo!",
        ["Then why are you here and not him?"] = "Entonces, ¿por qué estás tú aquí y no él?",
        ["My dad has given me the responsibility of expanding our business here."] = "Mi papá me ha dado la responsabilidad de expandir nuestro negocio aquí.",
        ["And you're up to the task?"] = "¿Y estás a la altura?",
        ["What a grown up boy you are! Mummy and daddy must be very pleased!"] = "¡Qué niño tan adulto eres! ¡Mamá y papá deben estar muy contentos!",
        ["Look mate - I may be young, I may be short, but I'm a respected merchant around here and don't have time to deal with simpletons like you."] = "Mire amigo, puede que sea joven, puede que sea bajo, pero soy un comerciante respetado por aquí y no tengo tiempo para tratar con tontos como usted.",
        ["Can you help me out with the prices for ores?"] = "¿Puedes ayudarme con los precios de los minerales?",
        ["That's easy. Been doing that since I was three."] = "Eso es fácil. He estado haciendo esto desde que tenía tres años.",
        ["I best go and speak with someone more my height."] = "Será mejor que vaya y hable con alguien de mi altura.",
        ["Then I shall not stop you, mister. I've got too much work to do."] = "Entonces no lo detendré, señor. Tengo demasiado trabajo que hacer.",
    },
    ["Farid Morrisane"] = {
        ["Hello."] = "Hola.",
        ["**Farid Morrisane (ores):** Hmmm, a new trader. I suggest you speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance for a lesson. Brugsen will give an interesting and complete lesson and the Tutor will give a smaller, plain lesson."] = "**Farid Morrisane (ores):** Hmmm, un nuevo comerciante. Te sugiero que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada para recibir una lección. Brugsen dará una lección interesante y completa y el Tutor dará una lección más breve y sencilla.",
        ["Hello, little boy."] = "Hola, pequeño.",
        ["I would appreciate it if you didn't talk to me in such a manner. I'll have you know I'm an accomplished merchant."] = "Le agradecería que no me hablara de esa manera. Le haré saber que soy un comerciante consumado.",
        ["Select an Option"] = "Selecciona una opción",
        ["Calm down, junior."] = "Cálmate, joven.",
        ["Don't tell me to calm down! And don't call me 'junior'."] = "¡No me digas que me calme! Y no me llames 'junior'.",
        ["I'll have you know I am Farid Morrisane, son of Ali Morrisane, the world's greatest merchant!"] = "Para que sepas, soy Farid Morrisane, hijo de Ali Morrisane, ¡el comerciante más grande del mundo!",
        ["Then why are you here and not him?"] = "Entonces, ¿por qué estás tú aquí y no él?",
        ["My dad has given me the responsibility of expanding our business here."] = "Mi papá me ha dado la responsabilidad de expandir nuestro negocio aquí.",
        ["And you're up to the task?"] = "¿Y estás a la altura?",
        ["What a grown up boy you are! Mummy and daddy must be very pleased!"] = "¡Qué niño tan adulto eres! ¡Mamá y papá deben estar muy contentos!",
        ["Look mate - I may be young, I may be short, but I'm a respected merchant around here and don't have time to deal with simpletons like you."] = "Mire amigo, puede que sea joven, puede que sea bajo, pero soy un comerciante respetado por aquí y no tengo tiempo para tratar con tontos como usted.",
        ["Can you help me out with the prices for ores?"] = "¿Puedes ayudarme con los precios de los minerales?",
        ["That's easy. Been doing that since I was three."] = "Eso es fácil. He estado haciendo esto desde que tenía tres años.",
        ["I best go and speak with someone more my height."] = "Será mejor que vaya y hable con alguien de mi altura.",
        ["Then I shall not stop you, mister. I've got too much work to do."] = "Entonces no lo detendré, señor. Tengo demasiado trabajo que hacer.",
    },
    ["Farkle"] = {
        ["Me Farkle! Me mighty ogre champion. Me win tournament easy, prove ogres are strongest."] = "¡Yo Farkle! Mi poderoso campeón ogro. Yo gano el torneo fácilmente, demuestro que los ogros son más fuertes.",
        ["Haha 'Farkle'."] = "Jaja 'Farkle'.",
        ["Me do impression of you - listen!"] = "Yo hago una impresión de ti, ¡escucha!",
        ["Blah blah blah me stupid human! Please no hurt me!"] = "¡Bla, bla, bla, estúpido humano! ¡Por favor no me hagas daño!",
        ["You like that human?"] = "¿Te gusta ese humano?",
        ["You'll be doing impressions of yourself losing if we meet in the arena!"] = "¡Harás imitaciones de ti mismo perdiendo si nos encontramos en la arena!",
        ["Haw! No way, human!"] = "¡Ja! ¡De ninguna manera, humano!",
    },
    ["Farli"] = {
        ["Hello there!"] = "¡Hola!",
        ["Hi."] = "Hola.",
        ["What brings you down here then?"] = "¿Qué te trae por aquí entonces?",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["It's a cavern."] = "Es una caverna.",
        ["Really? Great, thanks for that."] = "¿En serio? Genial, gracias por eso.",
        ["No problem!"] = "¡No hay problema!",
        ["So, is there actually anything in this cavern?"] = "Entonces, ¿hay realmente algo en esta caverna?",
        ["Well, there's rocks. A bit of water here and there too."] = "Bueno, hay piedras. Un poco de agua aquí y allá también.",
        ["Right. Good to know. I'm glad you were here, actually, because, you know, I'd have been lost without that."] = "Correcto. Es bueno saberlo. De hecho, me alegro de que estuvieras aquí, porque, ya sabes, me habría perdido sin eso.",
        ["Happy to help!"] = "¡Feliz de poder ayudar!",
        ["*(Shows previous options)*"] = "*(Muestra opciones anteriores)*",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm Farli. I came down here to explore the moment the cavern entrance opened up."] = "Soy Farli. Bajé aquí para explorar el momento en que se abrió la entrada de la caverna.",
        ["Have you discovered anything down there?"] = "¿Has descubierto algo ahí abajo?",
        ["Well, I did stumble across some nice-looking deposits of ore and some strange fish in the waters, but I haven't really been able to investigate further."] = "Bueno, me topé con algunos depósitos de mineral bonitos y algunos peces extraños en las aguas, pero realmente no he podido investigar más.",
        ["Why not?"] = "¿Por qué no?",
        ["It's as if the rocks are moving... Whenever I've tried to map this place, I find rocks are in different places to when I checked before!"] = "Es como si las rocas se estuvieran moviendo... ¡Cada vez que intento mapear este lugar, encuentro que las rocas están en lugares diferentes a los que había visto antes!",
        ["Moving rocks? Are you sure you haven't been drinking?"] = "¿Rocas en movimiento? ¿Estás seguro de que no has estado bebiendo?",
        ["Well, yes. I mean no. Look, that's not important. What is important is that the rocks down here are moving!"] = "Bueno, sí. Quiero decir que no. Mira, eso no es importante. ¡Lo importante es que las rocas aquí abajo se están moviendo!",
        ["I'll be sure to check that out..."] = "Me aseguraré de comprobarlo...",
        ["It's true! One time I was mining a rock, or what I thought was a rock, and it upped and ran off with my best pickaxe!"] = "¡Es verdad! Una vez estaba extrayendo una roca, o lo que pensé que era una roca, ¡se levantó y salió corriendo con mi mejor pico!",
        ["What does this pulley do?"] = "¿Qué hace esta polea?",
        ["Oh, that's just to get my supplies in and out of the cavern."] = "Oh, eso es sólo para que mis suministros entren y salgan de la caverna.",
        ["How does that work then?"] = "¿Cómo funciona eso entonces?",
        ["The miners above use the mine cart system to move about what we need from Keldagrim."] = "Los mineros de arriba usan el sistema de carro de mina para mover lo que necesitamos de Keldagrim.",
        ["Hmm, that could be handy for depositing things into my bank. You think you could arrange that?"] = "Hmm, eso podría ser útil para depositar cosas en mi banco. ¿Crees que podrías arreglar eso?",
        ["Hmm, maybe. I suppose if you're down here to help then I can sort something out."] = "Hmm, tal vez. Supongo que si estás aquí para ayudar, entonces puedo arreglar algo.",
        ["Thanks!"] = "¡Gracias!",
        ["Actually, I don't want to talk to you."] = "En realidad, no quiero hablar contigo.",
        ["Hmph! How rude!"] = "¡Hmph! ¡Qué grosero!",
    },
    ["Farmer (Draynor Village)"] = {
        ["What're you doing here? I'm tired of you soldiers stelaing my wheat!"] = "¿Qué haces aquí? ¡Estoy cansado de que ustedes, soldados, me roben el trigo!",
        ["I'm not a soldier!"] = "¡No soy un soldado!",
        ["In which case get off my land! I've got enough to deal with at the moment!"] = "¡En cuyo caso sal de mi tierra! ¡Ya tengo suficiente con qué lidiar en este momento!",
        ["Give me all your wheat!"] = "¡Dame todo tu trigo!",
        ["Fine, take the wheat. Just leave some for me and my children, for Saradomin's sake!"] = "Bien, toma el trigo. ¡Déjanos un poco para mí y mis hijos, por el bien de Saradomin!",
    },
    ["Farmer"] = {
        ["What're you doing here? I'm tired of you soldiers stelaing my wheat!"] = "¿Qué haces aquí? ¡Estoy cansado de que ustedes, soldados, me roben el trigo!",
        ["I'm not a soldier!"] = "¡No soy un soldado!",
        ["In which case get off my land! I've got enough to deal with at the moment!"] = "¡En cuyo caso sal de mi tierra! ¡Ya tengo suficiente con qué lidiar en este momento!",
        ["Give me all your wheat!"] = "¡Dame todo tu trigo!",
        ["Fine, take the wheat. Just leave some for me and my children, for Saradomin's sake!"] = "Bien, toma el trigo. ¡Déjanos un poco para mí y mis hijos, por el bien de Saradomin!",
        ["What are you selling? Compost? Fertiliser? I've tried it all."] = "¿Qué estás vendiendo? ¿Compost? ¿Fertilizante? Lo he probado todo.",
        ["Not even that smug scoundrel David could grow anything on this land. Not with how hard all of our harvests have been hit lately."] = "Ni siquiera ese sinvergüenza engreído David podría cultivar algo en esta tierra. No con lo duro que se han visto afectadas todas nuestras cosechas últimamente.",
        ["You need to be a level 10 thief to steal from this target."] = "Debes ser un ladrón de nivel 10 para robarle a este objetivo.",
        ["You pick the target's pocket."] = "Escoges el bolsillo del objetivo.",
        ["You steal [number] [name] seeds."] = "Robas semillas [número] [name].",
        ["[number] coins have been added to your money pouch."] = "[número] coins se han agregado a su bolsa de dinero.",
        ["You fail to steal from the target."] = "No logras robarle al objetivo.",
        ["You've been stunned."] = "Has quedado atónito.",
        ["You cannot keep pickpocketing as you have a full inventory."] = "No puedes seguir robando carteras porque tienes un inventario completo.",
    },
    ["Farmer (Marigold Farm)"] = {
        ["What are you selling? Compost? Fertiliser? I've tried it all."] = "¿Qué estás vendiendo? ¿Compost? ¿Fertilizante? Lo he probado todo.",
        ["Not even that smug scoundrel David could grow anything on this land. Not with how hard all of our harvests have been hit lately."] = "Ni siquiera ese sinvergüenza engreído David podría cultivar algo en esta tierra. No con lo duro que se han visto afectadas todas nuestras cosechas últimamente.",
        ["You need to be a level 10 thief to steal from this target."] = "Debes ser un ladrón de nivel 10 para robarle a este objetivo.",
