        ["The little gnome is too busy to talk."] = "El pequeño gnomo está demasiado ocupado para hablar.",
        ["Well done!"] = "¡Bien hecho!",
        ["Femi has given you another clue scroll!"] = "¡Femi te ha dado otro pergamino de pistas!",
        ["You've found a casket!"] = "¡Has encontrado un ataúd!",
