        ["What are you doing down here?"] = "¿Qué estás haciendo aquí abajo?",
        ["Shoring up the walls."] = "Apuntalando las paredes.",
        ["What does that do?"] = "¿Qué hace eso?",
        ["Stops them falling down."] = "Evita que se caigan.",
