    ["Fetcher"] = {
        ["It is dangerous to go beyond this point human. Let me help you prepare yourself."] = "Es peligroso ir más allá de este punto humano. Déjame ayudarte a prepararte.",
        ["Choose an option:"] = "Elige una opción:",
        ["Can you fetch any loot I might've missed?"] = "¿Puedes traer algún botín que me haya perdido?",
        ["I'm sorry human, I couldn't find anything for you."] = "Lo siento humano, no pude encontrar nada para ti.",
        ["I've found something for you!"] = "¡He encontrado algo para ti!",
        ["It looks like you didn't finish sorting through the last items I found you. Take a look."] = "Parece que no terminaste de clasificar los últimos elementos que te encontré. Échale un vistazo.",
        ["What should I fetch?"] = "¿Qué debo buscar?",
        ["Collect Beastmaster Durzag loot."] = "Recoge el botín de Beastmaster Durzag.",
        ["If you log out, items in the reward chest will be moved to your inventory or bank. If both of those places are full you will lose the items."] = "Si cierras sesión, los artículos del cofre de recompensas se moverán a tu inventario o banco. Si ambos lugares están llenos, perderás los artículos.",
        ["Collect Yakamaru loot."] = "Recoge el botín de Yakamaru.",
        ["I'll come back later."] = "Volveré más tarde.",
        ["I'm sorry human, I couldn't find Lil' Tuzzy anywhere."] = "Lo siento humano, no pude encontrar a Lil' Tuzzy por ningún lado.",
        ["Hey, I found something for you."] = "Oye, encontré algo para ti.",
        ["I'll see if I can find some loot for you!"] = "¡Veré si puedo encontrar algo de botín para ti!",
        ["Nope. I couldn't find anything."] = "No. No pude encontrar nada.",
        ["Show me my current raid lock."] = "Muéstrame mi bloqueo de incursión actual.",
        ["Can you automatically reset my raid lockout?"] = "¿Pueden restablecer automáticamente mi bloqueo de incursión?",
        ["That should be possible human."] = "Eso debería ser posible humano.",
        ["Automatically reset your raids lockout?"] = "¿Restablecer automáticamente el bloqueo de tus incursiones?",
        ["Yes"] = "si",
        ["It seems I'm already doing it for you human. Do you want me to stop?"] = "Parece que ya lo estoy haciendo por ti humano. ¿Quieres que me detenga?",
        ["Stop automatically"] = "Detener automáticamente",
        ["Would you pay any Teci for these burial charms?"] = "¿Pagarías a cualquier Teci por estos amuletos funerarios?",
        ["**Fetcher:** If you have no use for your charms, I'd be willing to exchange them for a small amount of Teci. Are you interested?"] = "**Fetcher:** Si no necesitas tus amuletos, estaría dispuesto a cambiarlos por una pequeña cantidad de Teci. ¿Estás interesado?",
        ["Exchange [#] charm[s] for [#] Teci?"] = "¿Intercambiar [#] charm[s] por [#] Teci?",
        ["Yes."] = "Sí.",
        ["Very well, human."] = "Muy bien, humano.",
        ["Goodbye."] = "Adiós.",
        ["I can't do anything with that human. Maybe if you were a little bit more well known, I could make an exchange."] = "No puedo hacer nada con ese humano. Quizás si fueras un poco más conocido podría hacer un intercambio.",
        ["RESET"] = "REINICIAR",
        ["You can only reset the Mazcab raid once every 48 hours. Ensure you wish to reset your progress before you continue!"] = "Solo puedes restablecer la incursión de Mazcab una vez cada 48 horas. ¡Asegúrate de que deseas restablecer tu progreso antes de continuar!",
        ["CANCEL"] = "CANCELAR",
        ["CONFIRM"] = "CONFIRMAR",
        ["Your raid progress has been reset."] = "El progreso de tu incursión se ha reiniciado.",
        ["Boss progress can only be reset once every 48 hours."] = "El progreso del jefe solo se puede restablecer una vez cada 48 horas.",
    },
    ["Fiara"] = {
        ["As you approach the...big creature thing, it lets out a hiss that sounds partly like a threat and partly like a sigh."] = "A medida que te acercas a la... gran criatura, deja escapar un silbido que suena en parte como una amenaza y en parte como un suspiro.",
        ["Hmm. What was that about?"] = "Mmm. ¿Qué fue eso?",
        ["*Hiss* Another human. Why do you all keep coming down here?"] = "*Hiss* Otro humano. ¿Por qué seguís viniendo aquí?",
        ["Erm, excuse me...Lady Fiara, but the druids told me to talk to you."] = "Erm, discúlpeme... Lady Fiara, pero los druidas me dijeron que hablara con usted.",
        ["*Hiss* Yes...the druids. They say and do far more than they should."] = "*Hiss* Sí... los druidas. Dicen y hacen mucho más de lo que deberían.",
        ["What's wrong with the druids? They seem to worship you."] = "¿Qué les pasa a los druidas? Parecen adorarte.",
        ["They worship everything that is green or sounds even slightly magical. Not just worship - they stalk. And when they have arrived, it is impossible to get them away. They are like insects."] = "Adoran todo lo que es verde o suena incluso ligeramente mágico. No sólo adoran: acechan. Y cuando han llegado, es imposible sacarlos. Son como insectos.",
        ["You want to get rid of them, eh? I might be able to-"] = "Quieres deshacerte de ellos, ¿eh? Tal vez pueda-",
        ["No, no. *Hiss* Now you're just like them. \"What can we do for you today, oh great Guardian of Guthix, Lady Fiara?"] = "No, no. *Hiss* Ahora eres como ellos. \"¿Qué podemos hacer por ti hoy, oh gran Guardiana de Guthix, Lady Fiara?",
        ["Erm, sorry, I guess."] = "Erm, lo siento, supongo.",
        ["*Hiss* Do not worry your feeble mind with it. What was it you wanted? Let's just get it over with."] = "*Hiss* No preocupes tu débil mente con eso. ¿Qué era lo que querías? Terminemos con esto de una vez.",
        ["Select an Option"] = "Selecciona una opción",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["It is the site of the Fist of Guthix."] = "Es el sitio del Puño de Guthix.",
        ["Fist of Guthix? What is that?"] = "¿Puño de Guthix? ¿Qué es eso?",
        ["It is what it is. If you do not already know, it's probably best that you don't learn."] = "Es lo que es. Si aún no lo sabes, probablemente sea mejor que no aprendas.",
        ["Umm, okay. What are you all doing down here then?"] = "Umm, está bien. ¿Qué están haciendo todos ustedes aquí abajo entonces?",
        ["*Hiss* Three druids are mainly just walking around NOT being quiet. Another one is setting up a fortress of crates and dragging all kinds of material junk into the cave. The fifth human, who isn't a druid, showed up when the following masses swarmed the cave."] = "*Hiss* Tres druidas están principalmente caminando SIN estar callados. Otro es montar una fortaleza de cajas y arrastrar todo tipo de material basura a la cueva. El quinto humano, que no es un druida, apareció cuando las siguientes masas invadieron la cueva.",
        ["I see. But...what drew them here in the first place?"] = "Ya veo. Pero... ¿qué los atrajo aquí en primer lugar?",
        ["The Fist of Guthix. And now they try to harness its power through this little business they've set up."] = "El Puño de Guthix. Y ahora intentan aprovechar su poder a través de este pequeño negocio que han montado.",
        ["Okay, but they told me to talk to you. Why did they want that?"] = "Está bien, pero me dijeron que hablara contigo. ¿Por qué querían eso?",
        ["Because I am the guardian of this site and I need to make sure that their games do not get out of control."] = "Porque soy el guardián de este sitio y necesito asegurarme de que sus juegos no se salgan de control.",
        ["Alright. Can you tell me about the games, then?"] = "Muy bien. ¿Puedes hablarme entonces de los juegos?",
        ["Ooh, that sounds interesting. I am a fan of power, myself."] = "Oh, eso suena interesante. Yo mismo soy un fanático del poder.",
        ["I figured you were. After all, you are human."] = "Me imaginé que sí. Después de todo, eres humano.",
        ["I guess I should talk to the druids about that business, then."] = "Supongo que entonces debería hablar con los druidas sobre ese asunto.",
        ["No, you should not. I am the guardian here. I need to make sure that the rules are obeyed and that their games do not go out of control."] = "No, no deberías. Yo soy el guardián aquí. Necesito asegurarme de que se cumplan las reglas y de que sus juegos no se salgan de control.",
        ["Okay, you tell me about it, then."] = "Está bien, entonces cuéntamelo.",
        ["Okay, I will tell you. Now, listen carefully so that you do not forget."] = "Está bien, te lo diré. Ahora, escucha atentamente para que no lo olvides.",
        ["The passageway on my left leads into the . If you want to participate in the games, this is where you must go."] = "El pasillo a mi izquierda conduce al . Si quieres participar en los juegos, aquí es donde debes ir.",
        ["Once enough adventurers have gathered, I will pair you up against each other, and send you into the arena. The arena is the cave of the Fist of Guthix. Allow me to show you."] = "Una vez que se hayan reunido suficientes aventureros, los emparejaré entre sí y los enviaré a la arena. La arena es la cueva del Puño de Guthix. Permíteme mostrarte.",
        ["Each game is divided into , and you and your opponent will take turns being the and the . I decide who starts as what."] = "Cada juego se divide en , y tú y tu oponente os turnaréis para ser el y el . Yo decido quién empieza como qué.",
        ["While you are the , you will see the text in the of the screen."] = "Mientras seas , verás el texto en el de la pantalla.",
        ["While you are the , this text will say ."] = "Mientras seas , este texto dirá .",
        ["The arena is large and circular, and ancient power emanates from its . You will start on opposite sides of this arena."] = "La arena es grande y circular, y un poder antiguo emana de su . Comenzarás en lados opuestos de esta arena.",
        ["The goal of the is simple: chase down and by any means necessary."] = "El objetivo del es simple: perseguir y por cualquier medio necesario.",
        ["The goal of the is not quite as easy. When you appear in the arena, you will find yourself close to a small stone altar - a . On top of this, you should see a ."] = "El objetivo del no es tan fácil. Cuando aparezcas en la arena, te encontrarás cerca de un pequeño altar de piedra: un . Además de esto, deberías ver un .",
        ["In the role of the , you must pick up a from the . This is what you will use to gather the powerful energy from the centre of the arena."] = "En el rol de , debes recoger un del . Esto es lo que usarás para reunir la poderosa energía del centro de la arena.",
        ["While you are - and ONLY while you , NOT when it's in your backpack - it will draw energy from the Fist of Guthix. Your objective is to get as many of these as possible."] = "Mientras estés , y SÓLO mientras estés , NO cuando estés en tu backpack, extraerá energía del Puño de Guthix. Su objetivo es conseguir tantos como sea posible.",
        ["The amount of you have gathered is listed in the ."] = "La cantidad de que has reunido aparece en .",
        ["As the , however, you must be careful. Your opponent, the , is there to defeat you. While you are , you will be . Also, you may feel very strong, but in the role of the , you will find your , more as you get closer to the centre - someone who otherwise may be an easy opponent to defeat in combat may instead prove most dangerous."] = "Sin embargo, al igual que el , debes tener cuidado. Tu oponente, el , está ahí para derrotarte. Mientras seas , serás . Además, puede que te sientas muy fuerte, pero en el papel de , encontrarás tu , más a medida que te acerques al centro: alguien que de otro modo podría ser un oponente fácil de derrotar en combate, puede resultar más peligroso.",
        ["You can of course try to fight back against your opponent, even though it may be difficult. Also, as the , you will be limited in your magical abilities as well. Only a certain spellbook can aid you in this role."] = "Por supuesto, puedes intentar contraatacar a tu oponente, aunque pueda resultar difícil. Además, como , tus habilidades mágicas también estarán limitadas. Sólo un determinado libro de hechizos puede ayudarte en este papel.",
        ["Speaking of , I should also mention that you will find that some spells are in the cave as they may be in other areas."] = "Hablando de , también debo mencionar que encontrarás que algunos hechizos son en la cueva como pueden serlo en otras áreas.",
        ["Finally, as the , you will also take from the powerful energies in the arena."] = "Finalmente, como , también tomarás de las poderosas energías de la arena.",
        ["Okay, so the hunter only has to hunt down their target?"] = "Bien, ¿entonces el cazador solo tiene que cazar a su objetivo?",
        ["That is correct."] = "Eso es correcto.",
        ["And the hunted will be weaker than usual, has to pick up a stone from the stone dispenser at the edge of the arena, and wield this stone in order to charge it?"] = "Y el cazado será más débil de lo habitual, ¿tiene que recoger una piedra del dispensador de piedras en el borde de la arena y empuñarla para cargarla?",
        ["Yes, and the of the arena you are, the more it will be ."] = "Sí, y cuanto de la arena seas, más será .",
        ["Anything else?"] = "¿Algo más?",
        ["Yes. You will find four small in the arena. Their doorways are blocked by . Only the can enter through these, and, while inside, will be completely to everyone else. The barriers are"] = "Sí. Encontrarás cuatro pequeños en la arena. Sus puertas están bloqueadas por . Sólo el puede entrar por estos y, mientras esté dentro, será completamente para todos los demás. Las barreras son",
        ["dangerous, however, and will as you pass through them."] = "peligroso, sin embargo, y será a medida que los atravieses.",
        ["Inside these , you will find . you can use them to - still to everyone else - but be aware that the magic is very old and the portals have not been actively used for thousands of years."] = "Dentro de estos , encontrarás . puedes usarlos para (aún para todos los demás), pero ten en cuenta que la magia es muy antigua y los portales no se han utilizado activamente durante miles de años.",
        ["They may act a bit strangely from time to time. Also, the portals require energy to work properly, and will from your stone. If you don't have enough charges, you won't be able to use the portal."] = "Es posible que actúen de forma un poco extraña de vez en cuando. Además, los portales requieren energía para funcionar correctamente y saldrán de tu piedra. Si no tiene suficientes cargos, no podrá utilizar el portal.",
        ["Okay, I will keep that in mind. So, when does the round end?"] = "Está bien, lo tendré en cuenta. Entonces, ¿cuándo termina la ronda?",
        ["A round can end in four different ways;"] = "Una ronda puede terminar de cuatro maneras diferentes;",
        ["One: If the ."] = "Uno: Si el .",
        ["Two: If the hunted - which is unlikely to happen."] = "Dos: Si el fue cazado, lo cual es poco probable que suceda.",
        ["Three: If the - each round can take no longer than ten minutes. You can see how much time there is left in the of the screen."] = "Tres: Si es , cada ronda no puede durar más de diez minutos. Puedes ver cuánto tiempo queda en el de la pantalla.",
        ["Four: If either player , in which case the other one will be declared the winner. The forfeiter will also be flagged as such as receive less tokens in the next game they play."] = "Cuatro: Si alguno de los jugadores hace , en cuyo caso el otro será declarado ganador. El perdedor también será marcado como tal por recibir menos fichas en el próximo juego que juegue.",
        ["When the first round as ended, the second round and the roles switch. The one who played the in first round will now have a chance to play the and gather ."] = "Cuando termina la primera ronda, la segunda ronda y los roles cambian. El que jugó el en la primera ronda ahora tendrá la oportunidad de jugar el y reunir el .",
        ["When both rounds have been played, the one with the ."] = "Cuando se hayan jugado ambas rondas, se jugará la que tenga el .",
        ["Ooh, what are the rewards?"] = "Oh, ¿cuáles son las recompensas?",
        ["The druids put a lot of value into the gathered energy, and you will be . How many tokens you get depends on your - a wide and balanced array of knowledge is something positive in"] = "Los druidas le dan mucho valor a la energía reunida y tú serás . La cantidad de tokens que obtenga depende de su : una gama amplia y equilibrada de conocimientos es algo positivo en",
        ["the eyes of Guthix - and how many you've got."] = "los ojos de Guthix - y cuántos tienes.",
        ["The can then be in the shop the druids have decided to clutter my cave with."] = "El puede ser en la tienda con la que los druidas han decidido abarrotar mi cueva.",
        ["You will also be awarded a , which is completely separate from the tokens. This will simply to keep track of how well you play the game. If you win, your rating improves. If you lose, your rating will suffer."] = "También recibirás un , que está completamente separado de los tokens. Esto simplemente servirá para realizar un seguimiento de qué tan bien juegas. Si ganas, tu calificación mejora. Si pierde, su calificación se verá afectada.",
        ["Your rating will improve significantly if you gather a lot . Also, the rating will be further adjusted if the difference in combat levels is large. If you lose to someone much more capable than you in combat,"] = "Tu calificación mejorará significativamente si reúnes mucho . Además, la calificación se ajustará aún más si la diferencia en los niveles de combate es grande. Si pierdes contra alguien mucho más capaz que tú en combate,",
        ["your rating won't suffer as much if you lost to someone around your own level."] = "tu calificación no se verá afectada tanto si pierdes contra alguien de tu mismo nivel.",
        ["Is that it?"] = "¿Es eso todo?",
        ["Almost. Patience is a great virtue."] = "Casi. La paciencia es una gran virtud.",
        ["Finally, you cannot bring just anything you want into the game. , but and . I will supply you with some means of healing and a large amount of , called and"] = "Finalmente, no puedes traer cualquier cosa que quieras al juego. , pero y . Te proporcionaré algunos medios de curación y una gran cantidad de , llamado y",
        [", for your . These can be used in place of any other runes you can take with you, but do note that they can only be used in the Fist of Guthix cave. Also, any or other forms of used in"] = ", para tu . Estos se pueden usar en lugar de cualquier otra runa que puedas llevar contigo, pero ten en cuenta que solo se pueden usar en la cueva del Puño de Guthix. Además, cualquier u otras formas de utilizadas en",
        ["the arena will be handed back to you after the game. Assuming they are still inTact, of course. And don't leave anything lying around! I don't want you to complete ruin this sacred site."] = "la arena te será devuelta después del juego. Suponiendo que todavía estén intactos, por supuesto. ¡Y no dejes nada tirado por ahí! No quiero que arruines por completo este sitio sagrado.",
        ["Now, do you have any questions?"] = "Ahora, ¿tienes alguna pregunta?",
        ["What are you?"] = "¿Qué eres?",
        ["I am Fiara, Guardian of Guthix. What are you?"] = "Soy Fiara, Guardián de Guthix. ¿Qué vas a?",
        ["I am Player. What are you guarding?"] = "Soy Player. ¿Qué estás protegiendo?",
        ["Hello, Player. I am guarding this very site."] = "Hola, Player. Estoy protegiendo este mismo sitio.",
        ["And what's so special about it?"] = "¿Y qué tiene de especial?",
        ["It is the site of the Fist of Guthix. If you do not already know that, you are probably not fit to learn."] = "Es el sitio del Puño de Guthix. Si aún no lo sabes, probablemente no estés capacitado para aprender.",
        ["Is there anything else I can help you with?"] = "¿Hay algo más en lo que pueda ayudarte?",
        ["I am Player, a Guardian of Saradomin."] = "Soy Player, un guardián de Saradomin.",
        ["Hello, Player, blind follower of the evil good and keeper of lies. Was there anything else you wanted?"] = "Hola, Player, seguidor ciego del mal bien y guardián de la mentira. ¿Había algo más que quisieras?",
        ["I am Player, also a Guardian of Guthix."] = "Soy Player, también guardián de Guthix.",
        ["Hello, Player, seer of light but bringer of lies. Was there anything else you wanted?"] = "Hola, Player, vidente de luz pero portador de mentiras. ¿Había algo más que quisieras?",
        ["I am Player, a Guardian of Zamorak."] = "Soy Player, un guardián de Zamorak.",
        ["Hello, Player, follower of the usurper and bringer of your own demise. Was there anything else you wanted?"] = "Hola, Player, seguidor del usurpador y portador de tu propia desaparición. ¿Había algo más que quisieras?",
        ["No, thanks."] = "No, gracias.",
        ["Never mind."] = "No importa.",
        ["Can I help you?"] = "¿Puedo ayudarte?",
        ["Hello, blind follower of evil good and keeper of lies. Can one such as I be of any help to you?"] = "Hola, seguidor ciego del mal bien y guardián de la mentira. ¿Alguien como yo puede serle de alguna ayuda?",
        ["Hello, Player, what tales do you bring with you today? One would think you'd already know whatever I have to tell you."] = "Hola, Player, ¿qué cuentos traes hoy? Uno pensaría que ya sabrías todo lo que tengo que decirte.",
        ["Hello, usurper, Should you not be raining destruction on those who want nothing to do with you?"] = "Hola, usurpador, ¿No deberías estar haciendo llover destrucción sobre aquellos que no quieren tener nada que ver contigo?",
        ["Greetings, Player, can I be of assistance?"] = "Saludos, Player, ¿puedo ser de ayuda?",
        ["I have some questions about the Fist of Guthix game."] = "Tengo algunas preguntas sobre el juego Fist of Guthix.",
        ["Could you tell me all about the game again?"] = "¿Podrías volver a contarme todo sobre el juego?",
        ["Okay, I will tell you. Now, listen carefully, so that you do not forget."] = "Está bien, te lo diré. Ahora escucha atentamente, para que no lo olvides.",
        ["How do I get charges?"] = "¿Cómo obtengo cargos?",
        ["You can only get charges while you are in the role of the . When the game starts, look around you - there should be a nearby. Pick up a from there and to gather . The closer to the centre you are, the more you will get."] = "Solo puedes recibir cargos mientras desempeñas el rol de . Cuando comience el juego, mira a tu alrededor: debería haber un cerca. Elija un desde allí y para reunir . Cuanto más cerca del centro estés, más obtendrás.",
        ["Any more questions?"] = "¿Alguna pregunta más?",
        ["I have more questions about the Fist of Guthix game."] = "Tengo más preguntas sobre el juego Fist of Guthix.",
        ["Why can't I get into the arena?"] = "¿Por qué no puedo entrar a la arena?",
        ["Why can't I get into the game?"] = "¿Por qué no puedo entrar al juego?",
        ["There must be enough players in the waiting room for a game to start. Also, there can only be a certain amount of players in the game at any time."] = "Debe haber suficientes jugadores en la sala de espera para que comience un juego. Además, solo puede haber una cierta cantidad de jugadores en el juego en cualquier momento.",
        ["I keep losing all the time!"] = "¡Sigo perdiendo todo el tiempo!",
        ["That was not a question, but I will give you some tips."] = "Esa no era una pregunta, pero te daré algunos consejos.",
        ["Remember that the of the arena, the . If you find yourself getting defeated easily and that your armour does you no good, you may want to try to flee to the outer edges of"] = "Recuerda que el de la arena, el . Si te derrotan fácilmente y tu armadura no te sirve de nada, quizás quieras intentar huir a los bordes exteriores de",
        ["the arena where you will be less weakened. This also applies to your opponent. if it is someone who appears to be a lot stronger than you, he or she will still be very weak closer to the centre - this is where you should strike."] = "la arena donde estarás menos debilitado. Esto también se aplica a tu oponente. Si se trata de alguien que parece ser mucho más fuerte que tú, seguirá siendo muy débil más cerca del centro; aquí es donde debes atacar.",
        ["You should also know that while you are in the very centre, the energy from the Fist of Guthix will help you replenish your run energy much faster than usual."] = "También debes saber que mientras estás en el centro, la energía del Puño de Guthix te ayudará a reponer tu energía de carrera mucho más rápido de lo habitual.",
        ["Also, use the ruins of the past to your advantage. Hide behind rubble and make a run for it when your opponent is out of reach. Use the buildings to hide or as a means of escape."] = "Además, utiliza las ruinas del pasado a tu favor. Escóndete detrás de los escombros y huye cuando tu oponente esté fuera de tu alcance. Utilice los edificios para esconderse o como medio de escape.",
        ["I am Fiara, a Guardian of Guthix."] = "Soy Fiara, un guardián de Guthix.",
        ["And you are guarding the Fist of Guthix, which, if I don't already know about, I am not fit to know about?"] = "¿Y tú estás custodiando el Puño de Guthix, que, si aún no lo sé, no soy digno de saberlo?",
        ["That is correct. Was there anything else?"] = "Eso es correcto. ¿Hubo algo más?",
        ["Just call me Player."] = "Solo llámame Player.",
        ["Alright, Player the Indecisive. How can I be of assistance?"] = "Muy bien, Player el Indeciso. ¿Cómo puedo ser de ayuda?",
        ["I'd like to talk about the Fist of Guthix."] = "Me gustaría hablar sobre el Puño de Guthix.",
        ["What do you think will happen now Guthix is dead?"] = "¿Qué crees que pasará ahora que Guthix está muerto?",
        ["There is no going back now. The young gods will return, one by one."] = "Ya no hay vuelta atrás. Los dioses jóvenes regresarán, uno por uno.",
        ["They will not share land, or followers. They are greedy, every last one of them."] = "No compartirán terrenos, ni seguidores. Son codiciosos, hasta el último de ellos.",
        ["We cannot let another God Wars happen. Guthix may be gone, but we still stand."] = "No podemos permitir que ocurra otra Guerra de Dioses. Puede que Guthix se haya ido, pero seguimos en pie.",
        ["I will never stop fighting for him. And you should remember the gift he gave you."] = "Nunca dejaré de luchar por él. Y deberías recordar el regalo que te dio.",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["<!-- Not sure where this fits in"] = "<!-- No estoy seguro de dónde encaja esto",
        ["What are you guarding?"] = "¿Qué estás protegiendo?",
        ["Guthix placed me here thousands of years ago to guard the Fist of Guthix."] = "Guthix me colocó aquí hace miles de años para proteger el Puño de Guthix.",
        ["You're guarding Guthix's hand...?"] = "¿Estás protegiendo la mano de Guthix...?",
        ["Do not take everything literally. No, I have been the guardian of this sacred site since the end of the Third Age, and it does not contain a hand."] = "No te tomes todo literalmente. No, soy el guardián de este lugar sagrado desde finales de la Tercera Edad y no contiene una mano.",
        ["What is it that you're guarding, then?"] = "¿Qué es lo que estás protegiendo entonces?",
        ["I have already told you. Now, was there anything else?"] = "Ya te lo he dicho. Ahora bien, ¿había algo más?",
        ["**Select an Option**"] = "**Seleccione una opción**",
        ["No, nothing else."] = "No, nada más.",
    },
    ["Fidelio"] = {
        ["Hello there."] = "Hola.",
        ["H-hello. You l-look like a s-stranger to these p-parts. Would you l-like to buy something? I h-have some s-special offers at the m-minute...some s-sample bottles for s- storing s-snail slime."] = "Hola. Pareces un extraño para estas partes. ¿Quieres comprar algo? Tengo algunas ofertas especiales en este momento... algunas botellas de muestra para almacenar baba de caracol.",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes, please."] = "Sí, por favor.",
        ["No thanks."] = "No, gracias.",
        ["(sigh) Th-that's okay. Nobody ever w-wants to buy my wares. Oh, s-sure, if it was food or c-clothes they would though!"] = "(suspiro) E-está bien. Nadie nunca quiere comprar mis productos. ¡Oh, claro, si fuera comida o ropa, lo harían!",
        ["Why are your prices so high?"] = "¿Por qué sus precios son tan altos?",
        ["As you p-probably know, the h-humans hate our kind and k-keep us trapped here. To get my s-stocks I have to sneak into the human lands in s-secret!"] = "Como p-probablemente sabes, los h-humanos odian a los de nuestra especie y nos mantienen atrapados aquí. ¡Para conseguir mis acciones tengo que colarme en las tierras humanas en secreto!",
        ["All the s-secrecy and d-danger has played h-havoc with my nerves!"] = "¡Todo el secretismo y el peligro han causado estragos en mis nervios!",
        ["But all your stuff is overpriced junk!"] = "¡Pero todas tus cosas son basura cara!",
        ["N-not at all! They are v-valuable human artefacts smuggled here at g-great personal risk!"] = "¡N-para nada! ¡Son artefactos humanos muy valiosos contrabandeados aquí con gran riesgo personal!",
    },
    ["Filip"] = {
        ["Hello?"] = "¿Hola?",
        ["Oh good, are you here for the presentation?"] = "Oh bien, ¿estás aquí para la presentación?",
        ["Erm, no, just who are you anyway?"] = "Erm, no, ¿quién eres tú de todos modos?",
        ["I'm Filip, and I'm waiting for some Very Important Penguins so we can begin our strategy update."] = "Soy Filip y estoy esperando algunos pingüinos muy importantes para que podamos comenzar nuestra actualización de estrategia.",
        ["I think they've gone... You're like the only penguin still here."] = "Creo que se han ido... Eres como el único pingüino que sigue aquí.",
        ["Oh, and I'd been practising and I'm ready to deliver my strategy update for the year. It's all about: Transformation, Transformation, Transformation!"] = "Ah, y he estado practicando y estoy listo para entregar mi actualización de estrategia para el año. Se trata de: ¡Transformación, Transformación, Transformación!",
        ["So what do you do around here then?"] = "Entonces, ¿qué haces por aquí?",
        ["I'm in charge of strategy, and more recently sails."] = "Estoy a cargo de la estrategia y, más recientemente, de navegación.",
        ["Sails? Do you mean sales?"] = "¿Velas? ¿Te refieres a ventas?",
        ["Yeah, that! There's been a recent boom in that sector. Here, take this pen...I'll show you! Now give it back to me, and say: Hey man, sell me this pen. Hey, can you sign this for me?"] = "¡Sí, eso! Ha habido un auge reciente en ese sector. Toma, toma este bolígrafo... ¡Te lo mostraré! Ahora devuélvemelo y di: Oye, véndeme este bolígrafo. Oye, ¿puedes firmar esto por mí?",
        ["I don't have anything to write with."] = "No tengo nada con qué escribir.",
        ["Well have you tried using that old Rod?"] = "Bueno, ¿has intentado usar ese viejo Rod?",
        ["It's no good, so you need a writing implement you can rely on. Here, I'll sell you this pen..."] = "No sirve, por lo que necesitas un instrumento de escritura en el que puedas confiar. Toma, te venderé este bolígrafo...",
        ["Perfect, I'll buy it."] = "Perfecto, lo compraré.",
        ["See!"] = "¡Mira!",
    },
    ["Financial advisor"] = {
        ["Money is useful because you can buy items from the if you don't want to craft them yourself."] = "El dinero es útil porque puedes comprar artículos de si no quieres crearlos tú mismo.",
        ["Gold are the currency of the human kingdoms. Your coins are kept in your at the bottom of your . You currently have 0 coins."] = "El oro es la moneda de los reinos humanos. Sus coins se guardan en su en la parte inferior de su . Actualmente tienes 0 coins.",
        ["There are three basic ways to make money: skilling, combat and trading. Some people have work for an adventurer like you, and will reward you for completing quests. Many enemies will drop items when they die. You can sell them to a or on the in . By getting a high level in skills, such as , , or , you can create or gather your own items and sell them for pure profit. You can only carry so many items in your backpack. You can deposit items you want to keep and not sell into your bank."] = "Hay tres formas básicas de ganar dinero: habilidades, combate y comercio. Algunas personas trabajan para un aventurero como tú y te recompensarán por completar misiones. Muchos enemigos dejarán caer objetos cuando mueran. Puedes venderlos en un o en un en un . Al obtener un alto nivel de habilidades, como , , o , puedes crear o reunir tus propios artículos y venderlos para obtener ganancias puras. Solo puedes llevar una cantidad limitada de artículos en tu backpack. Puede depositar en su banco los artículos que desee conservar y no vender.",
        ["You're nearly finished. The Prayer instructor would like to have a chat with you in the nearby church."] = "Ya casi has terminado. Al instructor de Prayer le gustaría charlar contigo en la iglesia cercana.",
    },
