    ["Fior"] = {
        ["Hi. What are you doing?"] = "Hola. ¿Qué estás haciendo?",
        ["Relaxing after a long day at the factory."] = "Relajarse después de un largo día en la fábrica.",
        ["If I keep up this winning streak, I mightn't have to go into work tomorrow."] = "Si mantengo esta racha ganadora, puede que no tenga que ir a trabajar mañana.",
