        ["Goodbye."] = "Adiós.",
    },
    ["Fisherman (Wendlewick)"] = {
        ["I'll never understand how Miriam manages to meet her fishing quota while frittering away so much time at the tavern."] = "Nunca entenderé cómo Miriam logra cumplir con su cuota de pesca mientras desperdicia tanto tiempo en la taberna.",
        ["Have you been to the Burnt Lobster Tavern? You wouldn't think it based on the name, but Gefen's an excellent cook."] = "¿Has estado en Burnt Lobster Tavern? No lo creerías por el nombre, pero Gefen es un excelente cocinero.",
        ["Sorry pal, I'd love to chat, but my break ends soon and I'm behind on my quota."] = "Lo siento amigo, me encantaría conversar, pero mi descanso termina pronto y estoy atrasado en mi cuota.",
        ["The number of fish in the area has been in steady decline for a while now."] = "La cantidad de peces en el área ha estado disminuyendo constantemente desde hace un tiempo.",
        ["We're still not sure why. Maybe it's related to the rumours of monsters in the east."] = "Todavía no estamos seguros de por qué. Quizás esté relacionado con los rumores sobre monstruos en el este.",
        ["Maya's fish farm has helped us a lot. Don't know what we'd have done without her."] = "La piscifactoría de Maya nos ha ayudado mucho. No sé qué hubiéramos hecho sin ella.",
        ["You'll find all sorts of fish around the village."] = "Encontrarás todo tipo de peces en el pueblo.",
        ["There are crayfish, trout and salmon in the rivers, and shrimps, anchovies, sardine and herring on the western shore."] = "Hay cangrejos, truchas y salmones en los ríos, y camarones, anchoas, sardinas y arenques en la costa occidental.",
        ["You can catch lobster, tuna, swordfish, mackerel, cod, bass and shark off the southern coast."] = "Puedes pescar langosta, atún, pez espada, caballa, bacalao, lubina y tiburón en la costa sur.",
        ["Old Man Jocko says there are still a few spots further inland where you can find giant crayfish, but I've never been able to catch one myself."] = "Old Man Jocko dice que todavía hay algunos lugares tierra adentro donde puedes encontrar cangrejos de río gigantes, pero yo nunca he podido pescar uno.",
    },
    ["Fisherman Frodi"] = {
        ["Hello."] = "Hola.",
        ["What would you like to talk about?"] = "¿De qué te gustaría hablar?",
        ["Good day. What are you doing?"] = "Buenos días. ¿Qué estás haciendo?",
        ["I'm painting my toenails... what's it look like I'm doing? Silly outsider..."] = "Me estoy pintando las uñas de los pies... ¿qué parece que estoy haciendo? Un forastero tonto...",
        ["Erm, good luck with that."] = "Erm, buena suerte con eso.",
        ["Thanks."] = "Gracias.",
        ["Your approval rating."] = "Su índice de aprobación.",
        ["What do people think of me around here?"] = "¿Qué piensa la gente de mí por aquí?",
        ["You haven't really won the hearts of the locals, if you see what I mean. At the last poll, only 25% of the population liked you."] = "Realmente no te has ganado el corazón de los lugareños, si entiendes lo que quiero decir. En la última encuesta, sólo le agradaste al 25% de la población.",
        ["Hey! This is the king's fishing spot. You'll need his approval to make use of it."] = "¡Oye! Este es el lugar de pesca del rey. Necesitará su aprobación para utilizarlo.",
        ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
        ["You know very well what I'm doing, Your Royal Highness."] = "Usted sabe muy bien lo que estoy haciendo, Su Alteza Real.",
        ["Just teasing!"] = "¡Solo bromeo!",
        ["Your people are growing dissatisfied with the regime, Your Royal Highness. At the last poll, only [*x*]% of the population supported you."] = "Su gente está cada vez más insatisfecha con el régimen, Su Alteza Real. En la última encuesta, sólo el [*x*]% de la población lo apoyó.",
    },
