    ["Fishmaskhead"] = {
        ["Er, hi, so...isn't there supposed to be a theme park around here somewhere?"] = "Er, hola, entonces... ¿no se supone que hay un parque temático por aquí en alguna parte?",
        ["Ha! That old chestnut. People still fall for that?"] = "¡Ja! Ese viejo castaño. ¿La gente todavía cae en eso?",
        ["Fall for what?"] = "¿Enamorarse de qué?",
        ["Oh, nothing. Why don't you, er, join us...for dinner?"] = "Oh, nada. ¿Por qué no te unes a nosotros... para cenar?",
        ["Ooh, what's on the menu?"] = "Oh, ¿qué hay en el menú?",
        ["Dibs on the sweet meats!"] = "¡Disfruta de las carnes dulces!",
        ["You can't call dibs! We share, remember?"] = "¡No puedes pedirlo! Compartimos, ¿recuerdas?",
        ["Aww, but you KNOW I've got a sweet tooth."] = "Ah, pero SABES que soy goloso.",
        ["And you KNOW I'm a pescatarian. I'm not eating that! It could have been anywhere."] = "Y SABES que soy pescatariano. ¡No voy a comer eso! Podría haber estado en cualquier lugar.",
        ["What? What aren't you eating?"] = "¿Qué? ¿Qué no estás comiendo?",
        ["We ARE stranded, remember. Beggars can't be choosers. Unless you want to start eating each other?"] = "Estamos varados, recuerda. Los mendigos no pueden elegir. ¿A menos que quieran empezar a comerse unos a otros?",
        ["Er, yeah, that would be uncivil."] = "Er, sí, eso sería descortés.",
        ["Right, see, even our meal agrees - cannonballs don't eat other cannonballs."] = "Bien, mira, incluso nuestra comida está de acuerdo: las balas de cañón no se comen a otras balas de cañón.",
        ["How many times? It's 'cannibals'!"] = "¿Cuántas veces? ¡Son 'caníbales'!",
        ["That's what I said. You KNOW I have a speech impediment, 'Keith'."] = "Eso es lo que dije. SABES que tengo un impedimento del habla, 'Keith'.",
        ["And I've told you my name is Puddinghead! Not cool, 'Jeff'."] = "¡Y ya les dije que mi nombre es Puddinghead! No está bien, 'Jeff'.",
        ["Urgh, would you boys stop arguing for just one minute?"] = "Urgh, ¿podrían dejar de discutir por un minuto?",
        ["Wait! Stop arguing for a sec. You're cannonballs, I mean, cannibals?"] = "¡Espera! Deja de discutir por un segundo. ¿Sois balas de cañón, quiero decir, caníbales?",
        ["And a pescatarian. I'm a person too, you know. Food is so rude these days. Am I right?"] = "Y un pescatariano. Yo también soy una persona, ¿sabes? La comida es muy grosera estos días. ¿Estoy en lo cierto?",
        ["You're a pescatarian cannibal? How does that work."] = "¿Eres un caníbal pescatariano? ¿Cómo funciona eso?",
        ["Mermaids."] = "Sirenas.",
        ["Oh, that's clever. No, wait, the other thing - that's gross! What about sea orphans. Do you eat those?"] = "Oh, eso es inteligente. No, espera, la otra cosa... ¡eso es asqueroso! ¿Qué pasa con los huérfanos del mar? ¿Comes esos?",
        ["Nah, I have a very strict diet regime. Sea orphans are half-person, half-fish - more like surf 'n' turf."] = "No, tengo una dieta muy estricta. Los huérfanos del mar son mitad personas, mitad peces, más como surf y tierra.",
        ["We're getting off-topic here! Right, so, who gets the legs?"] = "¡Nos estamos saliendo del tema! Bien, entonces, ¿quién se queda con las piernas?",
        ["None of you! Not unless you want to stay stranded! I'll take you back, but NO eating me or my crew."] = "¡Ninguno de ustedes! ¡No, a menos que quieras quedarte varado! Te llevaré de regreso, pero NO me comeré a mí ni a mi tripulación.",
        ["Aww."] = "Ay.",
        ["Spoilsport."] = "Aguafiestas.",
        ["Wait, not even travel snacks?"] = "Espera, ¿ni siquiera bocadillos de viaje?",
        ["Well, I suppose we could try to not eat you if it gets us off this island. We've been stranded here since The Harbinger sank our ship."] = "Bueno, supongo que podríamos intentar no comerte si eso nos saca de esta isla. Hemos estado varados aquí desde que The Harbinger hundió nuestro barco.",
        ["Yes, not eating me would help. Now, what about your friend over there. Is she coming too?"] = "Sí, no comerme ayudaría. Ahora, ¿qué pasa con tu amigo de allí? ¿Ella también viene?",
        ["Who, Jellyhead-head? Nah, she'll be fine. I think she likes it here. Besides, she hasn't said much since she put that thing on her head."] = "¿Quién, Jellyhead-head? No, ella estará bien. Creo que a ella le gusta estar aquí. Además, no ha dicho mucho desde que se puso esa cosa en la cabeza.",
    },
    ["Fishmonger (Rellekka)"] = {
        ["I don't sell to outerlanders."] = "No vendo a extranjeros.",
        ["Only Fremenniks may purchase fish here."] = "Sólo los Fremenniks pueden comprar pescado aquí.",
        ["The fishmonger is staring at you suspiciously. You cannot steal from his stall while he distrusts you."] = "El pescadero te mira con recelo. No puedes robar en su puesto mientras él desconfíe de ti.",
        ["Hello there, [Fremennik name]. Looking for fresh fish?"] = "Hola, [Fremennik name]. ¿Buscas pescado fresco?",
    },
    ["Fishmonger"] = {
        ["I don't sell to outerlanders."] = "No vendo a extranjeros.",
        ["Only Fremenniks may purchase fish here."] = "Sólo los Fremenniks pueden comprar pescado aquí.",
        ["The fishmonger is staring at you suspiciously. You cannot steal from his stall while he distrusts you."] = "El pescadero te mira con recelo. No puedes robar en su puesto mientras él desconfíe de ti.",
        ["Hello there, [Fremennik name]. Looking for fresh fish?"] = "Hola, [Fremennik name]. ¿Buscas pescado fresco?",
        ["Greetings, Sir. Get your fresh fish here!"] = "Saludos, señor. ¡Consigue tu pescado fresco aquí!",
        ["I've heard that the Etceterian fish is stored in a cow shed."] = "He oído que el pescado etceteriano se almacena en un establo para vacas.",
        ["Greetings, Your Highness. Have some fresh fish!"] = "Saludos, Alteza. ¡Come pescado fresco!",
        ["Welcome, [Fremennik Name]. My fish is fresher than any in Miscellania."] = "Bienvenido, [Fremennik Name]. Mi pescado es más fresco que cualquiera de Miscellania.",
    },
    ["Fishmonger's assistant"] = {
        ["Have you been up to much lately?"] = "¿Has estado haciendo mucho últimamente?",
        ["I just came back from Lev's. His cakes are delicious."] = "Acabo de regresar de Lev. Sus pasteles son deliciosos.",
        ["Hello there. How are you?"] = "Hola. ¿Cómo estás?",
        ["I'm doing well, thanks. Blessings of Inanna be upon you, traveller."] = "Estoy bien, gracias. Bendiciones de Inanna sean contigo, viajero.",
        ["How's your day going?"] = "¿Cómo va tu día?",
        ["Could be better. I ran into a bear in the Highweald earlier. I managed to escape but had to leave my gear behind."] = "Podría ser mejor. Me encontré con un oso en Highweald antes. Logré escapar pero tuve que dejar mi equipo.",
        ["Stay alert if you venture into the forest. It's been dangerous lately."] = "Mantente alerta si te aventuras en el bosque. Ha sido peligroso últimamente.",
        ["I can't complain. The sun is shining, the birds are singing... What more can you ask for?"] = "No me puedo quejar. El sol brilla, los pájaros cantan... ¿Qué más se puede pedir?",
        ["Leave me be, outlander."] = "Déjame en paz, forastero.",
        ["My kids are looking forward to the lamplight festival."] = "Mis hijos esperan con ansias el festival de las lámparas.",
        ["This year's candles are the best we've ever made, if I do say so myself."] = "Las velas de este año son las mejores que hemos hecho jamás, si me permite decirlo.",
        ["Nice to meet you."] = "Encantado de conocerte.",
        ["If you want small talk, go speak to Gefen."] = "Si quieres una pequeña charla, habla con Gefen.",
        ["Our harvests, our fish, our very land... Something's not right."] = "Nuestras cosechas, nuestros peces, nuestra propia tierra... Algo no está bien.",
        ["Hopefully your arrival is a sign of brighter days ahead."] = "Esperemos que tu llegada sea una señal de que se avecinan días mejores.",
        ["So... tired... There was loud barking coming from Zeeva's all night."] = "Muy... cansado... Hubo fuertes ladridos provenientes de casa de Zeeva durante toda la noche.",
        ["She needs to teach that dog some manners."] = "Necesita enseñarle algunos modales a ese perro.",
        ["You're the new outlander, right?"] = "Eres el nuevo forastero, ¿verdad?",
        ["I am!"] = "¡Lo soy!",
        ["It's nice to meet you. I hope you're enjoying our village."] = "Es un placer conocerte. Espero que estés disfrutando de nuestro pueblo.",
    },
    ["Fizzy Bunny"] = {
        ["That's an interesting title... I was the same until my pal, the Makeover Mage, helped me out."] = "Es un título interesante... Yo era el mismo hasta que mi amigo, el Makeover Mage, me ayudó.",
        ["You've unlocked the 'Cracked' colour for the 'the Egg' title!"] = "¡Has desbloqueado el color 'Agrietado' para el título 'el Huevo'!",
        ["Let me slap some new colours on that title for you, maybe they'll serve you well."] = "Déjame ponerle algunos colores nuevos a ese título, tal vez te sirvan.",
        ["Well met, Player!"] = "¡Bien conocido, Player!",
        ["Select an Option"] = "Selecciona una opción",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["I was overseeing the creation of some delicious statuettes - modelled after yours truly - when I was hit with a scrumptious epiphany!"] = "Estaba supervisando la creación de unas deliciosas estatuillas, inspiradas en un servidor, ¡cuando tuve una revelación deliciosa!",
        ["Cocoamancy! Animated chocolate goodies! Not just a tasty treat, but an exciting toy!"] = "¡Coamancia! ¡Delicias de chocolate animadas! ¡No sólo es un sabroso manjar, sino también un juguete emocionante!",
        ["Unfortunately I was led astray by the confidence of a peer I sought assitance from; seems he was lying a bit about his experience, and now the bunnies are loose!"] = "Desafortunadamente, la confianza de un compañero del que busqué ayuda me desvió; Parece que estaba mintiendo un poco sobre su experiencia, ¡y ahora los conejitos están sueltos!",
        ["They've started inhabiting chocolate burrows nearby, and every few minutes the rascals seem to pop up in a different place."] = "Han comenzado a habitar madrigueras de chocolate cercanas, y cada pocos minutos los sinvergüenzas parecen aparecer en un lugar diferente.",
        ["If you manage to track them down, I would be ecstatic to offer you spring tokens in exchange for any you return to me."] = "Si logras localizarlos, me encantaría ofrecerte fichas de primavera a cambio de las que me devuelvas.",
        ["I've got something for you."] = "Tengo algo para ti.",
        ["Are you pulling my leg? You don't have any rabbits! Come back when you've got something for me."] = "¿Me estás tomando el pelo? ¡No tienes conejos! Vuelve cuando tengas algo para mí.",
        ["You will not receive any Spring tokens for this. Hand in ayway?"] = "No recibirás ningún token Spring por esto. ¿Entregar de todos modos?",
        ["Yes."] = "Sí.",
        ["You have reached the Spring token soft cap of 30,000. You need to spend some tokens in Gummy's store before you can earn more."] = "Ha alcanzado el límite flexible del token Spring de 30 000. Debes gastar algunas fichas en la tienda de Gummy antes de poder ganar más.",
        ["The following has been added to your currency pouch: [number] x Spring tokens"] = "Se ha agregado lo siguiente a su bolsa de divisas: [número] x tokens Spring",
        ["Amazing work, Player! Take these as payment and get back out there, stat!"] = "¡Trabajo increíble, Player! ¡Toma esto como pago y vuelve a salir, inmediatamente!",
        ["Farewell."] = "Adiós.",
        ["Farewell, Fizzy."] = "Adiós, Fizzy.",
        ["Come back soon! With as many chocolate rabbits as you can hold!"] = "¡Vuelve pronto! ¡Con tantos conejos de chocolate como puedas sostener!",
    },
    ["Flesh-hatcher Mhekarnahz"] = {
        ["Warped by the depths below, Flesh-hatcher Mhekarnahz sees all."] = "Deformado por las profundidades inferiores, Flesh-hatcher Mhekarnahz lo ve todo.",
        ["Requirements"] = "Requisitos",
        ["Completion Time: [time] - New Personal Record! An improvement of [number] seconds!"] = "Tiempo de finalización: [time] - ¡Nuevo récord personal! ¡Una mejora de [número] segundos!",
        ["You have killed [number] Flesh-hatcher Mhekarnahz."] = "Has matado a [número] Flesh-hatcher Mhekarnahz.",
        ["The corpse is empty."] = "El cadáver está vacío.",
    },
    ["Fletcher"] = {
        ["Welcome, fellow dreamer."] = "Bienvenido, compañero soñador.",
        ["If you could provide me some resources from your base camp, I could create a fletcher's hut for you to train at within this dream, and teach you something of Ilujankan fletching techniques."] = "Si pudieras proporcionarme algunos recursos de tu campamento base, podría crear una cabaña de fletcher para que entrenes dentro de este sueño y enseñarte algo sobre las técnicas de fletching de Ilujankan.",
        ["Thank you for the wood. If you keep supplying me with more, I can teach you much about ilujankan fletching techniques."] = "Gracias por la madera. Si sigues proporcionándome más, puedo enseñarte mucho sobre las técnicas de emplumado ilujankan.",
        ["You are learning much of our ways. Keep on as you are, and I will share a story with you."] = "Estás aprendiendo mucho de nuestras costumbres. Sigue como estás y compartiré una historia contigo.",
        ["You have learned much. I shall soon share my tale with Paskeeper Sharrigan."] = "Has aprendido mucho. Pronto compartiré mi historia con Paskeeper Sharrigan.",
        ["I have recounted my tale to Pastkeeper Sharrigan. Thank you for all of your efforts. Perhaps you should train at one of the other stations for a time."] = "Le he contado mi historia a Pastkeeper Sharrigan. Gracias por todos sus esfuerzos. Quizás deberías entrenar en alguna de las otras estaciones por un tiempo.",
        ["You must build a station before you can contribute resources to it."] = "Debes construir una estación antes de poder aportarle recursos.",
        ["Contribute [number] x wood and store [number] XP in this station?"] = "¿Contribuir [número] x madera y almacenar [número] XP en esta estación?",
        ["Yes."] = "Sí.",
        ["The fletcher's hut now has [number]/135,000 Fletching XP stored in it."] = "La cabaña del Fletcher ahora tiene [número]/135,000 Fletching XP almacenados.",
        ["You contribute to the station: [number] x wood"] = "Tú contribuyes a la estación: [número] x madera.",
        ["You have too few of this resource to contribute to this station."] = "Tienes muy pocos recursos de este recurso para contribuir a esta estación.",
        ["This skilling station is already at maximum capacity of resources."] = "Esta estación de habilidades ya está en su máxima capacidad de recursos.",
        ["**CONTRIBUTE [NUMBER] X WOOD AND STORE [NUMBER] XP IN THIS STATION?**"] = "**¿CONTRIBUIR [número] X MADERA Y ALMACENAR [número] XP EN ESTA ESTACIÓN?**",
        ["The fletcher's hut now has [number]/350,000 Fletching XP stored in it."] = "La cabaña del Fletcher ahora tiene [número]/350,000 Fletching XP almacenados.",
    },
    ["Flint"] = {
        ["You need the following skills to start this quest: 74 Firemaking, 76 Constitution, 64 Agility."] = "Necesitas las siguientes habilidades para comenzar esta misión: 74 Firemaking, 76 Constitution, 64 Agility.",
        ["What are you all doing here?"] = "¿Qué están haciendo todos aquí?",
        ["Top secret, my friend. But perhaps when you're more experienced you could help us."] = "Alto secreto, amigo mío. Pero quizás cuando tengas más experiencia puedas ayudarnos.",
        ["I see."] = "Ya veo.",
        ["Ah, Player! Welcome, welcome!"] = "¡Ah, Player! ¡Bienvenidos, bienvenidos!",
        ["Chat to Sera and Emmett if you want to try out our activities."] = "Chatea con Sera y Emmett si quieres probar nuestras actividades.",
        ["It's all a bit too energetic for me, especially after our last adventure!"] = "¡Es todo demasiado enérgico para mí, especialmente después de nuestra última aventura!",
    },
    ["Flippers McGraw"] = {
        ["Keep walking, mate."] = "Sigue caminando, amigo.",
        ["I don't suppose y-"] = "Supongo que no-",
        ["Can I smell fish? Give me some fish and I might 'suppose'."] = "¿Puedo oler a pescado? Dame un poco de pescado y tal vez \"supongo\".",
        ["Give raw fish to Flippers?"] = "¿Darle pescado crudo a Flippers?",
        ["Yes."] = "Sí.",
        ["Thanks. Not bad."] = "Gracias. Nada mal.",
        ["Now, will you-"] = "Ahora, ¿podrías-?",
        ["Nope."] = "No.",
        ["Oh my, what was that slice of deliciousness? I must have more!"] = "Dios mío, ¿qué fue ese trozo de delicia? ¡Debo tener más!",
        ["Now, will y-"] = "Ahora, ¿quieres?",
        ["Yes! Whatever it is, yes! If you can get me more of those, I'll do it."] = "¡Sí! Sea lo que sea, ¡sí! Si puedes conseguirme más de esos, lo haré.",
        ["You'll join my ship cr-"] = "Te unirás a mi barco cr-",
        ["I ain't swabbing nothing."] = "No estoy limpiando nada.",
        ["You could be my lookou-"] = "Podrías ser mi lookou-",
        ["Nope, on account of the cultural prejudice that is a 'crow's nest'."] = "No, por el prejuicio cultural que es un 'nido de cuervo'.",
        ["Well, what would yo-"] = "Bueno, ¿qué harías?",
        ["I'm a fixer."] = "Soy un reparador.",
        ["That's not a traditional crew pos-"] = "Esa no es una posición de equipo tradicional.",
        ["It's whatever you need it to be, Cap. Now, more fish like that. Please, I suppose."] = "Es lo que necesites, Cap. Ahora, más peces así. Por favor, supongo.",
        ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
        ["Captain."] = "Capitán.",
        ["Hey, Flippers, what are you doing?"] = "Oye, Flippers, ¿qué estás haciendo?",
        ["Ah, you know, just hanging around the fishing spots. These idiots keep just dropping fish all over the place. It's like free breakfast buffet all the time."] = "Ah, ya sabes, simplemente dando vueltas por los lugares de pesca. Estos idiotas siguen tirando peces por todos lados. Es como un desayuno buffet gratis todo el tiempo.",
        ["Coming here was a great plan, Cap! We should never leave. Fish as far as the eye can see! And the smell, oh gods, the smell &nbsp;I am in the penguin afterlife!"] = "¡Venir aquí fue un gran plan, Cap! Nunca deberíamos irnos. ¡Pesca hasta donde alcanza la vista! Y el olor, oh dioses, el olor. ¡Estoy en el más allá de los pingüinos!",
        ["Have you seen these dragon monks? They're completely nutso!"] = "¿Has visto a estos monjes dragón? ¡Están completamente locos!",
        ["I mean, I could understand if they were trying to attain the form of a penguin, but a dragon? Sheesh. Sometimes, I think I'm the only sane person left in this world."] = "Quiero decir, podría entender si estuvieran tratando de alcanzar la forma de un pingüino, pero ¿un dragón? Cielos. A veces pienso que soy la única persona cuerda que queda en este mundo.",
        ["I'm just gonna go climb these towers and jump off, see if I can fly yet."] = "Voy a escalar estas torres y saltar, para ver si todavía puedo volar.",
        ["Great, have fun!"] = "¡Genial, diviértete!",
        ["No, wait! You're a penguin! You can't fly!"] = "¡No, espera! ¡Eres un pingüino! ¡No puedes volar!",
        ["Don't tell me what I can and can't do. You're not the boss of me, er, Cap."] = "No me digas qué puedo y qué no puedo hacer. No eres mi jefe, eh, Cap.",
        ["No, I mean you literally, physically can't fly. It's not me stopping you, it's physics."] = "No, quiero decir que, literalmente, físicamente no puedes volar. No soy yo quien te detiene, es la física.",
        ["Yeah, well, physics can do one."] = "Sí, bueno, la física puede hacerlo.",
        ["Can we visit the berry bar? I've got a thirst on like you wouldn't believe. I'm one parched penguin."] = "¿Podemos visitar el bar de bayas? Tengo una sed como no lo creerías. Soy un pingüino reseco.",
        ["Boring! There's nothing here to do. Can we go yet? Can we? Huh?"] = "¡Aburrido! Aquí no hay nada que hacer. ¿Podemos irnos todavía? ¿Podemos? ¿Eh?",
        ["Not yet, Flippers."] = "Todavía no, Flippers.",
        ["Aww. You're mean."] = "Ay. Eres malo.",
        ["You are such a child, sometimes."] = "A veces eres un niño.",
        ["Brr, this place shivers my flippers. It's so quiet and spooky. Can we leave soon?"] = "Brr, este lugar me hace temblar las aletas. Es tan silencioso y espeluznante. ¿Podemos irnos pronto?",
        ["Ha-Has she gone? I'm scared!"] = "Ja-¿Se ha ido? ¡Tengo miedo!",
        ["What's wrong, Flippers?"] = "¿Qué pasa, Flippers?",
        ["M-my nemesis! She was here just before you arrived, and she won't leave me alone! K-keeps trying to... I can't even say it; it makes me feel sick even thinking about it."] = "¡M-mi némesis! ¡Estuvo aquí justo antes de que llegaras y no me dejará en paz! K-sigue intentando... Ni siquiera puedo decirlo; Me hace sentir mal incluso pensar en ello.",
        ["So spell it out."] = "Así que explícalo.",
        ["She tries to... to... to H_U_G me. Isn't that just the grossest?"] = "Ella trata de... de... ABRAZARME. ¿No es eso lo más asqueroso?",
        ["You're scared of a woman that's trying to, let me get this straight, trying to hug you?"] = "¿Tienes miedo de una mujer que intenta, déjame aclararlo, intentar abrazarte?",
        ["*blech* Don't say it or you'll make me 'feed the chicks'."] = "*blech* No lo digas o me obligarás a \"alimentar a los polluelos\".",
        ["It's not a woman either - it's a little girl."] = "Tampoco es una mujer, es una niña.",
        ["She's the cutest thing too."] = "Ella también es la cosa más linda.",
        ["She keeps calling me Sophie. I keep telling her she's got the wrong penguin. She's not getting the message, though. Children are the worst."] = "Sigue llamándome Sophie. Sigo diciéndole que se equivocó de pingüino. Sin embargo, ella no entiende el mensaje. Los niños son lo peor.",
    },
    ["Flo (The Beach)"] = {
        ["Ready to head back?"] = "¿Listo para regresar?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yeah, I'm ready to go."] = "Sí, estoy listo para partir.",
        ["No, I'll stay a little longer."] = "No, me quedaré un poco más.",
        ["I can't complain."] = "No me puedo quejar.",
        ["Although, saying that, I wouldn't mind getting my hands on that beastie in the pool. She'd make a meal fit for a kingdom."] = "Aunque, dicho esto, no me importaría tener en mis manos a esa bestia en la piscina. Haría una comida digna de un reino.",
        ["I might need a bigger rod though!"] = "¡Quizás necesite una caña más grande!",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
