    ["Fred Binder"] = {
        ["Hey you! You there! Have some free rope!"] = "¡Hola, tú! ¡Tú allí! ¡Ten un poco de cuerda gratis!",
        ["Who are you, and why are you giving away free rope?"] = "¿Quién eres y por qué regalas cuerda?",
        ["I could get into a lot of trouble if I told you that."] = "Podría meterme en muchos problemas si te dijera eso.",
        ["Uh... All right?"] = "Eh... ¿Está bien?",
        ["Bye!"] = "¡Adiós!",
        ["Hey you! Yes you! How would you like... Oh, you already have some..."] = "¡Hola, tú! ¡Sí tú! ¿Cómo te gustaría...? Oh, ya tienes algunos...",
        ["Sorry, what?"] = "Lo siento, ¿qué?",
        ["I was going to give you some rope, but it looks like you have plenty."] = "Iba a darte un poco de cuerda, pero parece que tienes suficiente.",
    },
    ["Fred the Farmer"] = {
        ["What are you doing on my land?"] = "¿Qué haces en mi tierra?",
        ["Choose an option:"] = "Elige una opción:",
        ["I'm looking for something to kill."] = "Estoy buscando algo para matar.",
        ["What, on my land? Leave my livestock alone!"] = "¿Qué, en mi tierra? ¡Deja en paz a mi ganado!",
        ["I'm lost."] = "Estoy perdido.",
        ["How can you be lost? Just follow the road east and south. You'll end up in Lumbridge fairly quickly."] = "¿Cómo puedes estar perdido? Simplemente siga la carretera hacia el este y el sur. Terminarás en Lumbridge bastante rápido.",
        ["I'm looking for work."] = "Estoy buscando trabajo.",
        ["Fred! Fred! I've seen 'The Thing'!"] = "¡Fred! ¡Fred! ¡He visto 'La Cosa'!",
        ["You... you actually saw it? Run for the hills! Player, grab as many chickens as you can! We have to..."] = "Tú... ¿realmente lo viste? ¡Corre hacia las colinas! Player, ¡agarra tantas gallinas como puedas! Tenemos que...",
        ["Fred!"] = "¡Fred!",
        ["...flee! Oh, woe is me! The shape-shifter is coming! We're all..."] = "...¡huye! ¡Ay de mí! ¡El cambiaformas ya viene! Todos somos...",
        ["FRED!"] = "¡FRED!",
        ["...doomed. What?"] = "...condenado. ¿Qué?",
        ["It's not a shape-shifter or any other kind of monster."] = "No es un cambiaformas ni ningún otro tipo de monstruo.",
        ["Well, what is it, [boy/girl]?"] = "Bueno, ¿qué pasa, [boy/girl]?",
        ["Well, it's just two penguins... disguised as a sheep."] = "Bueno, son solo dos pingüinos... disfrazados de oveja.",
        ["Have you been out in the sun too long?"] = "¿Has estado demasiado tiempo al sol?",
        ["Hello again."] = "Hola de nuevo.",
        ["What are you doing on my..."] = "¿Qué estás haciendo en mi...?",
        ["Ah, it's the sheep shearer! That wool you gave me sold exceptionally well. Please accept this as an extra thanks."] = "¡Ah, es el esquilador de ovejas! Esa lana que me diste se vendió excepcionalmente bien. Acepte esto como un agradecimiento adicional.",
        ["[The farmer hands over 1,940 coins.]"] = "[El agricultor entrega 1.940 coins.]",
        ["Thank you!"] = "¡Gracias!",
        ["What are you doing on my land? You're not the one who keeps leaving all my gates open and letting out all my chickens are you?"] = "¿Qué haces en mi tierra? No eres tú quien sigue dejando todas mis puertas abiertas y dejando salir a todas mis gallinas, ¿verdad?",
        ["Can you tell me about the battlefield?"] = "¿Puedes hablarme sobre el campo de batalla?",
        ["Hmph. Yes, a great big portal appears not far from my farm and Saradomin and Zamorak come traipsing over my land, happy as you please."] = "Hmph. Sí, aparece un gran portal no muy lejos de mi granja y Saradomin y Zamorak vienen recorriendo mi tierra, felices como quieran.",
        ["Bloomin' soldiers everywhere, spooking my chickens and telling everyone they should join up with some army of other."] = "Soldados florecientes por todas partes, asustando a mis gallinas y diciéndoles a todos que deberían unirse a algún ejército de otros.",
        ["Then, without a warning, Saradomin himself plonks a war camp on top of my house. Well, I was angry, I'll tell you."] = "Entonces, sin previo aviso, el propio Saradomin instala un campamento de guerra en lo alto de mi casa. Bueno, estaba enojado, te lo diré.",
        ["So, I left a sternly written letter with the duke, and built a new house here, bringing my sheep with me."] = "Entonces, dejé una carta escrita con severidad al duque y construí una nueva casa aquí, trayendo mis ovejas conmigo.",
        ["And you know what... the THING followed..."] = "Y sabes qué... la COSA siguió...",
        ["The battle destroyed some other peoples houses, too, and there's a rebuilding effort going on right now to help them."] = "La batalla también destruyó las casas de otras personas, y ahora mismo se están realizando esfuerzos de reconstrucción para ayudarlos.",
        ["Not that I needed help moving my house! Hank and Explorer Jack are too soft, in my opinion, accepting help from passing adventurers like that."] = "¡No es que necesitara ayuda para mudar mi casa! Hank y Explorer Jack son demasiado blandos, en mi opinión, al aceptar ayuda de aventureros que pasan como ese.",
        ["At least they're not fighting any more though."] = "Al menos ya no pelean.",
        ["But don't expect me to just hand you more jobs! Find your own work!"] = "¡Pero no esperes que te dé más trabajos! ¡Encuentra tu propio trabajo!",
        ["They're still fighting it out now, over to the west. As for you, maybe you should stop lumbering about in my house and do something useful!"] = "Todavía están peleando, hacia el oeste. En cuanto a ti, ¡tal vez deberías dejar de andar pesadamente por mi casa y hacer algo útil!",
    },
    ["Freda"] = {
        ["Hello!"] = "¡Hola!",
        ["Well hello there! My, you're a cheerful one! How can I help you?"] = "Bueno, ¡hola! ¡Dios mío, eres alegre! ¿Le puedo ayudar en algo?",
        ["Select an Option"] = "Selecciona una opción",
        ["Who are you?"] = "¿Quién eres?",
        ["I'm Freda, welcome to my humble home!"] = "Soy Freda, ¡bienvenido a mi humilde hogar!",
        ["My husband, Sabbot, and I came here to start a trading post. You know, selling dwarven arms to the Guard."] = "Mi esposo, Sabbot, y yo vinimos aquí para iniciar un puesto comercial. Ya sabes, vender armas enanas a la Guardia.",
        ["Then the trolls came and took over the plateau before we could get established, so I came to live here."] = "Luego vinieron los trolls y se apoderaron de la meseta antes de que pudiéramos establecernos, así que vine a vivir aquí.",
        ["What about your husband?"] = "¿Qué pasa con tu marido?",
        ["That stubborn old mule won't leave the cave we were in! He'd rather die than let the trolls win."] = "¡Esa vieja mula testaruda no sale de la cueva en la que estábamos! Preferiría morir antes que dejar que los trolls ganen.",
        ["I send him soup and letters now and then, and those nice men in town make sure he's okay."] = "Le envío sopa y cartas de vez en cuando, y esos buenos hombres de la ciudad se aseguran de que esté bien.",
        ["Is there anything else you want?"] = "¿Hay algo más que quieras?",
        ["Aren't you afraid of the trolls up here?"] = "¿No les tienes miedo a los trolls de aquí?",
        ["Not at all. There used to be a few around here, but I soon dealt with them."] = "Para nada. Solía ​​haber algunos por aquí, pero pronto me ocupé de ellos.",
        ["How? Aren't trolls really fierce in combat?"] = "¿Cómo? ¿No son los trolls realmente feroces en combate?",
        ["Yes, but I'm fiercer!"] = "Sí, ¡pero soy más feroz!",
        ["I'll have you know I've not been a trader all my life. I do know which end of an axe will do the most damage to a troll."] = "Debes saber que no he sido comerciante en toda mi vida. Sé qué extremo de un hacha le hará más daño a un troll.",
        ["Besides, some of those nice young men from town give me a hand if the trolls come in numbers. But after the last time the trolls seem to have got the hint."] = "Además, algunos de esos jóvenes simpáticos del pueblo me echan una mano si los trolls vienen en gran número. Pero después de la última vez, los trolls parecen haber captado la indirecta.",
        ["It's astonishing what waving an axe at groin height will do to break the will of even the biggest troll!"] = "¡Es sorprendente lo que puede hacer agitar un hacha a la altura de la ingle para romper la voluntad incluso del troll más grande!",
        ["So why don't you live with your husband then?"] = "Entonces, ¿por qué no vives con tu marido?",
        ["Well, I can take on the occasional wandering troll, but a whole horde of them is something else entirely."] = "Bueno, puedo enfrentarme a algún troll errante ocasional, pero una horda entera de ellos es algo completamente distinto.",
        ["This place may not be that safe, but at least it's not the middle of a warzone."] = "Puede que este lugar no sea tan seguro, pero al menos no está en medio de una zona de guerra.",
        ["Anything else I can help you with?"] = "¿Puedo ayudarte con algo más?",
        ["That's all, thanks."] = "Eso es todo, gracias.",
        ["Oh? Well you take care on your way back."] = "¿Ah? Bueno, cuídate en el camino de regreso.",
        ["Hello, Freda."] = "Hola, Freda.",
        ["Hello there. I heard from some of the boys in town that you really gave those trolls a thrashing!"] = "Hola. ¡Escuché de algunos de los chicos de la ciudad que realmente les diste una paliza a esos trolls!",
        ["You keep it up. Every little helps."] = "Sigue así. Todo ayuda.",
        ["I will!"] = "¡Lo haré!",
        ["Anything else you need?"] = "¿Necesitas algo más?",
        ["Can I buy some Climbing boots?"] = "¿Puedo comprar unas botas de escalada?",
        ["I don't see why not. Let me see what I've got in your size."] = "No veo por qué no. Déjame ver lo que tengo en tu talla.",
        ["Buy standard boots for 12gp."] = "Compra botas estándar por 12 po.",
        ["Sorry, you don't have anywhere to put these."] = "Lo sentimos, no tienes ningún lugar donde colocarlos.",
        ["You can not afford that."] = "No puedes permitirte eso.",
        ["Oops, it looks like you're a little short there. That's 12 gold you need to buy these boots."] = "Vaya, parece que te falta un poco. Son 12 de oro lo que necesitas para comprar estas botas.",
        ["[You purchase the climbing boots.]"] = "[Compras las botas de montaña.]",
        ["See full range of stock."] = "Ver gama completa de stock.",
    },
    ["Free item shop"] = {
        ["*If any magic golem outfit piece is not owned:*"] = "*Si alguna pieza del traje de golem mágico no es de tu propiedad:*",
        ["*If inventory is full:*"] = "*Si el inventario está lleno:*",
        ["To receive a piece of the magic golem outfit, you need a free space in your backpack."] = "Para recibir una pieza del traje de golem mágico, necesitas un espacio libre en tu backpack.",
        ["I'm a placeholder NPC so players can quickly get free items in the mining and smithing beta."] = "Soy un NPC marcador de posición para que los jugadores puedan obtener rápidamente elementos gratis en la versión beta de minería y herrería.",
