    ["Freidir"] = {
        ["I cannot speak to you outerlander! Talk to Brundt, the Chieftain!"] = "¡No puedo hablar contigo, extranjero! ¡Habla con Brundt, el cacique!",
        ["They are too suspicious of you for you to get close enough to steal from them."] = "Sospechan demasiado de ti como para que te acerques lo suficiente como para robarles.",
        ["*When speaking to Freidir in Rellekka.*"] = "*Al hablar con Freidir en Rellekka.*",
        ["Hello."] = "Hola.",
        ["*Freidir may greet you with any of the following at random:*"] = "*Freidir puede saludarte con cualquiera de los siguientes al azar:*",
        ["How are you, [Fremennik name]? I hope all fares well with you this day!"] = "¿Cómo estás, [Fremennik name]? ¡Espero que a todos les vaya bien este día!",
        ["I'm fine, thanks, how are you?"] = "Estoy bien, gracias, ¿cómo estás?",
        ["All is well with me also!"] = "¡Todo está bien para mí también!",
        ["Hello again, [sister/brother] [Fremennik name]. What need you of me this day? You can always rely on my assistance!"] = "Hola de nuevo, [sister/brother] [Fremennik name]. ¿Qué necesitas de mí este día? ¡Siempre puedes confiar en mi ayuda!",
        ["Hello. Did you want something, [Fremennik name]?"] = "Hola. ¿Querías algo, [Fremennik name]?",
        ["[Fremennik name], it has been too long since last we met!"] = "[Fremennik name], ¡ha pasado demasiado tiempo desde la última vez que nos vimos!",
        ["Welcome back, [sister/brother] [Fremennik name]. It is always a pleasure to see you here!"] = "Bienvenido de nuevo, [sister/brother] [Fremennik name]. ¡Siempre es un placer verte por aquí!",
        ["Hello to you, too!"] = "¡Hola a ti también!",
        ["Always good to see you, [sister/brother] [Fremennik name]."] = "Siempre es un placer verte, [sister/brother] [Fremennik name].",
        ["Select an option (all greetings continue with dialogue below)"] = "Seleccione una opción (todos los saludos continúan con el diálogo a continuación)",
        ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
        ["*Freidir may reply to you with any of the following at random:*"] = "*Freidir puede responderle con cualquiera de los siguientes mensajes al azar:*",
        ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Él murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
        ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
        ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
        ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
        ["Goodbye."] = "Adiós.",
    },
    ["Fremennik banker"] = {
        ["Good day. How may I help you?"] = "Buenos días. ¿Cómo puedo ayudarte?",
        ["Select an option"] = "Seleccione una opción",
        ["I'd like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
        ["*(Will open your bank.)*"] = "*(Abrirá su banco.)*",
        ["I'd like to check my PIN settings."] = "Me gustaría comprobar la configuración de mi PIN.",
        ["*(Will open you bank pin settings.)*"] = "*(Abrirá la configuración del PIN del banco.)*",
        ["I'd like to see my collection box."] = "Me gustaría ver mi caja de colección.",
        ["*(Will open you collection box.)*"] = "*(Abrirá su caja de colección.)*",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is a branch of the Bank of Runescape. We have branches in many towns."] = "Esta es una sucursal del Banco de Runescape. Disponemos de sucursales en muchas localidades.",
        ["And what do you do?"] = "¿Y tú a qué te dedicas?",
        ["We will look after your items and money for you. Leave your valuables with us if you want to keep them safe."] = "Nos ocuparemos de tus artículos y de tu dinero. Deje sus objetos de valor con nosotros si desea mantenerlos seguros.",
        ["Didn't you used to be called the Bank of Varrock?"] = "¿No te llamaban el Banco de Varrock?",
        ["Yes we did, but people kept coming into our branches outside of Varrock and telling us that our signs were wrong. They acted as if we didn't know what town we were in or something."] = "Sí, lo hicimos, pero la gente seguía entrando a nuestras sucursales fuera de Varrock y diciéndonos que nuestros carteles estaban equivocados. Actuaron como si no supiéramos en qué ciudad estábamos o algo así.",
    },
    ["Fremennik scout"] = {
        ["Hello."] = "Hola.",
        ["Greetings, adventurer! Braving the dangers of the terrible dungeons, I see."] = "¡Saludos, aventurero! Ya veo, desafiando los peligros de las terribles mazmorras.",
        ["Select an option"] = "Seleccione una opción",
        ["What are you doing here?"] = "¿Qué estás haciendo aquí?",
        ["I'm setting up another base for adventurers to use. It's hard and dangerous work, I can tell you."] = "Estoy preparando otra base para que la utilicen los aventureros. Es un trabajo duro y peligroso, te lo aseguro.",
        ["Can I help?"] = "¿Puedo ayudar?",
        ["Certainly! I have lots to do, so feel free to dig in."] = "¡Por supuesto! Tengo mucho que hacer, así que siéntete libre de profundizar.",
        ["**Fremennik scout:** If you look around the room, you should find some crates containing raw fish, logs, and metal bars. I need the fish cooked, the logs turned into bows, and the bars turned into battleaxes. If you take care of this for me, I'll make sure you can continue."] = "**Fremennik scout:** Si miras alrededor de la habitación, deberías encontrar algunas cajas que contienen pescado crudo, logs y barras de metal. Necesito el pescado cocido, los logs convertidos en arcos y las barras convertidas en hachas de batalla. Si te encargas de esto por mí, me aseguraré de que puedas continuar.",
        ["Do you have a knife I can use?"] = "¿Tienes un cuchillo que pueda usar?",
        ["You already have a knife, so what do you need mine for?"] = "Ya tienes un cuchillo, entonces, ¿para qué necesitas el mío?",
        ["Could you remind me what I have to do?"] = "¿Podrías recordarme qué tengo que hacer?",
        ["Do you have a hammer I can use?"] = "¿Tienes un martillo que pueda usar?",
        ["I'll get back to work now."] = "Volveré a trabajar ahora.",
        ["You already have a hammer, so what do you need mine for?"] = "Ya tienes un martillo, entonces, ¿para qué necesitas el mío?",
        ["Consider it done!"] = "¡Considérelo hecho!",
        ["Can you unlock the door?"] = "¿Puedes desbloquear la puerta?",
        ["Good luck with that."] = "Buena suerte con eso.",
        ["Thank you."] = "Gracias.",
        ["*First time choosing this option:*"] = "*Primera vez que elijo esta opción:*",
        ["Can you unlock the door for me?"] = "¿Puedes abrirme la puerta?",
        ["Well, I could, but I'd need something in return from you. If you help me out, I will unlock it for you."] = "Bueno, podría, pero necesitaría algo a cambio de tu parte. Si me ayudas, lo desbloquearé.",
        ["Okay, I can help."] = "Está bien, puedo ayudar.",
        ["That's great! Let me just give you some instructions."] = "¡Eso es genial! Déjame darte algunas instrucciones.",
        ["I don't want to help."] = "No quiero ayudar.",
        ["I guess you won't be continuing, then."] = "Entonces supongo que no continuarás.",
        ["Fine!"] = "¡Bien!",
        ["Fine."] = "Bien.",
        ["*Subsequent times:*"] = "*Tiempos posteriores:*",
        ["I've already told you: if you want the door unlocked, you need to help me out."] = "Ya te lo dije: si quieres que la puerta esté abierta, debes ayudarme.",
        ["I sure am!"] = "¡Claro que sí!",
