        ["Yes."] = "Sí.",
        ["No, thanks."] = "No, gracias.",
    },
    ["Fur trader"] = {
        ["Would you like to trade in fur?"] = "¿Le gustaría comerciar con pieles?",
        ["Select an Option"] = "Selecciona una opción",
        ["Yes."] = "Sí.",
        ["No, thanks."] = "No, gracias.",
        ["These hides are very soft. Did you trap these yourself?"] = "Estas pieles son muy suaves. ¿Los atrapaste tú mismo?",
        ["Hunt... skin..."] = "Cazar... piel...",
        ["Fur keep cold out... wind bite less."] = "Las pieles mantienen el frío afuera... el viento muerde menos.",
        ["They look heavy."] = "Se ven pesados.",
        ["Heavy... means warm."] = "Pesado... significa cálido.",
        ["This fur... death in snow."] = "Esta piel... muerte en la nieve.",
        ["I don't sell to outerlanders."] = "No vendo a extranjeros.",
        ["Only Fremenniks may purchase furs here."] = "Sólo los Fremenniks pueden comprar pieles aquí.",
        ["The fur trader is staring at you suspiciously. You cannot steal from his stall while he distrusts you."] = "El comerciante de pieles te mira con recelo. No puedes robar en su puesto mientras él desconfíe de ti.",
        ["*When speaking to Fur trader in Rellekka.*"] = "*Al hablar con un comerciante de pieles en Rellekka.*",
        ["Welcome back, [Fremennik name]! Have you seen the furs I have today?"] = "¡Bienvenido de nuevo, [Fremennik name]! ¿Has visto las pieles que tengo hoy?",
        ["Select an option"] = "Seleccione una opción",
        ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
        ["*Fur trader may reply to you with any of the following at random:*"] = "*El comerciante de pieles puede responderle con cualquiera de los siguientes mensajes al azar:*",
        ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
        ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
        ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
        ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
        ["We'll keep his stories alive, at least his legend will live forever."] = "Mantendremos vivas sus historias, al menos su leyenda vivirá para siempre.",
        ["Let me see your wares."] = "Déjame ver tus productos.",
    },
    ["Fur trader (Hollow Hill)"] = {
        ["These hides are very soft. Did you trap these yourself?"] = "Estas pieles son muy suaves. ¿Los atrapaste tú mismo?",
        ["Hunt... skin..."] = "Cazar... piel...",
        ["Fur keep cold out... wind bite less."] = "Las pieles mantienen el frío afuera... el viento muerde menos.",
        ["They look heavy."] = "Se ven pesados.",
        ["Heavy... means warm."] = "Pesado... significa cálido.",
        ["This fur... death in snow."] = "Esta piel... muerte en la nieve.",
    },
    ["Fur trader (Rellekka)"] = {
        ["I don't sell to outerlanders."] = "No vendo a extranjeros.",
        ["Only Fremenniks may purchase furs here."] = "Sólo los Fremenniks pueden comprar pieles aquí.",
        ["The fur trader is staring at you suspiciously. You cannot steal from his stall while he distrusts you."] = "El comerciante de pieles te mira con recelo. No puedes robar en su puesto mientras él desconfíe de ti.",
        ["*When speaking to Fur trader in Rellekka.*"] = "*Al hablar con un comerciante de pieles en Rellekka.*",
        ["Welcome back, [Fremennik name]! Have you seen the furs I have today?"] = "¡Bienvenido de nuevo, [Fremennik name]! ¿Has visto las pieles que tengo hoy?",
        ["Select an option"] = "Seleccione una opción",
        ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
        ["*Fur trader may reply to you with any of the following at random:*"] = "*El comerciante de pieles puede responderle con cualquiera de los siguientes mensajes al azar:*",
        ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
        ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
        ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
        ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
        ["We'll keep his stories alive, at least his legend will live forever."] = "Mantendremos vivas sus historias, al menos su leyenda vivirá para siempre.",
        ["Let me see your wares."] = "Déjame ver tus productos.",
    },
    ["Furies' Chosen"] = {
        ["Welcome, mortal."] = "Bienvenido, mortal.",
        ["That's an interesting Anima crystal you have there. Would you be willing to donate it?"] = "El cristal de Anima que tienes ahí es interesante. ¿Estarías dispuesto a donarlo?",
        ["Hand in your Anima crystal?"] = "¿Entregar tu cristal de Anima?",
        ["Yes. (Gain 500 reputation with Zamorak)"] = "Sí. (Gana 500 de reputación con Zamorak)",
        ["You have gained 500 reputation with the Zamorakian forces!"] = "¡Has ganado 500 puntos de reputación con las fuerzas zamorakianas!",
        ["Thank you for your help."] = "Gracias por tu ayuda.",
        ["I notice you have a stock of seals from around the Heart. Would you be interested in donating them?"] = "Noté que tienes un stock de sellos de todo el Corazón. ¿Estarías interesado en donarlos?",
        ["**EXCHANGE SEALS FOR REPUTATION WITH THE ZAMORAKIANS?**"] = "**¿CAMBIAR SELLOS POR REPUTACIÓN CON LOS ZAMORAKIANOS?**",
        ["Hand in Seren seals."] = "Entregue los sellos Seren.",
        ["Your Seals of the Cywir were worth [number] reputation with the Zamorakian forces!"] = "¡Tus Sellos de Cywir valían [número] reputación ante las fuerzas zamorakianas!",
        ["Hand in Sliske seals."] = "Entregue los sellos Sliske.",
        ["Your Seals of the faceless were worth [number] reputation with the Zamorakian forces!"] = "¡Tus Sellos de los sin rostro valían [número] reputación ante las fuerzas zamorakianas!",
        ["Hand in Zaros seals"] = "Entrega de sellos de Zaros",
        ["Your Seals of the Dragon riders were worth [number] reputation with the Zamorakian forces!"] = "¡Tus jinetes de los Sellos del Dragón valían [número] reputación con las fuerzas zamorakianas!",
        ["Hand in all seals."] = "Entregue todos los sellos.",
        ["No thank you."] = "No, gracias.",
        ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
        ["What's going on here?"] = "¿Qué está pasando aquí?",
        ["You find yourself in the Heart of Gielinor, adventurer. Hear the cries and relish the chaos of the battlefield as the forces of Zamorak do battle with the vile minions of Zaros, Sliske and Seren! Leading us into battle are the ferocious Twin Furies: Avaryss the unceasing and Nymora the vengeful."] = "Te encuentras en el Corazón de Gielinor, aventurero. ¡Escucha los gritos y disfruta del caos del campo de batalla mientras las fuerzas de Zamorak luchan contra los viles secuaces de Zaros, Sliske y Seren! Liderándonos a la batalla están las feroces Furias Gemelas: Avaryss la incesante y Nymora la vengativa.",
        ["Why are you all just stood here? Shouldn't you be fighting?"] = "¿Por qué están todos aquí parados? ¿No deberías estar peleando?",
        ["We are not all savages. Upon this platform a truce has been established, allowing us - the envoys of each faction - to use words rather than violence to sway fresh recruits. For below the battle rages on, so we must do what we can to persuade the mercenaries that join the fray to fight for our cause. Take a look at what I have to offer. I assure you, I'll make it worth your while to fight for Zamorak."] = "No todos somos salvajes. Sobre esta plataforma se ha establecido una tregua que nos permite a nosotros, los enviados de cada facción, utilizar palabras en lugar de violencia para influir en nuevos reclutas. Porque abajo la batalla continúa, por lo que debemos hacer lo que podamos para persuadir a los mercenarios que se unen a la refriega para que luchen por nuestra causa. Echa un vistazo a lo que tengo para ofrecerte. Te lo aseguro, haré que valga la pena luchar por Zamorak.",
        ["What is your opinion of me?"] = "¿Cuál es tu opinión sobre mí?",
        ["How can I improve my reputation?"] = "¿Cómo puedo mejorar mi reputación?",
        ["There are a few ways you can improve your standing. The easiest thing you can do is defeat our enemies, and use Ingression fragments to call in reinforcements for us. The bounty master over there, Feng, can also help you improve your standing by offering you bounties. Speak to him if you'd like to know more. Oh, and I'm sure if you could somehow find a way to defeat the other factions' generals that would certainly earn you a lot of favour."] = "Hay algunas formas de mejorar tu posición. Lo más fácil que puedes hacer es derrotar a nuestros enemigos y usar fragmentos de Ingresión para pedir refuerzos para nosotros. El maestro de recompensas de allí, Feng, también puede ayudarte a mejorar tu posición ofreciéndote recompensas. Habla con él si quieres saber más. Ah, y estoy seguro de que si de alguna manera pudieras encontrar una manera de derrotar a los generales de las otras facciones, eso sin duda te haría ganar mucho favor.",
        ["Where can I get armour like that?"] = "¿Dónde puedo conseguir una armadura así?",
        ["You can collect armour shards and crests around the Heart which can then be combined to make armour similar to my own. If you prove your worth to me, I can show you how to improve it further and unlock its true potential."] = "Puedes recolectar fragmentos de armadura y crestas alrededor del Corazón que luego se pueden combinar para crear una armadura similar a la mía. Si me demuestras tu valía, puedo mostrarte cómo mejorarlo aún más y desbloquear su verdadero potencial.",
        ["I'd like to reclaim my rewards."] = "Me gustaría reclamar mis recompensas.",
        ["There's nothing I can give you."] = "No hay nada que pueda darte.",
        ["I'd like to reclaim my insignia."] = "Me gustaría reclamar mi insignia.",
        ["Furies' Chosen hands you a Zamorak insignia."] = "Furies' Chosen te entrega una insignia de Zamorak.",
        ["Never mind."] = "No importa.",
        ["You can now discover the blueprint for Avernic components if you have at least 89 Invention."] = "Ahora puede descubrir el plano de los componentes de Avernic si tiene al menos 89 Invention.",
        ["You have unlocked the Fury Wings cosmetic override."] = "Has desbloqueado la anulación cosmética Fury Wings.",
        ["[You can't gain any more reputation with that faction.]"] = "[No puedes ganar más reputación con esa facción.]",
    },
    ["Fycie"] = {
        ["You's better talk to Dad, We not talk to wierdly 'umans."] = "Será mejor que hables con Dad. No hablamos con humanos extraños.",
        ["Thanks for da chompy, it was deloverly!"] = "Gracias por el chompy, ¡estuvo delicioso!",
        ["Human done good!"] = "¡Humano hecho bien!",
        ["[Fycie has given you another clue scroll!]"] = "[¡Fycie te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    },
    ["Fyre"] = {
        ["Excellent job adventurer, the wolves have been repelled once more."] = "Excelente trabajo aventurero, los lobos han sido repelidos una vez más.",
        ["There is no time to rest, The End of Things approaches."] = "No hay tiempo para descansar, El Fin de las Cosas se acerca.",
    },
    ["Aereck"] = {
        ["Welcome to the church of holy Saradomin."] = "Bienvenido a la iglesia del santo Saradomin.",
        ["Welcome back to the church of holy Saradomin, my friend! What can I do for you today?"] = "¡Bienvenido de nuevo a la iglesia del santo Saradomin, amigo mío! ¿Qué puedo hacer por ti hoy?",
        ["If you find any bones or ashes on your adventures, please feel free to offer them at this altar. You will be rewarded by Saradomin's light with greater knowledge for each one offered."] = "Si encuentras huesos o cenizas en tus aventuras, no dudes en ofrecerlos en este altar. La luz de Saradomin te recompensará con mayor conocimiento por cada uno ofrecido.",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["Ask about your construction contract."] = "Pregunta por tu construction contract.",
        ["Select an option"] = "Selecciona una opción",
        ["What do you need repairing?"] = "¿Qué necesitas reparar?",
        ["Let me see, right now I need you to repair the following pieces of furniture."] = "Déjame ver, ahora mismo necesito que repares el siguiente pieces of furniture.",
        ["What materials do I need?"] = "¿Qué materiales necesito?",
        ["You need: Planks x [number], Steel nails x [number], [Additional material] x [number]"] = "Necesitas: Planks x [número], Steel nails x [número], [Additional material] x [número]",
        ["I'm looking for a quest!"] = "¡Estoy buscando una misión!",
        ["That's lucky, I need someone to do a quest for me."] = "Qué suerte, necesito que alguien haga una misión para mí.",
        ["Not Right Now"] = "Ahora no",
        ["Oh, well. If you do have some spare time on your hands, come back and talk to me."] = "Oh, bueno. Si tienes algo de tiempo libre, regresa y habla conmigo.",
        ["Accept Quest"] = "Aceptar misión",
        ["Thank you. The problem is there's a ghost in the graveyard just south of this church. I would like you to get rid of it."] = "Gracias. El problema es que hay un fantasma en el cementerio justo al sur de esta iglesia. Me gustaría que te deshagas de él.",
        ["You'll need the help of my friend, Father Urhney, who is a bit of a ghost expert."] = "Necesitarás la ayuda de mi amigo, Father Urhney, que es un experto en fantasmas.",
        ["He's currently living in a little shack in the south of Lumbridge Swamps, near the coast."] = "Actualmente vive en una pequeña choza en el sur de Lumbridge Swamps, cerca de la costa.",
        ["My name is Father Aereck, by the way. Pleased to meet you."] = "Por cierto, mi nombre es Father Aereck. Encantado de conocerte.",
        ["Likewise."] = "Igualmente.",
        ["Take care travelling through the swamps. To get there just follow the path south, through the graveyard."] = "Ten cuidado al viajar por los pantanos. Para llegar allí sólo sigue el camino hacia el sur, a través del cementerio.",
        ["I will, thanks."] = "Lo haré, gracias.",
        ["Can you change my gravestone now?"] = "¿Puedes cambiar mi lápida ahora?",
        ["Certainly. All proceeds are donated to the Varrockian Guards' Widows & Orphans Fund."] = "Por supuesto. Todas las ganancias se donan al Fondo de Huérfanos y Viudas de los Guardias Varrockianos.",
        ["Who's Saradomin?"] = "¿Quién es Saradomin?",
        ["Surely you have heard of our god, Saradomin?"] = "¿Seguro que has oído hablar de nuestro dios, Saradomin?",
        ["He who created the forces of goodness and purity in this world? I cannot believe your ignorance!"] = "¿Quien creó las fuerzas de la bondad y la pureza en este mundo? ¡No puedo creer tu ignorancia!",
        ["This is the god with more followers than any other...at least in this part of the world."] = "Este es el dios con más seguidores que cualquier otro... al menos en esta parte del mundo.",
        ["He defeated the evil Zamorak in the battle of Lumbridge nearby, and he defends us from evil!"] = "¡Derrotó al malvado Zamorak en la cercana batalla de Lumbridge y nos defiende del mal!",
        ["Oh, THAT Saradomin."] = "Oh, ESE Saradomin.",
        ["There is only one Saradomin."] = "Sólo hay un Saradomin.",
        ["Yeah. I, uh, thought you said something else."] = "Sí. Pensé que habías dicho algo más.",
        ["Oh, sorry, I'm not from this world."] = "Oh, lo siento, no soy de este mundo.",
        ["That's...strange."] = "Eso es... extraño.",
        ["I thought things not from this world were all, you know, slime and tentacles."] = "Pensé que las cosas que no eran de este mundo eran todas, ya sabes, baba y tentáculos.",
        ["Not me."] = "Yo no.",
        ["Well, I can see that. Still, there's something special about you."] = "Bueno, puedo verlo. Aún así, hay algo especial en ti.",
        ["Thanks, I think."] = "Gracias, creo.",
        ["I am! Do you like my disguise?"] = "¡Lo soy! ¿Te gusta mi disfraz?",
        ["Argh! Avaunt, foul creature from another dimension! Avaunt! Begone in the name of Saradomin!"] = "¡Argh! ¡Criatura asquerosa y audaz de otra dimensión! ¡Avaunt! ¡Vete en nombre de Saradomin!",
        ["Okay, okay, I was only joking!"] = "Está bien, está bien, ¡solo estaba bromeando!",
        ["Can you tell me about the battlefield?"] = "¿Puedes hablarme sobre el campo de batalla?",
        ["Nice place you've got here."] = "Bonito lugar el que tienes aquí.",
        ["It is, isn't it? It was built over two centuries ago."] = "Lo es, ¿no? Fue construido hace más de dos siglos.",
        ["Can you bless my ring?"] = "¿Puedes bendecir mi anillo?",
        ["Ah, you wish to show your devotion to Saradomin by dedicating a ring to him? Very well, it would be my pleasure to assist."] = "Ah, ¿deseas mostrar tu devoción por Saradomin dedicándole un anillo? Muy bien, sería un placer ayudarte.",
        ["[Father Aereck inscribes the symbol of Saradomin on your ring's signet face, and offers a brief benediction over it.]"] = "[Father Aereck inscribe el símbolo de Saradomin en la cara del sello de su anillo y ofrece una breve bendición sobre él.]",
        ["Can you tell me about the crater?"] = "¿Puedes hablarme sobre el campo de batalla?",
        ["Ah, Lumbridge Battlefield - the site of the return of Saradomin! That was a momentous day for the church, and I was there!"] = "Ah, Lumbridge Battlefield: ¡el sitio del regreso de Saradomin! ¡Ese fue un día trascendental para la iglesia y yo estuve allí!",
        ["In a titanic battle that lasted for months, the mighty Saradomin drove back the forces of Zamorak to the Underworld where they belong."] = "En una batalla titánica que duró meses, el poderoso Saradomin hizo retroceder a las fuerzas de Zamorak al inframundo al que pertenecen.",
        ["And now Saradomin is here, we can be sure that we will be safe under his divine protection."] = "Y ahora que Saradomin está aquí, podemos estar seguros de que estaremos a salvo bajo su protección divina.",
        ["All praise Saradomin!"] = "¡Todos los elogios para Saradomin!",
        ["Lumbridge battlefield is where Saradomin himself is currently fighting Zamorak! Thank goodness that he is here! If he'd not shown up when he did, we'd all be thralls of Zamorak now! But he came to us from far away in our time of need, and even now he fights evil on Lumbridge Battlefield. Oh, you must be on your way to Saradomin's war camp in order to help out. It's to the northwest of here. We cannot let evil conquer! Good luck! And may Saradomin be with you!"] = "¡El campo de batalla de Lumbridge es donde el propio Saradomin está luchando actualmente contra Zamorak! ¡Gracias a Dios que está aquí! Si no hubiera aparecido cuando lo hizo, ¡ahora todos seríamos esclavos de Zamorak! Pero vino a nosotros desde muy lejos en nuestro momento de necesidad, e incluso ahora lucha contra el mal en Lumbridge Battlefield. Oh, debes estar de camino al campamento de guerra de Saradomin para poder ayudar. Está al noroeste de aquí. ¡No podemos dejar que el mal venza! ¡Buena suerte! ¡Y que Saradomin esté contigo!",
        ["Have you gotten rid of the ghost yet?"] = "¿Ya te has deshecho del fantasma?",
        ["How was I supposed to do that?"] = "¿Cómo se suponía que debía hacer eso?",
        ["Well, you should go find Father Urhney as he knows all about ghosts."] = "Bueno, deberías ir a buscar a Father Urhney, ya que sabe todo sobre fantasmas.",
        ["You can get to the swamp he lives in by going south through the cemetery."] = "Puedes llegar al pantano en el que vive yendo hacia el sur a través del cementerio.",
        ["You'll have to head south through the swamp - stick to the coastline and you'll find his house in no time."] = "Tendrás que dirigirte hacia el sur a través del pantano; sigue la costa y encontrarás su casa en poco tiempo.",
        ["Have you got rid of the ghost yet?"] = "¿Ya te has deshecho del fantasma?",
        ["I had a talk with Father Urhney. He has given me a funny amulet for talking to ghosts."] = "Tuve una conversación con Father Urhney. Me ha dado un amuleto curioso para hablar con fantasmas.",
        ["I always wondered what that amulet was. Well, I hope it's useful. Tell me when you get rid of the ghost."] = "Siempre me pregunté qué era ese amuleto. Bueno, espero que sea útil. Avísame cuando te deshagas del fantasma.",
        ["That would explain it. Hmm. Well, I haven't seen any skulls."] = "Eso lo explicaría. Mmm. Bueno, no he visto ninguna calavera.",
        ["I hate warlocks. Ah, well, good luck."] = "Odio a los warlocks. Bueno, buena suerte.",
        ["Great! Put it in the ghost's coffin and see what happens."] = "¡Genial! Ponlo en el ataúd del fantasma y mira qué pasa.",
        ["Don't worry, I'm sure you'll find it again."] = "No te preocupes, seguro que lo encuentras de nuevo.",
        ["I don't want it! Put it in the coffin and see what happens."] = "¡No lo quiero! Mételo en el ataúd y mira qué pasa.",
        ["Hi there. Hey, you're the one that got rid of that ghost. I wanted to reward you to say thanks for helping out."] = "Hola. Oye, tú eres quien se deshizo de ese fantasma. Quería recompensarte para agradecerte por ayudar.",
        ["You've got rid of that ghost, haven't you?"] = "Te has deshecho de ese fantasma, ¿verdad?",
        ["Thank you so much. I don't have much money, so I can't pay you, but I could improve your gravestone."] = "Muchas gracias. No tengo mucho dinero, así que no puedo pagarte, pero podría mejorar tu lápida.",
        ["Yes, the gravestone that appears when you die. If you go somewhere dangerous, you'll often find that people have died there and you'll see their gravestones. Most people have very plain ones, but I can upgrade you to a better design."] = "Sí, la lápida que aparece cuando mueres. Si vas a un lugar peligroso, a menudo descubrirás que la gente ha muerto allí y verás sus lápidas. La mayoría de las personas tienen diseños muy sencillos, pero puedo mejorarte con un mejor diseño.",
    },
    ["Urhney"] = {
        ["Go away! I'm meditating!"] = "¡Vete! ¡Estoy meditando!",
        ["Well, that's friendly."] = "Bueno, eso es amigable.",
        ["I said go away!"] = "¡Dije que te fueras!",
        ["Okay, okay. Sheesh, what a grouch."] = "Está bien, está bien. Joder, qué cascarrabias.",
        ["I've come to repossess your house."] = "He venido a recuperar tu casa.",
        ["On what grounds?"] = "¿Por qué motivos?",
        ["Repeated failure to make mortgage repayments."] = "Incumplimiento reiterado del pago de la hipoteca.",
        ["What? But I don't have a mortgage - I build this house myself!"] = "¿Qué? Pero no tengo una hipoteca: ¡la casa la construyo yo mismo!",
        ["Sorry, I must have got the wrong address. All the houses look the same around here."] = "Lo siento, debo haberme equivocado de dirección. Todas las casas parecen iguales por aquí.",
        ["What? What houses? This is the only one. What are you talking about?"] = "¿Qué? ¿Qué casas? Éste es el único. ¿De qué estás hablando?",
        ["Never mind."] = "No importa.",
        ["I don't know, I just wanted this house."] = "No lo sé, sólo quería esta casa.",
        ["Oh, go away and stop wasting my time."] = "Oh, vete y deja de hacerme perder el tiempo.",
        ["*(After The Restless Ghost)* I've lost that ghostspeak amulet you gave me."] = "*(Después de The Restless Ghost)* He perdido ese amuleto de habla fantasma que me diste.",
        ["Father Urhney sighs."] = "Father Urhney suspira.",
        ["*(If the amulet is equipped, or in inventory:)*"] = "*(Si el amuleto está equipado o en el inventario:)*",
        ["What are you talking about? I can see you've got it with you."] = "¿De qué estás hablando? Puedo ver que lo tienes contigo.",
        ["*(If the amulet is in the bank:)*"] = "*(Si el amuleto está en el banco:)*",
        ["Why do you insist on wasting my time? Has it even occurred to you to look in your bank? Now go away!"] = "¿Por qué insistes en hacerme perder el tiempo? ¿Se te ha ocurrido siquiera buscar en tu banco? ¡Ahora vete!",
        ["*(If the player has a cramulet:)*"] = "*(Si el player tiene cramulet:)*",
        ["It's probably tangled up in your cramulet."] = "Probablemente esté enredado en tu cramulet.",
        ["*(If the player genuinely has lost their ghostspeak amulet:)*"] = "*(Si el player realmente ha perdido su amuleto de habla fantasma:)*",
        ["How careless can you get? Those things aren't easy to come by, you know! It's a good job I've got a spare."] = "¿Qué tan descuidado puedes llegar a ser? Esas cosas no son fáciles de conseguir, ¿sabes? Es un buen trabajo. Tengo uno de repuesto.",
        ["[Father Urhney hands you an amulet.]"] = "[Father Urhney te entrega un amuleto.]",
        ["Be more careful this time."] = "Ten más cuidado esta vez.",
        ["Okay, I'll try to be."] = "Está bien, intentaré serlo.",
        ["Can you tell me about the crater?"] = "¿Puedes hablarme sobre el cráter?",
        ["There were enough people clattering around my house before, and then Zamorak decides he wants a war camp right next to my hut."] = "Antes había suficiente gente haciendo ruido en mi casa, y entonces Zamorak decide que quiere un campamento de guerra justo al lado de mi cabaña.",
        ["At least Zamorak has gone now, but he's left his camp littering my swamp."] = "Al menos Zamorak ya se fue, pero dejó su campamento ensuciando mi pantano.",
        ["Can you tell me about the battlefield?"] = "¿Puedes contarme sobre el campo de batalla?",
        ["There were enough people clattering around my house before, and then Zamorak decides he wants a war camp right next to my hut. Well, I'm not going to move again! At least Saradomin is there to deal with it this time. Maybe you should toddle off to Saradomin's camp and help out. And close the door on the way out!"] = "Antes había suficiente gente haciendo ruido en mi casa, y entonces Zamorak decide que quiere un campamento de guerra justo al lado de mi cabaña. ¡Pues no me voy a mover más! Al menos Saradomin está ahí para solucionarlo esta vez. Quizás deberías ir al campamento de Saradomin y ayudar. ¡Y cierra la puerta al salir!",
        ["Aren't you afraid of Zamorak?"] = "¿No le tienes miedo a Zamorak?",
        ["Yes, I'm terrified. But he's looking the other way, and Saradomin will defeat him soon. So why don't you go and deal with him while I get back to my meditation. I'm sure Saradomin will appreciate it."] = "Sí, estoy aterrorizado. Pero él está mirando para otro lado y Saradomin lo derrotará pronto. Entonces, ¿por qué no vas y te ocupas de él mientras yo vuelvo a mi meditación? Estoy seguro de que Saradomin lo agradecerá.",
        ["You don't want to dip into those pockets without good reason. They're holy...and filthy."] = "No querrás echar mano de esos bolsillos sin una buena razón. Son santos... y sucios.",
        ["[pic=Clue scroll (medium) detail.png]"] = "[pic=Desplazamiento de pistas (mediano) detail.png]",
        ["The sooner you answer the question, the sooner you can leave me in peace."] = "Cuanto antes respondas la pregunta, antes podrás dejarme en paz.",
        ["Enter amount: [Input field]"] = "Ingrese la cantidad: [Input field]",
        ["Wrong! Now go away. I'm meditating."] = "¡Mal! Ahora vete. Estoy meditando.",
        ["[If only to get rid of you, Father Urnhey has given you another clue scroll!]"] = "[¡Aunque sólo sea para deshacerse de ti, el padre Urnhey te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Congratulations. Either you can count, you got lucky, or you do not trust your own mind and traffic in otherworldly sources of infernal knowledge."] = "Felicitaciones. O puedes contar, has tenido suerte o no confías en tu propia mente y traficas con fuentes de conocimiento infernal sobrenaturales.",
        ["Regardless, for the love of Saradomin... Please. Leave me and don't bother me again. I want to be left alone."] = "De todos modos, por el amor de Saradomin... Por favor. Déjame y no me vuelvas a molestar. Quiero que me dejen en paz.",
        ["Father Aereck sent me to talk to you."] = "Father Aereck me envió a hablar contigo.",
        ["I suppose I'd better talk to you then. What has he got himself into this time?"] = "Supongo que será mejor que hable contigo entonces. ¿En qué se ha metido esta vez?",
        ["Select an option"] = "Selecciona una opción",
        ["A ghost is haunting his graveyard."] = "Un fantasma está rondando su cementerio.",
        ["Oh, the silly fool."] = "Oh, tonto ingenuo.",
        ["I leave town for five months and he's already having problems."] = "Me voy de la ciudad por cinco meses y él ya tiene problemas.",
        ["*sigh*"] = "*suspiro*",
        ["Well, I can't go back and exorcise it - I vowed not to leave this place until I've spent a full two years praying and meditating."] = "Bueno, no puedo regresar y exorcizarlo; prometí no dejar este lugar hasta que haya pasado dos años completos orando y meditando.",
        ["I'll tell you what I can do, though - take this amulet."] = "Sin embargo, te diré lo que puedo hacer: toma este amuleto.",
        ["Sorry, that's not really possible. I don't have space to carry anything. I'll be right back!"] = "Lo siento, eso no es realmente posible. No tengo espacio para llevar nada. ¡Vuelvo enseguida!",
        ["It is a ghostspeak amulet."] = "Es un ghostspeak amulet.",
        ["It's called that because, when you wear it, you can speak to ghosts. Many ghosts are doomed to remain in this world because they have some important task left uncompleted."] = "Se llama así porque, cuando lo usas, puedes hablar con fantasmas. Muchos fantasmas están condenados a permanecer en este mundo porque tienen alguna tarea importante sin terminar.",
        ["If you know what this task is, you can get rid of the ghost. I'm not making any guarantees, mind you, but it's the best I can do right now."] = "Si sabes cuál es esta tarea, podrás deshacerte del fantasma. No te garantizo nada, ojo, pero es lo mejor que puedo hacer ahora.",
        ["Thank you. I'll give it a try."] = "Gracias. Lo intentaré.",
        ["You mean he gets into lots of problems?"] = "¿Quieres decir que se mete en muchos problemas?",
        ["Yeah. Even when we were trainee priests he kept getting stuck up bell ropes."] = "Sí. Incluso cuando éramos sacerdotes en formación, se quedaba atascado en las cuerdas de las campanas.",
        ["Anyway, I don't have time for chit-chat. What's his problem this time?"] = "En fin, no tengo tiempo para charlas. ¿Cuál es su problema esta vez?",
    },
}

dialogues.all = {
    ["[To talk to cats, you need a catspeak amulet. You can get one from Tiny Zemouregal in New Varrock.]"] = "[Para hablar con los gatos, necesitas un amuleto de lengua de gato. Puedes conseguir uno de Tiny Zemouregal en New Varrock.]",
    ["[To talk to cats, you need to wear your catspeak amulet.]"] = "[Para hablar con los gatos, debes usar tu amuleto catspeak.]",
    ["Come on, kitty, time to move on."] = "Vamos, gatito, es hora de seguir adelante.",
    ["P-p-please don't shout at me. I'm s-s-scared of whatever's in that kennel."] = "P-p-por favor no me grites. Tengo mucho miedo de lo que sea que haya en esa perrera.",
    ["Oh, I'm sorry, I didn't mean to frighten you."] = "Oh, lo siento, no quise asustarte.",
    ["It's fine. I'm used to it. I once belonged to a w-w-witch. She didn't treat me too well."] = "Está bien. Estoy acostumbrado. Una vez pertenecí a una bruja. Ella no me trató muy bien.",
    ["B-b-but I did learn a lot."] = "P-p-pero aprendí mucho.",
    ["Well, if you did move on, you'd get away from that kennel."] = "Bueno, si siguieras adelante, te alejarías de esa perrera.",
    ["I th-th-think I need some courage. There's something that would h-h-help."] = "Creo que necesito algo de coraje. Hay algo que ayudaría.",
    ["Name it, and I'll see if I can get it for you."] = "Name y veré si puedo conseguírtelo.",
    ["There's a book - reading it was my only comfort, but it was s-s-stolen. It's hidden in the Zamorak temple, behind the black stone altar slab."] = "Hay un libro. Leerlo fue mi único consuelo, pero me lo robaron. Está escondido en el templo Zamorak, detrás de la losa del altar de piedra negra.",
    ["[As you look at the altar you notice a strange book hidden beneath it.]"] = "[Al mirar el altar, notas un extraño libro escondido debajo.]",
    ["You've found it - the book of power! You fool! At last, it is mine!"] = "Lo has encontrado: ¡el libro del poder! ¡Tonto! ¡Por fin es mío!",
    ["Before you can say anything, the cat snatches the book and confidently strides off in the direction of New Varrock's graveyard..."] = "Antes de que puedas decir algo, el gato agarra el libro y se aleja con confianza en dirección al cementerio de New Varrock...",
    ["You have made progress in the 'A Cat's Bane' Task. ([number]/4)"] = "Has progresado en la tarea \"La perdición de un gato\". ([número]/4)",
    ["I wonder why they all headed off towards the graveyard..."] = "Me pregunto por qué todos se dirigieron hacia el cementerio...",
    ["Poor Fluffs. I wonder what happened to your kittens."] = "Pobre Fluffs. Me pregunto qué pasó con tus gatitos.",
    ["Perhaps you are not such a fool, human. The Necrofelinominom is too powerful, and now in safer paws than mine - those of my new owner, Gertrude."] = "Quizás no seas tan tonto, humano. El Necrofelinominom es demasiado poderoso y ahora está en garras más seguras que las mías: las de mi nuevo dueño, Gertrude.",
    ["What's all this about an Assassin's Contract list."] = "¿Qué es todo eso sobre la lista de contratos de asesino?",
    ["Keep your voice down, and perhaps I'll share my secrets with you."] = "Baja la voz y tal vez comparta mis secretos contigo.",
    ["The Assassin's Contract list is only something for the most worthy."] = "La lista de contratos de The Assassin es sólo algo para los más dignos.",
    ["Ask about.."] = "Pregunta sobre..",
    ["*(Only initially:)*"] = "*(Sólo inicialmente:)*",
    ["I'm worthy"] = "soy digno",
    ["I'm worthy. I'll prove it."] = "Soy digno. Lo probaré.",
    ["I see you've already got a copy of the Assassin's Contract list, take a look at the list and see if your skills are as good as you think!"] = "Veo que ya tienes una copia de la lista de contratos de the Assassin, ¡échale un vistazo a la lista y comprueba si tus habilidades son tan buenas como crees!",
    ["*(Returns to the previous questions.)*"] = "*(Vuelve a las preguntas anteriores.)*",
    ["*(Only after choosing some other option:)*"] = "*(Sólo después de elegir alguna otra opción:)*",
    ["How can I help?"] = "¿Cómo puedo ayudar?",
    ["*(As after the first question.)*"] = "*(Como después de la primera pregunta.)*",
    ["Assassin Contracts"] = "Asesino Contracts",
    ["Assassin's Contracts?"] = "¿Contracts del asesino?",
    ["There's a selection of contracts for aspiring assassins to undertake to test their skills and see if they're worthy."] = "Hay una selección de contracts para que los aspirantes a asesinos se comprometan a probar sus habilidades y ver si son dignos.",
    ["Anything from making antipoison and entering dangerous places, to assassinating specific targets with discretion."] = "Cualquier cosa, desde hacer antiveneno y entrar en lugares peligrosos, hasta asesinar objetivos específicos con discreción.",
    ["Ok, I'll see if my skills are a match for your contracts."] = "Ok, veré si mis habilidades coinciden con las de tu contracts.",
    ["Contagion mixture"] = "Mezcla de contagio",
    ["Contagion, isn't that dangerous?"] = "Contagio, ¿no es peligroso?",
    ["Not in itself, but when put together correctly... it can be lethal."] = "No en sí mismo, pero cuando se combina correctamente... puede ser letal.",
    ["If you can source the reagents I would be most impressed."] = "Si pudiera conseguir los reactivos, estaría muy impresionado.",
    ["What do you need?"] = "¿Qué necesitas?",
    ["This list is for your eyes only, it will require..."] = "Esta lista es sólo para sus ojos, requerirá...",
    ["*(Contagion Reagents book opens.)*"] = "*(Se abre el libro Reactivos de contagio.)*",
    ["Contagion list"] = "Lista de contagios",
    ["Can I see the list again?"] = "¿Puedo ver la lista nuevamente?",
    ["I've got some reagents"] = "tengo algunos reactivos",
    ["*(Without any missing reagents:)*"] = "*(Sin faltar reactivos:)*",
    ["Looks like we're still missing some reagents. See if you can do better."] = "Parece que todavía nos faltan algunos reactivos. Vea si puede hacerlo mejor.",
    ["*(With reagents:)*"] = "*(Con reactivos:)*",
    ["*(If the overload salve is carried:)*"] = "*(Si se lleva el ungüento de sobrecarga:)*",
    ["I've brought you an Overload salve."] = "Te he traído un ungüento para sobrecarga.",
    ["Good work getting that one. This will give the contagion the unstable properties it needs."] = "Buen trabajo consiguiendo ese. Esto le dará al contagio las propiedades inestables que necesita.",
    ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
    ["*(If the divine rocktail bubble is carried:)*"] = "*(Si se lleva la divina burbuja cola de roca:)*",
    ["I've brought you a Divine rocktail bubble."] = "Te he traído una burbuja divina de cola de roca.",
    ["Excellent job in acquiring this. The bubbles will help the contagion spread nicely."] = "Excelente trabajo al adquirir esto. Las burbujas ayudarán a que el contagio se propague bien.",
    ["*(If the empty bird's nest is carried:)*"] = "*(Si se lleva el nido de pájaro vacío:)*",
    ["I've brought you an empty bird's nest."] = "Te he traído un nido de pájaro vacío.",
    ["You've done well to source this. I can weave this into the mix."] = "Has hecho bien en conseguir esto. Puedo incorporar esto a la mezcla.",
    ["*(If the harmonic dust is carried:)*"] = "*(Si se transporta polvo armónico:)*",
    ["I've brought you 134 Harmonic Dust."] = "Te he traído 134 polvo armónico.",
    ["I'll hodl onto those. The contagion will really spread with this, With a bit of a ripple at first, building up in waves and into the ether."] = "Me centraré en . El contagio realmente se extenderá con esto, con como una pequeña onda al principio, acumulándose en ondas y hacia el éter.",
    ["*(If the basiliskbane ore is carried:)*"] = "*(Si se lleva el mineral azote de basilisco:)*",
    ["I've brought you some Basiliskbane ore"] = "Te he traído un poco de mineral Basiliskbane",
    ["Well, I am impressed. The power this will imbibe into the contagion will be perfect."] = "Bueno, estoy impresionado. El poder que esto imbuirá en el contagio será perfecto.",
    ["*(If the sack of onions is carried:)*"] = "*(Si se lleva el saco de cebollas:)*",
    ["I've brought you a sack of onions."] = "Te he traído un saco de cebollas.",
    ["I expected no less. This will add some potency."] = "No esperaba menos. Esto agregará algo de potencia.",
    ["*(If all the reagents have been delivered:)*"] = "*(Si se han entregado todos los reactivos:)*",
    ["You've acquired all the reagents for the Faceless Assasin to make the Contagion and completed one of your Assassin's Contracts."] = "Has adquirido todos los reactivos del Asesino sin rostro para crear el Contagio y has completado uno de tus Contracts de Asesino.",
    ["*(With the task completed:)*"] = "*(Con la tarea completada :)*",
    ["I believe we're done with the reagents for now."] = "Creo que por ahora hemos terminado con los reactivos.",
    ["Don't bother me, can't you see I'm busy?"] = "No me molestes, ¿no ves que estoy ocupado?",
    ["No, I can't... can I go into the factory?"] = "No, no puedo... ¿puedo entrar a la fábrica?",
    ["You can go in. The Consortium, in their infinite wisdom, has decided to open up the factory to all and sundry."] = "Puedes entrar. El Consorcio, en su infinita sabiduría, ha decidido abrir la fábrica a todos.",
    ["How come?"] = "¿Cómo es eso?",
    ["We've built a new blast furnace and always have a shortage of people to work on it."] = "Hemos construido un nuevo alto horno y siempre nos falta gente para trabajar en él.",
    ["I'll have a look, thanks."] = "Echaré un vistazo, gracias.",
    ["Just don't go causing any trouble, I still run this factory!"] = "¡No vayas a causar problemas, todavía dirijo esta fábrica!",
    ["*The dialogue shown depends on which Factory Worker is spoken to.*"] = "*El diálogo que se muestra depende de con qué Factory Worker se habla.*",
    ["What are you dwarves doing in this factory?"] = "¿Qué están haciendo ustedes, enanos, en esta fábrica?",
    ["Working of course, can't you see that?"] = "Funciona, por supuesto, ¿no lo ves?",
    ["But working on what?"] = "¿Pero trabajar en qué?",
    ["Refining the ore that is being brought into the factory, of course."] = "Refinar el mineral que se lleva a la fábrica, por supuesto.",
    ["And what does that mean?"] = "¿Y eso qué significa?",
    ["It means you should stop asking so many questions and get back to work!"] = "¡Significa que debes dejar de hacer tantas preguntas y volver al trabajo!",
    ["Who owns this factory?"] = "¿A quién pertenece esta fábrica?",
    ["The Consortium does and that's all you need to know."] = "El Consorcio sí lo hace y eso es todo lo que necesitas saber.",
    ["But what company? I thought there were all these different companies?"] = "¿Pero qué empresa? Pensé que había todas estas empresas diferentes.",
    ["Oh yes, all the major companies own this plant. It's too vital to be in the hands of one company alone."] = "Oh, sí, todas las empresas importantes son propietarias de esta planta. Es demasiado vital para estar en manos de una sola empresa.",
    ["And what exactly are you doing here?"] = "¿Y qué haces aquí exactamente?",
    ["I tire of these questions. Let me get back to work!"] = "Me canso de estas preguntas. ¡Déjame volver al trabajo!",
    ["I'm sorry, I'm looking for the blast furnace?"] = "Lo siento, ¿estoy buscando el alto horno?",
    ["Do I look like a guide to you?"] = "¿Te parezco una guía?",
    ["No, you look like a hard-working dwarf, but can you please tell me where the blast furnace is?"] = "No, pareces un enano trabajador, pero ¿podrías decirme dónde está el alto horno?",
    ["Alright, just head down the stairs, it's easy to find."] = "Muy bien, baja las escaleras, es fácil de encontrar.",
    ["Thanks."] = "Gracias.",
    ["Are you okay?"] = "¿Estás bien?",
    ["Don't I look okay?"] = "¿No me veo bien?",
    ["If you were any shorter you wouldn't exist."] = "Si fueras más bajo, no existirías.",
    ["Very funny, human."] = "Muy divertido, humano.",
    ["Good day. How may I help you?"] = "Buenos días. ¿Cómo puedo ayudarte?",
    ["I'd Like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
    ["I'd like to check my PIN settings."] = "Me gustaría comprobar la configuración de mi PIN.",
    ["I'd like to see my collection box."] = "Me gustaría ver mi caja de colección.",
    ["What is this place?"] = "¿Qué es este lugar?",
    ["This is a branch of the Bank of RuneScape. We have branches in many towns."] = "Esta es una sucursal del Banco de RuneScape. Disponemos de sucursales en muchas localidades.",
    ["And what do you do?"] = "¿Y tú a qué te dedicas?",
    ["We will look after your items and money for you. Leave your valuables with us if you want to keep them safe."] = "Nos ocuparemos de tus artículos y de tu dinero. Deje sus objetos de valor con nosotros si desea mantenerlos seguros.",
    ["Didn't you used to be called the Bank of Varrock?"] = "¿No te llamaban el Banco de Varrock?",
    ["Yes we did, but people kept on coming into our branches outside of Varrock and telling us that our signs were wrong. They acted as if we didn't know what town we were in or something."] = "Sí, lo hicimos, pero la gente seguía entrando a nuestras sucursales fuera de Varrock y diciéndonos que nuestros carteles estaban equivocados. Actuaron como si no supiéramos en qué ciudad estábamos o algo así.",
    ["What?"] = "¿Qué?",
    ["Before we go any further, I should inform you that you have items ready for collection from the Grand Exchange."] = "Antes de continuar, debo informarle que tiene artículos listos para ser recogidos en Grand Exchange.",
    ["**WHAT WOULD YOU LIKE TO SAY?**"] = "**¿QUÉ TE GUSTARÍA DECIR?**",
    ["What do you do?"] = "¿A qué te dedicas?",
    ["You can store your stuff here if you want. You can dump anything you don't want to carry while you're relaxing in the oasis and pick it up again on the way out."] = "Puedes guardar tus cosas aquí si quieres. Puedes tirar todo lo que no quieras llevar mientras te relajas en el oasis y recogerlo de nuevo al salir.",
    ["To be honest, I'm wasted here. But ever since the Duel Arena collapsed, I don't know where my fighting skills would be best placed."] = "Para ser honesto, estoy perdido aquí. Pero desde que el Duel Arena colapsó, no sé dónde estarían mejor ubicadas mis habilidades de lucha.",
    ["You could always try the Al Kharid security force!"] = "¡Siempre puedes probar la fuerza de seguridad Al Kharid!",
    ["No thanks."] = "No, gracias.",
    ["Do you visit the oasis?"] = "¿Visitas el oasis?",
    ["Do you ever visit the oasis?"] = "¿Alguna vez visitas el oasis?",
    ["When I can. As much as I miss the arena, the oasis is a nice change of scenery. And the crocodiles seem to enjoy the rotten fruit I throw to them. Wanna buy some?"] = "Cuando pueda. Por mucho que extraño la arena, el oasis es un agradable cambio de escenario. Y los cocodrilos parecen disfrutar de la fruta podrida que les tiro. ¿Quieres comprar algunos?",
    ["Yes, please."] = "Sí, por favor.",
    ["No, thanks."] = "No, gracias.",
    ["I'd like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
    ["I'd like to see my Collection box."] = "Me gustaría ver mi caja de Colección.",
    ["Would you like to trade?"] = "¿Le gustaría negociar?",
    ["I suppose so."] = "Supongo que sí.",
    ["There was a moon - close to a lush-looking planet - whose tiny winged inhabitants opened portals to explore the wonders of the universe. This is their story."] = "Había una luna, cercana a un planeta de aspecto exuberante, cuyos diminutos habitantes alados abrían portales para explorar las maravillas del universo. Esta es su historia.",
    ["I discovered my first evidence of the race I would come to know as fairies in my exploration of the myriad nature worlds."] = "Descubrí mi primera evidencia de la raza que llegaría a conocer como hadas en mi exploración de los innumerables mundos de la naturaleza.",
    ["These were environments of wild diversity, prolific with the strangest of fauna and flora, where the strongest survived and the weak were food."] = "Eran entornos de diversidad salvaje, prolíficos con la fauna y la flora más extrañas, donde los más fuertes sobrevivían y los débiles eran alimento.",
    ["Much later, similar creatures were found on Gielinor, such as the jadinko and ganodermic beasts, but with an undeniably common origin."] = "Mucho más tarde, se encontraron criaturas similares en Gielinor, como el jadinko y las bestias ganodermicas, pero con un origen innegablemente común.",
    ["Were they, perhaps, the final products of a great experiment? Could the same hand have forged the Blade that I wielded?"] = "¿Fueron, quizás, los productos finales de un gran experimento? ¿Podría la misma mano haber forjado la espada que yo empuñé?",
    ["On one dark world, teeming with all manner of fungi in its humid jungles and moist swamps, I met with a race of surprisingly intellectual mushrooms."] = "En un mundo oscuro, repleto de todo tipo de hongos en sus selvas húmedas y pantanos húmedos, me encontré con una raza de hongos sorprendentemente intelectuales.",
    ["They lacked mobility, but travelled and reproduced by dispersing spores that fused with the nervous system of local animals, allowing them to control the host."] = "Carecían de movilidad, pero viajaban y se reproducían dispersando esporas que se fusionaban con el sistema nervioso de los animales locales, permitiéndoles controlar al huésped.",
    ["Bonding with me in this way, I was able to communicate with the myceloids. Friendly though they were, it took much persuasion to convince the symbiotic parasites to detach from my brain upon taking root."] = "Al unirme de esta manera, pude comunicarme con los micelios. Aunque eran amigables, fue necesaria mucha persuasión para convencer a los parásitos simbióticos de que se separaran de mi cerebro al echar raíces.",
    ["Another world teemed with insects. A culture of winged invertebrates that bore some resemblance to the fairies of Zanaris, but the swarms were mindless and tirelessly industrious."] = "Otro mundo lleno de insectos. Una cultura de invertebrados alados que guardaba cierto parecido con las hadas de Zanaris, pero los enjambres eran tontos e incansablemente trabajadores.",
    ["The migration of these insects - which was achieved through an innate ability to teleport over short distances - also seemed to have a direct impact on the local climate, for reasons I could not discern."] = "La migración de estos insectos, que se logró mediante una capacidad innata de teletransportarse en distancias cortas, también parecía tener un impacto directo en el clima local, por razones que no pude discernir.",
    ["This brings us to the moon of Zanaris, its dark magical forests, giant fungi and, as I discovered on a return visit, a network of fairy rings they had made from the World Gate I'd placed there."] = "Esto nos lleva a la luna de Zanaris, sus oscuros bosques mágicos, hongos gigantes y, como descubrí en una visita posterior, una red de anillos de hadas que habían hecho a partir de la Puerta del Mundo que había colocado allí.",
    ["The fairies of Zanaris, caretakers of the world below, obviously shared a common ancestry with the creatures I had encountered on the nature worlds."] = "Las hadas de Zanaris, cuidadoras del mundo inferior, obviamente compartían una ascendencia común con las criaturas que había encontrado en los mundos naturales.",
    ["However, they were changed, transcendent, inextricably bound to the abundant magical energy of Gielinor, in order to fulfil a specific purpose."] = "Sin embargo, fueron cambiados, trascendentes, indisolublemente ligados a la abundante energía mágica de Gielinor, para cumplir un propósito específico.",
    ["The fairies are an embodiment of magic - their life-force infused with anima."] = "Las hadas son una encarnación de la magia: su fuerza vital infundida con ánima.",
    ["It is why they work so tirelessly to maintain Gielinor's weather and seasons, for the planet's equilibrium is intrinsic to their own wellbeing."] = "Es por eso que trabajan tan incansablemente para mantener el clima y las estaciones de Gielinor, ya que el equilibrio del planeta es intrínseco a su propio bienestar.",
    ["They have no choice. It is now necessary for their very survival, but they perform their duty without complaint."] = "No tienen otra opción. Ahora es necesario para su supervivencia, pero cumplen con su deber sin quejarse.",
    ["This fairy ring will take you out of Zanaris. It leads to the place known as Al Kharid in your realm. Once passed, you can not return this way. Before leaving, make sure that you have fully sampled the delights of our marketplace."] = "Este anillo de hadas te sacará de Zanaris. Conduce al lugar conocido como Al Kharid en tu reino. Una vez pasado, no se puede volver por este camino. Antes de partir, asegúrese de haber probado todas las delicias de nuestro mercado.",
    ["Select an Option"] = "Selecciona una opción",
    ["I think I'll stay here a bit longer."] = "Creo que me quedaré aquí un poco más.",
    ["I think I'll stay down here a bit longer."] = "Creo que me quedaré aquí un poco más.",
    ["As you wish."] = "Como desees.",
    ["Yes, I'm ready to leave."] = "Sí, estoy listo para partir.",
    ["Hello, my name is Player. Who are you?"] = "Hola, mi nombre es Player. ¿Quién eres?",
    ["Oh hello Player. I'm Aeryka. Aery for short."] = "Oh, hola Player. Soy Aeryka. Aery para abreviar.",
    ["Airy Fairy?"] = "¿Aireado Fairy?",
    ["That's right. What can I do for you?"] = "Así es. ¿Qué puedo hacer por ti?",
    ["What's that crop circle thing doing here?"] = "¿Qué hace ese círculo en las cosechas aquí?",
    ["Crop circle? Oh, you mean the Puromantic portal?"] = "¿Círculo de cultivos? Oh, ¿te refieres al portal Puromantic?",
    ["The pyromanic what?"] = "¿El pirománico qué?",
    ["The Puromantic portal. At least that's what we call them. It's the way the implings travel from Puro-Puro to other planes."] = "El portal Puromántico. Al menos así es como los llamamos. Es la forma en que los implings viajan de Puro-Puro a otros planos.",
    ["Puro-Puro?"] = "¿Puro-Puro?",
    ["The impling home. We call it Puro-Puro. The implings just call it home, I think."] = "El hogar implícito. Lo llamamos Puro-Puro. Creo que los implícitos simplemente lo llaman hogar.",
    ["It's still here."] = "Todavía está aquí.",
    ["Pardon?"] = "¿Perdón?",
    ["It's still here. The crop circle is still here."] = "Todavía está aquí. El círculo de las cosechas todavía está aquí.",
    ["Oh yes, thanks Aery. It didn't go anywhere in the meantime, then?"] = "Oh, sí, gracias Aery. ¿Entonces no llegó a ninguna parte mientras tanto?",
    ["Nope. It just sat there."] = "No. Simplemente se quedó allí.",
    ["Jolly good. I can come back and visit Puro-Puro whenever I want then. Brilliant!"] = "Muy bien. Entonces puedo volver a visitar Puro-Puro cuando quiera. ¡Brillante!",
    ["Is there anything else you want to ask?"] = "¿Hay algo más que quieras preguntar?",
    ["What's in Puro-Puro?"] = "¿Qué hay en Puro-Puro?",
    ["Implings...and wheat."] = "Implicaciones... y trigo.",
    ["Erm, anything else?"] = "Erm, ¿algo más?",
    ["Not really. Though I have noticed quite a lot of you humans travelling through the portal recently. I suppose you must like wheat."] = "En realidad, no. Aunque he notado que muchos de ustedes, humanos, viajan a través del portal recientemente. Supongo que te debe gustar el trigo.",
    ["Well, most of us prefer lobsters to be perfectly honest, but there must be something interesting there."] = "Bueno, para ser honesto, la mayoría de nosotros preferimos las langostas, pero debe haber algo interesante allí.",
    ["Oh, I did notice a very serious-looking gnome go into the portal. Maybe he knows what's going on."] = "Oh, noté que un gnomo de aspecto muy serio entró en el portal. Quizás él sepa lo que está pasando.",
    ["Do you remember what his name was?"] = "¿Recuerdas cómo se llamaba?",
    ["Errm, Egg-nog, or something like that."] = "Errm, ponche de huevo o algo así.",
    ["Right, thanks! I'll have a chat with him when I go. Maybe he'll know what's going on."] = "¡Bien, gracias! Charlaré con él cuando vaya. Quizás él sepa lo que está pasando.",
    ["So what are these implings then?"] = "Entonces, ¿cuáles son estas implicaciones?",
    ["Well, no-one knows for sure. The mischievous little creatures are probably related to imps. And they fly as well. Also, like imps, they love collecting things. I'm not sure why, though. They also seem to like being chased."] = "Bueno, nadie lo sabe con seguridad. Estas pequeñas y traviesas criaturas probablemente estén emparentadas con diablillos. Y también vuelan. Además, al igual que los diablillos, les encanta coleccionar cosas. Aunque no estoy seguro de por qué. También parece que les gusta que los persigan.",
    ["So how would I get hold of what they are carrying, then?"] = "Entonces, ¿cómo podría conseguir lo que llevan?",
    ["Catch them, I suppose. I don't know really. Why would you want to?"] = "Atrápalos, supongo. Realmente no lo sé. ¿Por qué querrías hacerlo?",
    ["Well, if they were carrying something useful. Maybe I could catch them with a big net - like butterflies."] = "Bueno, si llevaran algo útil. Tal vez podría atraparlas con una red grande, como mariposas.",
    ["Sounds a bit cruel to me, but I suppose that's possible."] = "Suena un poco cruel para mí, pero supongo que es posible.",
    ["I've heard I may find dragon equipment in Puro-Puro."] = "He oído que puedo encontrar equipo para dragones en Puro-Puro.",
    ["Really? You humans like that stuff a lot, don't you? I don't like really old stuff myself."] = "¿En serio? A los humanos les gustan mucho esas cosas, ¿no? A mí tampoco me gustan las cosas realmente viejas.",
    ["Old?"] = "¿Viejo?",
    ["Yes, dragon stuff feels really old."] = "Sí, las cosas de dragones parecen muy viejas.",
    ["How can you tell that?"] = "¿Cómo puedes saber eso?",
    ["From its magical aura, obviously. Oh, I forget you humans can't feel auras."] = "Por su aura mágica, obviamente. Oh, olvidé que los humanos no pueden sentir auras.",
    ["How old is old?"] = "¿Cuántos años tiene la edad?",
    ["Really, really, old."] = "De verdad, de verdad, viejo.",
    ["Can you be any more precise?"] = "¿Puedes ser más preciso?",
    ["Not really. Time doesn't really mean a lot round here. Hundreds, maybe thousands of your human lifespans, I suppose. Anyway, it would have to be old since it all comes from the Necrosyrtes."] = "En realidad, no. El tiempo realmente no significa mucho por aquí. Cientos, tal vez miles de vidas humanas, supongo. De todos modos tendría que ser antiguo ya que todo proviene de los Necrosyrtes.",
    ["Necrosyrtes? Who are they?"] = "¿Necrosirtes? ¿Quiénes son?",
    ["Old and powerful creatures. I don't think there have been any around here for aeons. I haven't seen one. I don't think they are very nice. Not like me. Anyway, this is all ancient history. Boooring!"] = "Criaturas viejas y poderosas. No creo que haya habido ninguno por aquí desde hace eones. No he visto ninguno. No creo que sean muy agradables. No como yo. De todos modos, todo esto es historia antigua. ¡Abucheos!",
    ["While I'm on the subject do you have any dragon stuff I can have?"] = "Ya que estoy en el tema, ¿tienes algo de dragón que pueda tener?",
    ["Oh, I did have loads, but I threw it away."] = "Oh, tenía un montón, pero lo tiré.",
    ["Only joking. No, sorry, I can't help you there. You'll have to look for it yourself. Although, maybe if you find Necrosyrtes then they'll give you some. I heard they give dragon stuff away to people they like. Not fairies. We're too nice."] = "Sólo bromeo. No, lo siento, no puedo ayudarte en eso. Tendrás que buscarlo tú mismo. Aunque, tal vez si encuentras Necrosyrtes entonces te darán algunos. He oído que regalan cosas de dragones a la gente que les gusta. No hadas. Somos demasiado amables.",
    ["No, bye!"] = "¡No, adiós!",
    ["See you around!"] = "¡Nos vemos!",
    ["Select an option"] = "Seleccione una opción",
    ["I want to buy a fairy enchantment."] = "Quiero comprar un encantamiento de hadas.",
    ["Here you go!"] = "¡Aquí tienes!",
    ["Talk about something else."] = "Habla de otra cosa.",
    ["Why are you carrying that toolbox?"] = "¿Por qué llevas esa caja de herramientas?",
    ["It's the fizgog! It's picking up cable again!"] = "¡Es el fizgog! ¡Está captando cable otra vez!",
    ["Uh, right. So is it safe to use the fairy rings then?"] = "Ah, claro. Entonces, ¿es seguro usar los anillos de hadas?",
    ["Sure, as long as you have been given permission to use them. You should just be aware that using the fairy rings sometimes has strange results - the locations that you have been to may affect the locations you are trying to reach. I could fix it by replacing the fizgog and the whosprangit; I've put in a request for some new parts, but they're pretty hard to get hold of it seems."] = "Claro, siempre y cuando se te haya dado permiso para usarlos. Sólo debes tener en cuenta que el uso de los anillos de hadas a veces tiene resultados extraños: los lugares en los que has estado pueden afectar los lugares a los que intentas llegar. Podría solucionarlo reemplazando el fizgog y el whosprangit; He solicitado algunas piezas nuevas, pero parece que es bastante difícil conseguirlas.",
    ["Hello, can I help you at all?"] = "Hola, ¿puedo ayudarte en algo?",
    ["What do you do around here?"] = "¿Qué haces por aquí?",
    ["Oh, I'm the resident healer. My name is Nuff, Fairy Nuff. Who are you?"] = "Oh, soy el sanador residente. Mi nombre es Nuff, Fairy Nuff. ¿Quién eres?",
    ["My name is Player."] = "Mi nombre es Player.",
    ["Pleased to meet you, Player. As I was saying, I'm the healer in Zanaris. I graduated over 200 human years ago. Look, there's my Advanced Healing Certificate on the wall. I never go anywhere without it. It's my job to look after the sick, wounded or dying fairies around here. Of course, fairies being magical by nature, not many of them get hurt, so I don't normally have much to do."] = "Encantado de conocerte, Player. Como decía, soy el sanador de Zanaris. Me gradué hace más de 200 años humanos. Mira, ahí está mi Certificado de Curación Avanzada en la pared. Nunca voy a ningún lado sin él. Mi trabajo es cuidar de las hadas enfermas, heridas o moribundas de aquí. Por supuesto, como las hadas son mágicas por naturaleza, no muchas de ellas resultan heridas, así que normalmente no tengo mucho que hacer.",
    ["What about healing humans? Lots of adventurers must get hurt fighting the Otherworldly beings."] = "¿Qué pasa con la curación de humanos? Muchos aventureros deben resultar heridos luchando contra seres del Otro Mundo.",
    ["Yes, they do. Silly isn't it? I do use my healing magic on humans sometimes, but I don't like them attacking our other guests, so I charge them for the service."] = "Sí, lo hacen. Tonto ¿no? A veces uso mi magia curativa con humanos, pero no me gusta que ataquen a nuestros otros invitados, así que les cobro por el servicio.",
    ["How much do you charge to heal someone, then?"] = "¿Cuánto cobras por curar a alguien, entonces?",
    ["Well, the gold that you humans are so fond of has no real value in Zanaris, so I ask my patients to pay me in gems. I will heal 40 life points for an opal, 50 life points for either a sapphire or a piece of jade, 70 life points for an emerald or red topaz, 90 for a ruby and 110 for a diamond."] = "Bueno, el oro que tanto les gusta a los humanos no tiene valor real en Zanaris, así que les pido a mis pacientes que me paguen en gemas. Curaré 40 puntos de vida por un ópalo, 50 puntos de vida por un zafiro o un trozo de jade, 70 puntos de vida por una esmeralda o topacio rojo, 90 por un rubí y 110 por un diamante.",
    ["Only 110 life points for a diamond? Doesn't that seem a bit steep?"] = "¿Solo 110 puntos de vida por un diamante? ¿No parece un poco caro?",
    ["Maybe to you, but you'd be surprised how many adventurers are willing to pay those prices."] = "Quizás para ti, pero te sorprendería saber cuántos aventureros están dispuestos a pagar esos precios.",
    ["No thanks. Just looking around."] = "No, gracias. Sólo mirando a mi alrededor.",
    ["Okay. If you want to know anything, just ask."] = "Está bien. Si quieres saber algo, sólo pregunta.",
    ["Hello Player, do you need any assistance?"] = "Hola Player, ¿necesitas ayuda?",
    ["Yes, please. I need healing."] = "Sí, por favor. Necesito curación.",
    ["Sure, how many life points would you like me to heal?"] = "Claro, ¿cuántos puntos de vida te gustaría que sane?",
    ["40 Life points."] = "40 puntos de vida.",
    ["That will cost you 1 opal."] = "Eso te costará 1 ópalo.",
    ["All right."] = "Muy bien.",
    ["You don't have to pay me!"] = "¡No tienes que pagarme!",
    ["Whoops, sorry."] = "Vaya, lo siento.",
    ["On second thoughts, no thanks."] = "Pensándolo bien, no, gracias.",
    ["Okay, suit yourself."] = "Está bien, haz lo que quieras.",
    ["50 Life points."] = "50 puntos de vida.",
    ["That will cost you 1 sapphire or 1 piece of jade."] = "Eso te costará 1 zafiro o 1 pieza de jade.",
    ["You don't have a sapphire or a piece of jade with you!"] = "¡No llevas ni un zafiro ni un trozo de jade contigo!",
    ["70 Life points."] = "70 puntos de vida.",
    ["That will cost you 1 emerald or 1 red topaz."] = "Eso te costará 1 esmeralda o 1 topacio rojo.",
    ["You don't have an emerald or a red topaz to pay me with!"] = "¡No tienes una esmeralda o un topacio rojo para pagarme!",
    ["90 Life points."] = "90 puntos de vida.",
    ["That will cost you 1 ruby."] = "Eso te costará 1 rubí.",
    ["You don't have a ruby to pay me!"] = "¡No tienes ni un rubí para pagarme!",
    ["110 Life points."] = "110 puntos de vida.",
    ["That will cost you 1 diamond."] = "Eso te costará 1 diamante.",
    ["You don't have a diamond to pay me!"] = "¡No tienes un diamante para pagarme!",
    ["Thank you so much for all you've done for us, Player."] = "Muchas gracias por todo lo que has hecho por nosotros, Player.",
    ["Oh, Player, thanks so much for your help! You're a true friend to us fairies!"] = "Oh, Player, ¡muchas gracias por tu ayuda! ¡Eres un verdadero amigo para nosotras las hadas!",
    ["I have a puzzle for you!"] = "¡Tengo un rompecabezas para ti!",
    ["[Fairy Nuff has given you a puzzle box!]"] = "[¡Fairy Nuff te ha regalado una caja de rompecabezas!]",
    ["Is that your best attempt? You'll have to try harder."] = "¿Es ese tu mejor intento? Tendrás que esforzarte más.",
    ["[Fairy Nuff has given you another clue scroll!]"] = "[¡Fairy Nuff te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["There you go!"] = "¡Ahí lo tienes!",
    ["How do crops and such survive down here?"] = "¿Cómo sobreviven los cultivos y demás aquí abajo?",
    ["How do crops and such survive down here? Surely they need a bit of sunlight?"] = "¿Cómo sobreviven los cultivos y demás aquí abajo? ¿Seguramente necesitan un poco de luz solar?",
    ["Clearly you come from a plane dependent on sunlight. Down here, the plants grow in the aura of faerie."] = "Claramente vienes de un plano que depende de la luz solar. Aquí abajo, las plantas crecen en un aura de hadas.",
    ["What's so good about this place?"] = "¿Qué tiene de bueno este lugar?",
    ["Zanaris is a meeting point of cultures. Those from many worlds converge here to exchange knowledge and goods."] = "Zanaris es un punto de encuentro de culturas. Personas de muchos mundos convergen aquí para intercambiar conocimientos y bienes.",
    ["Have you managed to work out a plan yet?"] = "¿Ya has logrado elaborar un plan?",
    ["Not yet, Player, but it looks like we'll need to ask you for your help again, I'm afraid. I'll be able to tell you more once we have finished making our battle plans."] = "Todavía no, Player, pero parece que tendremos que pedirte ayuda nuevamente, me temo. Podré contarles más una vez que hayamos terminado de hacer nuestros planes de batalla.",
    ["I've lost my magic watering can."] = "He perdido mi regadera mágica.",
    ["Oh, what a nuisance! Have another."] = "¡Oh, qué molestia! Toma otro.",
    ["[The Fairy Queen gives you a magic watering can.]"] = "[El Fairy Queen te ofrece una regadera mágica.]",
    ["Don't fret Player! My farming advisors tell me you added it to your tool belt!"] = "¡No te preocupes Player! ¡Mis asesores agrícolas me dicen que lo agregaste a tu cinturón de herramientas!",
    ["Oh, great! Thanks!"] = "¡Oh, genial! ¡Gracias!",
    ["How's everything in Zanaris?"] = "¿Cómo va todo en Zanaris?",
    ["All seems to be going pretty well now that the Fairy Godfather has been sorted out. Thanks so much for your help with that little problem."] = "Todo parece ir bastante bien ahora que se ha solucionado el padrino de Fairy. Muchas gracias por tu ayuda con ese pequeño problema.",
    ["My pleasure. If you get any other issues you need sorting out, just let me know."] = "Es un placer. Si tienes algún otro problema que necesites solucionar, házmelo saber.",
    ["Ello, sugar. I'm afraid I can't gossip right now, I've got a cake in the oven."] = "Hola, cariño. Me temo que ahora no puedo cotillear, tengo un pastel en el horno.",
    ["Oi you! Did you think I didn't see that? That's my chocolate bar, that is!"] = "¡Oye tú! ¿Pensaste que no vi eso? ¡Esa es mi barra de chocolate, eso es!",
    ["Oh, sorry. I didn't realise it belonged to anybody."] = "Oh, lo siento. No me di cuenta de que pertenecía a nadie.",
    ["That's alright, honey. You look a bit thin anyway. Take it if you need it."] = "Está bien, cariño. Te ves un poco delgada de todos modos. Tómalo si lo necesitas.",
    ["Can I help you at all?"] = "¿Puedo ayudarte en algo?",
    ["Yes, please. What are you selling?"] = "Sí, por favor. ¿Qué estás vendiendo?",
    ["How should I use your shop?"] = "¿Cómo debo utilizar su tienda?",
    ["I'm glad you ask! You can buy as many of the items stocked as you wish. You can also sell most items to the shop."] = "¡Me alegra que lo preguntes! Puede comprar tantos artículos almacenados como desee. También puedes vender la mayoría de los artículos en la tienda.",
    ["*When talking to the Fairy shopkeeper in Zanaris.*"] = "*Al hablar con Fairy shopkeeper en Zanaris.*",
    ["You need to be a level 113 thief to steal from this target."] = "Debes ser un ladrón de nivel 113 para robarle a este objetivo.",
    ["You cannot keep pickpocketing as you have a full inventory."] = "No puedes seguir robando carteras porque tienes un inventario completo.",
    ["You pick the target's pocket."] = "Escoges el bolsillo del objetivo.",
    ["[number] coins have been added to your money pouch."] = "[número] coins se han agregado a su bolsa de dinero.",
    ["*(One of the following dialogues is played:)*"] = "*(Se reproduce uno de los siguientes diálogos:)*",
    ["*(Dialogue 1:)*"] = "*(Diálogo 1:)*",
    ["Err, hello. Do you have any idea what a Winter Fairy actually does?"] = "Err, hola. ¿Tienes alguna idea de lo que realmente hace un Winter Fairy?",
    ["No, no idea at all."] = "No, ni idea.",
    ["Oh, pity. Neither do I, but I'm supposed to be one this week."] = "Oh, lástima. Yo tampoco, pero se supone que lo seré esta semana.",
    ["*(Dialogue 2:)*"] = "*(Diálogo 2:)*",
    ["Have you got any idea where Burthorpe is? The co-ordinator says I need to go there and paint all the leaves yellow, but I've never heard of that place!"] = "¿Tienes alguna idea de dónde está Burthorpe? El coordinador dice que tengo que ir allí y pintar todas las hojas de amarillo, ¡pero nunca había oído hablar de ese lugar!",
    ["*(Dialogue 3:)*"] = "*(Diálogo 3:)*",
    ["Be careful when you pick mushrooms near the strange ruins to the south. Some of them will try to eat you!"] = "Ten cuidado al recoger setas cerca de las extrañas ruinas del sur. ¡Algunos de ellos intentarán comerte!",
    ["*(Dialogue 4:)*"] = "*(Diálogo 4:)*",
    ["I'm afraid I can't stop to chat. I've just been told to get ready to go to Etceteria for some reason or other!"] = "Me temo que no puedo parar a charlar. ¡Me acaban de decir que me prepare para ir a Etceteria por alguna razón u otra!",
    ["*(Dialogue 5:)*"] = "*(Diálogo 5:)*",
    ["Picking mushrooms near the forge will probably end quite badly for you. Not as bad as the ones by the strange ruins to the south though. They're much bigger."] = "Recoger setas cerca de la fragua probablemente terminará bastante mal para ti. Aunque no son tan malos como los de las extrañas ruinas del sur. Son mucho más grandes.",
    ["*(Dialogue 6:)*"] = "*(Diálogo 6:)*",
    ["Sorry, I can't talk I'm looking for Sarah-Jane!"] = "Lo siento, no puedo hablar. ¡Estoy buscando a Sarah-Jane!",
    ["*(Dialogue 7:)*"] = "*(Diálogo 7 :)*",
    ["Is your name Freddie, and are you losing your teeth?"] = "¿Te llamas Freddie y estás perdiendo los dientes?",
    ["Err, no. I'm afraid not."] = "Err, no. Me temo que no.",
    ["Oh, right. You don't have any idea where I can find him do you?"] = "Ah, claro. No tienes idea de dónde puedo encontrarlo, ¿verdad?",
    ["No, I don't know that either."] = "No, yo tampoco lo sé.",
    ["Oh, ok then. If you do find out please let me know. The co-ordinator has sent me to find him."] = "Oh, está bien entonces. Si lo averiguas por favor házmelo saber. El coordinador me ha enviado a buscarlo.",
    ["Hello there."] = "Hola.",
    ["Good day. Can I help you with anything?"] = "Buenos días. ¿Puedo ayudarte con algo?",
    ["Yes, I'd like a drink please."] = "Sí, me gustaría un trago por favor.",
    ["What's going on in town?"] = "¿Qué está pasando en la ciudad?",
    ["Well since you gave the two gangs a good kicking, things have improved hugely. Both gangs seem to be spending all their gold here drowning their sorrows."] = "Bueno, desde que les diste una buena patada a las dos pandillas, las cosas han mejorado enormemente. Ambas bandas parecen estar gastando todo su oro aquí ahogando sus penas.",
    ["That's great! So do I get a cut in the profits?"] = "¡Eso es genial! Entonces, ¿recibo una parte de las ganancias?",
    ["Get out of here, you cheeky rascal. A cut in my profits? As if!"] = "Sal de aquí, bribón descarado. ¿Un recorte en mis ganancias? ¡Como si!",
    ["Nothing much really, the same as you would expect of any border town on the edge of the desert."] = "Nada realmente, lo mismo que se esperaría de cualquier ciudad fronteriza al borde del desierto.",
    ["So can you tell me anything about those two gangs in the town?"] = "Entonces, ¿puedes contarme algo sobre esas dos pandillas en la ciudad?",
    ["Nothing much to really say about them. They're all paying customers so I won't rock the boat if you don't mind."] = "No hay mucho que decir sobre ellos. Todos son clientes que pagan, así que no haré problemas si no te importa.",
    ["Is there anything else I can help you with?"] = "¿Hay algo más en lo que pueda ayudarte?",
    ["No thanks I'm ok."] = "No gracias estoy bien.",
    ["No thanks I'm ok. Thanks for your time."] = "No, gracias, estoy bien. Gracias por tu tiempo.",
    ["Yes, I'd like to talk about something else."] = "Sí, me gustaría hablar de otra cosa.",
    ["The 'Asp and Snake'? What a strange name for a bar."] = "¿El 'Áspide y la Serpiente'? Qué nombre más extraño para un bar.",
    ["I know what you're thinking, asps are a type of snake, right?"] = "Sé lo que estás pensando, los áspides son un tipo de serpiente, ¿verdad?",
    ["I admit it is a little confusing, but neither 'The Asp' nor 'The Snake' have quite the same ring to them."] = "Admito que es un poco confuso, pero ni 'The Asp' ni 'The Snake' suenan igual.",
    ["I get your point. I quite like the name."] = "Entiendo tu punto. Me gusta bastante el nombre.",
    ["*(After The Feud:)* Could you tell Traitorous Hesham that someone has poisoned his drink."] = "*(Después de The Feud:)* ¿Podrías decirle al traidor Hesham que alguien ha envenenado su bebida?",
    ["Could you tell Traitorous Hesham that someone has poisoned his drink."] = "¿Podrías decirle al traidor Hesham que alguien ha envenenado su bebida?",
    ["What! Drink being poisoned in my bar! My reputation could be destroyed if someone died here. Thank you adventurer."] = "¡Qué! ¡Bebe siendo envenenado en mi bar! Mi reputación podría destruirse si alguien muriera aquí. Gracias aventurero.",
    ["No problem at all."] = "No hay ningún problema.",
    ["Here have a beer - it's on the house."] = "Toma una cerveza, la invita la casa.",
    ["Thanks!"] = "¡Gracias!",
    ["Faisal the barman gives you a beer."] = "Faisal the barman te regala una cerveza.",
    ["Congratulations! You have completed: 'Free Beer Here' - Tell Faisal the Barman that Traitorous Hesham's drink was poisoned."] = "¡Felicitaciones! Has completado: 'Cerveza gratis aquí' - Dile a Faisal the Barman que la bebida del Traidor Hesham fue envenenada.",
    ["Thanks but no thanks, I don't drink."] = "Gracias pero no gracias, no bebo.",
    ["Don't say that around here too loud please, it may catch and then I'd be out of business."] = "No digas eso por aquí demasiado alto, por favor, puede sonar y entonces me quedaría sin negocio.",
    ["You could always open up a non alcoholic fruit juice bar. You'd have less problems with drunken customers."] = "Siempre puedes abrir una barra de jugos de frutas sin alcohol. Tendrías menos problemas con clientes borrachos.",
    ["You might be onto something there, but then what would I do with the drunken sailor?"] = "Puede que tengas algo ahí, pero entonces, ¿qué haría con el drunken sailor?",
    ["Who?"] = "¿Quién?",
    ["Jalal the Drunk. Oh never mind its a long story."] = "Jalal the Drunk. Oh, no importa, es una larga historia.",
    ["Yuck! I don't like beer."] = "¡Qué asco! No me gusta la cerveza.",
    ["Fine, no need to insult me then."] = "Bien, entonces no necesitas insultarme.",
    ["Woo woo."] = "Guau, guau.",
    ["If only there was an item I could wear that would help me communicate with you..."] = "Si tan solo hubiera un artículo que pudiera usar y que me ayudara a comunicarme con ustedes...",
    ["Woo woo wooo. (You can't make out the words but you sense whatever she's saying is laced with sarcasm)"] = "Woo woo wooo. (No puedes distinguir las palabras pero sientes que todo lo que dice está lleno de sarcasmo)",
    ["So your journey has finally led you here, Slayer!"] = "¡Así que tu viaje finalmente te ha llevado hasta aquí, Slayer!",
    ["Who's there?"] = "¿Quién está ahí?",
    ["Ah, I am but a spirit now. Bound forever to this place to preserve everything we hold sacred."] = "Ah, ahora no soy más que un espíritu. Unidos para siempre a este lugar para preservar todo lo que consideramos sagrado.",
    ["This is where it all began. Where I, one of the seven original Slayer Masters, placed my sword down and swore that I would forever more be dedicated to the deliverance of souls to the afterlife. Welcome to the Order of the Slayers. This is the origin of everything you have trained for. My life ended long ago but little did I know my promise truly meant forever. And you are here because it is time for you to begin your journey to becoming a Slayer Master."] = "Aquí es donde empezó todo. Donde yo, uno de los siete Slayer Masters originales, puse mi espada y juré que siempre estaría dedicado a la liberación de almas al más allá. Bienvenidos a la Orden de los Cazadores. Este es el origen de todo para lo que te has entrenado. Mi vida terminó hace mucho tiempo, pero no sabía que mi promesa realmente significaba para siempre. Y usted está aquí porque es hora de que comience su viaje para convertirse en Slayer Master.",
    ["Yes, if you accept, over time I will teach you everything there is to know about our Order. So, do you wish to begin?"] = "Sí, si aceptas, con el tiempo te enseñaré todo lo que hay que saber sobre nuestra Orden. Entonces, ¿quieres empezar?",
    ["Start training to become a Slayer Master?"] = "¿Empezar a entrenar para convertirte en un Slayer Master?",
    ["Yes."] = "Sí.",
    ["Excellent."] = "Excelente.",
    ["So what do I need to do?"] = "Entonces, ¿qué debo hacer?",
    ["We need to go back to the start. All the monsters you have fought and killed so far have developed your combat skills against them, but that is not enough. Now it is time to understand them. Every creature has a soul - that spark within them that is the basis for everything that they are. As part of your training to become a Slayer Master, I request your assistance. The Order is in ruins covered in a magic that has locked away the secrets of our past. You must capture these souls and deliver them back here. Each soul gathered will weaken the spell that we placed over the Order all those years ago. And in return I will offer you further training."] = "Necesitamos volver al principio. Todos los monstruos con los que has luchado y matado hasta ahora han desarrollado tus habilidades de combate contra ellos, pero eso no es suficiente. Ahora es el momento de entenderlos. Cada criatura tiene un alma, esa chispa dentro de ellas que es la base de todo lo que son. Como parte de tu formación para convertirte en Slayer Master, solicito tu ayuda. La Orden está en ruinas cubierta por una magia que ha encerrado los secretos de nuestro pasado. Debes capturar estas almas y devolverlas aquí. Cada alma reunida debilitará el hechizo que colocamos sobre la Orden hace tantos años. Y a cambio te ofreceré más formación.",
    ["I have to capture the soul of every Slayer creature?"] = "¿Tengo que capturar el alma de cada criatura Slayer?",
    ["I never said the journey was going to be easy. If you wish to give up, you may leave now. I have waited this long, I can wait more if required."] = "Nunca dije que el viaje iba a ser fácil. Si deseas rendirte, puedes irte ahora. He esperado tanto tiempo, puedo esperar más si es necesario.",
    ["I'm ready."] = "Estoy listo.",
    ["*(If you don't have two empty inventory slots:)*"] = "*(Si no tienes dos espacios de inventario vacíos:)*",
    ["You need 2 free inventory spaces for the next step of your training."] = "Necesitas 2 espacios de inventario gratuitos para el siguiente paso de tu capacitación.",
    ["*(Dialogue terminates. After clearing inventory, the dialogue begins again at **Faiza:** Excellent.)*"] = "*(El diálogo termina. Después de limpiar el inventario, el diálogo comienza nuevamente en **Faiza:** Excelente.)*",
    ["*(If you have two empty inventory slots:)*"] = "*(Si tienes dos espacios de inventario vacíos:)*",
    ["*Faiza gives you some empty ushtabi and a Slayer Codex.*"] = "*Faiza te ofrece algunos ushtabi vacíos y un códice Slayer.*",
    ["These ushabti are vessels that can contain the soul of a Slayer monster. Simply kill a monster with one of these with you and it has a chance of capturing the creature's soul. Bring it back here and you can deliver the soul in return for greater understanding and take another step on your way to becoming a Slayer Master. The Codex in turn will allow you to track your progress. As you capture each monster it will be marked in the Codex, this will lead to a greater understanding which in turn comes with its own rewards."] = "Estos ushabti son recipientes que pueden contener el alma de un monstruo Slayer. Simplemente mata a un monstruo con uno de estos contigo y tendrás la posibilidad de capturar el alma de la criatura. Tráelo de vuelta aquí y podrás entregar el alma a cambio de una mayor comprensión y dar un paso más en tu camino para convertirte en un Slayer Master. El Codex, a su vez, te permitirá seguir tu progreso. A medida que captures cada monstruo, se marcará en el Códice, lo que conducirá a una mayor comprensión que a su vez viene con sus propias recompensas.",
    ["*You can now purchase more ushabti from the Slayer Masters around the world.*"] = "*Ahora puedes comprar más ushabti de Slayer Masters en todo el mundo.*",
    ["*(Continues with normal dialogue below.)*"] = "*(Continúa con el diálogo normal a continuación.)*",
    ["Sorry, but I have better things to do!"] = "Lo siento, ¡pero tengo mejores cosas que hacer!",
    ["*(Dialogue terminates. After returning, the dialogue begins again at **Faiza:** Excellent.)*"] = "*(El diálogo termina. Después de regresar, el diálogo comienza nuevamente en **Faiza:** Excelente.)*",
    ["A disappointing answer, however if this is your desire I cannot interfere. However the offer remains; you are welcome to return at any time and begin your training."] = "Una respuesta decepcionante, sin embargo, si este es tu deseo, no puedo interferir. Sin embargo la oferta permanece; Eres bienvenido a regresar en cualquier momento y comenzar tu entrenamiento.",
    ["Welcome back, Slayer."] = "Bienvenido de nuevo, Slayer.",
    ["*(If you are eligible for a free ushtabi (given for each Slayer level above 99):*"] = "*(Si eres elegible para recibir un ushtabi gratis (otorgado por cada nivel de Slayer superior a 99):*",
    ["*Faiza gives you an empty ushtabi.*"] = "*Faiza te da un ushtabi vacío.*",
    ["*(If you have lost Slayer Codex:)*"] = "*(Si has perdido el Códice Slayer:)*",
    ["It seems you have lost your Slayer Codex. Would you like another?"] = "Parece que has perdido tu códice Slayer. ¿Quieres otro?",
    ["Faiza gives you a Slayer Codex."] = "Faiza te ofrece un códice Slayer.",
    ["*(Continues with normal dialogue.)*"] = "*(Continúa con el diálogo normal.)*",
    ["Can you explain what I need to do?"] = "¿Puedes explicar lo que tengo que hacer?",
    ["We need to go back to the start. All the monsters you have fought against and killed so far have developed your combat skills against them but that is not enough. Now it is time to understand them. Every creature has a soul - that spark within them that is the basis for everything that they are. As part of your training to become a Slayer Master, I request your assistance. The Order is in ruins covered in magic that has locked away the secrets of our past. You must capture these souls and deliver them back here. Each soul gathered will weaken the spell that we placed over the Order all those years ago. And in return, I will offer you further training."] = "Necesitamos volver al principio. Todos los monstruos contra los que has luchado y matado hasta ahora han desarrollado tus habilidades de combate contra ellos, pero eso no es suficiente. Ahora es el momento de entenderlos. Cada criatura tiene un alma, esa chispa dentro de ellas que es la base de todo lo que son. Como parte de tu formación para convertirte en Slayer Master, solicito tu ayuda. La Orden está en ruinas cubierta de magia que ha encerrado los secretos de nuestro pasado. Debes capturar estas almas y devolverlas aquí. Cada alma reunida debilitará el hechizo que colocamos sobre la Orden hace tantos años. Y a cambio te ofreceré más formación.",
    ["I have to capture the soul of every slayer creature?"] = "¿Tengo que capturar el alma de cada criatura asesina?",
    ["I never said the journey was going to be easy. These ushtabi are vessels that can contain the soul of a Slayer monster. Simple kill a monster with one of these with you and it has a chance of capturing the creature's soul. Bring it back here and you can deliver the soul in return for greater understanding and take another step on your way to becoming a Slayer Master."] = "Nunca dije que el viaje iba a ser fácil. Estos ushtabi son recipientes que pueden contener el alma de un monstruo Slayer. Simplemente mata a un monstruo con uno de estos contigo y tendrás la posibilidad de capturar el alma de la criatura. Tráelo de vuelta aquí y podrás entregar el alma a cambio de una mayor comprensión y dar un paso más en tu camino para convertirte en un Slayer Master.",
    ["You can purchase more ushtabi from Slayer Masters around the world."] = "Puedes comprar más ushtabi en Slayer Masters en todo el mundo.",
    ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
    ["What is the best way to catch a soul?"] = "¿Cuál es la mejor manera de atrapar un alma?",
    ["As your understanding of Slayer increases, the chance of catching a soul significantly increases. Additionally, being on a Slayer task increases your chance of capturing the soul."] = "A medida que aumenta su comprensión de Slayer, la posibilidad de atrapar un alma aumenta significativamente. Además, estar en una tarea Slayer aumenta tus posibilidades de capturar el alma.",
    ["What else can I do with these souls?"] = "¿Qué más puedo hacer con estas almas?",
    ["If understanding is not enough you can also capture these souls and bring them here. Within these walls, the soul remains in stasis unable to move to the afterlife. You may wish to release a soul in one of the rooms ahead. There they will stay, under your command, allowing you to kill them over and over again. You may find this useful if you are on a Slayer task. There are others that have also found this place and they too wish to learn the secrets of the Order. If you meet one of those people, perhaps they would allow you to witness the spirits they have captured."] = "Si la comprensión no es suficiente, también puedes capturar estas almas y traerlas aquí. Dentro de estos muros, el alma permanece en estasis incapaz de pasar al más allá. Es posible que desees liberar un alma en una de las habitaciones más adelante. Allí permanecerán, bajo tu mando, permitiéndote matarlos una y otra vez. Puede que esto le resulte útil si se encuentra en una tarea Slayer. Hay otros que también han encontrado este lugar y también desean conocer los secretos de la Orden. Si conoces a una de esas personas, tal vez te permitan presenciar los espíritus que han capturado.",
    ["What can you tell me about the Order?"] = "¿Qué me puedes contar sobre la Orden?",
    ["That can wait. First capture some souls and begin your journey of understanding."] = "Eso puede esperar. Primero captura algunas almas y comienza tu viaje de comprensión.",
    ["I have to go now."] = "Tengo que irme ahora.",
    ["Farewell."] = "Adiós.",
    ["For both meeting Morvran's Platinum Rush of Blood challenge and completing the Slayer Codex, you have unlocked the title "] = "Tanto para superar el desafío Platinum Rush of Blood de Morvran como para completar el Códice Slayer, has desbloqueado el título ",
    ["Welcome, welcome! It's wonderful to see a fresh face. You'll need to speak to Orla to get a rundown of our research before I can help you."] = "¡Bienvenido, bienvenido! Es maravilloso ver una cara nueva. Tendrás que hablar con Orla para obtener un resumen de nuestra investigación antes de que pueda ayudarte.",
    ["Ah, excellent - a new volunteer! You're already on your way, but I have plenty to share with you. Shall we get started?"] = "Ah, excelente, ¡un nuevo voluntario! Ya estás en camino, pero tengo mucho que compartir contigo. ¿Empezamos?",
    ["First, we will learn how to make portents. These varied items can be held in your inventory for different effects. Why don't you try and make one?"] = "Primero, aprenderemos a hacer portentos. Estos variados elementos se pueden guardar en su inventario para lograr diferentes efectos. ¿Por qué no intentas hacer uno?",
    ["Not at the moment, thanks."] = "Por el momento no, gracias.",
    ["*After creating a portent:*"] = "*Después de crear un presagio:*",
    ["I have much more to show you! Would you like to continue with my lessons?"] = "¡Tengo mucho más que mostrarte! ¿Te gustaría continuar con mis lecciones?",
    ["Select an otpion"] = "Selecciona una opción",
    ["Yes!"] = "¡Sí!",
    ["You've made a portent, so it's time for something more advanced. Why not try your hand at a divine location?"] = "Has hecho un presagio, así que es hora de algo más avanzado. ¿Por qué no probar suerte en un lugar divino?",
    ["*After creating a divine location:*"] = "*Después de crear una ubicación divina:*",
    ["You are proving to be an excellent pupil! Would you like to learn more?"] = "¡Estás demostrando ser un excelente alumno! ¿Quieres saber más?",
    ["Well the next logical step seems to be to learn about signs. These useful little items can be worn in your pocket slot for various effects! Make one, and see what benefit it gives you."] = "Bueno, el siguiente paso lógico parece ser aprender sobre las señales. ¡Estos pequeños y útiles objetos se pueden llevar en la ranura de tu bolsillo para conseguir diversos efectos! Haga uno y vea qué beneficio le brinda.",
    ["*After creating a sign and with Divination level 10 or higher:*"] = "*Después de crear un letrero y con Divination nivel 10 o superior:*",
    ["This is my very latest discovery. Would you like me to share it with you?"] = "Este es mi último descubrimiento. ¿Quieres que lo comparta contigo?",
    ["As you increase your skill in divination, you'll find yourself moving on to more complex wisps. It just so happens I've discovered something useful for that very situation! With a large amount of divine energy of the correct tier, you will be able to make a boon. This means you will be more effective when converting memories of the tier for which your boon was made, giving you a greater return! Why don't you give it a go?"] = "A medida que aumentes tu habilidad en adivinación, te encontrarás pasando a mechones más complejos. ¡Da la casualidad de que descubrí algo útil para esa misma situación! Con una gran cantidad de energía divina del nivel correcto, podrás realizar una bendición. Esto significa que serás más efectivo al convertir recuerdos del nivel para el cual se creó tu bendición, ¡lo que te brindará un mayor retorno! ¿Por qué no lo intentas?",
    ["I'm afraid my lessons are slightly too advanced for you at the moment. When you've increased your experience in divination, though, please do come and see me."] = "Me temo que mis lecciones son demasiado avanzadas para ti en este momento. Sin embargo, cuando hayas aumentado tu experiencia en adivinación, por favor ven a verme.",
    ["You need Divination level <13> to continue with Faizan's lessons."] = "Necesitas el nivel Divination <13> para continuar con las lecciones de Faizan.",
    ["*After creating a boon:*"] = "*Después de crear una bendición:*",
    ["Your knowledge of divination currently equals my own. Orla tells me she's discovered something new, though. Perhaps you should speak to her!"] = "Tu conocimiento de adivinación actualmente es igual al mío. Sin embargo, Orla me dice que ha descubierto algo nuevo. ¡Quizás deberías hablar con ella!",
    ["Ok, I'll speak to Orla."] = "Ok, hablaré con Orla.",
    ["I'd like to ask about portents."] = "Me gustaría preguntar sobre los presagios.",
    ["How do I make portents?"] = "¿Cómo hago portentos?",
    ["**Faizan Augour:** First, you'll need to find out what ingredients you need to make your chosen portent. All portents require some tier of divine energy and a secondary ingredient. Then, simply weave the divine energy to make your portent. This can be done straight from your backpack - no need for any tools."] = "**Faizan Augour:** Primero, necesitarás averiguar qué ingredientes necesitas para hacer el portento elegido. Todos los portentos requieren algún nivel de energía divina y un ingrediente secundario. Luego, simplemente entreteje la energía divina para hacer tu portento. Esto se puede hacer directamente desde su backpack, sin necesidad de herramientas.",
    ["How do I use portents?"] = "¿Cómo uso los portentos?",
    ["How do I make signs?"] = "¿Cómo hago carteles?",
    ["How do I use signs?"] = "¿Cómo uso los signos?",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["**Faizan Augour:** When a portent has been created, it can be kept in your inventory. Its effect will kick in automatically when needed - without you having to activate it!"] = "**Faizan Augour:** Cuando se ha creado un portento, se puede guardar en su inventario. Su efecto se activará automáticamente cuando sea necesario, ¡sin que tengas que activarlo!",
    ["How do you make portents?"] = "¿Cómo se hacen presagios?",
    ["How do you make signs?"] = "¿Cómo se hacen los carteles?",
    ["How do you use signs?"] = "¿Cómo se utilizan los signos?",
    ["I'd like to ask about divine locations."] = "Me gustaría preguntar sobre lugares divinos.",
    ["How do I make divine locations?"] = "¿Cómo hago lugares divinos?",
    ["**Faizan Augour:** Well first you'll need the ingredients. All divine locations require some tier of divine energy and a secondary ingredient. The secondary ingredient will most likely be a sample of what you would expect to get from your divine location. For example, if you're making a divine bronze rock, you'll need either copper or tin ore. Be aware that you may need a large amount of that secondary ingredient. When you've got your ingredients, you just need to weave the divine energy. Remember that you can do this anywhere, and you don't need any tools."] = "**Faizan Augour:** Bueno, primero necesitarás los ingredientes. Todos los lugares divinos requieren algún nivel de energía divina y un ingrediente secundario. Lo más probable es que el ingrediente secundario sea una muestra de lo que esperarías obtener de tu ubicación divina. Por ejemplo, si estás haciendo una roca de bronce divina, necesitarás mineral de cobre o estaño. Tenga en cuenta que es posible que necesite una gran cantidad de ese ingrediente secundario. Cuando tengas tus ingredientes, sólo necesitas tejer la energía divina. Recuerda que puedes hacer esto en cualquier lugar y no necesitas ninguna herramienta.",
    ["How do you use divine locations?"] = "¿Cómo se utilizan las ubicaciones divinas?",
    ["How do I use divine locations?"] = "¿Cómo uso ubicaciones divinas?",
    ["**Faizan Augour:** When you've made a divine location, you can place it and use it much like anywhere you would gather resources normally, for example a tree, or an ore rock. It's beneficial to place them in busy areas, as others can use your location too. When they do, there's a chance that you'll get additional resources."] = "**Faizan Augour:** Cuando hayas creado una ubicación divina, puedes colocarla y usarla como en cualquier lugar donde normalmente recolectarías recursos, por ejemplo, un árbol o una roca mineral. Es beneficioso colocarlos en áreas concurridas, ya que otros también pueden usar su ubicación. Cuando lo hagan, existe la posibilidad de que obtenga recursos adicionales.",
    ["How do you make divine locations?"] = "¿Cómo se crean lugares divinos?",
    ["I'd like to ask about signs."] = "Me gustaría preguntar sobre las señales.",
    ["**Faizan Augour:** Much like portents, you just need some divine energy of the correct tier and a secondary ingredient. Weave the divine energy straight from your backpack to make your chosen sign, no tools required."] = "**Faizan Augour:** Al igual que los portentos, solo necesitas algo de energía divina del nivel correcto y un ingrediente secundario. Entreteje la energía divina directamente desde tu backpack para hacer el letrero que elijas, sin necesidad de herramientas.",
    ["To use a sign, you simply need to equip it! It will then sit in your pocket, dormant, until it is triggered. The point at which it is triggered depends on the purpose of the sign, of course."] = "¡Para usar un letrero, simplemente necesitas equiparlo! Luego permanecerá en su bolsillo, inactivo, hasta que se active. El momento en el que se activa depende, por supuesto, del propósito del signo.",
    ["How do you use portents?"] = "¿Cómo se utilizan los portentos?",
    ["I'd like to ask about boons."] = "Me gustaría preguntar sobre las bendiciones.",
    ["Ah, boons are particularly interesting. To make one, you will need a large amount of divine energy of the correct tier. Weave the divine energy to make your selected boon. As before, this can be done anywhere - straight from your backpack - and doesn't require any tools. The boon will be automatically applied to you, giving you a permanent, passive benefit. Then, when converting memories of the same tier as that boon, you will receive additional experience or divine energy."] = "Ah, las bendiciones son particularmente interesantes. Para hacer uno, necesitarás una gran cantidad de energía divina del nivel correcto. Teje la energía divina para hacer tu bendición seleccionada. Como antes, esto se puede hacer en cualquier lugar, directamente desde su backpack, y no requiere ninguna herramienta. La bendición se le aplicará automáticamente, brindándole un beneficio pasivo permanente. Luego, al convertir recuerdos del mismo nivel que esa bendición, recibirás experiencia adicional o energía divina.",
    ["Thanks for the explanation."] = "Gracias por la explicación.",
    ["I have made one further discovery. Would you like me to share it with you?"] = "He hecho un descubrimiento más. ¿Quieres que lo comparta contigo?",
    ["I have discovered you can use divine energy to change one item into another! Just take the correct tier and amount of divine energy, along with a secondary ingredient, and you are able to produce a higher quality object. You should try it!"] = "¡He descubierto que puedes usar energía divina para transformar un objeto en otro! Simplemente tome el nivel y la cantidad correctos de energía divina, junto con un ingrediente secundario, y podrá producir un objeto de mayor calidad. ¡Deberías probarlo!",
    ["Ah, my favourite volunteer! You should speak to Orla; she has something to congratulate you on your achievement in divination so far."] = "¡Ah, mi voluntario favorito! Deberías hablar con Orla; Ella tiene algo para felicitarte por tus logros en adivinación hasta ahora.",
    ["Ah, my favourite volunteer! What can I do for you?"] = "¡Ah, mi voluntario favorito! ¿Qué puedo hacer por ti?",
    ["I'd like to ask about signs and portents."] = "Me gustaría preguntar sobre señales y presagios.",
    ["I'd like to ask about transmutation."] = "Me gustaría preguntar sobre la transmutación.",
    ["Transmutation is a most interesting application of divine energy. It seems you can take an item, combine it with divine energy and transform it into a greater one!"] = "La transmutación es una aplicación muy interesante de la energía divina. ¡Parece que puedes tomar un objeto, combinarlo con energía divina y transformarlo en uno mayor!",
    ["For example, we can transmute logs into oak logs; iron ore into silver ore... The possibilities are tremendous!"] = "Por ejemplo, podemos transmutar logs en oak logs; mineral de hierro en mineral de plata... ¡Las posibilidades son tremendas!",
    ["To do this, you will need an amount of divine energy of the correct tier, and a secondary ingredient. It seems that some of the secondary ingredient is destroyed in the process, so it is likely that you will need a good amount."] = "Para hacer esto, necesitarás una cantidad de energía divina del nivel correcto y un ingrediente secundario. Parece que parte del ingrediente secundario se destruye en el proceso, por lo que es probable que necesites una buena cantidad.",
    ["When you have your ingredients, weave your divine energy and conduct your transmutation!"] = "¡Cuando tengas tus ingredientes, teje tu energía divina y lleva a cabo tu transmutación!",
    ["Greetings! Duke Horacio has called for aid, and Falador answers! While we'd love to help our fellow Saradominists battle the evil forces of Zamorak, our primary duty is to protect the citizens of Lumbridge. Fear not, we shall protect you from any Zamorakian scum that decides to wander out of the crater!"] = "¡Saludos! ¡Duke Horacio ha pedido ayuda y Falador responde! Si bien nos encantaría ayudar a nuestros compañeros saradoministas a luchar contra las fuerzas malignas de Zamorak, nuestro deber principal es proteger a los ciudadanos de Lumbridge. ¡No temas, te protegeremos de cualquier escoria zamorakiana que decida salir del cráter!",
    ["Not gonna' introduce ya'self then?"] = "¿No te vas a presentar entonces?",
    ["Thank you for heeding my call, human."] = "Gracias por atender mi llamado, humano.",
    ["It's hard to ignore a demon stepping out of a bonfire."] = "Es difícil ignorar a un demonio que sale de una hoguera.",
    ["I have been sent as an emissary of the Queen of Ashes, and require any and all help."] = "Me han enviado como emisario de la Reina de las Cenizas y necesito toda la ayuda.",
    ["What is it you need?"] = "¿Qué es lo que necesitas?",
    ["Many interesting embers have been turning up in this world, and my Queen wishes to analyse their properties. Collect as many burning embers as possible and bring them back to me."] = "Muchas brasas interesantes han ido apareciendo en este mundo, y mi Reina desea analizar sus propiedades. Recoge tantas brasas encendidas como puedas y tráemelas.",
    ["Sounds simple enough."] = "Suena bastante simple.",
    ["What are you?"] = "¿Qué eres?",
    ["A failed experiment. Considered unworthy. Incredibly angry. Redeemed by Fire."] = "Un experimento fallido. Considerado indigno. Increíblemente enojado. Redimidos por el fuego.",
    ["It sounds like you've got a pretty large grudge against someone."] = "Parece que tienes un gran rencor contra alguien.",
    ["That's not even the half of it."] = "Eso no es ni la mitad.",
    ["What do you plan to do with these Burning Embers?"] = "¿Qué planeas hacer con estas brasas ardientes?",
    ["Some questions are best left unanswered, human."] = "Es mejor dejar algunas preguntas sin respuesta, humano.",
    ["Like 'What's your relationship with Zaros'?"] = "Como '¿Cuál es tu relación con Zaros'?",
    ["Yes, like that one."] = "Sí, como ese.",
    ["How did you get here?"] = "¿Cómo llegaste aquí?",
    ["My Queen noticed this world appear in the heavens as if it had been revealed from behind a curtain. Last year she felt an increase in fire energy in this location. She had her pyradins spend a year preparing to use that energy. With it, she could bring me through the planes, in the hopes that the energy would build up once more."] = "Mi Reina notó que este mundo aparecía en los cielos como si hubiera sido revelado detrás de una cortina. El año pasado sintió un aumento en la energía del fuego en este lugar. Hizo que sus piradins pasaran un año preparándose para usar esa energía. Con él, podría llevarme a través de los planos, con la esperanza de que la energía se acumulara una vez más.",
    ["You worked an entire year in the hope that the energy might return?"] = "¿Trabajaste un año entero con la esperanza de que la energía regresara?",
    ["I did not personally; my task is to act as scout and herald for my Queen; to seek worlds that are ready for her Enlightenment, and deliver messages between those who are already Enlightened."] = "Yo personalmente no; mi tarea es actuar como explorador y heraldo de mi Reina; buscar mundos que estén listos para su Iluminación y entregar mensajes entre aquellos que ya están Iluminados.",
    ["How long will you be around for?"] = "¿Cuánto tiempo estarás aquí?",
    ["Without a continuous source, all fire comes to an end. I can only last here for the amount of time my Queen's strength allows me. Be sure to collect my embers quickly!"] = "Sin una fuente continua, todo fuego llega a su fin. Sólo puedo durar aquí el tiempo que me permita la fuerza de mi Reina. ¡Asegúrate de recoger mis brasas rápidamente!",
    ["*(Only after asking one of the latter two questions:)*"] = "*(Sólo después de hacer una de las dos últimas preguntas :)*",
    ["Who is the Queen of Ashes?"] = "¿Quién es la Reina de las Cenizas?",
    ["A redeemer, and life-giver. My queen accepted me for what I was, and gave me a second chance in life. Soon, Gielinor will feel the same redemption."] = "Un redentor y dador de vida. Mi reina me aceptó tal como era y me dio una segunda oportunidad en la vida. Pronto, Gielinor sentirá la misma redención.",
    ["How soon is 'soon'?"] = "¿Qué tan pronto es \"pronto\"?",
    ["The Queen of Ashes rushes nothing, small one. She is biding her time and will arrive when she feels this world is ready."] = "La Reina de las Cenizas no se apresura, pequeña. Ella está esperando su momento y llegará cuando sienta que este mundo está listo.",
    ["So... soon?"] = "Entonces... ¿pronto?",
    ["Yes, soon."] = "Sí, pronto.",
    ["Thank you for helping me collect these particular burning embers. I still have some time here to thank you for your efforts. Soon I will depart, but rest assured you will be hearing from my Queen in the near future."] = "Gracias por ayudarme a recolectar estas brasas ardientes en particular. Todavía tengo algo de tiempo aquí para agradecerles por sus esfuerzos. Pronto partiré, pero ten por seguro que tendrás noticias de mi Reina en un futuro próximo.",
    ["*(As during the event.)*"] = "*(Como durante el evento.)*",
    ["*(Only after asking something else:)*"] = "*(Solo después de preguntar algo más :)*",
    ["*(If a reward isn't unlocked:)*"] = "*(Si una recompensa no está desbloqueada:)*",
    ["I require more offerings before I can reward you."] = "Necesito más ofertas antes de poder recompensarte.",
    ["*(If a reward is unlocked:)*"] = "*(Si se desbloquea una recompensa:)*",
    ["There you are!"] = "¡Ahí estás!",
    ["*(Without rewards to claim and none claimed:)*"] = "*(Sin recompensas para reclamar y ninguna reclamada:)*",
    ["You'll need to help me some more before I can offer you any rewards."] = "Tendrás que ayudarme un poco más antes de poder ofrecerte alguna recompensa.",
    ["*(Without rewards to claim and some claimed:)*"] = "*(Sin recompensas que reclamar y algunas reclamadas:)*",
    ["*(Without all rewards claimed:)*"] = "*(Sin todas las recompensas reclamadas :)*",
    ["You've already claimed all of the rewards I have to offer."] = "Ya has reclamado todas las recompensas que tengo para ofrecer.",
    ["Tell me about the Drop: 15th Anniversary Edition."] = "Háblame de Drop: Edición del 15.º aniversario.",
    ["*If the player completed Deathcon II*"] = "*Si el player completó Deathcon II*",
    ["Hello again sugar, my clever friend who completed the puzzle book."] = "Hola de nuevo, cariño, mi inteligente amiga que completó el libro de rompecabezas.",
    ["I'm back, by popular demand. For the 15th Aniversary celebrations they've asked me to host a special edition of The Drop. We've hand-picked questions all about the history of RuneScape. If you get them all right, you'll get a new title and a huge prismatic star! I'm sure you'll be a winner in no time, you can't keep talent down."] = "Estoy de regreso, por demanda popular. Para las celebraciones del 15º aniversario me pidieron que presentara una edición especial de The Drop. Hemos seleccionado preguntas sobre la historia de RuneScape. ¡Si los haces bien, obtendrás un nuevo título y una enorme estrella prismática! Estoy seguro de que serás un ganador en poco tiempo, no puedes reprimir el talento.",
    ["Enter The Drop: 15th Anniversary Edition."] = "Ingrese The Drop: Edición del 15º aniversario.",
    ["*If The Drop has not started*"] = "*Si The Drop no ha comenzado*",
    ["The Drop: 15th Anniversary Edition starts in X minutes."] = "The Drop: Edición del 15.º aniversario comienza en X minutos.",
    ["What are the rewards?"] = "¿Cuáles son las recompensas?",
    ["If you get all the answers correct sweetie, you can get the limited edition title, 'the Historian' and a huge bonus XP star! You've got to get them all right in one go though to get them, so keep trying! Then you'll get a star for the star you are. Break a leg, sweetie!"] = "Si obtienes todas las respuestas correctas, cariño, ¡puedes obtener el título de edición limitada, 'el Historiador' y una enorme estrella de XP adicional! Tienes que hacerlos bien de una sola vez para conseguirlos, ¡así que sigue intentándolo! Entonces obtendrás una estrella por la estrella que eres. ¡Rómpete una pierna, cariño!",
    ["Good to see you sweetie!"] = "¡Qué bueno verte, cariño!",
    ["You're looking well as always, Fame."] = "Te ves bien como siempre, Fame.",
    ["Why did you move the statues?"] = "¿Por qué moviste las estatuas?",
    ["I loved the garden that Pete and I made for the fifteenth anniversary celebrations, and I wanted to make sure that it was preserved. It was so gorgeous, and the world deserves to keep beauty like that. And, there was the lovely serendipity of the Arc, and all of these new islands, so I knew just what I had to do. I claimed one as my own and got the statues shipped over here. So they can spend the rest of time in this glorious atmosphere and so everyone can enjoy them. Don't they look lovely?"] = "Me encantó el jardín que Pete y yo hicimos para las celebraciones del decimoquinto aniversario y quería asegurarme de que se conservara. Era tan hermoso y el mundo merece mantener una belleza así. Y estaba la encantadora casualidad del Arco y todas estas nuevas islas, así que sabía exactamente lo que tenía que hacer. Reclamé una como mía y envié las estatuas aquí. Para que puedan pasar el resto del tiempo en este glorioso ambiente y para que todos puedan disfrutar de ellos. ¿No se ven preciosos?",
    ["Absolutely. It's quite the setting for them."] = "Absolutamente. Es todo un escenario para ellos.",
    ["Why are you here?"] = "¿Por qué estás aquí?",
    ["Well, darling, why wouldn't I be? Don't you just love the atmosphere? Every star has to have their bolt-hole, their little piece of tranquillity where they can truly be themselves. This is that place for me. My little haven."] = "Bueno, cariño, ¿por qué no lo estaría? ¿No te encanta el ambiente? Cada estrella tiene que tener su refugio, su pedacito de tranquilidad donde poder ser verdaderamente ella misma. Este es ese lugar para mí. Mi pequeño refugio.",
    ["So you're staying here?"] = "¿Entonces te quedarás aquí?",
    ["Well, if my public calls for me, I will of course answer them, it's only right. But for now, this is my home."] = "Bueno, si mi público me llama, por supuesto les responderé, es lo correcto. Pero por ahora esta es mi casa.",
    ["What are you planning to do next?"] = "¿Qué planeas hacer a continuación?",
    ["It's tiring having so much talent, so I'm taking this time to recuperate so I can come back at full capacity. Feel free to visit me from time to time, sweetie, your company is always welcome. But, yes, I shall be here until I am completely reinvigorated."] = "Es agotador tener tanto talento, así que me estoy tomando este tiempo para recuperarme y poder regresar a plena capacidad. No dudes en visitarme de vez en cuando, cariño, tu compañía siempre es bienvenida. Pero sí, estaré aquí hasta que esté completamente revitalizado.",
    ["Bye."] = "Adiós.",
    ["Break a leg, sweetie!"] = "¡Rómpete una pierna, cariño!",
    ["You've unlocked the next step."] = "Has desbloqueado el siguiente paso.",
    ["Really?"] = "¿En serio?",
    ["Like really though? This is the next step?"] = "¿Te gusta realmente? ¿Este es el siguiente paso?",
    ["Why not? I know Mazcab lore."] = "¿Por qué no? Conozco la tradición Mazcab.",
    ["But but..."] = "Pero pero...",
    ["HAHAHAHAHAHAHAHAHAHAHAHAHA. I'm joking. But I've been asked to give you a message from a hooded stranger... It reads... 'Mod Raven woz ere."] = "JAJAJAJAJAJAJAJAJAJAJAJAJAJA. Estoy bromeando. Pero me han pedido que te dé un mensaje de un extraño encapuchado... Dice... 'Mod Raven woz ere'.",
    ["Famine does not acknowledge you. She releases a heavy sigh."] = "Famine no te reconoce. Ella lanza un profundo suspiro.",
    ["Famine is not amused by your antics."] = "A Famine no le divierten tus payasadas.",
    ["Congratulations! You have completed: 'The Feast and the Famine' - Attempt to be funny and show a primal feast to someone who won't appreciate it at Stormguard."] = "¡Felicitaciones! Has completado: 'The Feast and the Famine': intenta ser gracioso y mostrar un festín primitivo a alguien que no lo apreciará en Stormguard.",
    ["Arr!"] = "¡Arr!",
    ["Is there something I can help ye with?"] = "¿Hay algo en lo que pueda ayudarte?",
    ["I would like to join your crew."] = "Me gustaría unirme a tu equipo.",
    ["Of course you would!"] = "¡Por supuesto que sí!",
    ["Arr, well we'll get you sorted out with a team hat right away."] = "Arr, bueno, te solucionaremos el problema con una gorra de equipo de inmediato.",
    ["Go wait in the waiting room, I'll call you when we are ready to begin."] = "Ve a esperar en la sala de espera, te llamaré cuando estemos listos para comenzar.",
    ["If wearing hat or helmet"] = "Si usa sombrero o casco",
    ["However, I don't let anyone on the team if they are wearing a hat or a helmet."] = "Sin embargo, no dejo a nadie en el equipo si lleva gorra o casco.",
    ["You can go and store it in the deposit box next to Jimmy's stall."] = "Puedes ir y guardarlo en la caja de depósito al lado del puesto de Jimmy.",
    ["Why not?"] = "¿Por qué no?",
    ["Well, in order to tell my crew from San Fan's I will need to give you a hat like mine."] = "Bueno, para decírselo a mi equipo de San Fan's tendré que regalarles un sombrero como el mío.",
    ["If you are wearing a hat it might get lost when I give you my crew's hat."] = "Si llevas sombrero, es posible que se pierda cuando te entregue el sombrero de mi equipo.",
    ["You wouldn't want that would you?"] = "No querrías eso, ¿verdad?",
    ["No, that sounds very reasonable in fact."] = "No, de hecho, eso suena muy razonable.",
    ["If you do not have an empty inventory"] = "Si no tienes un inventario vacío",
    ["Well, I'll be glad to have you aboard, but you will need to go and store all of your gear first."] = "Bueno, me alegrará tenerte a bordo, pero primero tendrás que ir a guardar todo tu equipo.",
    ["What do you mean?"] = "¿Qué quieres decir?",
    ["Well, you will need all of your inventory space for the ingredients, and all of the other things I'll need you to haul about."] = "Bueno, necesitarás todo el espacio de tu inventario para los ingredientes y todas las demás cosas que necesitaré que cargues.",
    ["There is a bank deposit box next to Jimmy's stall if you need it. Come and see me when you have a fully empty inventory."] = "Hay una caja de depósito bancaria al lado del puesto de Jimmy si la necesitas. Ven a verme cuando tengas el inventario completamente vacío.",
    ["Who are you, and what is this place?"] = "¿Quién eres y qué es este lugar?",
    ["Arrharrharr!"] = "¡Arrarra!",
    ["Do you not recognise me? I am the famous dandy pirate 'Fancy' Dan!"] = "¿No me reconoces? ¡Soy el famoso pirata dandy 'Fancy' Dan!",
    ["Yes, of course, any pirate knows who you are."] = "Sí, por supuesto, cualquier pirata sabe quién eres.",
    ["But of course."] = "Pero claro.",
    ["As for what this place is, it is my glorious still, producing the best quality 'rum' this side of Braindeath Island."] = "En cuanto a lo que es este lugar, es mi glorioso alambique, que produce el 'ron' de mejor calidad de este lado de Braindeath Island.",
    ["Oh, and the run-down swill-producing ditch that San Fan over there calls a still."] = "Ah, y la zanja deteriorada que produce basura y que San Fan llama alambique.",
    ["So with two stills you have plenty of 'rum' right?"] = "Entonces con dos fotogramas tienes mucho 'ron', ¿verdad?",
    ["Well we would do, if that hatchet-faced harridan wouldn't keep trying to torch the place!"] = "¡Bueno, lo haríamos si esa bruja con cara de hacha no siguiera intentando incendiar el lugar!",
    ["I say!"] = "¡Yo digo!",
    ["A little while ago we had some real problems getting rum to the island, hence the two stills."] = "Hace poco tuvimos verdaderos problemas para llevar ron a la isla, de ahí los dos alambiques.",
    ["However, after a little misunderstanding involving San's still and a barrel of gunpowder our relationship seems to have become a little strained."] = "Sin embargo, después de un pequeño malentendido que involucró al alambique de San y un barril de pólvora, nuestra relación parece haberse vuelto un poco tensa.",
    ["Apparently it is perfectly within the pirate code to burn each others stills, so long as nobody directly attacks the other person's crew, so run production has taken a slight dip of late."] = "Aparentemente está perfectamente dentro del código pirata quemar imágenes fijas unos de otros, siempre y cuando nadie ataque directamente a la tripulación de la otra persona, por lo que la producción ha disminuido ligeramente últimamente.",
    ["Can I help out?"] = "¿Puedo ayudar?",
    ["Yes, probably. I have a bunch of jobs that need doing, if you feel up to it."] = "Sí, probablemente. Tengo un montón de trabajos que hacer, si te sientes con ganas.",
    ["What would you like to know about?"] = "¿Qué te gustaría saber?",
    ["Brewing 'Rum"] = "Elaborar ron",
    ["How do I help you brew 'Rum'?"] = "¿Cómo te ayudo a preparar 'ron'?",
    ["Well the stills we have set up are based on the ones on Braindeath Island... well roughly at any rate."] = "Bueno, las imágenes fijas que hemos creado se basan en las de Braindeath Island... bueno, más o menos, en cualquier caso.",
    ["All you have to do is help put the ingredients into the hopper and keep the boilers burning."] = "Todo lo que tienes que hacer es ayudar a poner los ingredientes en la tolva y mantener las calderas encendidas.",
    ["If you add enough ingredients to the hopper's then you have the ability to pick up a single bottle of rum when it brews."] = "Si agregas suficientes ingredientes a la tolva, podrás recoger una sola botella de ron cuando se prepare.",
    ["So, if ye add 5 buckets of water to the hopper's, then ye get access to one bottle. If you add 3 bowls of coloured water you get access to one bottle, and if you add one of anything else you get access to one bottle."] = "Entonces, si agregas 5 cubos de agua a la tolva, tendrás acceso a una botella. Si agregas 3 tazones de agua coloreada, tendrás acceso a una botella, y si agregas uno de cualquier otra cosa, tendrás acceso a una botella.",
    ["This is cumulative, meaning that if you add (for example ) 10 buckets of water, 3 sweetgrubs and 6 bowls of coloured water, then you have a chance to collect 7 bottles of rum for the team."] = "Esto es acumulativo, lo que significa que si agregas (por ejemplo) 10 cubos de agua, 3 larvas dulces y 6 tazones de agua coloreada, tendrás la oportunidad de recolectar 7 botellas de ron para el equipo.",
    ["The boilers are easy as pie to sort out. You just put some logs in, light them with a tinderbox, and then keep putting logs in until they are good and hot."] = "Las calderas son muy fáciles de clasificar. Simplemente pones un poco de logs, los enciendes con un yesquero y luego sigues poniendo logs hasta que estén bien y calientes.",
    ["Three logs should do it, but it's best to keep heaping them in just in case."] = "Tres logs deberían ser suficientes, pero es mejor seguir amontonándolos por si acaso.",
    ["The ingredients are; Bitternuts, Scrapey Tree Bark, Sweetgrubs, Buckets of Water and some Coloured Water."] = "Los ingredientes son; Nueces amargas, corteza de árbol raspada, larvas dulces, cubos de agua y un poco de agua coloreada.",
    ["Where can I get Bitternuts?"] = "¿Dónde puedo conseguir Bitternuts?",
    ["There are plenty of Bitternut trees inside this walled off area. The problem is that the trees are too tricky for a human to climb."] = "Hay muchos árboles Bitternut dentro de esta área amurallada. El problema es que los árboles son demasiado complicados para que un humano los trepe.",
    ["You will need to catch a monkey and send it up the tree to get the nut for you."] = "Tendrás que atrapar un mono y enviarlo al árbol para que te consiga la nuez.",
    ["Send it up the tree? How does that work?"] = "¿Enviarlo al árbol? ¿Cómo funciona eso?",
    ["Well, if you were a monkey, and some random person grabbed you, dumped some dye in your fur and shoved you up a tree, you would hurl the closest heavy object at them too."] = "Bueno, si fueras un mono y una persona al azar te agarrara, te arrojara un poco de dye en tu pelaje y te empujara hacia un árbol, también les arrojarías el objeto pesado más cercano.",
    ["Wait a second, dye?"] = "Espera un segundo, ¿dye?",
    ["Yes, you'll need to get a bowl of coloured water and pour it on the monkey. Otherwise you won't be able to tell which team the monkey belongs to."] = "Sí, necesitarás conseguir un recipiente con agua coloreada y verterlo sobre el mono. De lo contrario no podrás saber a qué equipo pertenece el mono.",
    ["That makes sense...I think..."] = "Eso tiene sentido... Creo...",
    ["Anything else?"] = "¿Algo más?",
    ["Where can I get Scrapey Tree Bark?"] = "¿Dónde puedo conseguir la corteza de árbol Scrapey?",
    ["Where can I get Scrapey tree bark...and why do I get the feeling I won't like the answer?"] = "¿Dónde puedo conseguir corteza de árbol Scrapey... y por qué tengo la sensación de que no me gustará la respuesta?",
    ["Inside this walled area there are a few Scrapey trees. They are the big, ill looking ones, you can't miss them."] = "Dentro de esta zona amurallada hay algunos árboles Scrapey. Son los grandes y feos, no te los puedes perder.",
    ["Basically, you cut them down and then carve the bark off with a knife."] = "Básicamente, los cortas y luego les cortas la corteza con un cuchillo.",
    ["It's pretty simple, except the sap tends so make people feel kind of ill if they get any on themselves."] = "Es bastante simple, excepto que la savia tiende a hacer que las personas se sientan un poco enfermas si se manchan.",
    ["How ill?"] = "¿Qué tan enfermo?",
    ["Don't worry, we aren't talking deadly ill or anything."] = "No te preocupes, no estamos hablando de una enfermedad mortal ni nada por el estilo.",
    ["It's more like you'll feel quite dizzy and weak for a bit."] = "Es más como si te sintieras bastante mareado y débil por un tiempo.",
    ["Joy..."] = "Alegría...",
    ["Where can I get Sweetgrubs?"] = "¿Dónde puedo conseguir larvas dulces?",
    ["Sweetgrubs? What are they?"] = "¿Larvas dulces? ¿Cuáles son?",
    ["Well, lacking any sluglings in the area, we add these little grubs called Sweetgrubs. If you ignore the gag-inducing aftertaste, they are quite sweet."] = "Bueno, a falta de babosas en el área, agregamos estas pequeñas larvas llamadas Sweetgrubs. Si ignoras el regusto que provoca náuseas, son bastante dulces.",
    ["How... how can you drink the stuff?"] = "¿Cómo... cómo puedes beber esa cosa?",
    ["Quite easily!"] = "¡Muy fácil!",
    ["Pirates are renowned as being tough for a reason."] = "Los piratas tienen fama de ser duros por una razón.",
    ["So where do I get these grubs from anyway?"] = "Entonces, ¿de dónde obtengo estas larvas?",
    ["Well, there are a few sweetgrub mounds inside there. We have a handful of rat meat that you can use on the mounds to draw the grubs to the surface."] = "Bueno, hay algunos montículos de larvas dulces ahí dentro. Tenemos un puñado de carne de rata que puedes usar en los montículos para atraer las larvas a la superficie.",
    ["Mind your fingers though, they are voracious little things."] = "Pero ten cuidado con los dedos, son cositas voraces.",
    ["And here was me thinking that nothing could be more disgusting than Braindeath 'Rum'."] = "Y aquí estaba yo pensando que nada podría ser más repugnante que Braindeath 'Rum'.",
    ["Arr, that's where ye'd be wrong lad, 'cos new, improved Braindeath 'Rum' Classic is now 200% more disgustin' then any leadin' competitor!"] = "Arr, ahí es donde te equivocarías muchacho, porque el nuevo y mejorado Braindeath 'Rum' Classic es ahora un 200% más repugnante que cualquier competidor líder.",
    ["Legal disclaimer; the dangerous amount of disgustin' in new Braindeath 'Rum' Classic be too much for pregnant women, donkeys and anyone with more than seven letters in their last name."] = "Aviso legal; La peligrosa cantidad de asco del nuevo Braindeath 'Rum' Classic es demasiado para las mujeres embarazadas, los burros y cualquier persona con más de siete letras en su apellido.",
    ["What was that?"] = "¿Qué fue eso?",
    ["What was what?"] = "¿Qué fue qué?",
    ["Is there anything else?"] = "¿Hay algo más?",
    ["Where can I get buckets of water?"] = "¿Dónde puedo conseguir baldes de agua?",
    ["How do I get..."] = "¿Cómo consigo...?",
    ["Wait, no, that question makes me sound like I haven't a clue what I'm doing."] = "Espera, no, esa pregunta me hace parecer como si no tuviera ni idea de lo que estoy haciendo.",
    ["Where can I get buckets in there?"] = "¿Dónde puedo conseguir cubos allí?",
    ["There are a few lying about. Help yourself."] = "Hay algunos por ahí. Ayudar a sí mismo.",
    ["There is a pump in the still, so long as it's working you should have almost unlimited water."] = "Hay una bomba en el alambique, mientras esté funcionando deberías tener agua casi ilimitada.",
    ["Hold on, do I have to add anything disgusting and/or potential lethal to the water before I pour it in?"] = "Espera, ¿tengo que agregar algo repugnante y/o potencialmente letal al agua antes de verterla?",
    ["Perish the thought!"] = "¡Maldito pensamiento!",
    ["Ok, just checking."] = "Ok, solo estoy comprobando.",
    ["Where can I get coloured water?"] = "¿Dónde puedo conseguir agua coloreada?",
    ["What sort of coloured water are we talking about here?"] = "¿De qué tipo de agua coloreada estamos hablando aquí?",
    ["Well, the other still has an area of waste ground with a flower growing on it. If you go and grab one of the flowers and jam it in the kettle, the water will boil out the colour."] = "Bueno, el otro todavía tiene un terreno baldío con una flor creciendo en él. Si vas y agarras una de las flores y la metes en la tetera, el agua perderá el color.",
    ["We use the colour to keep our rum easily identifiable."] = "Usamos el color para que nuestro ron sea fácilmente identificable.",
    ["So I just empty the kettle into the hopper, right?"] = "Así que simplemente vacío el hervidor en la tolva, ¿verdad?",
    ["No, no, you'll need to take an empty bowl and fill it from the kettle."] = "No, no, tendrás que coger un recipiente vacío y llenarlo con la tetera.",
    ["That way you can use the stuff on a monkey if you need to."] = "De esa manera puedes usar las cosas en un mono si es necesario.",
    ["Use it on a monkey...of course."] = "Úselo en un mono... por supuesto.",
    ["Repairing the Still"] = "Reparando el alambique",
    ["How do I repair the still?"] = "¿Cómo reparo el alambique?",
    ["Well, assuming those scurvy dogs have managed to set any of it on fire, then you will need to tip a bucket of water on it before you can repair it."] = "Bueno, suponiendo que esos perros con escorbuto hayan logrado prenderle fuego a algo, entonces tendrás que echarle un balde de agua antes de poder repararlo.",
    ["Then, it all comes down to what part of it was damaged."] = "Luego, todo se reduce a qué parte resultó dañada.",
    ["How do I repair Hoppers?"] = "¿Cómo reparo las tolvas?",
    ["How can I repair hoppers?"] = "¿Cómo puedo reparar las tolvas?",
    ["Well, assuming that they are not on fire, all you need to do is use the heavy lumber patches. They are big enough to cover most holes."] = "Bueno, suponiendo que no estén en llamas, todo lo que necesitas hacer es usar los parches de madera pesados. Son lo suficientemente grandes como para cubrir la mayoría de los agujeros.",
    ["Will I need a hammer?"] = "¿Necesitaré un martillo?",
    ["No, just shove it into place and whack it until it lines up."] = "No, simplemente empújalo en su lugar y golpéalo hasta que quede alineado.",
    ["How do I repair Pipes and the pump?"] = "¿Cómo reparo las tuberías y la bomba?",
    ["How do I repair pipes and the pump?"] = "¿Cómo reparo las tuberías y la bomba?",
    ["Well, if you use a pipe section on the damaged part you should be able to replace it easily."] = "Bueno, si usas una sección de tubería en la parte dañada deberías poder reemplazarla fácilmente.",
    ["No, likely you'll just need to whack the old one out and slot the new one in with your hands."] = "No, probablemente solo tendrás que sacar el viejo y colocar el nuevo con las manos.",
    ["How do I repair Bridges?"] = "¿Cómo reparo puentes?",
    ["How do I repair bridges?"] = "¿Cómo reparo puentes?",
    ["Well, we have these handy bridge sections you can use to repair the bridges."] = "Bueno, tenemos estas prácticas secciones de puentes que puedes usar para reparar los puentes.",
    ["The main problem is, while a still will keep working if a bit of it is only damaged, the bridges are completely out of commission if they are even slightly damaged."] = "El problema principal es que, mientras que un alambique seguirá funcionando si solo se daña una parte, los puentes quedan completamente fuera de servicio si se dañan aunque sea ligeramente.",
    ["Is that going to be a problem? I mean, I can jump across I think."] = "¿Eso va a ser un problema? Quiero decir, creo que puedo saltar.",
    ["Don't try that! Our lawyers tell us we aren't covered for injuries sustained while jumping over burned bridges."] = "¡No intentes eso! Nuestros abogados nos dicen que no estamos cubiertos por las lesiones sufridas al saltar sobre puentes quemados.",
    ["Seriously, just keep off the bridges until they are fixed."] = "En serio, mantente alejado de los puentes hasta que estén reparados.",
    ["How do I get repair items?"] = "¿Cómo obtengo artículos de reparación?",
    ["Where do I get all this stuff anyway?"] = "¿De dónde consigo todas estas cosas?",
    ["We have a load of items already on a table inside the still. You can also make new ones if you grab some logs."] = "Ya tenemos un montón de artículos en una mesa dentro del alambique. También puedes crear otros nuevos si compras logs.",
    ["How does that work?"] = "¿Cómo funciona eso?",
    ["We have a worktable set up in the still. If you use the logs in it can craft up a handy replacement for part of the still."] = "Tenemos una mesa de trabajo instalada en el alambique. Si usa el logs, puede crear un reemplazo útil para parte del alambique.",
    ["Don't worry about them fitting, the things are held together by nails, replacement parts and soot by now."] = "No te preocupes por que encajen, las cosas se mantienen juntas gracias a nails, las piezas de repuesto y el hollín.",
    ["Well...how sanitary..."] = "Bueno... qué sanitario...",
    ["Ok, I think I've heard enough"] = "Ok, creo que ya he escuchado suficiente.",
    ["Ok, I think I've heard enough."] = "Ok, creo que ya he escuchado suficiente.",
    ["Fine. Glad I could help."] = "Bien. Me alegra poder ayudar.",
    ["Sabotaging San's Still"] = "Saboteando el alambique de San",
    ["So...how would I go about sabotaging the enemy still?"] = "Entonces... ¿cómo haría para seguir saboteando al enemigo?",
    ["Ok, here's what you need to do."] = "Ok, esto es lo que debes hacer.",
    ["The wood around here is really dry and flammable, so take one of the torches, light it up, and then go and attack the enemy still with it."] = "La madera que hay por aquí está muy seca e inflamable, así que toma una de las antorchas, enciéndela y luego ataca al enemigo que todavía la tiene.",
    ["That's it?"] = "¿Eso es todo?",
    ["Most of their still is soaked in 'alcohol' and made from tinder dry wood."] = "La mayor parte de su alambique está empapado en 'alcohol' y hecho de yesca de madera seca.",
    ["Essentially, if it isn't ours, try using a torch on it and see what happens."] = "Básicamente, si no es nuestro, intente usar una antorcha y vea qué sucede.",
    ["Ok, I get you."] = "Ok, te entiendo.",
    ["What will you pay me?"] = "¿Qué me pagarás?",
    ["So what will you give me for helping out?"] = "Entonces, ¿qué me darás por ayudar?",
    ["Hahahaha! What a mercenary attitude! You'll do fine here."] = "¡Jajajaja! ¡Qué actitud tan mercenaria! Te irá bien aquí.",
    ["Well, for each bottle that your team produces, I'll give you one piece of eight."] = "Bueno, por cada botella que produzca tu equipo, te daré una pieza de ocho.",
    ["If you managed to set something on fire then I'll toss in another, same for repairing the still."] = "Si lograste prender fuego a algo, arrojaré otro, lo mismo para reparar el alambique.",
    ["What can I use these pieces of eight for?"] = "¿Para qué puedo utilizar estos ocho?",
    ["See Honest Jimmy there? He will trade you some pretty nice stuff for them."] = "¿Ves Honest Jimmy allí? Te cambiará algunas cosas muy bonitas por ellas.",
    ["Great!"] = "¡Genial!",
    ["Category:NPC dialogue"] = "Categoría: Diálogo NPC",
    ["Now you look like someone who goes to a lot of fancy dress parties."] = "Ahora pareces alguien que va a muchas fiestas de disfraces.",
    ["Errr...what are you saying exactly?"] = "Errr... ¿qué estás diciendo exactamente?",
    ["I'm just saying that perhaps you would like to peruse my selection of garments."] = "Sólo digo que quizás te gustaría examinar mi selección de prendas.",
    ["Or, if that doesn't interest you, then maybe you have something else to offer? I'm always on the lookout for interesting or unusual new materials."] = "O, si eso no te interesa, ¿quizás tengas algo más que ofrecer? Siempre estoy buscando materiales nuevos, interesantes o inusuales.",
    ["Okay, let's see what you've got, then."] = "Bien, entonces veamos qué tienes.",
    ["*(After Eagles' Peak:)* Could you make another bird costume for me?"] = "*(Después de Eagles' Peak:)* ¿Podrías hacerme otro disfraz de pájaro?",
    ["Could you make another eagle costume for me?"] = "¿Podrías hacerme otro disfraz de águila?",
    ["Certainly, if you can supply the materials. I'll need appropriate feathers, swamp tar and some yellow dye. It'll also cost you 25 gold pieces."] = "Por supuesto, si puedes proporcionar los materiales. Necesitaré plumas apropiadas, alquitrán de pantano y algo de yellow dye. También te costará 25 piezas de oro.",
    ["I'll see what I can do."] = "Veré qué puedo hacer.",
    ["Okay, here are the materials. Eagle me up."] = "Bien, aquí están los materiales. Águilame.",
    ["I'm afraid I don't have that much money with me."] = "Me temo que no tengo tanto dinero conmigo.",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["There we go, one eagle costume. You should be the envy of the entire party wearing that."] = "Ahí vamos, un disfraz de águila. Deberías ser la envidia de todo el grupo usando eso.",
    ["On second thoughts, that's too expensive."] = "Pensándolo bien, eso es demasiado caro.",
    ["Well, feel free to come back if you change your mind."] = "Bueno, no dudes en volver si cambias de opinión.",
    ["I think I might just leave the perusing for now thanks."] = "Creo que podría dejar la lectura por ahora, gracias.",
    ["I think I might just leave the perusing for now, thanks."] = "Creo que podría dejar la lectura por ahora, gracias.",
    ["*(If you do not have suitable fur in your inventory:)* Can you make clothing suitable for hunting in?"] = "*(Si no tienes pieles adecuadas en tu inventario:)* ¿Puedes hacer ropa adecuada para cazar?",
    ["Can you make clothing suitable for hunting?"] = "¿Puedes hacer ropa adecuada para cazar?",
    ["Certainly. Take a look at my range of made-to-order items. If you can supply the furs, I'll gladly make any of these for you."] = "Por supuesto. Echa un vistazo a mi gama de artículos hechos a medida. Si puedes proporcionarme las pieles, con mucho gusto te haré cualquiera de estas.",
    ["*(If you have fur in your inventory:)* Could you make anything out of this fur that I got from hunting?"] = "*(Si tienes pelaje en tu inventario:)* ¿Podrías hacer algo con este pelaje que obtuve cazando?",
    ["Could you make anything out of this fur that I got from hunting?"] = "¿Podrías hacer algo con este pelaje que obtuve cazando?",
    ["What sort of unusual materials did you have in mind?"] = "¿Qué tipo de materiales inusuales tenías en mente?",
    ["Well, some more colourful feathers might be useful. For some surreal reason, all I normally seem to get offered are large quantities of rather beaten-up looking chicken feathers."] = "Bueno, algunas plumas más coloridas podrían ser útiles. Por alguna razón surrealista, lo único que normalmente me ofrecen son grandes cantidades de plumas de pollo de aspecto bastante desgastado.",
    ["People must have some very strange pastimes around these parts, that's all I can say."] = "La gente debe tener pasatiempos muy extraños por estos lares, eso es todo lo que puedo decir.",
    ["Ok, let's see what you've got then."] = "Ok, veamos qué tienes entonces.",
    ["Are you a surface-dweller?"] = "¿Eres un habitante de la superficie?",
    ["Yes..."] = "Sí...",
    ["Haha! You look funny! All tall and skinny with tiny eyes!"] = "¡Jaja! ¡Te ves gracioso! ¡Todo alto y delgado con ojos diminutos!",
    ["Are you Player? Did you help Zanik save the city?"] = "¿Eres Player? ¿Ayudaste a Zanik a salvar la ciudad?",
    ["Yes, that was me!"] = "¡Sí, ese era yo!",
    ["When I'm older I'm going to be an adventurer, just like Zanik!"] = "Cuando sea mayor seré un aventurero, ¡como Zanik!",
    ["Sorry, I'm not meant to talk to strangers."] = "Lo siento, no debo hablar con extraños.",
    ["Shh! Don't tell anyone!"] = "¡Shh! ¡No se lo digas a nadie!",
    ["Don't tell anyone what?"] = "¿No decirle a nadie qué?",
    ["SHHH!"] = "¡SHHH!",
    ["Help! Help! The surface people are attacking!"] = "¡Ayuda! ¡Ayuda! ¡La gente de la superficie está atacando!",
    ["It's alright, I'm friendly!"] = "¡Está bien, soy amigable!",
    ["Hello there...thanks for helping out Trufitus commune with the gods Bwana. We've been able to return to the village thanks to your help."] = "Hola... gracias por ayudar a Trufitus a comunicarse con los dioses Bwana. Hemos podido regresar al pueblo gracias a vuestra ayuda.",
    ["What do you do here?"] = "¿Qué haces aquí?",
    ["Ha, well I'm retired now, but in my heyday I was quite the expert fisherman! These days I just help out around the village where I can, my old bones don't allow me to do any more than that."] = "Ja, bueno, ahora estoy retirado, ¡pero en mi apogeo era un pescador bastante experto! Actualmente sólo ayudo en el pueblo donde puedo, mis viejos huesos no me permiten hacer más que eso.",
    ["Is there anything interesting to do here?"] = "¿Hay algo interesante que hacer aquí?",
    ["Bwana, if anyone else asks me that question today, I'll explode! Go and ask Murcaily!"] = "Bwana, si alguien más me hace esa pregunta hoy, ¡explotaré! ¡Ve y pregúntale a Murcaily!",
    ["I'm just enjoying the sunshine, Bwana. Try asking Murcaily."] = "Solo estoy disfrutando del sol, Bwana. Intente preguntarle a Murcaily.",
    ["Well, I think that there's some work to be done...perhaps Murcaily can help you. He usually tends to the hardwood grove to the east of Trufitus' hut."] = "Bueno, creo que hay trabajo por hacer... tal vez Murcaily pueda ayudarte. Por lo general, atiende el bosquecillo de madera al este de la cabaña de Trufitus.",
    ["Sorry Bwana, I'm already busy, why not go and talk to Murcaily! He's around the village somewhere."] = "Lo siento Bwana, ya estoy ocupado, ¿por qué no vas y hablas con Murcaily? Está en alguna parte del pueblo.",
    ["I've been doing some work around the village."] = "He estado trabajando en el pueblo.",
    ["Hey, I've seen you working around the village. You've been doing a lot of good work around here for us. Let me give you something for your trouble."] = "Oye, te he visto trabajando en el pueblo. Has estado haciendo un muy buen trabajo aquí para nosotros. Déjame darte algo por tu molestia.",
    ["I've already given you some trading sticks and I don't have any more on me at the moment. Why not go and talk to some of the other villagers and get some contributions?"] = "Ya te he dado algunos palitos de intercambio y no tengo ninguno más en este momento. ¿Por qué no vas y hablas con algunos de los otros aldeanos y consigues algunas contribuciones?",
    ["Ok, thanks."] = "Vale, gracias.",
    ["Ahhhhhhhh - Get away from me you beast!"] = "Ahhhhhhhh - ¡Aléjate de mí, bestia!",
    ["Ahhhhhhhh!"] = "¡Ahhhhhhhh!",
    ["Ahhhhhhhh - It's a monster!"] = "Ahhhhhhhh - ¡Es un monstruo!",
    ["Waahhhhh! - It's da evil broodoo beast come ta eat my very soul!"] = "¡Waahhhhh! - ¡Es una bestia malvada que viene a comerse mi alma!",
    ["What's the problem... oh, I'm wearing this big scary mask! I'd better take it off before I start talking to the natives."] = "¿Cuál es el problema? ¡Oh, estoy usando esta gran máscara aterradora! Será mejor que me lo quite antes de empezar a hablar con los nativos.",
    ["Is it chilly out here, or is it just me?"] = "¿Hace frío aquí afuera o soy solo yo?",
    ["Maybe put on a shirt."] = "Tal vez ponerte una camisa.",
    ["Hello."] = "Hola.",
    ["**Farid Morrisane (ores):** Hmmm, a new trader. I suggest you speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance for a lesson. Brugsen will give an interesting and complete lesson and the Tutor will give a smaller, plain lesson."] = "**Farid Morrisane (ores):** Hmmm, un nuevo comerciante. Te sugiero que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada para recibir una lección. Brugsen dará una lección interesante y completa y el Tutor dará una lección más breve y sencilla.",
    ["Hello, little boy."] = "Hola, pequeño.",
    ["I would appreciate it if you didn't talk to me in such a manner. I'll have you know I'm an accomplished merchant."] = "Le agradecería que no me hablara de esa manera. Le haré saber que soy un comerciante consumado.",
    ["Calm down, junior."] = "Cálmate, joven.",
    ["Don't tell me to calm down! And don't call me 'junior'."] = "¡No me digas que me calme! Y no me llames 'junior'.",
    ["I'll have you know I am Farid Morrisane, son of Ali Morrisane, the world's greatest merchant!"] = "Para que sepas, soy Farid Morrisane, hijo de Ali Morrisane, ¡el comerciante más grande del mundo!",
    ["Then why are you here and not him?"] = "Entonces, ¿por qué estás tú aquí y no él?",
    ["My dad has given me the responsibility of expanding our business here."] = "Mi papá me ha dado la responsabilidad de expandir nuestro negocio aquí.",
    ["And you're up to the task?"] = "¿Y estás a la altura?",
    ["What a grown up boy you are! Mummy and daddy must be very pleased!"] = "¡Qué niño tan adulto eres! ¡Mamá y papá deben estar muy contentos!",
    ["Look mate - I may be young, I may be short, but I'm a respected merchant around here and don't have time to deal with simpletons like you."] = "Mire amigo, puede que sea joven, puede que sea bajo, pero soy un comerciante respetado por aquí y no tengo tiempo para tratar con tontos como usted.",
    ["Can you help me out with the prices for ores?"] = "¿Puedes ayudarme con los precios de los minerales?",
    ["That's easy. Been doing that since I was three."] = "Eso es fácil. He estado haciendo esto desde que tenía tres años.",
    ["I best go and speak with someone more my height."] = "Será mejor que vaya y hable con alguien de mi altura.",
    ["Then I shall not stop you, mister. I've got too much work to do."] = "Entonces no lo detendré, señor. Tengo demasiado trabajo que hacer.",
    ["Me Farkle! Me mighty ogre champion. Me win tournament easy, prove ogres are strongest."] = "¡Yo Farkle! Mi poderoso campeón ogro. Yo gano el torneo fácilmente, demuestro que los ogros son más fuertes.",
    ["Haha 'Farkle'."] = "Jaja 'Farkle'.",
    ["Me do impression of you - listen!"] = "Yo hago una impresión de ti, ¡escucha!",
    ["Blah blah blah me stupid human! Please no hurt me!"] = "¡Bla, bla, bla, estúpido humano! ¡Por favor no me hagas daño!",
    ["You like that human?"] = "¿Te gusta ese humano?",
    ["You'll be doing impressions of yourself losing if we meet in the arena!"] = "¡Harás imitaciones de ti mismo perdiendo si nos encontramos en la arena!",
    ["Haw! No way, human!"] = "¡Ja! ¡De ninguna manera, humano!",
    ["Hello there!"] = "¡Hola!",
    ["Hi."] = "Hola.",
    ["What brings you down here then?"] = "¿Qué te trae por aquí entonces?",
    ["It's a cavern."] = "Es una caverna.",
    ["Really? Great, thanks for that."] = "¿En serio? Genial, gracias por eso.",
    ["No problem!"] = "¡No hay problema!",
    ["So, is there actually anything in this cavern?"] = "Entonces, ¿hay realmente algo en esta caverna?",
    ["Well, there's rocks. A bit of water here and there too."] = "Bueno, hay piedras. Un poco de agua aquí y allá también.",
    ["Right. Good to know. I'm glad you were here, actually, because, you know, I'd have been lost without that."] = "Correcto. Es bueno saberlo. De hecho, me alegro de que estuvieras aquí, porque, ya sabes, me habría perdido sin eso.",
    ["Happy to help!"] = "¡Feliz de poder ayudar!",
    ["*(Shows previous options)*"] = "*(Muestra opciones anteriores)*",
    ["Who are you?"] = "¿Quién eres?",
    ["I'm Farli. I came down here to explore the moment the cavern entrance opened up."] = "Soy Farli. Bajé aquí para explorar el momento en que se abrió la entrada de la caverna.",
    ["Have you discovered anything down there?"] = "¿Has descubierto algo ahí abajo?",
    ["Well, I did stumble across some nice-looking deposits of ore and some strange fish in the waters, but I haven't really been able to investigate further."] = "Bueno, me topé con algunos depósitos de mineral bonitos y algunos peces extraños en las aguas, pero realmente no he podido investigar más.",
    ["It's as if the rocks are moving... Whenever I've tried to map this place, I find rocks are in different places to when I checked before!"] = "Es como si las rocas se estuvieran moviendo... ¡Cada vez que intento mapear este lugar, encuentro que las rocas están en lugares diferentes a los que había visto antes!",
    ["Moving rocks? Are you sure you haven't been drinking?"] = "¿Rocas en movimiento? ¿Estás seguro de que no has estado bebiendo?",
    ["Well, yes. I mean no. Look, that's not important. What is important is that the rocks down here are moving!"] = "Bueno, sí. Quiero decir que no. Mira, eso no es importante. ¡Lo importante es que las rocas aquí abajo se están moviendo!",
    ["I'll be sure to check that out..."] = "Me aseguraré de comprobarlo...",
    ["It's true! One time I was mining a rock, or what I thought was a rock, and it upped and ran off with my best pickaxe!"] = "¡Es verdad! Una vez estaba extrayendo una roca, o lo que pensé que era una roca, ¡se levantó y salió corriendo con mi mejor pico!",
    ["What does this pulley do?"] = "¿Qué hace esta polea?",
    ["Oh, that's just to get my supplies in and out of the cavern."] = "Oh, eso es sólo para que mis suministros entren y salgan de la caverna.",
    ["How does that work then?"] = "¿Cómo funciona eso entonces?",
    ["The miners above use the mine cart system to move about what we need from Keldagrim."] = "Los mineros de arriba usan el sistema de carro de mina para mover lo que necesitamos de Keldagrim.",
    ["Hmm, that could be handy for depositing things into my bank. You think you could arrange that?"] = "Hmm, eso podría ser útil para depositar cosas en mi banco. ¿Crees que podrías arreglar eso?",
    ["Hmm, maybe. I suppose if you're down here to help then I can sort something out."] = "Hmm, tal vez. Supongo que si estás aquí para ayudar, entonces puedo arreglar algo.",
    ["Actually, I don't want to talk to you."] = "En realidad, no quiero hablar contigo.",
    ["Hmph! How rude!"] = "¡Hmph! ¡Qué grosero!",
    ["What're you doing here? I'm tired of you soldiers stelaing my wheat!"] = "¿Qué haces aquí? ¡Estoy cansado de que ustedes, soldados, me roben el trigo!",
    ["I'm not a soldier!"] = "¡No soy un soldado!",
    ["In which case get off my land! I've got enough to deal with at the moment!"] = "¡En cuyo caso sal de mi tierra! ¡Ya tengo suficiente con qué lidiar en este momento!",
    ["Give me all your wheat!"] = "¡Dame todo tu trigo!",
    ["Fine, take the wheat. Just leave some for me and my children, for Saradomin's sake!"] = "Bien, toma el trigo. ¡Déjanos un poco para mí y mis hijos, por el bien de Saradomin!",
    ["What are you selling? Compost? Fertiliser? I've tried it all."] = "¿Qué estás vendiendo? ¿Compost? ¿Fertilizante? Lo he probado todo.",
    ["Not even that smug scoundrel David could grow anything on this land. Not with how hard all of our harvests have been hit lately."] = "Ni siquiera ese sinvergüenza engreído David podría cultivar algo en esta tierra. No con lo duro que se han visto afectadas todas nuestras cosechas últimamente.",
    ["You need to be a level 10 thief to steal from this target."] = "Debes ser un ladrón de nivel 10 para robarle a este objetivo.",
    ["You steal [number] [name] seeds."] = "Robas semillas [número] [name].",
    ["You fail to steal from the target."] = "No logras robarle al objetivo.",
    ["You've been stunned."] = "Has quedado atónito.",
    ["Ello there! Welcome to Winkin's Farm. What can I do for ya?"] = "¡Hola! Bienvenido a la granja de Winkin. ¿Qué puedo hacer por ti?",
    ["Ha! I told ya, it's Winkin's Farm. This is where we grow the magical ogleroots for the rest of the world."] = "¡Ja! Ya te lo dije, es Winkin's Farm. Aquí es donde cultivamos las mágicas raíces de ogle para el resto del mundo.",
    ["So, what can I do here?"] = "Entonces, ¿qué puedo hacer aquí?",
    ["Ya can improve yer Farming skill by getting some flags from me or Mrs. Winkin, inside. Then, head out to the fields and flag where ya think plants are, er, planted."] = "Puedes mejorar tu habilidad Farming obteniendo algunas banderas mías o de Mrs. Winkin, adentro. Luego, dirígete a los campos y marca dónde crees que se plantan plantas.",
    ["Is that it?"] = "¿Es eso todo?",
    ["Not at all! There's more. When ya've placed yar flags, the farmers will collect them up and give out points. Ya can trade these points for seeds or experience at the shop inside."] = "¡Para nada! Hay más. Cuando hayas colocado banderas de yar, los granjeros las recogerán y te darán puntos. Puedes canjear estos puntos por semillas o experiencia en la tienda del interior.",
    ["Okay, that sounds great! I'll get planting, then."] = "¡Está bien, eso suena genial! Entonces empezaré a plantar.",
    ["Aye, but be careful where ya plant the flags. If there's no plant under yar flag, the farmer will keep it and they cost a pretty penny to buy more."] = "Sí, pero ten cuidado donde plantas las banderas. Si no hay ninguna planta bajo la bandera de yar, el granjero se la quedará y le costará un centavo comprar más.",
    ["I see. Thanks for the help."] = "Ya veo. Gracias por la ayuda.",
    ["Bye, for now. If I have to say 'flag' one more time, I tell ya..."] = "Adiós, por ahora. Si tengo que decir 'bandera' una vez más, os lo digo...",
    ["Do you have any flags?"] = "¿Tienes alguna bandera?",
    ["Let me check for ya."] = "Déjame comprobarlo.",
    ["Arr, a new'un, eh? Aye, it's always good to see a new face round these parts. Now, usually we charge for flags, since so many go missing - but ya can have yar first set for free."] = "Arr, un nuevo, ¿eh? Sí, siempre es bueno ver una cara nueva por estos lares. Ahora, normalmente cobramos por las banderas, ya que muchas se pierden, pero puedes configurar la primera de forma gratuita.",
    ["Wow, thanks!"] = "¡Vaya, gracias!",
    ["Now, remember: if ya plant the flags in any old place that don't have seeds in it, ya'll lose yer flag - and they ain't cheap to buy back from me or Mrs. Winkin. Anyway, here's yer first lot."] = "Ahora, recuerda: si plantas las banderas en cualquier lugar antiguo que no tenga semillas, perderás tu bandera, y no es barato comprármelas a mí o a Mrs. Winkin. De todos modos, aquí está tu primer lote.",
    ["Thanks very much! I'll be off, then."] = "¡Muchas gracias! Entonces me voy.",
    ["Bye now."] = "Adiós.",
    ["Ah! First things first. One of the farm lads dropped off some flags for ya. Ya can have them back. Here ya go."] = "¡Ah! Lo primero es lo primero. Uno de los muchachos de la granja te dejó algunas banderas. Puedes recuperarlos. Aquí tienes.",
    ["Righty-ho! Ya can have a total of 10 flags. To get yerself a full set of flags'll cost ya [number] gold pieces. Would ya like to buy these flags?"] = "Righty-ho! Puedes tener un total de 10 banderas. Conseguir un juego completo de banderas te costará [número] piezas de oro. ¿Te gustaría comprar estas banderas?",
    ["[number] coins have been removed from your money pouch."] = "[número] coins se han eliminado de su bolsa de dinero.",
    ["Here ya go, then."] = "Aquí tienes, entonces.",
    ["Right y'are then! See ya."] = "¡Así es! Nos vemos.",
    ["It looks like ya got all the flags ya need right now. Ya don't need to buy any more."] = "Parece que ya tienes todas las banderas que necesitas ahora. No necesitas comprar más.",
    ["Where is Mr. Winkin?"] = "¿Dónde está el Sr. Winkin?",
    ["Farmer Winkin? Well, last I 'eard he was heading into market with a fresh load of Ogleroots."] = "¿Granjero Winkin? Bueno, lo último que oí es que iba al mercado con una nueva carga de Ogleroots.",
    ["Ogleroots?"] = "¿Ogleroots?",
    ["Aye! We get them growing a lot here in the farmyard. We dig 'em up and sell 'em to yar lot."] = "¡Sí! Los hacemos crecer mucho aquí en el corral. Los desenterramos y los vendemos a muchos.",
    ["My lot?"] = "¿Mi suerte?",
    ["Aye! Humans."] = "¡Sí! Humanos.",
    ["Oh, I see. Thanks!"] = "Ah, ya veo. ¡Gracias!",
    ["Bye now!"] = "¡Adiós!",
    ["I have all the bad luck. My sheep all run off somewhere, and then those mourners tell me they're infected!"] = "Yo tengo toda la mala suerte. ¡Todas mis ovejas huyen a alguna parte y luego esos dolientes me dicen que están infectadas!",
    ["Well, I hope things start to look up for you."] = "Bueno, espero que las cosas empiecen a mejorar para ti.",
    ["Hello there. Sorry about your sheep..."] = "Hola. Perdón por tus ovejas...",
    ["That's alright. It had to be done for the sake of the town. I just hope none of my other livestock get infected."] = "Está bien. Había que hacerlo por el bien de la ciudad. Sólo espero que ninguno de mis otros animales se infecte.",
    ["Hello there. Have you heard the truth about your sheep?"] = "Hola. ¿Has oído la verdad sobre tus ovejas?",
    ["Aye. Councillor Halgrive told me about the fake plague. My poor sheep suffered and died for a pack of liars...it's the innocent who pay the price for man's ambition. To tell you the truth..."] = "Sí. Councillor Halgrive me habló de la plaga falsa. Mis pobres ovejas sufrieron y murieron por una manada de mentirosos... son los inocentes quienes pagan el precio de la ambición del hombre. A decir verdad...",
    ["I'm glad you killed King Lathas. We were all sheep in his eyes. You brought justice to these lands."] = "Me alegra que hayas matado a King Lathas. Todos éramos ovejas ante sus ojos. Trajiste justicia a estas tierras.",
    ["I am glad you exiled King Lathas. Good riddance to him. Though I hear his cousin's not much better."] = "Me alegra que hayas exiliado a King Lathas. Buen viaje para él. Aunque he oído que su primo no está mucho mejor.",
    ["Hey! This is the Queen's farm. You'll need her approval to make use of it."] = "¡Oye! Esta es la granja de la Reina. Necesitará su aprobación para utilizarlo.",
    ["What would you like to talk about?"] = "¿De qué te gustaría hablar?",
    ["Good day. What are you doing?"] = "Buenos días. ¿Qué estás haciendo?",
    ["I'm tending to these farming patches. They need a little more work before I can plant anything."] = "Estoy atendiendo estos terrenos agrícolas. Necesitan un poco más de trabajo antes de que pueda plantar algo.",
    ["Good luck with that."] = "Buena suerte con eso.",
    ["Thank you, [Fremennik name]."] = "Gracias, [Fremennik name].",
    ["What's wrong with the patches?"] = "¿Qué pasa con los parches?",
    ["The centre patch is full of weeds, and as soon as I clear them they grow back. The south patch is always far too dry. And the soil in the north patch is terrible; it needs a good dose of compost."] = "El parche central está lleno de malas hierbas y, en cuanto las limpio, vuelven a crecer. La zona sur siempre es demasiado seca. Y el suelo en la zona norte es terrible; necesita una buena dosis de abono.",
    ["Your approval rating."] = "Su índice de aprobación.",
    ["What do people think of me around here?"] = "¿Qué piensa la gente de mí por aquí?",
    ["Your people are growing dissatisfied with the regime, Your Royal Highness. At the last poll, only [approval rating]% of the population supported you."] = "Su gente está cada vez más insatisfecha con el régimen, Su Alteza Real. En la última encuesta, sólo el [approval rating]% de la población lo apoyó.",
    ["You are well regarded, Your Royal Highness. At the last poll, [approval rating]% of the population supported you."] = "Usted es bien considerado, Su Alteza Real. En la última encuesta, el [approval rating]% de la población lo apoyó.",
    ["You are universally adored, Your Royal Highness. At the last poll, [approval rating]% of the population supported you."] = "Usted es universalmente adorado, Su Alteza Real. En la última encuesta, el [approval rating]% de la población lo apoyó.",
    ["*When player rakes the weedy patch, or waters the dry patch nearby*"] = "*Cuando el jugador rastrilla la zona de maleza o riega la zona seca cercana*",
    ["Don't trouble yourself further, [Sir/Madam], you've already done so much!"] = "No te preocupes más, [Sir/Madam], ¡ya has hecho mucho!",
    ["Don't trouble yourself further, Your Highness, you've already done so much!"] = "No se preocupe más, Alteza, ¡ya ha hecho mucho!",
    ["**What would you like to do?**"] = "**¿Qué te gustaría hacer?**",
    ["Ask about their request."] = "Pregunta sobre su solicitud.",
    ["What're you requesting today?"] = "¿Qué pides hoy?",
    ["I've been working on my own farm recently and need a few items to bolster my productivity!"] = "¡He estado trabajando en mi propia granja recientemente y necesito algunos artículos para aumentar mi productividad!",
    ["I'm trying to get some extra crops going, so I'll need : [Seed] x [number]"] = "Estoy intentando conseguir algunos cultivos adicionales, así que necesitaré: [Seed] x [número]",
    ["I'm also looking for a new animal, I'm currently after A [animal]"] = "También estoy buscando un nuevo animal, actualmente estoy buscando A [animal]",
    ["If you complete this, I'll give you : Farming reputation boon (small) x 1. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: bendición de reputación Farming (pequeña) x 1. ¡Estoy seguro de que también ganarás algo de reputación con el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido! Solo estoy aquí por [número] horas y [número] minutos. Para ser exactos.",
    ["Give them the items & animals for their request"] = "Dales los artículos y animales que soliciten.",
    ["You don't have enough items to fulfil my request. I won't take favourited animals."] = "No tienes suficientes artículos para cumplir con mi solicitud. No aceptaré animales favoritos.",
    ["For completing this request you've received Brassica primer x 1."] = "Por completar esta solicitud, recibió 1 imprimación para Brassica.",
    ["You've received : Farming reputation boon (small) x 1 And 2,750 farming reputation."] = "Has recibido: bendición de reputación Farming (pequeña) x 1 y 2750 de reputación agrícola.",
    ["Thank you for your help!"] = "¡Gracias por tu ayuda!",
    ["[A new request will be available in [time].]"] = "[Una nueva solicitud estará disponible en [time].]",
    ["You've already completed this request, there will be a new daily request in [time].."] = "Ya has completado esta solicitud, habrá una nueva solicitud diaria en [time].",
    ["Hi there."] = "Hola.",
    ["Hey."] = "Hola.",
    ["Why, I'm an esteemed farmer and tree surgeon, Farmer Jimbo! People from far and wide request my help in healing and protecting their farming endeavours. I've even had requests from kings and queens before!"] = "¡Soy un estimado agricultor y podador de árboles, Farmer Jimbo! Personas de todas partes solicitan mi ayuda para sanar y proteger sus actividades agrícolas. ¡Incluso he recibido solicitudes de reyes y reinas antes!",
    ["*If not at protected tree in Varrock*"] = "*Si no está en el árbol protegido en Varrock*",
    ["Oh wait, that reminds me. I'm currently on a journey... King Roald! I was meant to be healing his tree!"] = "Oh, espera, eso me recuerda. Actualmente estoy en un viaje... ¡King Roald! ¡Estaba destinado a curar su árbol!",
    ["Right..."] = "Cierto...",
    ["<i>dialogue returns to menu</i>"] = "<i>el diálogo vuelve al menú</i>",
    ["*If at the protected tree in Varrock*"] = "*Si en el árbol protegido en Varrock*",
    ["King Roald asked me to look after this tree to ensure nothing unfortunate befalls it. There were rumors that this tree had died. But as you can see, it's in perfect health! It's so vibrant and full of life, it'll be fully grown before long. They grow up so fast..."] = "King Roald me pidió que cuidara este árbol para asegurarme de que no le suceda nada desafortunado. Hubo rumores de que este árbol había muerto. Pero como puedes ver, ¡se encuentra en perfecto estado de salud! Es tan vibrante y lleno de vida que en poco tiempo crecerá por completo. Crecen tan rápido...",
    ["*If at any other place*"] = "*Si en cualquier otro lugar*",
    ["I've been investigating certain trees while on my travels. Such as here."] = "He estado investigando ciertos árboles durante mis viajes. Como aquí.",
    ["*If in Yanille near the Timbo tree*"] = "*Si en Yanille cerca del árbol Timbo*",
    ["Such a shame. If only I could have reached this poor thing in time."] = "Qué pena. Si tan solo hubiera podido llegar a esta pobre cosa a tiempo.",
    ["<i>Conversation terminates</i>"] = "<i>La conversación termina</i>",
    ["*If near the tree patches (see locations)*"] = "*Si está cerca de los parches de árboles (ver ubicaciones)*",
    ["*If tree is fully grown*"] = "*Si el árbol está completamente desarrollado*",
    ["What a lovely tree. The person who grew it must have been a true professional."] = "Qué árbol tan bonito. La persona que lo cultivó debe haber sido un verdadero profesional.",
    ["*continues below*"] = "*continúa abajo*",
    ["*If tree is chopped down*"] = "*Si el árbol es talado*",
    ["Stop! What are you doing? How dare you nurture a tree from a sapling to just take a hatchet to it!"] = "¡Para! ¿Qué estás haciendo? ¡Cómo te atreves a cultivar un árbol a partir de un retoño para simplemente golpearlo con un hacha!",
    ["*If tree patch is empty*"] = "*Si el huerto está vacío*",
    ["So much potential here, but not being utilised... How sad."] = "Hay mucho potencial aquí, pero no se está utilizando... Qué triste.",
    ["*If a sapling is planted in patch*"] = "*Si se planta un retoño en un parche*",
    ["Aww, a little sapling. Young one, You'll soon grow up to be big and strong!"] = "Oh, un pequeño retoño. Joven, ¡pronto crecerás y serás grande y fuerte!",
    ["*If tree is healthy and growing*<!-- obtained from a pineapple tree in stage 3 -->"] = "*Si el árbol está sano y creciendo*<!-- obtained from a pineapple tree in stage 3 -->",
    ["It makes me happy to see a young healthy tree!"] = "¡Me hace feliz ver un árbol joven y sano!",
    ["*If tree is dead* <!-- obtained from a willow tree dead at stage 2 -->"] = "*Si el árbol está muerto* <!-- obtained from a willow tree dead at stage 2 -->",
    ["Another loss, how sad."] = "Otra pérdida, que tristeza.",
    ["Oh wait, that reminds me, my destination... King Roald! I was meant to be healing his tree!"] = "Oh, espera, eso me recuerda mi destino... ¡King Roald! ¡Estaba destinado a curar su árbol!",
    ["*If at Varrock tree patch*"] = "*Si en el parche del árbol Varrock*",
    ["I should probably move out of his courtyard before he notices..."] = "Probablemente debería salir de su patio antes de que se dé cuenta...",
    ["*If not at the protected tree in Varrock*"] = "*Si no en el árbol protegido en Varrock*",
    ["Ask about the protected tree in Varrock"] = "Pregunta por el árbol protegido en Varrock",
    ["A protected tree in Varrock?"] = "¿Un árbol protegido en Varrock?",
    ["Yes, King Roald planted a tree and..."] = "Sí, King Roald plantó un árbol y...",
    ["Yes! I was meant to be healing that tree! Oh dear, I should probably get moving."] = "¡Sí! ¡Estaba destinado a curar ese árbol! Dios mío, probablemente debería ponerme en marcha.",
    ["Goodbye"] = "Adiós",
    ["<i>Conversation terminates</i><!-- Still needs: Diseased, Dead (in multiple stages diseased/dead?) and other grow stages. -->"] = "<i>La conversación termina</i><!-- Still needs: Diseased, Dead (in multiple stages diseased/dead?) and other grow stages. -->",
    ["Another sheep's wandered off over night. If this continues, I'll've none left by winter."] = "Otra oveja se alejó durante la noche. Si esto continúa, para el invierno no me quedará nada.",
    ["All the noises in the night...the voices..."] = "Todos los ruidos de la noche... las voces...",
    ["Farmer Rachel stares into the fire and drifts away into quiet whispers that you can't quite make out."] = "Farmer Rachel mira fijamente el fuego y se aleja en susurros silenciosos que no puedes entender.",
    ["I uncovered what became of your sheep. I'm afraid they were lured to a cave north of here and killed."] = "Descubrí lo que fue de tus ovejas. Me temo que los atrajeron a una cueva al norte de aquí y los mataron.",
    ["The entity responsible has been dealt with. Your flock should be safe."] = "Se ha solucionado el problema con la entidad responsable. Tu rebaño debería estar a salvo.",
    ["That is sad news, but thank you for taking the time to help me, traveller. The whispers have been quiet of late as well."] = "Es una triste noticia, pero gracias por tomarte el tiempo de ayudarme, viajero. Los rumores también se han calmado últimamente.",
    ["Oh, but now I think about it, someone should check in on Silverquill!"] = "Oh, pero ahora que lo pienso, ¡alguien debería comprobar cómo está Silverquill!",
    ["Silverquill?"] = "¿Pluma plateada?",
    ["She's a friend of Inanna's - a gentle giant of a hedgehog who has her nest in that cave!"] = "Ella es amiga de Inanna: ¡un gentil erizo gigante que tiene su nido en esa cueva!",
    ["I've been so worried about my sheep, I didn't think about her. I hope she's alright too..."] = "He estado tan preocupado por mi oveja que no pensé en ella. Espero que ella también esté bien...",
    ["I'll check in on her as soon as I can."] = "La visitaré tan pronto como pueda.",
    ["Thank you. Take care, y'hear?"] = "Gracias. Cuídate, ¿entiendes?",
    ["You keep away from the produce, you hear me?"] = "Mantente alejado de los productos, ¿me oyes?",
    ["Best pumpkins this side of the sea. You squish them, I squish you, savvy?"] = "Las mejores calabazas de este lado del mar. Tú los aplastas, yo te aplasto, ¿inteligente?",
    ["You steal an avantoe seed."] = "Robas una semilla de avantoe.",
    ["You steal a banana tree seed."] = "Robas una semilla de plátano.",
    ["You steal a bittercap mushroom spore."] = "Robas una espora de hongo amargo.",
    ["You steal a cactus seed."] = "Robas una semilla de cactus.",
    ["You steal a cadantine seed."] = "Robas una semilla cadantina.",
    ["You steal a curry tree seed."] = "Robas una semilla de árbol de curry.",
    ["You steal a dwellberry bush seed."] = "Robas una semilla de arbusto de mora.",
    ["You steal an evil turnip seed."] = "Robas una semilla de nabo malvada.",
    ["You steal a grapevine seed."] = "Robas una semilla de vid.",
    ["You steal an irit seed."] = "Robas una semilla de irit.",
    ["You steal a jangerberry bush seed."] = "Robas una semilla de arbusto de jangerberry.",
    ["You steal a kwuarm seed."] = "Robas una semilla de kwuarm.",
    ["You steal a maple seed."] = "Robas una semilla de arce.",
    ["You steal an orange tree seed."] = "Robas una semilla de naranjo.",
    ["You steal a palm tree seed."] = "Robas una semilla de palmera.",
    ["You steal a papaya tree seed."] = "Robas una semilla de árbol de papaya.",
    ["You steal a pineapple plant seed."] = "Robas una semilla de una planta de piña.",
    ["You steal a poison ivy bush seed."] = "Robas una semilla de arbusto de hiedra venenosa.",
    ["You steal a ranarr seed."] = "Robas una semilla de ranarr.",
    ["You steal a snapdragon seed."] = "Robas una semilla de boca de dragón.",
    ["You steal a spirit weed seed."] = "Robas una semilla de hierba espiritual.",
    ["You steal a starbloom flower seed."] = "Robas una semilla de flor de estrella.",
    ["You steal a toadflax seed."] = "Robas una semilla de lino de sapo.",
    ["You steal a watermelon seed."] = "Robas una semilla de sandía.",
    ["You steal a wergali seed."] = "Robaste una semilla de wergali.",
    ["You steal a whiteberry bush seed."] = "Robas una semilla de arbusto de mora blanca.",
    ["You steal a yew tree seed."] = "Robas una semilla de yew tree.",
    ["In case you didn't know, you don't have to stand by your Farming patch. Your crops will grow even if you're not around."] = "En caso de que no lo sepas, no tienes que mantener tu parche Farming. Tus cultivos crecerán incluso si no estás presente.",
    ["Did you know that if your Farming patch has fully grown, it will never catch disease or die? It will be perfectly safe until you choose to harvest it."] = "¿Sabías que si tu parche Farming ha crecido completamente, nunca contraerá enfermedades ni morirá? Será perfectamente seguro hasta que decidas cosecharlo.",
    ["Hello! Have you come to sample my marvellous wares?"] = "¡Hola! ¿Has venido a probar mis maravillosos productos?",
    ["Choose an option:"] = "Elige una opción:",
    ["Yes, I'd like to see what you have."] = "Sí, me gustaría ver lo que tienes.",
    ["Perhaps. Your stall has some odd-looking stuff; what are they for?"] = "Quizás. Tu puesto tiene algunas cosas de aspecto extraño; ¿para qué sirven?",
    ["I have the finest of items for those who would find their own things to do. Would you like to see them?"] = "Tengo los mejores artículos para aquellos que buscan sus propias cosas que hacer. ¿Quieres verlos?",
    ["But what are they for?"] = "¿Pero para qué sirven?",
    ["Although the world has many things to do, some people like to play games of their own."] = "Aunque el mundo tiene muchas cosas que hacer, a algunas personas les gusta jugar sus propios juegos.",
    ["I sell them the tools to keep track of time, mark out places and routes, decide things randomly, even to hold great ballots of their group."] = "Les vendo las herramientas para llevar la cuenta del tiempo, marcar lugares y rutas, decidir las cosas al azar, incluso para realizar grandes votaciones de su grupo.",
    ["Let me see, then."] = "Déjame ver entonces.",
    ["These tools, are they complicated?"] = "Estas herramientas, ¿son complicadas?",
    ["No, mister/madam, they are not complicated."] = "No, señor/señora, no son complicados.",
    ["I have a book that explains them, should you need."] = "Tengo un libro que los explica, si es necesario.",
    ["I don't think this is for me."] = "No creo que esto sea para mí.",
    ["That is a shame. I shall be here if you change your mind."] = "Eso es una pena. Estaré aquí si cambias de opinión.",
    ["Can I have a treasure chest?"] = "¿Puedo tener un cofre del tesoro?",
    ["No, you may only have one chest at a time. Can I interest you in my other wares?"] = "No, solo puedes tener un cofre a la vez. ¿Puedo interesarte en mis otros productos?",
    ["[Faruq gives you a treasure chest.]"] = "[Faruq te regala un cofre del tesoro.]",
    ["Now, can I interest you in my other wares?"] = "Ahora, ¿puedo interesarte por mis otros productos?",
    ["Go away, I'm very busy."] = "Vete, estoy muy ocupado.",
    ["Sorry to disturb you."] = "Lamento molestarte.",
    ["What are you busy doing?"] = "¿Qué estás ocupado haciendo?",
    ["I'm cooking pizzas for the people in this camp."] = "Estoy cocinando pizzas para la gente de este campamento.",
    ["Not that these louts appreciate my gourmet cooking!"] = "¡No es que estos patanes aprecien mi cocina gourmet!",
    ["So what is a gourmet chef doing cooking for bandits?"] = "Entonces, ¿qué hace un chef gourmet cocinando para bandidos?",
    ["Well, I'm an outlaw. I was accused of giving the king food poisoning! The thought of it! I think he just drank too much wine that night."] = "Bueno, soy un proscrito. ¡Me acusaron de intoxicar al rey! ¡La idea de ello! Creo que bebió demasiado vino esa noche.",
    ["I had to flee the kingdom of Misthalin. The bandits give me refuge here as long as I cook for them."] = "Tuve que huir del reino de Misthalin. Los bandidos me dan refugio aquí mientras cocine para ellos.",
    ["Can I have some pizza too?"] = "¿Puedo comer pizza también?",
    ["Well, this pizza is really meant to be for the bandits. I guess I could sell you some pizza bases though."] = "Bueno, esta pizza realmente está destinada a los bandidos. Aunque supongo que podría venderte algunas bases de pizza.",
    ["Yes, okay."] = "Sí, está bien.",
    ["Oh, if I have to pay I don't want any."] = "Oh, si tengo que pagar no quiero nada.",
    ["Okay, I'll leave you to it."] = "Está bien, te dejo con eso.",
    ["Have you anything to sell?"] = "¿Tienes algo que vender?",
    ["Well, I guess I can sell you some half-made pizzas."] = "Bueno, supongo que puedo venderte algunas pizzas a medio hacer.",
    ["*Redirected to Tony's Pizza Bases*"] = "*Redirigido a Tony's Pizza Bases*",
    ["Goodbye."] = "Adiós.",
    ["Thanks! I've been craving one of these for ages!"] = "¡Gracias! ¡He estado deseando uno de estos durante años!",
    ["Welcome to the church of holy Saradomin."] = "Bienvenido a la iglesia del santo Saradomin.",
    ["Welcome back to the church of holy Saradomin, my friend! What can I do for you today?"] = "¡Bienvenido de nuevo a la iglesia del santo Saradomin, amigo mío! ¿Qué puedo hacer por ti hoy?",
    ["If you find any bones or ashes on your adventures, please feel free to offer them at this altar. You will be rewarded by Saradomin's light with greater knowledge for each one offered."] = "Si encuentras huesos o cenizas en tus aventuras, no dudes en ofrecerlos en este altar. La luz de Saradomin te recompensará con mayor conocimiento por cada uno ofrecido.",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["Ask about your construction contract."] = "Pregunta por tu construction contract.",
    ["What do you need repairing?"] = "¿Qué necesitas reparar?",
    ["Let me see, right now I need you to repair the following pieces of furniture."] = "Déjame ver, ahora mismo necesito que repares el siguiente pieces of furniture.",
    ["What materials do I need?"] = "¿Qué materiales necesito?",
    ["You need: Planks x [number], Steel nails x [number], [Additional material] x [number]"] = "Necesitas: Planks x [número], Steel nails x [número], [Additional material] x [número]",
    ["I'm looking for a quest!"] = "¡Estoy buscando una misión!",
    ["That's lucky, I need someone to do a quest for me."] = "Qué suerte, necesito que alguien haga una misión para mí.",
    ["Not Right Now"] = "Ahora no",
    ["Oh, well. If you do have some spare time on your hands, come back and talk to me."] = "Oh, bueno. Si tienes algo de tiempo libre, regresa y habla conmigo.",
    ["Accept Quest"] = "Aceptar misión",
    ["Thank you. The problem is there's a ghost in the graveyard just south of this church. I would like you to get rid of it."] = "Gracias. El problema es que hay un fantasma en el cementerio justo al sur de esta iglesia. Me gustaría que te deshagas de él.",
    ["You'll need the help of my friend, Father Urhney, who is a bit of a ghost expert."] = "Necesitarás la ayuda de mi amigo, Father Urhney, que es un experto en fantasmas.",
    ["He's currently living in a little shack in the south of Lumbridge Swamps, near the coast."] = "Actualmente vive en una pequeña choza en el sur de Lumbridge Swamps, cerca de la costa.",
    ["My name is Father Aereck, by the way. Pleased to meet you."] = "Por cierto, mi nombre es Father Aereck. Encantado de conocerte.",
    ["Likewise."] = "Igualmente.",
    ["Take care travelling through the swamps. To get there just follow the path south, through the graveyard."] = "Ten cuidado al viajar por los pantanos. Para llegar allí sólo sigue el camino hacia el sur, a través del cementerio.",
    ["I will, thanks."] = "Lo haré, gracias.",
    ["Can you change my gravestone now?"] = "¿Puedes cambiar mi lápida ahora?",
    ["Certainly. All proceeds are donated to the Varrockian Guards' Widows & Orphans Fund."] = "Por supuesto. Todas las ganancias se donan al Fondo de Huérfanos y Viudas de los Guardias Varrockianos.",
    ["Who's Saradomin?"] = "¿Quién es Saradomin?",
    ["Surely you have heard of our god, Saradomin?"] = "¿Seguro que has oído hablar de nuestro dios, Saradomin?",
    ["He who created the forces of goodness and purity in this world? I cannot believe your ignorance!"] = "¿Quien creó las fuerzas de la bondad y la pureza en este mundo? ¡No puedo creer tu ignorancia!",
    ["This is the god with more followers than any other...at least in this part of the world."] = "Este es el dios con más seguidores que cualquier otro... al menos en esta parte del mundo.",
    ["He defeated the evil Zamorak in the battle of Lumbridge nearby, and he defends us from evil!"] = "¡Derrotó al malvado Zamorak en la cercana batalla de Lumbridge y nos defiende del mal!",
    ["Oh, THAT Saradomin."] = "Oh, ESE Saradomin.",
    ["There is only one Saradomin."] = "Sólo hay un Saradomin.",
    ["Yeah. I, uh, thought you said something else."] = "Sí. Pensé que habías dicho algo más.",
    ["Oh, sorry, I'm not from this world."] = "Oh, lo siento, no soy de este mundo.",
    ["That's...strange."] = "Eso es... extraño.",
    ["I thought things not from this world were all, you know, slime and tentacles."] = "Pensé que las cosas que no eran de este mundo eran todas, ya sabes, baba y tentáculos.",
    ["Not me."] = "Yo no.",
    ["Well, I can see that. Still, there's something special about you."] = "Bueno, puedo verlo. Aún así, hay algo especial en ti.",
    ["Thanks, I think."] = "Gracias, creo.",
    ["I am! Do you like my disguise?"] = "¡Lo soy! ¿Te gusta mi disfraz?",
    ["Argh! Avaunt, foul creature from another dimension! Avaunt! Begone in the name of Saradomin!"] = "¡Argh! ¡Criatura asquerosa y audaz de otra dimensión! ¡Avaunt! ¡Vete en nombre de Saradomin!",
    ["Okay, okay, I was only joking!"] = "Está bien, está bien, ¡solo estaba bromeando!",
    ["Can you tell me about the battlefield?"] = "¿Puedes hablarme sobre el campo de batalla?",
    ["Nice place you've got here."] = "Bonito lugar el que tienes aquí.",
    ["It is, isn't it? It was built over two centuries ago."] = "Lo es, ¿no? Fue construido hace más de dos siglos.",
    ["Can you bless my ring?"] = "¿Puedes bendecir mi anillo?",
    ["Ah, you wish to show your devotion to Saradomin by dedicating a ring to him? Very well, it would be my pleasure to assist."] = "Ah, ¿deseas mostrar tu devoción por Saradomin dedicándole un anillo? Muy bien, sería un placer ayudarte.",
    ["[Father Aereck inscribes the symbol of Saradomin on your ring's signet face, and offers a brief benediction over it.]"] = "[Father Aereck inscribe el símbolo de Saradomin en la cara del sello de su anillo y ofrece una breve bendición sobre él.]",
    ["Can you tell me about the crater?"] = "¿Puedes hablarme sobre el cráter?",
    ["Ah, Lumbridge Battlefield - the site of the return of Saradomin! That was a momentous day for the church, and I was there!"] = "Ah, Lumbridge Battlefield: ¡el sitio del regreso de Saradomin! ¡Ese fue un día trascendental para la iglesia y yo estuve allí!",
    ["In a titanic battle that lasted for months, the mighty Saradomin drove back the forces of Zamorak to the Underworld where they belong."] = "En una batalla titánica que duró meses, el poderoso Saradomin hizo retroceder a las fuerzas de Zamorak al inframundo al que pertenecen.",
    ["And now Saradomin is here, we can be sure that we will be safe under his divine protection."] = "Y ahora que Saradomin está aquí, podemos estar seguros de que estaremos a salvo bajo su protección divina.",
    ["All praise Saradomin!"] = "¡Todos los elogios para Saradomin!",
    ["Lumbridge battlefield is where Saradomin himself is currently fighting Zamorak! Thank goodness that he is here! If he'd not shown up when he did, we'd all be thralls of Zamorak now! But he came to us from far away in our time of need, and even now he fights evil on Lumbridge Battlefield. Oh, you must be on your way to Saradomin's war camp in order to help out. It's to the northwest of here. We cannot let evil conquer! Good luck! And may Saradomin be with you!"] = "¡El campo de batalla de Lumbridge es donde el propio Saradomin está luchando actualmente contra Zamorak! ¡Gracias a Dios que está aquí! Si no hubiera aparecido cuando lo hizo, ¡ahora todos seríamos esclavos de Zamorak! Pero vino a nosotros desde muy lejos en nuestro momento de necesidad, e incluso ahora lucha contra el mal en Lumbridge Battlefield. Oh, debes estar de camino al campamento de guerra de Saradomin para poder ayudar. Está al noroeste de aquí. ¡No podemos dejar que el mal venza! ¡Buena suerte! ¡Y que Saradomin esté contigo!",
    ["Have you gotten rid of the ghost yet?"] = "¿Ya te has deshecho del fantasma?",
    ["How was I supposed to do that?"] = "¿Cómo se suponía que debía hacer eso?",
    ["Well, you should go find Father Urhney as he knows all about ghosts."] = "Bueno, deberías ir a buscar a Father Urhney, ya que sabe todo sobre fantasmas.",
    ["You can get to the swamp he lives in by going south through the cemetery."] = "Puedes llegar al pantano en el que vive yendo hacia el sur a través del cementerio.",
    ["You'll have to head south through the swamp - stick to the coastline and you'll find his house in no time."] = "Tendrás que dirigirte hacia el sur a través del pantano; sigue la costa y encontrarás su casa en poco tiempo.",
    ["Have you got rid of the ghost yet?"] = "¿Ya te has deshecho del fantasma?",
    ["I had a talk with Father Urhney. He has given me a funny amulet for talking to ghosts."] = "Tuve una conversación con Father Urhney. Me ha dado un amuleto curioso para hablar con fantasmas.",
    ["I always wondered what that amulet was. Well, I hope it's useful. Tell me when you get rid of the ghost."] = "Siempre me pregunté qué era ese amuleto. Bueno, espero que sea útil. Avísame cuando te deshagas del fantasma.",
    ["That would explain it. Hmm. Well, I haven't seen any skulls."] = "Eso lo explicaría. Mmm. Bueno, no he visto ninguna calavera.",
    ["I hate warlocks. Ah, well, good luck."] = "Odio a los warlocks. Bueno, buena suerte.",
    ["Great! Put it in the ghost's coffin and see what happens."] = "¡Genial! Ponlo en el ataúd del fantasma y mira qué pasa.",
    ["Don't worry, I'm sure you'll find it again."] = "No te preocupes, seguro que lo encuentras de nuevo.",
    ["I don't want it! Put it in the coffin and see what happens."] = "¡No lo quiero! Mételo en el ataúd y mira qué pasa.",
    ["Hi there. Hey, you're the one that got rid of that ghost. I wanted to reward you to say thanks for helping out."] = "Hola. Oye, tú eres quien se deshizo de ese fantasma. Quería recompensarte para agradecerte por ayudar.",
    ["You've got rid of that ghost, haven't you?"] = "Te has deshecho de ese fantasma, ¿verdad?",
    ["Thank you so much. I don't have much money, so I can't pay you, but I could improve your gravestone."] = "Muchas gracias. No tengo mucho dinero, así que no puedo pagarte, pero podría mejorar tu lápida.",
    ["Yes, the gravestone that appears when you die. If you go somewhere dangerous, you'll often find that people have died there and you'll see their gravestones. Most people have very plain ones, but I can upgrade you to a better design."] = "Sí, la lápida que aparece cuando mueres. Si vas a un lugar peligroso, a menudo descubrirás que la gente ha muerto allí y verás sus lápidas. La mayoría de las personas tienen diseños muy sencillos, pero puedo mejorarte con un mejor diseño.",
    ["This faithless place needs a chapel. Here will do."] = "Este lugar infiel necesita una capilla. Aquí servirá.",
    ["Come in, come in."] = "Pasa, pasa.",
    ["**Select an Option**"] = "**Seleccione una opción**",
    ["What does a chapel do?"] = "¿Qué hace una capilla?",
    ["We need an altar, of course, and burners for incense."] = "Necesitamos un altar, por supuesto, y quemadores para incienso.",
    ["We have an altar, of course, and burners for incense."] = "Tenemos un altar, por supuesto, y quemadores para incienso.",
    ["You can always just pray at altars of course, but personally I like to pile up bones on them as offerings. Very pious."] = "Siempre puedes rezar en los altares, por supuesto, pero personalmente me gusta apilar huesos sobre ellos como ofrendas. Muy piadoso.",
    ["If you burn herbs in the burners, the offerings are even more efficient! Everyone loves efficient offerings."] = "Si quemas hierbas en los quemadores, ¡las ofrendas son aún más eficientes! A todo el mundo le encantan las ofertas eficientes.",
    ["You can burn any type of herb at the chapel. Doing so grants extra experience while training prayer by offering bones or ashes, and occasionally saves offered materials."] = "Puedes quemar cualquier tipo de hierba en la capilla. Hacerlo otorga experiencia adicional mientras entrenas la oración al ofrecer huesos o cenizas y, ocasionalmente, guarda los materiales ofrecidos.",
    ["All players on the same world contribute to a shared duration of burning herbs."] = "Todos los jugadores del mismo mundo contribuyen a una duración compartida de quemar hierbas.",
    ["Upgrading the chapel improves your experience, the duration of herbs, and saves even more materials."] = "Actualizar la capilla mejora tu experiencia, la duración de las hierbas y ahorra aún más materiales.",
    ["At tier 1, offerings are worth 250% experience. You have a 3% chance to save offerings. Each herb contributed by a player adds 15 seconds of benefit."] = "En el nivel 1, las ofertas valen un 250 % de experiencia. Tienes un 3% de posibilidades de guardar ofertas. Cada hierba aportada por un jugador añade 15 segundos de beneficio.",
    ["At tier 2, offerings are worth 300% experience. You have a 6% chance to save offerings. Each herb contributed by a player adds 18 seconds of benefit."] = "En el nivel 2, las ofertas valen un 300% de experiencia. Tienes un 6% de posibilidades de guardar ofertas. Cada hierba aportada por un jugador añade 18 segundos de beneficio.",
    ["At tier 3, offerings are worth 350% experience. You have a 10% chance to save offerings. Each herb contributed by a player adds 21 seconds of benefit."] = "En el nivel 3, las ofertas valen un 350% de experiencia. Tienes un 10% de posibilidades de guardar ofertas. Cada hierba aportada por un jugador añade 21 segundos de beneficio.",
    ["At tier 3, you can switch prayer books here."] = "En el nivel 3, puedes cambiar los libros de oraciones aquí.",
    ["Which god do you worship, anyway?"] = "¿A qué dios adoras, de todos modos?",
    ["That would be... an ecumenical matter."] = "Eso sería... un asunto ecuménico.",
    ["You'll need to upgrade your chapel further before I let you tear down the current decor."] = "Tendrás que mejorar aún más tu capilla antes de que te permita derribar la decoración actual.",
    ["**Switch chapel decor to which god?**"] = "**¿Cambiar la decoración de la capilla a qué dios?**",
    ["Oh to be a father in the times of whiskey."] = "Oh, ser padre en los tiempos del whisky.",
    ["I sing and I drink and I wake up in gutters."] = "Canto, bebo y me despierto en las alcantarillas.",
    ["Top of the morning to you."] = "Lo mejor de la mañana para ti.",
    ["To err is human, to forgive, quite difficult."] = "Errar es humano, perdonar, bastante difícil.",
    ["I need a think I drink."] = "Necesito pensar en beber.",
    ["Saradomin loves me, he loves me not, he loves me..."] = "Saradomin me ama, no me ama, me ama...",
    ["*sigh* He loves me not."] = "*suspiro* Él no me ama.",
    ["May Saradomin bless you! I can see you have many mighty adventures ahead of you."] = "¡Que Saradomin te bendiga! Puedo ver que tienes muchas aventuras maravillosas por delante.",
    ["Are you Player?"] = "¿Eres Player?",
    ["I've heard all about how you killed the demon Delrith!"] = "¡He oído todo acerca de cómo mataste al demonio Delrith!",
    ["My partner Badden and I are observing another group of wizards, and we think they're planning to summon another demon."] = "Mi compañero Badden y yo estamos observando otro grupo de magos y creemos que están planeando convocar a otro demonio.",
    ["They haven't found a place to perform their ritual yet, but when they do, we might need your help!"] = "Aún no han encontrado un lugar para realizar su ritual, pero cuando lo encuentren, ¡podríamos necesitar tu ayuda!",
    ["Go away! I'm meditating!"] = "¡Vete! ¡Estoy meditando!",
    ["Well, that's friendly."] = "Bueno, eso es amigable.",
    ["I said go away!"] = "¡Dije que te fueras!",
    ["Okay, okay. Sheesh, what a grouch."] = "Está bien, está bien. Joder, qué cascarrabias.",
    ["I've come to repossess your house."] = "He venido a recuperar tu casa.",
    ["On what grounds?"] = "¿Por qué motivos?",
    ["Repeated failure to make mortgage repayments."] = "Incumplimiento reiterado del pago de la hipoteca.",
    ["What? But I don't have a mortgage - I build this house myself!"] = "¿Qué? Pero no tengo una hipoteca: ¡la casa la construyo yo mismo!",
    ["Sorry, I must have got the wrong address. All the houses look the same around here."] = "Lo siento, debo haberme equivocado de dirección. Todas las casas parecen iguales por aquí.",
    ["What? What houses? This is the only one. What are you talking about?"] = "¿Qué? ¿Qué casas? Éste es el único. ¿De qué estás hablando?",
    ["Never mind."] = "No importa.",
    ["I don't know, I just wanted this house."] = "No lo sé, sólo quería esta casa.",
    ["Oh, go away and stop wasting my time."] = "Oh, vete y deja de hacerme perder el tiempo.",
    ["*(After The Restless Ghost)* I've lost that ghostspeak amulet you gave me."] = "*(Después de The Restless Ghost)* He perdido ese amuleto de habla fantasma que me diste.",
    ["Father Urhney sighs."] = "Father Urhney suspira.",
    ["*(If the amulet is equipped, or in inventory:)*"] = "*(Si el amuleto está equipado o en el inventario:)*",
    ["What are you talking about? I can see you've got it with you."] = "¿De qué estás hablando? Puedo ver que lo tienes contigo.",
    ["*(If the amulet is in the bank:)*"] = "*(Si el amuleto está en el banco:)*",
    ["Why do you insist on wasting my time? Has it even occurred to you to look in your bank? Now go away!"] = "¿Por qué insistes en hacerme perder el tiempo? ¿Se te ha ocurrido siquiera buscar en tu banco? ¡Ahora vete!",
    ["*(If the player has a cramulet:)*"] = "*(Si el player tiene cramulet:)*",
    ["It's probably tangled up in your cramulet."] = "Probablemente esté enredado en tu cramulet.",
    ["*(If the player genuinely has lost their ghostspeak amulet:)*"] = "*(Si el player realmente ha perdido su amuleto de habla fantasma:)*",
    ["How careless can you get? Those things aren't easy to come by, you know! It's a good job I've got a spare."] = "¿Qué tan descuidado puedes llegar a ser? Esas cosas no son fáciles de conseguir, ¿sabes? Es un buen trabajo. Tengo uno de repuesto.",
    ["[Father Urhney hands you an amulet.]"] = "[Father Urhney te entrega un amuleto.]",
    ["Be more careful this time."] = "Ten más cuidado esta vez.",
    ["Okay, I'll try to be."] = "Está bien, intentaré serlo.",
    ["There were enough people clattering around my house before, and then Zamorak decides he wants a war camp right next to my hut."] = "Antes había suficiente gente haciendo ruido en mi casa, y entonces Zamorak decide que quiere un campamento de guerra justo al lado de mi cabaña.",
    ["At least Zamorak has gone now, but he's left his camp littering my swamp."] = "Al menos Zamorak ya se fue, pero dejó su campamento ensuciando mi pantano.",
    ["There were enough people clattering around my house before, and then Zamorak decides he wants a war camp right next to my hut. Well, I'm not going to move again! At least Saradomin is there to deal with it this time. Maybe you should toddle off to Saradomin's camp and help out. And close the door on the way out!"] = "Antes había suficiente gente haciendo ruido en mi casa, y entonces Zamorak decide que quiere un campamento de guerra justo al lado de mi cabaña. ¡Pues no me voy a mover más! Al menos Saradomin está ahí para solucionarlo esta vez. Quizás deberías ir al campamento de Saradomin y ayudar. ¡Y cierra la puerta al salir!",
    ["Aren't you afraid of Zamorak?"] = "¿No le tienes miedo a Zamorak?",
    ["Yes, I'm terrified. But he's looking the other way, and Saradomin will defeat him soon. So why don't you go and deal with him while I get back to my meditation. I'm sure Saradomin will appreciate it."] = "Sí, estoy aterrorizado. Pero él está mirando para otro lado y Saradomin lo derrotará pronto. Entonces, ¿por qué no vas y te ocupas de él mientras yo vuelvo a mi meditación? Estoy seguro de que Saradomin lo agradecerá.",
    ["You don't want to dip into those pockets without good reason. They're holy...and filthy."] = "No querrás echar mano de esos bolsillos sin una buena razón. Son santos... y sucios.",
    ["[pic=Clue scroll (medium) detail.png]"] = "[pic=Desplazamiento de pistas (mediano) detail.png]",
    ["The sooner you answer the question, the sooner you can leave me in peace."] = "Cuanto antes respondas la pregunta, antes podrás dejarme en paz.",
    ["Enter amount: [Input field]"] = "Ingrese la cantidad: [Input field]",
    ["Wrong! Now go away. I'm meditating."] = "¡Mal! Ahora vete. Estoy meditando.",
    ["[If only to get rid of you, Father Urnhey has given you another clue scroll!]"] = "[¡Aunque sólo sea para deshacerse de ti, el padre Urnhey te ha dado otro pergamino de pistas!]",
    ["Congratulations. Either you can count, you got lucky, or you do not trust your own mind and traffic in otherworldly sources of infernal knowledge."] = "Felicitaciones. O puedes contar, has tenido suerte o no confías en tu propia mente y traficas con fuentes de conocimiento infernal sobrenaturales.",
    ["Regardless, for the love of Saradomin... Please. Leave me and don't bother me again. I want to be left alone."] = "De todos modos, por el amor de Saradomin... Por favor. Déjame y no me vuelvas a molestar. Quiero que me dejen en paz.",
    ["Father Aereck sent me to talk to you."] = "Father Aereck me envió a hablar contigo.",
    ["I suppose I'd better talk to you then. What has he got himself into this time?"] = "Supongo que será mejor que hable contigo entonces. ¿En qué se ha metido esta vez?",
    ["A ghost is haunting his graveyard."] = "Un fantasma está rondando su cementerio.",
    ["Oh, the silly fool."] = "Oh, tonto ingenuo.",
    ["I leave town for five months and he's already having problems."] = "Me voy de la ciudad por cinco meses y él ya tiene problemas.",
    ["*sigh*"] = "*suspiro*",
    ["Well, I can't go back and exorcise it - I vowed not to leave this place until I've spent a full two years praying and meditating."] = "Bueno, no puedo regresar y exorcizarlo; prometí no dejar este lugar hasta que haya pasado dos años completos orando y meditando.",
    ["I'll tell you what I can do, though - take this amulet."] = "Sin embargo, te diré lo que puedo hacer: toma este amuleto.",
    ["Sorry, that's not really possible. I don't have space to carry anything. I'll be right back!"] = "Lo siento, eso no es realmente posible. No tengo espacio para llevar nada. ¡Vuelvo enseguida!",
    ["It is a ghostspeak amulet."] = "Es un ghostspeak amulet.",
    ["It's called that because, when you wear it, you can speak to ghosts. Many ghosts are doomed to remain in this world because they have some important task left uncompleted."] = "Se llama así porque, cuando lo usas, puedes hablar con fantasmas. Muchos fantasmas están condenados a permanecer en este mundo porque tienen alguna tarea importante sin terminar.",
    ["If you know what this task is, you can get rid of the ghost. I'm not making any guarantees, mind you, but it's the best I can do right now."] = "Si sabes cuál es esta tarea, podrás deshacerte del fantasma. No te garantizo nada, ojo, pero es lo mejor que puedo hacer ahora.",
    ["Thank you. I'll give it a try."] = "Gracias. Lo intentaré.",
    ["You mean he gets into lots of problems?"] = "¿Quieres decir que se mete en muchos problemas?",
    ["Yeah. Even when we were trainee priests he kept getting stuck up bell ropes."] = "Sí. Incluso cuando éramos sacerdotes en formación, se quedaba atascado en las cuerdas de las campanas.",
    ["Anyway, I don't have time for chit-chat. What's his problem this time?"] = "En fin, no tengo tiempo para charlas. ¿Cuál es su problema esta vez?",
    ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
    ["I want [number] [items] for that."] = "Quiero [número] [items] para eso.",
    ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
    ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
    ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
    ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
    ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
    ["I think you should claim the XP from that patch before having it chopped down."] = "Creo que deberías reclamar los XP de ese parche antes de eliminarlo.",
    ["Pay 200 gp to have the tree chopped down?"] = "¿Pagar 200 po para que talen el árbol?",
    ["Yes, get rid of the tree."] = "Sí, deshazte del árbol.",
    ["I'll want 200 gp for chopping down that tree."] = "Querré 200 po por talar ese árbol.",
    ["The gardener obligingly removes your tree."] = "El jardinero amablemente retira su árbol.",
    ["Would you chop my tree down for me?"] = "¿Podrías talar mi árbol por mí?",
    ["You look like you could chop it down yourself. I can chop the tree down for you if you like, but I'll want 200 gp to make it worth my while."] = "Parece que podrías cortarlo tú mismo. Puedo talar el árbol si quieres, pero necesitaré 200 po para que valga la pena.",
    ["200 gp? I'll do it myself."] = "¿200 po? Lo haré yo mismo.",
    ["Okay, go ahead."] = "Está bien, adelante.",
    ["I don't have 200 gp I'm afraid."] = "Me temo que no tengo 200 po.",
    ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
    ["If you like, but I want [number] [item] for that."] = "Si quieres, pero quiero [número] [item] para eso.",
    ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
    ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
    ["Okay, it's a deal."] = "Está bien, es un trato.",
    ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["No, that's too much."] = "No, eso es demasiado.",
    ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
    ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
    ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
    ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
    ["Can you sell me something?"] = "¿Puedes venderme algo?",
    ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
    ["Some plant cure."] = "Alguna cura vegetal.",
    ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
    ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
    ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
    ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
    ["A bucket of compost."] = "Un balde de abono.",
    ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
    ["A rake."] = "Un rastrillo.",
    ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See more items)"] = "(Ver más artículos)",
    ["A watering can"] = "una regadera",
    ["A watering can."] = "Una regadera.",
    ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
    ["A gardening trowel"] = "Una paleta de jardinería",
    ["A gardening trowel."] = "Una paleta de jardinería.",
    ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["A seed dibber"] = "Un zambullidor de semillas",
    ["A seed dibber."] = "Un arrancador de semillas.",
    ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See previous items)"] = "(Ver artículos anteriores)",
    ["Forget it."] = "Olvídalo.",
    ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
    ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
    ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    ["I'm working. What do you have to say that's so urgent?"] = "Estoy trabajando. ¿Qué tienes que decir que sea tan urgente?",
    ["What can you tell me about Al Kharid?"] = "¿Qué puedes contarme sobre Al Kharid?",
    ["There's a lot of space here. More open space than back home."] = "Hay mucho espacio aquí. Más espacio abierto que en casa.",
    ["So where is back home?"] = "Entonces, ¿dónde está tu casa?",
    ["Pollnivneach. It's a town to the south of the Shantay Pass."] = "Pollnivneach. Es un pueblo al sur del paso Shantay.",
    ["So, what do you do here?"] = "Entonces, ¿qué haces aquí?",
    ["I'm on guard duty. Making sure nobody tries to steal anything from the house and tents in the middle of town."] = "Estoy de guardia. Asegurándonos de que nadie intente robar nada de la casa y las tiendas de campaña en el centro de la ciudad.",
    ["Why are you only guarding those buildings?"] = "¿Por qué sólo estás protegiendo esos edificios?",
    ["That's all I've been hired to guard."] = "Eso es todo lo que me han contratado para proteger.",
    ["*If the player has asked any of the Al Kharid merchants about Ali Morrisane:*"] = "*Si el player ha preguntado a alguno de los comerciantes de Al Kharid sobre Ali Morrisane:*",
    ["I hear you work for Ali Morrisane..."] = "He oído que trabajas para Ali Morrisane...",
    ["Yeah, he hired me. He owns this house and these two tents, too."] = "Sí, me contrató. Él es dueño de esta casa y también de estas dos tiendas.",
    ["Is the work good?"] = "¿Está bien el trabajo?",
    ["It pays better than back home."] = "Se paga mejor que en casa.",
    ["Why, what did you do back home?"] = "¿Por qué? ¿Qué hiciste en casa?",
    ["Never you mind."] = "No importa.",
    ["But Ali Morrisane pays us well, at least."] = "Pero Ali Morrisane nos paga bien, al menos.",
    ["Maybe I should talk to him..."] = "Quizás debería hablar con él...",
    ["Why not? He always likes to meet potential business partners."] = "¿Por qué no? Siempre le gusta conocer posibles socios comerciales.",
    ["*If the player has asked Karim, Shop assistant, or Shopkeeper about Ali Morrisane:*"] = "*Si el player ha preguntado a Karim, Shop assistant o Shopkeeper sobre Ali Morrisane:*",
    ["I hear you've been threatening the other shopkeepers."] = "He oído que has estado amenazando a los demás comerciantes.",
    ["So? They talk too much."] = "¿Y entonces? Hablan demasiado.",
    ["You're not going to deny it?"] = "¿No lo vas a negar?",
    ["Why bother? None of them can fight back, after all."] = "¿Por qué molestarse? Después de todo, ninguno de ellos puede defenderse.",
    ["The Feline akh starts to call for help."] = "El Feline akh comienza a pedir ayuda.",
    ["What was it I heard about some pits around here?"] = "¿Qué fue lo que escuché sobre algunos pozos por aquí?",
    ["- Felkrash breaks down into tears -"] = "- Felkrash rompe a llorar -",
    ["It is... It used to be my rat pits. You could bring your cats here to fight. It was going to be glorious! It was open for years. Not a single person visited! How could so many be so foolish as to ignore such brilliance?"] = "Es... Solía ser mi nido de ratas. Podrías traer a tus gatos aquí para pelear. ¡Iba a ser glorioso! Estuvo abierto durante años. ¡Ni una sola persona nos visitó! ¿Cómo es posible que tantos sean tan tontos como para ignorar semejante brillantez?",
    ["I guess brilliance is one word for it."] = "Supongo que brillantez es una palabra para describirlo.",
    ["Felkrash glares at you angrily, you walk away while you can. -"] = "Felkrash te mira enojado, te alejas mientras puedas. -",
    ["Can you train my cat for me?"] = "¿Puedes entrenar a mi gato por mí?",
    ["Can you show me how to train my cat into a wily cat?"] = "¿Puedes mostrarme cómo entrenar a mi gato para que se convierta en un gato astuto?",
    ["I can only train overgrown cats into wilycats."] = "Sólo puedo entrenar gatos demasiado grandes para convertirlos en gatos astutos.",
    ["You already have a mature cat, look after that first."] = "Ya tienes un gato adulto, cuídalo primero.",
    ["Your overgrown cat has grown into a lean mean hunting cat."] = "Tu gato, ya crecido, se ha convertido en un gato cazador delgado y malvado.",
    ["You should really name your cat."] = "Realmente deberías nombrar a tu gato.",
    ["Can you rename my cat?"] = "¿Puedes cambiarle el nombre a mi gato?",
    ["I'll only help you name wily or lazy cats. Bring me one and I'll help you out."] = "Sólo te ayudaré a nombrar gatos astutos o perezosos. Tráeme uno y te ayudaré.",
    ["Hey Player, you finally got around to naming me."] = "Hola Player, finalmente pudiste nombrarme.",
    ["Sorry I took so long, [cat's name], it took a while to come up with a name for you."] = "Lo siento, me tomó tanto tiempo, [cat's name], me tomó un tiempo encontrar un nombre para ti.",
    ["So, cat, what do you think of the name?"] = "Entonces, gato, ¿qué opinas del nombre?",
    ["Miaaow!"] = "¡Miaaow!",
    ["Can you tell me more about Wily cats?"] = "¿Puedes contarme más sobre los gatos Wily?",
    ["Of course, of course, they're the highest form of cat that I know of."] = "Por supuesto, por supuesto, son la forma más elevada de gato que conozco.",
    ["They're tougher, stronger and faster than other variations of cat, they can catch butterflies and kalphite larva and are far superior to any other type of cat at hunting."] = "Son más duros, fuertes y rápidos que otras variaciones de gato, pueden atrapar mariposas y larvas de kalfita y son muy superiores a cualquier otro tipo de gato en la caza.",
    ["So is there any drawbacks to owning them?"] = "Entonces, ¿hay algún inconveniente en poseerlos?",
    ["Wily cats need looking after or else they get fat and lazy."] = "Los gatos astutos necesitan cuidados o se vuelven gordos y perezosos.",
    ["So how do I look after them then?"] = "Entonces, ¿cómo los cuido?",
    ["The key is to keep it active, bring it hunting regularly."] = "La clave es mantenerlo activo y llevarlo a cazar con regularidad.",
    ["Try keep it happy too, they can be a little nasty when they're cranky."] = "Intenta mantenerlo feliz también, pueden ser un poco desagradables cuando están de mal humor.",
    ["What happens if I neglect my cat, not that I would or anything?"] = "¿Qué pasa si descuido a mi gato, no es que lo haría ni nada por el estilo?",
    ["They would get fat and lazy, be much worse at hunting and would show you up as a really poor cat trainer."] = "Se volverían gordos y perezosos, serían mucho peores cazando y te mostrarían como un gato realmente pobre trainer.",
    ["Can I retrain my lazy cat?"] = "¿Puedo volver a entrenar a mi gato perezoso?",
    ["Yes you can get your lazy cat back in shape with a lot of rat catching, but you really shouldn't let it get into that state in the first place."] = "Sí, puedes hacer que tu gato perezoso vuelva a estar en forma atrapando muchas ratas, pero en primer lugar, no deberías dejar que llegue a ese estado.",
    ["Hi!"] = "¡Hola!",
    ["Could you help me lift these boxes? They are really heavy!"] = "¿Podrías ayudarme a levantar estas cajas? ¡Son realmente pesados!",
    ["Sorry, I'm a bit busy."] = "Lo siento, estoy un poco ocupado.",
    ["Oh, OK, I'll do it myself."] = "Oh, está bien, lo haré yo mismo.",
    ["OK then."] = "Bueno, entonces.",
    ["Thanks traveller!"] = "¡Gracias viajero!",
    ["Thanks again friend!"] = "¡Gracias de nuevo amigo!",
    ["The little gnome is too busy to talk."] = "El pequeño gnomo está demasiado ocupado para hablar.",
    ["Well done!"] = "¡Bien hecho!",
    ["Femi has given you another clue scroll!"] = "¡Femi te ha dado otro pergamino de pistas!",
    ["You've found a casket!"] = "¡Has encontrado un ataúd!",
    ["Meow, meow meow."] = "Miau, miau, miau.",
    ["*sigh* Why is life so difficult? Why can't she just like me the same way I like her? I mean we have so many things in common. She likes mice, I like mice. She likes playing with string, I like playing with string. She coughs up sticky balls of fur. *sigh* She's so beautiful."] = "*suspiro* ¿Por qué la vida es tan difícil? ¿Por qué no puedo gustarle de la misma manera que a mí me gusta ella? Quiero decir que tenemos tantas cosas en común. A ella le gustan los ratones, a mí me gustan los ratones. A ella le gusta jugar con cuerdas, a mí me gusta jugar con cuerdas. Tose bolas de pelo pegajosas. *suspiro* Ella es tan hermosa.",
    ["Welcome, fellow mercenary, welcome."] = "Bienvenido, compañero mercenario, bienvenido.",
    ["Can you assign me a bounty?"] = "¿Puedes asignarme una recompensa?",
    ["Which faction do you fight for today, my friend?"] = "¿Por qué facción luchas hoy, amigo mío?",
    ["**SELECT A FACTION TO EARN REPUTATION WITH.**"] = "**SELECCIONA UNA FACCIÓN CON LA QUE GANAR REPUTACIÓN.**",
    ["Very well. Your bounty is to slay those loyal to [Faction] in the name of Sliske!"] = "Muy bien. ¡Tu recompensa es matar a los leales a [Faction] en nombre de Sliske!",
    ["Very well. Your bounty is to slay those loyal to [Faction] in the name of Zamorak!"] = "Muy bien. ¡Tu recompensa es matar a los leales a [Faction] en nombre de Zamorak!",
    ["Very well. Your bounty is to slay those loyal to [Faction] in the name of Seren!"] = "Muy bien. ¡Tu recompensa es matar a los leales a [Faction] en nombre de Seren!",
    ["Very well. Your bounty is to slay those loyal to [Faction] in the name of Zaros!"] = "Muy bien. ¡Tu recompensa es matar a los leales a [Faction] en nombre de Zaros!",
    ["So bloodthirsty! You have had your quota of bounties, my friend. Come back another day."] = "¡Qué sanguinario! Ya has tenido tu cuota de recompensas, amigo mío. Vuelve otro día.",
    ["You already have a bounty to slay those loyal to [Faction] in the name of Sliske!"] = "¡Ya tienes una recompensa para matar a los leales a [Faction] en nombre de Sliske!",
    ["You already have a bounty to slay those loyal to [Faction] in the name of Zamorak!"] = "¡Ya tienes una recompensa para matar a los leales a [Faction] en nombre de Zamorak!",
    ["You already have a bounty to slay those loyal to [Faction] in the name of Seren!"] = "¡Ya tienes una recompensa para matar a los leales a [Faction] en nombre de Seren!",
    ["You already have a bounty to slay those loyal to [Faction] in the name of Zaros!"] = "¡Ya tienes una recompensa para matar a los leales a [Faction] en nombre de Zaros!",
    ["How many bounties do I have available?"] = "¿Cuántas recompensas tengo disponibles?",
    ["I can assign you [number] [bounty/bounties] before you reach your quota. You can have one now, if you like?"] = "Puedo asignarte [número] [bounty/bounties] antes de que alcances tu cuota. ¿Puedes tener uno ahora, si quieres?",
    ["Yes, I'd like a bounty."] = "Sí, me gustaría una recompensa.",
    ["No, not right now."] = "No, no ahora mismo.",
    ["I can assign you [number] [bounty/bounties] before you reach your quota."] = "Puedo asignarte [número] [bounty/bounties] antes de que alcances tu cuota.",
    ["I'd like to abandon my current bounty."] = "Me gustaría abandonar mi recompensa actual.",
    ["Hmm, abandon your bounty? I must warn you, it will still count towards your quota. Are you sure?"] = "Hmm, ¿abandonas tu recompensa? Debo advertirte que seguirá contando para tu cuota. ¿Está seguro?",
    ["**ABANDON YOUR CURRENT BOUNTY?**"] = "**¿ABANDONAS TU RECOMPENSA ACTUAL?**",
    ["Yes, abandon my bounty."] = "Sí, abandona mi recompensa.",
    ["No, keep my bounty."] = "No, quédate con mi recompensa.",
    ["Can you tell me more about your bounties?"] = "¿Puedes contarme más sobre tus recompensas?",
    ["I assign bounties to fellow mercenaries like yourself. This is a war, you see, and there's killin' to be done. The deals I cut with the faction representatives here mean you can pick one to do your bounties for, earning reputation with them in return."] = "Asigno recompensas a compañeros mercenarios como tú. Verás, esto es una guerra y hay que matar. Los acuerdos que cerré con los representantes de las facciones aquí significan que puedes elegir uno para hacer tus recompensas, ganando reputación con ellos a cambio.",
    ["What does a bounty entail?"] = "¿Qué implica una recompensa?",
    ["Well, killin' of course. One hundred kills of the faction I assign you, to be precise, but if you kill their general it counts as twenty-five! You pick the faction you fight for, I pick the faction you fight against, then away you go. Happy hunting."] = "Bueno, matar, por supuesto. Te asigno cien muertes de la facción, para ser precisos, ¡pero si matas a su general cuenta como veinticinco! Tú eliges la facción por la que luchas, yo elijo la facción contra la que luchas y luego te vas. Feliz caza.",
    ["So why are you even here in the first place?"] = "Entonces, ¿por qué estás aquí en primer lugar?",
    ["I'm a mercenary, much like anyone else in this war-torn place. 'Course I have my own nefarious agenda, but that's for me to know."] = "Soy un mercenario, como cualquier otra persona en este lugar devastado por la guerra. Por supuesto que tengo mis propios planes nefastos, pero eso es algo que debo saber yo.",
    ["Happy hunting."] = "Feliz caza.",
    ["You can't hand in a bounty, I haven't assigned you one..."] = "No puedes entregar una recompensa, no te he asignado ninguna...",
    ["You haven't completed your bounty yet. Go and slay some more."] = "Aún no has completado tu recompensa. Ve y mata a algunos más.",
    ["Ah yes, I see you've completed your bounty. Good hunting, here's your reward."] = "Ah, sí, veo que has completado tu recompensa. Buena caza, aquí tienes tu recompensa.",
    ["You have gained 150 reputation with the Serenist forces!"] = "¡Has ganado 150 de reputación con las fuerzas serenistas!",
    ["You have gained 150 reputation with the Sliskean forces!"] = "¡Has ganado 150 de reputación con las fuerzas de Sliske!",
    ["You have gained 150 reputation with the Zamorakian forces!"] = "¡Has ganado 150 puntos de reputación con las fuerzas zamorakianas!",
    ["You have gained 150 reputation with the Zarosian forces!"] = "¡Has ganado 150 de reputación con las fuerzas zarosianas!",
    ["You can now discover the blueprint for Ilujankan components if you have at least 89 Invention."] = "Ahora puede descubrir el plano de los componentes de Ilujankan si tiene al menos 89 Invention.",
    ["Interestin' find. You've brought it to the right place."] = "Interesante hallazgo. Lo has traído al lugar correcto.",
    ["Of course I did."] = "Por supuesto que lo hice.",
    ["It was a matter of time. There's only five people up here."] = "Era cuestión de tiempo. Sólo hay cinco personas aquí arriba.",
    ["I did?"] = "¿Lo hice?",
    ["What could you possibly want it for?"] = "¿Para qué podrías quererlo?",
    ["I've heard of a [gal/guy] that collects weird trinkets. Might be able to extract a fair price."] = "He oído hablar de un [gal/guy] que colecciona baratijas extrañas. Quizás pueda obtener un precio justo.",
    ["Maybe you yourself would be interested in a reasonable trade? I've acquired an enchanted signal horn that I'd be willing to let go."] = "¿Tal vez usted mismo estaría interesado en un intercambio razonable? Adquirí una bocina de señales encantada que estaría dispuesto a dejar ir.",
    ["**Exchange your chest of junk for a signal horn?**"] = "**¿Cambiar tu cofre de basura por una bocina de señal?**",
    ["Yes"] = "si",
    ["[Feng gives you a horn in exchange for the chest. Whoever he's talking about must like some weird stuff.]"] = "[Feng te da un cuerno a cambio del cofre. De quienquiera que esté hablando le deben gustar algunas cosas raras.]",
    ["Let's play vampyres and vampyre hunters! I'll be the vampyre."] = "¡Juguemos a los cazadores vampyres y vampyre! Yo seré el vampyre.",
    ["No fair! You're always the vampyre."] = "¡No es justo! Siempre eres el vampyre.",
    ["But I'm hungry for blood... Blaaargh..."] = "Pero tengo hambre de sangre... Blaaargh...",
    ["Die, monster!"] = "¡Muere, monstruo!",
    ["A stake! My one weakness! Nooooo!"] = "¡Una estaca! ¡Mi única debilidad! ¡Nooooo!",
    ["The vampyre is weakened by your holy symbol of Saradomin."] = "El vampyre está debilitado por su símbolo sagrado de Saradomin.",
    ["Good day, sir."] = "Buenos días, señor.",
    ["What are you doing down here?"] = "¿Qué estás haciendo aquí abajo?",
    ["Shoring up the walls."] = "Apuntalando las paredes.",
    ["What does that do?"] = "¿Qué hace eso?",
    ["Stops them falling down."] = "Evita que se caigan.",
    ["Oh, I see."] = "Ah, ya veo.",
    ["Aye. If you want to chatter, you'd better talk to Thorodin over there. I'm working."] = "Sí. Si quieres charlar, será mejor que hables con Thorodin que está allí. Estoy trabajando.",
    ["Okay then."] = "Está bien, entonces.",
    ["We're allowed to talk again!"] = "¡Podemos hablar de nuevo!",
    ["Sorry - I find it so hard not to chat with strangers. They're just so interesting!"] = "Lo siento, me resulta muy difícil no charlar con extraños. ¡Son tan interesantes!",
    ["Let me know if you find any goodies out in the woods. I'm always on the hunt for new resources!"] = "Avísame si encuentras algo bueno en el bosque. ¡Siempre estoy buscando nuevos recursos!",
    ["Can I see your wares?"] = "¿Puedo ver tus productos?",
    ["I'm getting out of here Bwana, the place is infested with zombies."] = "Me voy de aquí Bwana, el lugar está infestado de zombies.",
    ["I'm getting out of here, bwana; the place is infested with zombies."] = "Me voy de aquí, bwana; el lugar está infestado de zombies.",
    ["Welcome to Fernahei's Fishing Shop Bwana! Would you like to see my items?"] = "¡Bienvenido a la tienda Fishing Bwana de Fernahei! ¿Quieres ver mis artículos?",
    ["Yes please!"] = "¡Sí, por favor!",
    ["No, but thanks for the offer."] = "No, pero gracias por la oferta.",
    ["That's fine and thanks for your interest."] = "Está bien y gracias por tu interés.",
    ["Never heard of ya."] = "Nunca había oído hablar de ti.",
    ["The world guardian."] = "El guardián del mundo.",
    ["Yea? Well I'm the Underworld guardian."] = "¿Sí? Bueno, soy el guardián del inframundo.",
    ["Who's asking?"] = "¿Quién pregunta?",
    ["The Ferryman is."] = "El Ferryman es.",
    ["Well, my name is Player."] = "Bueno, mi nombre es Player.",
    ["So it is."] = "Así es.",
    ["Ok... Ka told me to talk to you about boating on the River Noumenon."] = "Ok... Ka me dijo que te hablara sobre paseos en bote por el río Noumenon.",
    ["What is it ya wanna know?"] = "¿Qué es lo que quieres saber?",
    ["Ask about soul collection."] = "Pregunta por la recogida de almas.",
    ["Well, I guess we need the help. If ya wanna get ya hands dirty then take a boat from one of the jetties beside the bridge. Once you're on the river ya can row about collectin' souls. The more ya collect, the more Noumenon Favour ya get for escortin' them over the bridge."] = "Bueno, supongo que necesitamos ayuda. Si quieres ensuciarte las manos, toma un bote desde uno de los embarcaderos al lado del puente. Una vez que estés en el río podrás remar y recolectar almas. Cuanto más recolectes, más Noumenon Favor obtendrás por escoltarlos por el puente.",
    ["Ask about special souls."] = "Pregunta por almas especiales.",
    ["Ah, so you've heard of the 'special' souls have ya? The chosen few? Those are the ones that deserve a chance of reincarnation. Icthlarin hasn't seen 'em yet, what with him being so busy 'n' all. If ya manage to collect one, you'll absorb their power and gain skill in what ever their profession was in life. Today I have noticed these souls are *the five special souls of the day*."] = "Ah, entonces has oído hablar de las almas \"especiales\", ¿verdad? ¿Los pocos elegidos? Esos son los que merecen una oportunidad de reencarnar. Icthlarin aún no los ha visto, ya que está tan ocupado y todo. Si logras recolectar uno, absorberás su poder y ganarás habilidad en cualquiera que haya sido su profesión en la vida. Hoy he notado que estas almas son *las cinco almas especiales del día*.",
    ["Ask about chests."] = "Pregunta por los cofres.",
    ["Oh yes, almost forgot about the chests. Sometimes we get odd things surfacing on the river. All sorts get lost in the Noumenon. If ya keep your eyes peeled ya might notice a chest float up every so often. Get all kinds of things outta those."] = "Oh, sí, casi me olvido de los cofres. A veces aparecen cosas raras en el río. Todo tipo de cosas se pierden en el Noúmeno. Si mantienes los ojos bien abiertos, es posible que notes que un cofre flota hacia arriba de vez en cuando. Saca todo tipo de cosas de ellos.",
    ["You can now be ferried to this destination: [Well of Souls/Ed's Boatyard/Main Plaza/Sunken Market/Haunt on the Hill]."] = "Ahora puedes ser transportado a este destino: [Well of Souls/Ed's Boatyard/Main Plaza/Sunken Market/Haunt on the Hill].",
    ["You'll need to unlock a second ferry destination before you can use this service."] = "Deberá desbloquear un segundo destino de ferry antes de poder utilizar este servicio.",
    ["Select ferry destination"] = "Selecciona el destino del ferry",
    ["1. Well of Souls (ritual site)."] = "1. Pozo de las Ánimas (lugar ritual).",
    ["2. Ed's Boatyard (boat tours)."] = "2. Ed's Boatyard (paseos en barco).",
    ["3. Main Plaza (Soul Supplies)."] = "3. Plaza Principal (Suministros del Alma).",
    ["4. Sunken Market (bank)."] = "4. Mercado Hundido (banco).",
    ["5. Haunt on the Hill (dark portal)."] = "5. Haunt on the Hill (portal oscuro).",
    ["You have not yet used the ferry system to have a previous destination set."] = "Aún no has utilizado el sistema de ferry para establecer un destino anterior.",
    ["You have not yet used the ferry system to have a ferry to return to."] = "Aún no has utilizado el sistema de ferry para tener un ferry al que regresar.",
    ["It is dangerous to go beyond this point human. Let me help you prepare yourself."] = "Es peligroso ir más allá de este punto humano. Déjame ayudarte a prepararte.",
    ["Can you fetch any loot I might've missed?"] = "¿Puedes traer algún botín que me haya perdido?",
    ["I'm sorry human, I couldn't find anything for you."] = "Lo siento humano, no pude encontrar nada para ti.",
    ["I've found something for you!"] = "¡He encontrado algo para ti!",
    ["It looks like you didn't finish sorting through the last items I found you. Take a look."] = "Parece que no terminaste de clasificar los últimos elementos que te encontré. Échale un vistazo.",
    ["What should I fetch?"] = "¿Qué debo buscar?",
    ["Collect Beastmaster Durzag loot."] = "Recoge el botín de Beastmaster Durzag.",
    ["If you log out, items in the reward chest will be moved to your inventory or bank. If both of those places are full you will lose the items."] = "Si cierras sesión, los artículos del cofre de recompensas se moverán a tu inventario o banco. Si ambos lugares están llenos, perderás los artículos.",
    ["Collect Yakamaru loot."] = "Recoge el botín de Yakamaru.",
    ["I'll come back later."] = "Volveré más tarde.",
    ["I'm sorry human, I couldn't find Lil' Tuzzy anywhere."] = "Lo siento humano, no pude encontrar a Lil' Tuzzy por ningún lado.",
    ["Hey, I found something for you."] = "Oye, encontré algo para ti.",
    ["I'll see if I can find some loot for you!"] = "¡Veré si puedo encontrar algo de botín para ti!",
    ["Nope. I couldn't find anything."] = "No. No pude encontrar nada.",
    ["Show me my current raid lock."] = "Muéstrame mi bloqueo de incursión actual.",
    ["Can you automatically reset my raid lockout?"] = "¿Pueden restablecer automáticamente mi bloqueo de incursión?",
    ["That should be possible human."] = "Eso debería ser posible humano.",
    ["Automatically reset your raids lockout?"] = "¿Restablecer automáticamente el bloqueo de tus incursiones?",
    ["It seems I'm already doing it for you human. Do you want me to stop?"] = "Parece que ya lo estoy haciendo por ti humano. ¿Quieres que me detenga?",
    ["Stop automatically"] = "Detener automáticamente",
    ["Would you pay any Teci for these burial charms?"] = "¿Pagarías a cualquier Teci por estos amuletos funerarios?",
    ["**Fetcher:** If you have no use for your charms, I'd be willing to exchange them for a small amount of Teci. Are you interested?"] = "**Fetcher:** Si no necesitas tus amuletos, estaría dispuesto a cambiarlos por una pequeña cantidad de Teci. ¿Estás interesado?",
    ["Exchange [#] charm[s] for [#] Teci?"] = "¿Intercambiar [#] charm[s] por [#] Teci?",
    ["Very well, human."] = "Muy bien, humano.",
    ["I can't do anything with that human. Maybe if you were a little bit more well known, I could make an exchange."] = "No puedo hacer nada con ese humano. Quizás si fueras un poco más conocido podría hacer un intercambio.",
    ["RESET"] = "REINICIAR",
    ["You can only reset the Mazcab raid once every 48 hours. Ensure you wish to reset your progress before you continue!"] = "Solo puedes restablecer la incursión de Mazcab una vez cada 48 horas. ¡Asegúrate de que deseas restablecer tu progreso antes de continuar!",
    ["CANCEL"] = "CANCELAR",
    ["CONFIRM"] = "CONFIRMAR",
    ["Your raid progress has been reset."] = "El progreso de tu incursión se ha reiniciado.",
    ["Boss progress can only be reset once every 48 hours."] = "El progreso del jefe solo se puede restablecer una vez cada 48 horas.",
    ["As you approach the...big creature thing, it lets out a hiss that sounds partly like a threat and partly like a sigh."] = "A medida que te acercas a la... gran criatura, deja escapar un silbido que suena en parte como una amenaza y en parte como un suspiro.",
    ["Hmm. What was that about?"] = "Mmm. ¿Qué fue eso?",
    ["*Hiss* Another human. Why do you all keep coming down here?"] = "*Hiss* Otro humano. ¿Por qué seguís viniendo aquí?",
    ["Erm, excuse me...Lady Fiara, but the druids told me to talk to you."] = "Erm, discúlpeme... Lady Fiara, pero los druidas me dijeron que hablara con usted.",
    ["*Hiss* Yes...the druids. They say and do far more than they should."] = "*Hiss* Sí... los druidas. Dicen y hacen mucho más de lo que deberían.",
    ["What's wrong with the druids? They seem to worship you."] = "¿Qué les pasa a los druidas? Parecen adorarte.",
    ["They worship everything that is green or sounds even slightly magical. Not just worship - they stalk. And when they have arrived, it is impossible to get them away. They are like insects."] = "Adoran todo lo que es verde o suena incluso ligeramente mágico. No sólo adoran: acechan. Y cuando han llegado, es imposible sacarlos. Son como insectos.",
    ["You want to get rid of them, eh? I might be able to-"] = "Quieres deshacerte de ellos, ¿eh? Tal vez pueda-",
    ["No, no. *Hiss* Now you're just like them. \"What can we do for you today, oh great Guardian of Guthix, Lady Fiara?"] = "No, no. *Hiss* Ahora eres como ellos. \"¿Qué podemos hacer por ti hoy, oh gran Guardiana de Guthix, Lady Fiara?",
    ["Erm, sorry, I guess."] = "Erm, lo siento, supongo.",
    ["*Hiss* Do not worry your feeble mind with it. What was it you wanted? Let's just get it over with."] = "*Hiss* No preocupes tu débil mente con eso. ¿Qué era lo que querías? Terminemos con esto de una vez.",
    ["It is the site of the Fist of Guthix."] = "Es el sitio del Puño de Guthix.",
    ["Fist of Guthix? What is that?"] = "¿Puño de Guthix? ¿Qué es eso?",
    ["It is what it is. If you do not already know, it's probably best that you don't learn."] = "Es lo que es. Si aún no lo sabes, probablemente sea mejor que no aprendas.",
    ["Umm, okay. What are you all doing down here then?"] = "Umm, está bien. ¿Qué están haciendo todos ustedes aquí abajo entonces?",
    ["*Hiss* Three druids are mainly just walking around NOT being quiet. Another one is setting up a fortress of crates and dragging all kinds of material junk into the cave. The fifth human, who isn't a druid, showed up when the following masses swarmed the cave."] = "*Hiss* Tres druidas están principalmente caminando SIN estar callados. Otro es montar una fortaleza de cajas y arrastrar todo tipo de material basura a la cueva. El quinto humano, que no es un druida, apareció cuando las siguientes masas invadieron la cueva.",
    ["I see. But...what drew them here in the first place?"] = "Ya veo. Pero... ¿qué los atrajo aquí en primer lugar?",
    ["The Fist of Guthix. And now they try to harness its power through this little business they've set up."] = "El Puño de Guthix. Y ahora intentan aprovechar su poder a través de este pequeño negocio que han montado.",
    ["Okay, but they told me to talk to you. Why did they want that?"] = "Está bien, pero me dijeron que hablara contigo. ¿Por qué querían eso?",
    ["Because I am the guardian of this site and I need to make sure that their games do not get out of control."] = "Porque soy el guardián de este sitio y necesito asegurarme de que sus juegos no se salgan de control.",
    ["Alright. Can you tell me about the games, then?"] = "Muy bien. ¿Puedes hablarme entonces de los juegos?",
    ["Ooh, that sounds interesting. I am a fan of power, myself."] = "Oh, eso suena interesante. Yo mismo soy un fanático del poder.",
    ["I figured you were. After all, you are human."] = "Me imaginé que sí. Después de todo, eres humano.",
    ["I guess I should talk to the druids about that business, then."] = "Supongo que entonces debería hablar con los druidas sobre ese asunto.",
    ["No, you should not. I am the guardian here. I need to make sure that the rules are obeyed and that their games do not go out of control."] = "No, no deberías. Yo soy el guardián aquí. Necesito asegurarme de que se cumplan las reglas y de que sus juegos no se salgan de control.",
    ["Okay, you tell me about it, then."] = "Está bien, entonces cuéntamelo.",
    ["Okay, I will tell you. Now, listen carefully so that you do not forget."] = "Está bien, te lo diré. Ahora, escucha atentamente para que no lo olvides.",
    ["The passageway on my left leads into the . If you want to participate in the games, this is where you must go."] = "El pasillo a mi izquierda conduce al . Si quieres participar en los juegos, aquí es donde debes ir.",
    ["Once enough adventurers have gathered, I will pair you up against each other, and send you into the arena. The arena is the cave of the Fist of Guthix. Allow me to show you."] = "Una vez que se hayan reunido suficientes aventureros, los emparejaré entre sí y los enviaré a la arena. La arena es la cueva del Puño de Guthix. Permíteme mostrarte.",
    ["Each game is divided into , and you and your opponent will take turns being the and the . I decide who starts as what."] = "Cada juego se divide en , y tú y tu oponente os turnaréis para ser el y el . Yo decido quién empieza como qué.",
    ["While you are the , you will see the text in the of the screen."] = "Mientras seas , verás el texto en el de la pantalla.",
    ["While you are the , this text will say ."] = "Mientras seas , este texto dirá .",
    ["The arena is large and circular, and ancient power emanates from its . You will start on opposite sides of this arena."] = "La arena es grande y circular, y un poder antiguo emana de su . Comenzarás en lados opuestos de esta arena.",
    ["The goal of the is simple: chase down and by any means necessary."] = "El objetivo del es simple: perseguir y por cualquier medio necesario.",
    ["The goal of the is not quite as easy. When you appear in the arena, you will find yourself close to a small stone altar - a . On top of this, you should see a ."] = "El objetivo del no es tan fácil. Cuando aparezcas en la arena, te encontrarás cerca de un pequeño altar de piedra: un . Además de esto, deberías ver un .",
    ["In the role of the , you must pick up a from the . This is what you will use to gather the powerful energy from the centre of the arena."] = "En el rol de , debes recoger un del . Esto es lo que usarás para reunir la poderosa energía del centro de la arena.",
    ["While you are - and ONLY while you , NOT when it's in your backpack - it will draw energy from the Fist of Guthix. Your objective is to get as many of these as possible."] = "Mientras estés , y SÓLO mientras estés , NO cuando estés en tu backpack, extraerá energía del Puño de Guthix. Su objetivo es conseguir tantos como sea posible.",
    ["The amount of you have gathered is listed in the ."] = "La cantidad de que has reunido aparece en .",
    ["As the , however, you must be careful. Your opponent, the , is there to defeat you. While you are , you will be . Also, you may feel very strong, but in the role of the , you will find your , more as you get closer to the centre - someone who otherwise may be an easy opponent to defeat in combat may instead prove most dangerous."] = "Sin embargo, al igual que el , debes tener cuidado. Tu oponente, el , está ahí para derrotarte. Mientras seas , serás . Además, puede que te sientas muy fuerte, pero en el papel de , encontrarás tu , más a medida que te acerques al centro: alguien que de otro modo podría ser un oponente fácil de derrotar en combate, puede resultar más peligroso.",
    ["You can of course try to fight back against your opponent, even though it may be difficult. Also, as the , you will be limited in your magical abilities as well. Only a certain spellbook can aid you in this role."] = "Por supuesto, puedes intentar contraatacar a tu oponente, aunque pueda resultar difícil. Además, como , tus habilidades mágicas también estarán limitadas. Sólo un determinado libro de hechizos puede ayudarte en este papel.",
    ["Speaking of , I should also mention that you will find that some spells are in the cave as they may be in other areas."] = "Hablando de , también debo mencionar que encontrarás que algunos hechizos son en la cueva como pueden serlo en otras áreas.",
    ["Finally, as the , you will also take from the powerful energies in the arena."] = "Finalmente, como , también tomarás de las poderosas energías de la arena.",
    ["Okay, so the hunter only has to hunt down their target?"] = "Bien, ¿entonces el cazador solo tiene que cazar a su objetivo?",
    ["That is correct."] = "Eso es correcto.",
    ["And the hunted will be weaker than usual, has to pick up a stone from the stone dispenser at the edge of the arena, and wield this stone in order to charge it?"] = "Y el cazado será más débil de lo habitual, ¿tiene que recoger una piedra del dispensador de piedras en el borde de la arena y empuñarla para cargarla?",
    ["Yes, and the of the arena you are, the more it will be ."] = "Sí, y cuanto de la arena seas, más será .",
    ["Yes. You will find four small in the arena. Their doorways are blocked by . Only the can enter through these, and, while inside, will be completely to everyone else. The barriers are"] = "Sí. Encontrarás cuatro pequeños en la arena. Sus puertas están bloqueadas por . Sólo el puede entrar por estos y, mientras esté dentro, será completamente para todos los demás. Las barreras son",
    ["dangerous, however, and will as you pass through them."] = "peligroso, sin embargo, y será a medida que los atravieses.",
    ["Inside these , you will find . you can use them to - still to everyone else - but be aware that the magic is very old and the portals have not been actively used for thousands of years."] = "Dentro de estos , encontrarás . puedes usarlos para (aún para todos los demás), pero ten en cuenta que la magia es muy antigua y los portales no se han utilizado activamente durante miles de años.",
    ["They may act a bit strangely from time to time. Also, the portals require energy to work properly, and will from your stone. If you don't have enough charges, you won't be able to use the portal."] = "Es posible que actúen de forma un poco extraña de vez en cuando. Además, los portales requieren energía para funcionar correctamente y saldrán de tu piedra. Si no tiene suficientes cargos, no podrá utilizar el portal.",
    ["Okay, I will keep that in mind. So, when does the round end?"] = "Está bien, lo tendré en cuenta. Entonces, ¿cuándo termina la ronda?",
    ["A round can end in four different ways;"] = "Una ronda puede terminar de cuatro maneras diferentes;",
    ["One: If the ."] = "Uno: Si el .",
    ["Two: If the hunted - which is unlikely to happen."] = "Dos: Si el fue cazado, lo cual es poco probable que suceda.",
    ["Three: If the - each round can take no longer than ten minutes. You can see how much time there is left in the of the screen."] = "Tres: Si es , cada ronda no puede durar más de diez minutos. Puedes ver cuánto tiempo queda en el de la pantalla.",
    ["Four: If either player , in which case the other one will be declared the winner. The forfeiter will also be flagged as such as receive less tokens in the next game they play."] = "Cuatro: Si alguno de los jugadores hace , en cuyo caso el otro será declarado ganador. El perdedor también será marcado como tal por recibir menos fichas en el próximo juego que juegue.",
    ["When the first round as ended, the second round and the roles switch. The one who played the in first round will now have a chance to play the and gather ."] = "Cuando termina la primera ronda, la segunda ronda y los roles cambian. El que jugó el en la primera ronda ahora tendrá la oportunidad de jugar el y reunir el .",
    ["When both rounds have been played, the one with the ."] = "Cuando se hayan jugado ambas rondas, se jugará la que tenga el .",
    ["Ooh, what are the rewards?"] = "Oh, ¿cuáles son las recompensas?",
    ["The druids put a lot of value into the gathered energy, and you will be . How many tokens you get depends on your - a wide and balanced array of knowledge is something positive in"] = "Los druidas le dan mucho valor a la energía reunida y tú serás . La cantidad de tokens que obtenga depende de su : una gama amplia y equilibrada de conocimientos es algo positivo en",
    ["the eyes of Guthix - and how many you've got."] = "los ojos de Guthix - y cuántos tienes.",
    ["The can then be in the shop the druids have decided to clutter my cave with."] = "El puede ser en la tienda con la que los druidas han decidido abarrotar mi cueva.",
    ["You will also be awarded a , which is completely separate from the tokens. This will simply to keep track of how well you play the game. If you win, your rating improves. If you lose, your rating will suffer."] = "También recibirás un , que está completamente separado de los tokens. Esto simplemente servirá para realizar un seguimiento de qué tan bien juegas. Si ganas, tu calificación mejora. Si pierde, su calificación se verá afectada.",
    ["Your rating will improve significantly if you gather a lot . Also, the rating will be further adjusted if the difference in combat levels is large. If you lose to someone much more capable than you in combat,"] = "Tu calificación mejorará significativamente si reúnes mucho . Además, la calificación se ajustará aún más si la diferencia en los niveles de combate es grande. Si pierdes contra alguien mucho más capaz que tú en combate,",
    ["your rating won't suffer as much if you lost to someone around your own level."] = "tu calificación no se verá afectada tanto si pierdes contra alguien de tu mismo nivel.",
    ["Almost. Patience is a great virtue."] = "Casi. La paciencia es una gran virtud.",
    ["Finally, you cannot bring just anything you want into the game. , but and . I will supply you with some means of healing and a large amount of , called and"] = "Finalmente, no puedes traer cualquier cosa que quieras al juego. , pero y . Te proporcionaré algunos medios de curación y una gran cantidad de , llamado y",
    [", for your . These can be used in place of any other runes you can take with you, but do note that they can only be used in the Fist of Guthix cave. Also, any or other forms of used in"] = ", para tu . Estos se pueden usar en lugar de cualquier otra runa que puedas llevar contigo, pero ten en cuenta que solo se pueden usar en la cueva del Puño de Guthix. Además, cualquier u otras formas de utilizadas en",
    ["the arena will be handed back to you after the game. Assuming they are still inTact, of course. And don't leave anything lying around! I don't want you to complete ruin this sacred site."] = "la arena te será devuelta después del juego. Suponiendo que todavía estén intactos, por supuesto. ¡Y no dejes nada tirado por ahí! No quiero que arruines por completo este sitio sagrado.",
    ["Now, do you have any questions?"] = "Ahora, ¿tienes alguna pregunta?",
    ["I am Fiara, Guardian of Guthix. What are you?"] = "Soy Fiara, Guardián de Guthix. ¿Qué vas a?",
    ["I am Player. What are you guarding?"] = "Soy Player. ¿Qué estás protegiendo?",
    ["Hello, Player. I am guarding this very site."] = "Hola, Player. Estoy protegiendo este mismo sitio.",
    ["And what's so special about it?"] = "¿Y qué tiene de especial?",
    ["It is the site of the Fist of Guthix. If you do not already know that, you are probably not fit to learn."] = "Es el sitio del Puño de Guthix. Si aún no lo sabes, probablemente no estés capacitado para aprender.",
    ["I am Player, a Guardian of Saradomin."] = "Soy Player, un guardián de Saradomin.",
    ["Hello, Player, blind follower of the evil good and keeper of lies. Was there anything else you wanted?"] = "Hola, Player, seguidor ciego del mal bien y guardián de la mentira. ¿Había algo más que quisieras?",
    ["I am Player, also a Guardian of Guthix."] = "Soy Player, también guardián de Guthix.",
    ["Hello, Player, seer of light but bringer of lies. Was there anything else you wanted?"] = "Hola, Player, vidente de luz pero portador de mentiras. ¿Había algo más que quisieras?",
    ["I am Player, a Guardian of Zamorak."] = "Soy Player, un guardián de Zamorak.",
    ["Hello, Player, follower of the usurper and bringer of your own demise. Was there anything else you wanted?"] = "Hola, Player, seguidor del usurpador y portador de tu propia desaparición. ¿Había algo más que quisieras?",
    ["Can I help you?"] = "¿Puedo ayudarte?",
    ["Hello, blind follower of evil good and keeper of lies. Can one such as I be of any help to you?"] = "Hola, seguidor ciego del mal bien y guardián de la mentira. ¿Alguien como yo puede serle de alguna ayuda?",
    ["Hello, Player, what tales do you bring with you today? One would think you'd already know whatever I have to tell you."] = "Hola, Player, ¿qué cuentos traes hoy? Uno pensaría que ya sabrías todo lo que tengo que decirte.",
    ["Hello, usurper, Should you not be raining destruction on those who want nothing to do with you?"] = "Hola, usurpador, ¿No deberías estar haciendo llover destrucción sobre aquellos que no quieren tener nada que ver contigo?",
    ["Greetings, Player, can I be of assistance?"] = "Saludos, Player, ¿puedo ser de ayuda?",
    ["I have some questions about the Fist of Guthix game."] = "Tengo algunas preguntas sobre el juego Fist of Guthix.",
    ["Could you tell me all about the game again?"] = "¿Podrías volver a contarme todo sobre el juego?",
    ["Okay, I will tell you. Now, listen carefully, so that you do not forget."] = "Está bien, te lo diré. Ahora escucha atentamente, para que no lo olvides.",
    ["How do I get charges?"] = "¿Cómo obtengo cargos?",
    ["You can only get charges while you are in the role of the . When the game starts, look around you - there should be a nearby. Pick up a from there and to gather . The closer to the centre you are, the more you will get."] = "Solo puedes recibir cargos mientras desempeñas el rol de . Cuando comience el juego, mira a tu alrededor: debería haber un cerca. Elija un desde allí y para reunir . Cuanto más cerca del centro estés, más obtendrás.",
    ["Any more questions?"] = "¿Alguna pregunta más?",
    ["I have more questions about the Fist of Guthix game."] = "Tengo más preguntas sobre el juego Fist of Guthix.",
    ["Why can't I get into the arena?"] = "¿Por qué no puedo entrar a la arena?",
    ["Why can't I get into the game?"] = "¿Por qué no puedo entrar al juego?",
    ["There must be enough players in the waiting room for a game to start. Also, there can only be a certain amount of players in the game at any time."] = "Debe haber suficientes jugadores en la sala de espera para que comience un juego. Además, solo puede haber una cierta cantidad de jugadores en el juego en cualquier momento.",
    ["I keep losing all the time!"] = "¡Sigo perdiendo todo el tiempo!",
    ["That was not a question, but I will give you some tips."] = "Esa no era una pregunta, pero te daré algunos consejos.",
    ["Remember that the of the arena, the . If you find yourself getting defeated easily and that your armour does you no good, you may want to try to flee to the outer edges of"] = "Recuerda que el de la arena, el . Si te derrotan fácilmente y tu armadura no te sirve de nada, quizás quieras intentar huir a los bordes exteriores de",
    ["the arena where you will be less weakened. This also applies to your opponent. if it is someone who appears to be a lot stronger than you, he or she will still be very weak closer to the centre - this is where you should strike."] = "la arena donde estarás menos debilitado. Esto también se aplica a tu oponente. Si se trata de alguien que parece ser mucho más fuerte que tú, seguirá siendo muy débil más cerca del centro; aquí es donde debes atacar.",
    ["You should also know that while you are in the very centre, the energy from the Fist of Guthix will help you replenish your run energy much faster than usual."] = "También debes saber que mientras estás en el centro, la energía del Puño de Guthix te ayudará a reponer tu energía de carrera mucho más rápido de lo habitual.",
    ["Also, use the ruins of the past to your advantage. Hide behind rubble and make a run for it when your opponent is out of reach. Use the buildings to hide or as a means of escape."] = "Además, utiliza las ruinas del pasado a tu favor. Escóndete detrás de los escombros y huye cuando tu oponente esté fuera de tu alcance. Utilice los edificios para esconderse o como medio de escape.",
    ["I am Fiara, a Guardian of Guthix."] = "Soy Fiara, un guardián de Guthix.",
    ["And you are guarding the Fist of Guthix, which, if I don't already know about, I am not fit to know about?"] = "¿Y tú estás custodiando el Puño de Guthix, que, si aún no lo sé, no soy digno de saberlo?",
    ["That is correct. Was there anything else?"] = "Eso es correcto. ¿Hubo algo más?",
    ["Just call me Player."] = "Solo llámame Player.",
    ["Alright, Player the Indecisive. How can I be of assistance?"] = "Muy bien, Player el Indeciso. ¿Cómo puedo ser de ayuda?",
    ["I'd like to talk about the Fist of Guthix."] = "Me gustaría hablar sobre el Puño de Guthix.",
    ["What do you think will happen now Guthix is dead?"] = "¿Qué crees que pasará ahora que Guthix está muerto?",
    ["There is no going back now. The young gods will return, one by one."] = "Ya no hay vuelta atrás. Los dioses jóvenes regresarán, uno por uno.",
    ["They will not share land, or followers. They are greedy, every last one of them."] = "No compartirán terrenos, ni seguidores. Son codiciosos, hasta el último de ellos.",
    ["We cannot let another God Wars happen. Guthix may be gone, but we still stand."] = "No podemos permitir que ocurra otra Guerra de Dioses. Puede que Guthix se haya ido, pero seguimos en pie.",
    ["I will never stop fighting for him. And you should remember the gift he gave you."] = "Nunca dejaré de luchar por él. Y deberías recordar el regalo que te dio.",
    ["<!-- Not sure where this fits in"] = "<!-- No estoy seguro de dónde encaja esto",
    ["What are you guarding?"] = "¿Qué estás protegiendo?",
    ["Guthix placed me here thousands of years ago to guard the Fist of Guthix."] = "Guthix me colocó aquí hace miles de años para proteger el Puño de Guthix.",
    ["You're guarding Guthix's hand...?"] = "¿Estás protegiendo la mano de Guthix...?",
    ["Do not take everything literally. No, I have been the guardian of this sacred site since the end of the Third Age, and it does not contain a hand."] = "No te tomes todo literalmente. No, soy el guardián de este lugar sagrado desde finales de la Tercera Edad y no contiene una mano.",
    ["What is it that you're guarding, then?"] = "¿Qué es lo que estás protegiendo entonces?",
    ["I have already told you. Now, was there anything else?"] = "Ya te lo he dicho. Ahora bien, ¿había algo más?",
    ["No, nothing else."] = "No, nada más.",
    ["H-hello. You l-look like a s-stranger to these p-parts. Would you l-like to buy something? I h-have some s-special offers at the m-minute...some s-sample bottles for s- storing s-snail slime."] = "Hola. Pareces un extraño para estas partes. ¿Quieres comprar algo? Tengo algunas ofertas especiales en este momento... algunas botellas de muestra para almacenar baba de caracol.",
    ["(sigh) Th-that's okay. Nobody ever w-wants to buy my wares. Oh, s-sure, if it was food or c-clothes they would though!"] = "(suspiro) E-está bien. Nadie nunca quiere comprar mis productos. ¡Oh, claro, si fuera comida o ropa, lo harían!",
    ["Why are your prices so high?"] = "¿Por qué sus precios son tan altos?",
    ["As you p-probably know, the h-humans hate our kind and k-keep us trapped here. To get my s-stocks I have to sneak into the human lands in s-secret!"] = "Como p-probablemente sabes, los h-humanos odian a los de nuestra especie y nos mantienen atrapados aquí. ¡Para conseguir mis acciones tengo que colarme en las tierras humanas en secreto!",
    ["All the s-secrecy and d-danger has played h-havoc with my nerves!"] = "¡Todo el secretismo y el peligro han causado estragos en mis nervios!",
    ["But all your stuff is overpriced junk!"] = "¡Pero todas tus cosas son basura cara!",
    ["N-not at all! They are v-valuable human artefacts smuggled here at g-great personal risk!"] = "¡N-para nada! ¡Son artefactos humanos muy valiosos contrabandeados aquí con gran riesgo personal!",
    ["Hello?"] = "¿Hola?",
    ["Oh good, are you here for the presentation?"] = "Oh bien, ¿estás aquí para la presentación?",
    ["Erm, no, just who are you anyway?"] = "Erm, no, ¿quién eres tú de todos modos?",
    ["I'm Filip, and I'm waiting for some Very Important Penguins so we can begin our strategy update."] = "Soy Filip y estoy esperando algunos pingüinos muy importantes para que podamos comenzar nuestra actualización de estrategia.",
    ["I think they've gone... You're like the only penguin still here."] = "Creo que se han ido... Eres como el único pingüino que sigue aquí.",
    ["Oh, and I'd been practising and I'm ready to deliver my strategy update for the year. It's all about: Transformation, Transformation, Transformation!"] = "Ah, y he estado practicando y estoy listo para entregar mi actualización de estrategia para el año. Se trata de: ¡Transformación, Transformación, Transformación!",
    ["So what do you do around here then?"] = "Entonces, ¿qué haces por aquí?",
    ["I'm in charge of strategy, and more recently sails."] = "Estoy a cargo de la estrategia y, más recientemente, de navegación.",
    ["Sails? Do you mean sales?"] = "¿Velas? ¿Te refieres a ventas?",
    ["Yeah, that! There's been a recent boom in that sector. Here, take this pen...I'll show you! Now give it back to me, and say: Hey man, sell me this pen. Hey, can you sign this for me?"] = "¡Sí, eso! Ha habido un auge reciente en ese sector. Toma, toma este bolígrafo... ¡Te lo mostraré! Ahora devuélvemelo y di: Oye, véndeme este bolígrafo. Oye, ¿puedes firmar esto por mí?",
    ["I don't have anything to write with."] = "No tengo nada con qué escribir.",
    ["Well have you tried using that old Rod?"] = "Bueno, ¿has intentado usar ese viejo Rod?",
    ["It's no good, so you need a writing implement you can rely on. Here, I'll sell you this pen..."] = "No sirve, por lo que necesitas un instrumento de escritura en el que puedas confiar. Toma, te venderé este bolígrafo...",
    ["Perfect, I'll buy it."] = "Perfecto, lo compraré.",
    ["See!"] = "¡Mira!",
    ["Money is useful because you can buy items from the if you don't want to craft them yourself."] = "El dinero es útil porque puedes comprar artículos de si no quieres crearlos tú mismo.",
    ["Gold are the currency of the human kingdoms. Your coins are kept in your at the bottom of your . You currently have 0 coins."] = "El oro es la moneda de los reinos humanos. Sus coins se guardan en su en la parte inferior de su . Actualmente tienes 0 coins.",
    ["There are three basic ways to make money: skilling, combat and trading. Some people have work for an adventurer like you, and will reward you for completing quests. Many enemies will drop items when they die. You can sell them to a or on the in . By getting a high level in skills, such as , , or , you can create or gather your own items and sell them for pure profit. You can only carry so many items in your backpack. You can deposit items you want to keep and not sell into your bank."] = "Hay tres formas básicas de ganar dinero: habilidades, combate y comercio. Algunas personas trabajan para un aventurero como tú y te recompensarán por completar misiones. Muchos enemigos dejarán caer objetos cuando mueran. Puedes venderlos en un o en un en un . Al obtener un alto nivel de habilidades, como , , o , puedes crear o reunir tus propios artículos y venderlos para obtener ganancias puras. Solo puedes llevar una cantidad limitada de artículos en tu backpack. Puede depositar en su banco los artículos que desee conservar y no vender.",
    ["You're nearly finished. The Prayer instructor would like to have a chat with you in the nearby church."] = "Ya casi has terminado. Al instructor de Prayer le gustaría charlar contigo en la iglesia cercana.",
    ["Talk to crabs? How silly."] = "¿Hablar con cangrejos? Qué tonto.",
    ["(Dialogue 1:)"] = "(Diálogo 1 :)",
    ["*click*"] = "*clic*",
    ["(Dialogue 2:)"] = "(Diálogo 2 :)",
    ["*click* *click*"] = "*clic* *clic*",
    ["(Dialogue 3:)"] = "(Diálogo 3 :)",
    ["*click* *click* *click*"] = "*clic* *clic* *clic*",
    ["(Dialogue 4:)"] = "(Diálogo 4 :)",
    ["*clickclickclick*"] = "*clicclicclic*",
    ["(Dialogue 5:)"] = "(Diálogo 5 :)",
    ["*click* *clickclick* *click*"] = "*clic* *clicclic* *clic*",
    ["(Dialogue 6:)"] = "(Diálogo 6 :)",
    ["*click* *click* *clickclick*"] = "*clic* *clic* *clicclic*",
    ["It's a bit of a shame the villagers weren't open to sharing their homes with us."] = "Es una pena que los aldeanos no estuvieran dispuestos a compartir sus hogares con nosotros.",
    ["Understandable, I suppose. I probably wouldn't share my hut with them."] = "Comprensible, supongo. Probablemente no compartiría mi cabaña con ellos.",
    ["I must say, it's lovely to sleep under a roof. Can't get me now, bats!"] = "Debo decir que es maravilloso dormir bajo un techo. ¡No pueden atraparme ahora, murciélagos!",
    ["Player: Where did you sleep before you got huts?"] = "Player: ¿Dónde dormías antes de conseguir las cabañas?",
    ["We just buried ourselves in the sand. Fortunately this beach doesn't get many visitors, so little fear of being trodden and smushed. Wasn't particularly comfortable, though."] = "Nos enterramos en la arena. Afortunadamente, esta playa no recibe muchos visitantes, por lo que no hay miedo de ser pisoteada y aplastada. Aunque no fue particularmente cómodo.",
    ["My daughter, Shelly, was right to recommend you for the gift of crabspeak. I'm proud of her."] = "Mi hija, Shelly, hizo bien en recomendarte por el don de la lengua de cangrejo. Estoy orgulloso de ella.",
    ["Can I help you, your Royal Highness?"] = "¿Puedo ayudarle, Alteza Real?",
    ["Yes please. What are you selling?"] = "Sí, por favor. ¿Qué estás vendiendo?",
    ["**Player** No thanks."] = "**Player** No, gracias.",
    ["What's it like living down here?"] = "¿Cómo es vivir aquí abajo?",
    ["A lot drier in the winter than it is above ground."] = "Mucho más seco en invierno que en la superficie.",
    ["Take a look."] = "Echa un vistazo.",
    ["Hi. What are you doing?"] = "Hola. ¿Qué estás haciendo?",
    ["Relaxing after a long day at the factory."] = "Relajarse después de un largo día en la fábrica.",
    ["If I keep up this winning streak, I mightn't have to go into work tomorrow."] = "Si mantengo esta racha ganadora, puede que no tenga que ir a trabajar mañana.",
    ["Do you mind me asking how much you have won?"] = "¿Te importa que te pregunte cuánto has ganado?",
    ["Not at all, I'm up 10 coins so far."] = "Para nada, llevo 10 coins hasta ahora.",
    ["Umm ok."] = "Mmm, está bien.",
    ["So how do these rat pits work?"] = "Entonces, ¿cómo funcionan estos pozos de ratas?",
    ["The Keldagrim pits cater for those with the larger variety of cats."] = "Las fosas Keldagrim atienden a aquellos con una mayor variedad de gatos.",
    ["If you have an overgrown cat and a couple of coins you can challenge someone else who also has an overgrown cat and some spare change."] = "Si tienes un gato grande y un par de coins, puedes desafiar a otra persona que también tenga un gato grande y algo de cambio.",
    ["That sounds simple enough so far."] = "Eso suena bastante simple hasta ahora.",
    ["You then agree on a wager. It's rumoured that some ratcatchers can talk to their own cats and give them tactics to aid them."] = "Luego aceptas una apuesta. Se rumorea que algunos cazadores de ratas pueden hablar con sus propios gatos y darles tácticas para ayudarlos.",
    ["So then how do you win the challenge?"] = "Entonces, ¿cómo se gana el desafío?",
    ["I was just getting to that. Both the gamblers' cats are placed inside of the fenced off area, and whoever kills 9 rats first wins."] = "Estaba llegando a eso. Los gatos de ambos jugadores se colocan dentro del área vallada y quien mate primero a 9 ratas gana.",
    ["That sounds vile and cruel."] = "Eso suena vil y cruel.",
    ["It's a cruel world and the pits are no exception."] = "Es un mundo cruel y los boxes no son una excepción.",
    ["Each to their own I say."] = "Cada uno por su lado digo.",
    ["One more thing..."] = "Una cosa más...",
    ["Thanks for your help."] = "Gracias por tu ayuda.",
    ["It sounds a little dangerous for my cat."] = "Suena un poco peligroso para mi gato.",
    ["I agree. Cats have been known to be killed in fights."] = "Estoy de acuerdo. Se sabe que los gatos mueren en peleas.",
    ["Oh how terrible. Is there nothing you can do to save your cat?"] = "Oh, qué terrible. ¿No hay nada que puedas hacer para salvar a tu gato?",
    ["Of course there is, you can instruct it to be cautious, and it will leave once it feels as if it is in danger."] = "Por supuesto que sí, puedes indicarle que tenga cuidado y se irá una vez que sienta que está en peligro.",
    ["Oh that sounds quite wise."] = "Oh, eso suena muy sabio.",
    ["That depends on how you value your cat."] = "Eso depende de cómo valoras a tu gato.",
    ["Sorry, I don't follow."] = "Lo siento, no te sigo.",
    ["Well if your cat dies or it runs away you lose."] = "Bueno, si tu gato muere o se escapa, pierdes.",
    ["So the longer it stays in the fight the better chance you have of winning."] = "Entonces, cuanto más tiempo permanezca en la pelea, más posibilidades tendrás de ganar.",
    ["Wow that sounds like fun!"] = "¡Vaya, eso suena divertido!",
    ["I don't know about that."] = "No sé nada de eso.",
    ["One thing I know though is that it's a quick way to make and lose money."] = "Una cosa que sé es que es una forma rápida de ganar y perder dinero.",
    ["Is there a limit to how much you can bet?"] = "¿Existe un límite de cuánto puedes apostar?",
    ["Hmmm...let me see. If I'm not mistaken, you can currently bet up to a maximum of [number] coins."] = "Hmmm... déjame ver. Si no me equivoco, actualmente puedes apostar hasta un máximo de [número] coins.",
    ["That sounds like a silly amount of money to bet on a cat fight."] = "Suena como una cantidad tonta de dinero para apostar en una pelea de gatos.",
    ["You'd be surprised what some people would be willing to bet."] = "Te sorprendería lo que algunas personas estarían dispuestas a apostar.",
    ["There is a minimum bet of 100 coins too."] = "También hay una apuesta mínima de 100 coins.",
    ["Can I challenge you and your cat?"] = "¿Puedo desafiarte a ti y a tu gato?",
    ["No, not now, we don't really bet with outsiders."] = "No, ahora no, realmente no apostamos con forasteros.",
    ["But I'm not an outsider, am I not inside in the pits now?"] = "Pero no soy un outsider, ¿no estoy ahora en boxes?",
    ["I don't know, maybe once you've done something to win over my trust."] = "No lo sé, tal vez una vez que hayas hecho algo para ganarte mi confianza.",
    ["Can it be bought?"] = "¿Se puede comprar?",
    ["Your trust."] = "Tu confianza.",
    ["No. Regular townsfolk don't like us, which leads us to distrust them and anyone else."] = "No. No agradamos a la gente común del pueblo, lo que nos lleva a desconfiar de ellos y de cualquier otra persona.",
    ["Reeeeoooo!"] = "¡Reeeeoooo!",
    ["What does it take to become first mate on a ship?"] = "¿Qué se necesita para convertirse en primer oficial de un barco?",
    ["Good question. We have a diplomatic consession at the turn of the financial year. Said pirate is chosen should the existing mate be absent without leave."] = "Buena pregunta. Tenemos una conferencia diplomática al final del año financiero. Dicho pirata es elegido en caso de que el compañero existente esté ausente sin permiso.",
    ["I had no idea. I always figured it was all about popularity."] = "No tenía idea. Siempre pensé que se trataba de popularidad.",
    ["It is. I'm just pulling your leg."] = "Lo es. Sólo te estoy tomando el pelo.",
    ["Welcome, fellow dreamer."] = "Bienvenido, compañero soñador.",
    ["If you could provide me some resources from your base camp, I could create a fishery for you to train at within this dream, and teach you something of ilujankan fishing techniques."] = "Si pudieras proporcionarme algunos recursos de tu campamento base, podría crear una pesquería para que entrenes dentro de este sueño y enseñarte algo sobre las técnicas de pesca ilujankan.",
    ["Thank you for the clay. If you keep supplying me with more, I can teach you much about Ilujankan fishing techniques."] = "Gracias por la arcilla. Si sigues proporcionándome más, puedo enseñarte mucho sobre las técnicas de pesca de Ilujankan.",
    ["You are learning much of our ways. Keep on as you are, and I will share a story with you."] = "Estás aprendiendo mucho de nuestras costumbres. Sigue como estás y compartiré una historia contigo.",
    ["You have learned much. I shall soon share my tale with Paskeeper Sharrigan."] = "Has aprendido mucho. Pronto compartiré mi historia con Paskeeper Sharrigan.",
    ["You must build a station before you can contribute resources to it."] = "Debes construir una estación antes de poder aportarle recursos.",
    ["Contribute [number] x clay and store [number] XP in this station?"] = "¿Contribuir [número] x arcilla y almacenar [número] XP en esta estación?",
    ["The fishery now has [number]/350,000 Fishing XP stored in it."] = "La pesquería ahora tiene [número]/350,000 Fishing XP almacenados.",
    ["You contribute to the station: [number] x clay"] = "Tú contribuyes a la estación: [número] x arcilla.",
    ["You have too few of this resource to contribute to this station."] = "Tienes muy pocos recursos de este recurso para contribuir a esta estación.",
    ["This skilling station is already at maximum capacity of resources."] = "Esta estación de habilidades ya está en su máxima capacidad de recursos.",
    ["**CONTRIBUTE [NUMBER] X CLAY AND STORE [NUMBER] XP IN THIS STATION?**"] = "**¿CONTRIBUIR [número] X CLAY Y ALMACENAR [número] XP EN ESTA ESTACIÓN?**",
    ["Why the long face? No good catch today?"] = "¿Por qué la cara larga? ¿No hay buena pesca hoy?",
    ["I'm worried about old Groggy Gregg up in the crow's nest. He was once a great captain but now he's only sitting in his little wooden cage; drowning himself slowly in grog."] = "Me preocupa el viejo Groggy Gregg que está en la cofa. Alguna vez fue un gran capitán pero ahora solo está sentado en su pequeña jaula de madera; ahogándose lentamente en grog.",
    ["I love it out here! I came here to make money and catch big fish, but I stayed for the peace and the calm the ocean brings to my mind and the camaraderie amongst the people here."] = "¡Me encanta estar aquí! Vine aquí para ganar dinero y pescar peces grandes, pero me quedé por la paz y la calma que me trae el océano y la camaradería entre la gente de aquí.",
    ["Don't you ever get seasick on these platforms here?"] = "¿Nunca te mareas en estas plataformas?",
    ["Never! To me, it feels as if I'm cradled soothingly by the ocean, night and day."] = "¡Nunca! Para mí, siento como si el océano me acunara dulcemente, noche y día.",
    ["Not sure my stomach agrees..."] = "No estoy seguro de que mi estómago esté de acuerdo...",
    ["Oi! Watch where you're going! It sure is getting awfully crowded here these days."] = "¡Oye! ¡Mira por dónde vas! Seguro que estos días hay mucha gente aquí.",
    ["Cheer up! Isn't it lovely to have some company while fishing?"] = "¡Anímate! ¿No es maravilloso tener compañía mientras se pesca?",
    ["Why would that be a good thing?"] = "¿Por qué sería eso algo bueno?",
    ["Suddenly the platforms are overrun with young whippersnappers, stealing catches that could have been mine! I wonder who told everyone about this place."] = "De repente, las plataformas se ven invadidas por jóvenes ladrones que roban capturas que podrían haber sido mías. Me pregunto quién les contó a todos sobre este lugar.",
    ["You check to see if they're okay in the water."] = "Compruebas si están bien en el agua.",
    ["You are rewarded for checking on the diver - You receive [number] Fishing XP."] = "Serás recompensado por controlar al buceador: recibirás [número] Fishing XP.",
    ["You've already checked on them."] = "Ya los has revisado.",
    ["Sorry, you'll have to switch to a members' world in order to play Fish Flingers."] = "Lo sentimos, tendrás que cambiar al mundo de miembros para poder jugar Fish Flingers.",
    ["Fish Flingers starts in [number] [minute/minutes]."] = "Fish Flingers comienza en [número] [minute/minutes].",
    ["You've just missed the start of a Fish Flingers competition, I'm afraid. The waiting area for the next Fish Flingers competition opens in 15 minutes. If you speak to me again then, I'll teleport you to the competition."] = "Me temo que te acabas de perder el inicio de una competencia de Lanzadores de Peces. La sala de espera para la próxima competición Fish Flingers se abre en 15 minutos. Si vuelves a hablarme entonces, te teletransportaré a la competencia.",
    ["The waiting area for the next Fish Flingers competition opens in [number] [minute/minutes]. If you speak to me again then, I'll teleport you to the competition."] = "La zona de espera para la próxima competencia Fish Flingers se abre en [número] [minute/minutes]. Si vuelves a hablarme entonces, te teletransportaré a la competencia.",
    ["Teleport me to Fish Flingers."] = "Teletransportame a Fish Flingers.",
    ["When Fish Flingers starts you will use one of your entry tickets, leaving you with [number] more tickets. Okay?"] = "Cuando comience Fish Flingers, utilizarás uno de tus boletos de entrada, lo que te dejará con [número] boletos más. ¿Está bien?",
    ["Yes, I'll use a ticket to compete."] = "Sí, usaré un boleto para competir.",
    ["Oh no! The Fish Flingers competition has started I'm afraid, so I can't teleport you. The next competition starts in [number] minutes. If you speak to me again then, I'll teleport you to the competition."] = "¡Oh no! Me temo que la competencia Fish Flingers ha comenzado, así que no puedo teletransportarte. La próxima competición comienza en [número] minutos. Si vuelves a hablarme entonces, te teletransportaré a la competencia.",
    ["No, I've changed my mind."] = "No, he cambiado de opinión.",
    ["Give me a hint for the next competition."] = "Dame una pista para la próxima competición.",
    ["Can I enter the competition now?"] = "¿Puedo participar en el concurso ahora?",
    ["The waiting area for the next Fish Flingers competition opens in [number] minutes. If you speak to me again then, I'll teleport you to the competition."] = "La zona de espera para la próxima competencia Fish Flingers se abre en [número] minutos. Si vuelves a hablarme entonces, te teletransportaré a la competencia.",
    ["About Fish Flingers..."] = "Acerca de los arrojadores de pescado...",
    ["What would you like me to tell you?"] = "¿Qué te gustaría que te dijera?",
    ["What is the competition about?"] = "¿De qué se trata la competencia?",
    ["It's a chance for you to show how well you can catch fish by choosing the best tackle and habitat."] = "Es una oportunidad para que demuestres lo bien que puedes pescar eligiendo el mejor equipo y hábitat.",
    ["Us old-timers know of a special place, Isla Anglerine, where huge schools of unusual fish seem to gather."] = "Los veteranos conocemos un lugar especial, Isla Anglerine, donde parecen reunirse enormes bancos de peces inusuales.",
    ["I'm not sure what the fish find so appealing there, but it's a fisherman's paradise!"] = "No estoy seguro de qué es lo que les resulta tan atractivo a los peces allí, ¡pero es un paraíso para los pescadores!",
    ["I can teleport you to the island if you want to take part. Just say the word."] = "Puedo teletransportarte a la isla si quieres participar. Sólo di la palabra.",
    ["How do I catch fish?"] = "¿Cómo pesco?",
    ["Once I've teleported you, wait in the starting area for the competition to begin. Then, walk to the waterfront where you would like to fish."] = "Una vez que te haya teletransportado, espera en el área de inicio a que comience la competencia. Luego, camina hasta el paseo marítimo donde te gustaría pescar.",
    ["Next, select a hook and bait that you think the fish will like, add some weights to get the cast distance you need, and you're ready to cast your line."] = "A continuación, seleccione un anzuelo y un cebo que crea que le gustarán al pez, agregue algunos pesos para obtener la distancia de lanzamiento que necesita y estará listo para lanzar el sedal.",
    ["As you catch fish you'll be shown how effective your tackle is, and you'll be able to make improvements as you learn what each fish likes."] = "A medida que pesques, se te mostrará qué tan efectivo es tu aparejo y podrás realizar mejoras a medida que aprendas qué le gusta a cada pez.",
    ["Remember, different species are different sizes. You'll need to try fishing in different areas to find the heaviest species."] = "Recuerde, diferentes especies tienen diferentes tamaños. Tendrás que intentar pescar en diferentes zonas para encontrar las especies más pesadas.",
    ["It's also worth remembering that fish are adaptable creatures, so tackle that works well in one competition might not work so well in the next."] = "También vale la pena recordar que los peces son criaturas adaptables, por lo que el aparejo que funciona bien en una competencia puede no funcionar tan bien en la siguiente.",
    ["How often can I compete?"] = "¿Con qué frecuencia puedo competir?",
    ["Everyone is allowed 2 entry tickets every day. We hang on to the tickets for you, so there's no need to carry them about or store them in your bank."] = "A todo el mundo se le permiten 2 entradas cada día. Guardamos los billetes por usted, por lo que no es necesario llevarlos consigo ni guardarlos en su banco.",
    ["If you want to know how many you have left, or you want to claim more tickets, just let me know."] = "Si quieres saber cuántos te quedan o quieres reclamar más boletos, dímelo.",
    ["How many entry tickets do I have left?"] = "¿Cuántas entradas me quedan?",
    ["You've got [number] tickets left at the moment."] = "Te quedan entradas [número] en este momento.",
    ["When can I next claim entry tickets?"] = "¿Cuándo podré reclamar las entradas?",
    ["Enough time has passed since you last claimed entry tickets, so you can claim more as soon as you've used up the ones you have left."] = "Ha pasado suficiente tiempo desde la última vez que reclamaste boletos de entrada, por lo que podrás reclamar más tan pronto como hayas agotado los que te quedan.",
    ["Is there another way of getting entry tickets?"] = "¿Existe otra forma de conseguir entradas?",
    ["Funny you should ask that. We had a fierce storm recently. The gale picked up a whole load of entry tickets and scattered them all across Gielinor."] = "Es curioso que preguntes eso. Recientemente tuvimos una tormenta feroz. El vendaval recogió una gran cantidad de entradas y las esparció por todo Gielinor.",
    ["We picked up any we could find, but most of them ended up in the water."] = "Recogimos todos los que pudimos encontrar, pero la mayoría terminó en el agua.",
    ["So, you never know. You might find an entry ticket whenever you catch fish."] = "Entonces, nunca se sabe. Es posible que encuentres un boleto de entrada cada vez que pesques.",
    ["Let's talk about something else..."] = "Hablemos de otra cosa...",
    ["As often as you like!"] = "¡Tantas veces como quieras!",
    ["About the competition score..."] = "Sobre la puntuación de la competición...",
    ["Give me a copy of my competition history."] = "Dame una copia de mi historial de competencia.",
    ["You don't have room to carry it. No problem, just ask me again when you have a free inventory space."] = "No tienes espacio para cargarlo. No hay problema, solo pregúntame nuevamente cuando tengas un espacio libre en el inventario.",
    ["[The fisherman hands you a Fish Flingers scorecard.]"] = "[El pescador te entrega una tarjeta de puntuación de Fish Flingers.]",
    ["You already seem to have one in your inventory."] = "Parece que ya tienes uno en tu inventario.",
    ["How is my score calculated?"] = "¿Cómo se calcula mi puntuación?",
    ["We take into account the number of fish caught, the total weight caught, and the heaviest fish caught."] = "Tomamos en cuenta la cantidad de peces capturados, el peso total capturado y el pez más pesado capturado.",
    ["We also include how many big fish you caught and how often you helped other contestants to catch their big fish."] = "También incluimos cuántos peces grandes pescaste y con qué frecuencia ayudaste a otros concursantes a pescar sus peces grandes.",
    ["Finding the perfect tackle for each species is an important part of fishing. You'll get bonus points for each species you find the perfect tackle for."] = "Encontrar el aparejo perfecto para cada especie es una parte importante de la pesca. Obtendrás puntos de bonificación por cada especie para la que encuentres el equipo perfecto.",
    ["You'll know you've found the perfect tackle when your rating for catching that fish reaches 100%."] = "Sabrás que has encontrado el aparejo perfecto cuando tu calificación de captura de ese pez alcance el 100%.",
    ["After the competition you'll be shown your results, so you'll be able to see what had an impact on your score."] = "Después de la competencia se te mostrarán tus resultados, para que puedas ver qué tuvo un impacto en tu puntuación.",
    ["Tell me about big fish."] = "Háblame de peces grandes.",
    ["Maintain a 100% rating, and you'll eventually hook a valuable big fish. Big fish are so heavy that you'll need assistance from other contestants to heave it out of the water."] = "Mantén una calificación del 100% y eventualmente pescarás un pez grande y valioso. Los peces grandes son tan pesados ​​que necesitarás la ayuda de otros concursantes para sacarlos del agua.",
    ["Catching big fish significantly improves your score, but helping others to catch their big fish earns you the greatest reward of all."] = "Capturar peces grandes mejora significativamente tu puntuación, pero ayudar a otros a pescar sus peces grandes te otorga la mayor recompensa de todas.",
    ["Tell me about medals."] = "Háblame de las medallas.",
    ["If you perform well enough you'll receive up to four medals, which give you a bonus to your score. The noticeboard in the waiting area describes the conditions to win medals."] = "Si te desempeñas lo suficientemente bien, recibirás hasta cuatro medallas, lo que te dará una bonificación a tu puntuación. El tablón de anuncios de la zona de espera describe las condiciones para ganar medallas.",
    ["Show me the rewards shop."] = "Muéstrame la tienda de recompensas.",
    ["About rewards..."] = "Sobre las recompensas...",
    ["Tell me about the Fishing experience reward."] = "Cuéntame sobre la recompensa de la experiencia Fishing.",
    ["You'll find that the extra skill involved in competitive fishing can earn you more experience than your everyday fishing."] = "Descubrirás que la habilidad adicional que implica la pesca competitiva puede hacerte ganar más experiencia que la pesca diaria.",
    ["At the end of each competition you'll receive all the experience you've earned, so there's no need to speak to me to collect it."] = "Al final de cada competencia recibirás toda la experiencia que hayas obtenido, por lo que no es necesario que hables conmigo para recogerla.",
    ["It might take you a few tries to get used to the competition tackle, but once you've learned the best way to find and catch the biggest fish species you should notice a great improvement in the experience you get."] = "Puede que te lleve algunos intentos acostumbrarte al equipo de competición, pero una vez que hayas aprendido la mejor manera de encontrar y capturar las especies de peces más grandes, deberías notar una gran mejora en la experiencia que obtienes.",
    ["The amount of experience you earn depends on your skill at Fishing. Having a higher Fishing level means you earn more experience."] = "La cantidad de experiencia que ganes depende de tu habilidad en Fishing. Tener un nivel Fishing más alto significa que ganas más experiencia.",
    ["I'd like to know more about the raw fish reward."] = "Me gustaría saber más sobre la recompensa por pescado crudo.",
    ["We'll give you noted raw fish, which is much easier to carry to the bank."] = "Te daremos pescado crudo marcado, que es mucho más fácil de llevar al banco.",
    ["When you claim your noted fish you'll be given a selection of fish appropriate to your Fishing level. For example, if you'd normally be fishing swordfish, you'll be given a mix of swordfish and lobsters."] = "Cuando reclames tu pez anotado, se te dará una selección de peces apropiada para tu nivel Fishing. Por ejemplo, si normalmente pescas pez espada, te darán una mezcla de pez espada y langostas.",
    ["Tell me about the tackle box reward."] = "Cuéntame sobre la recompensa de la caja de aparejos.",
    ["The tackle box holds fishing equipment and raw fish, saving you inventory and bank space. They also hold a copy of your competition history, so you can review your performance."] = "La caja de aparejos contiene equipos de pesca y pescado crudo, lo que le ahorra inventario y espacio en el banco. También tienen una copia de su historial de competencia, para que pueda revisar su desempeño.",
    ["Admittedly, when you first get your tackle box it won't hold much, but over time you can upgrade it so it will hold much more."] = "Es cierto que cuando adquieres tu caja de aparejos por primera vez no cabe mucho, pero con el tiempo puedes mejorarla para que aguante mucho más.",
    ["Tell me about the fishing outfit reward."] = "Cuéntame sobre la recompensa del traje de pesca.",
    ["The fishing outfit increases the amount of Fishing experience you get. When you're fishing or playing Fish Flingers, it's a good idea to wear as many pieces of the fishing outfit as possible."] = "El equipo de pesca aumenta la cantidad de experiencia Fishing que obtienes. Cuando estás pescando o jugando a Fish Flingers, es una buena idea usar tantas piezas del traje de pesca como sea posible.",
    ["Let's talk about something else."] = "Hablemos de otra cosa.",
    ["It won't be long now. The competition starts in [number] [minute/minutes]."] = "Ya no falta mucho. La competición comienza en [número] [minute/minutes].",
    ["The competition is about to start. Have fun!"] = "La competencia está por comenzar. ¡Divertirse!",
    ["Here on Isla Anglerine, huge schools of unusual fish seem to gather. I'm not sure what the fish find so appealing here, but it's a fisherman's paradise!"] = "Aquí en Isla Anglerine, parecen reunirse enormes bancos de peces inusuales. No estoy seguro de qué es lo que les resulta tan atractivo a los peces aquí, ¡pero es un paraíso para los pescadores!",
    ["When the gates open, hurry to the any shoreline where you would like to fish."] = "Cuando se abran las puertas, apresúrate a llegar a la costa donde quieras pescar.",
    ["You can fish at either of the docks to the east and west, the lake to the north, the river east of the lake, and the beach to the far north-east."] = "Puedes pescar en cualquiera de los muelles al este y al oeste, el lago al norte, el río al este del lago y la playa al extremo noreste.",
    ["Fish Flingers starts in [number] minutes."] = "Fish Flingers comienza en [número] minutos.",
    ["Everyone likes to be rewarded for their efforts, of course. You can be awarded Fishing experience, raw fish, a fishing outfit and - if you get good enough - a tackle box to hold your fishing supplies."] = "A todos les gusta ser recompensados por sus esfuerzos, por supuesto. Podrás recibir experiencia Fishing, pescado crudo, un equipo de pesca y, si eres lo suficientemente bueno, una caja de aparejos para guardar tus suministros de pesca.",
    ["Tell me more about the rewards."] = "Cuéntame más sobre las recompensas.",
    ["Show me the reward shop."] = "Muéstrame la tienda de recompensas.",
    ["Good news! You're eligible to claim entry tickets. You now have [number] Fish Flingers entry tickets. Come back tomorrow to claim more."] = "¡Buenas noticias! Eres elegible para reclamar boletos de entrada. Ahora tienes entradas para [número] Fish Flingers. Vuelve mañana para reclamar más.",
    ["You'll need to get your tackle box from the bank before I can upgrade it."] = "Necesitarás conseguir tu caja de aparejos del banco antes de que pueda actualizarla.",
    ["[The tackle box in your inventory has been upgraded and can now hold more items.]"] = "[La caja de aparejos de tu inventario se ha actualizado y ahora puede contener más artículos.]",
    ["You already own the best tackle box available."] = "Ya posees la mejor caja de aparejos disponible.",
    ["We're still tidying up from the last competition. Give me a minute and I'll have that hint for you."] = "Todavía estamos ordenando lo de la última competencia. Dame un minuto y te daré esa pista.",
    ["You'll find bowline salmon at the beach. They've been sighted far from the shore, so attach lots of weights to your line to reach them."] = "Encontrarás salmón bolina en la playa. Han sido avistados lejos de la orilla, así que coloca muchos pesos en tu línea para alcanzarlos.",
    ["You'll find cove bass at the beach. They're clever and can spot metal a mile off. You'd better think carefully about what type of hook you use."] = "Encontrarás lubinas en la playa. Son inteligentes y pueden detectar metales a un kilómetro de distancia. Será mejor que pienses detenidamente qué tipo de anzuelo utilizas.",
    ["You'll find darter cod at the river. They're known to like shellfish, particularly grey ones."] = "Encontrarás bacalao dardo en el río. Se sabe que les gustan los mariscos, especialmente los grises.",
    ["You'll find darter cod at the river. They've been spotted close to the shore, so you won't need much weight on your line to reach them."] = "Encontrarás bacalao dardo en el río. Han sido vistos cerca de la orilla, por lo que no necesitarás mucho peso en tu línea para alcanzarlos.",
    ["You'll find drift herring at the docks. They've been seen a fair distance from the shore, but not too far. You'll need to attach a few weights to reach them."] = "Encontrarás arenque a la deriva en los muelles. Se les ha visto a bastante distancia de la orilla, pero no demasiado. Tendrás que colocar algunos pesos para alcanzarlos.",
    ["You'll find shallow bass at the lake. They've been spotted close to the shore, so you won't need much weight on your line to reach them."] = "Encontrarás lubinas poco profundas en el lago. Han sido vistos cerca de la orilla, por lo que no necesitarás mucho peso en tu línea para alcanzarlos.",
    ["You'll find spotted pike at the lake. They're known to like wriggling creatures, particularly red ones."] = "Encontrarás lucios moteados en el lago. Se sabe que les gustan las criaturas que se retuercen, especialmente las rojas.",
    ["You'll find thunder trout at the river. They're clever and can spot metal a mile off. You'd better think carefully about what type of hook you use."] = "Encontrarás truchas trueno en el río. Son inteligentes y pueden detectar metales a un kilómetro de distancia. Será mejor que pienses detenidamente qué tipo de anzuelo utilizas.",
    ["You'll find yearning trout at the docks. They're known to like fluttering creatures, particularly green ones."] = "Encontrarás anhelantes truchas en los muelles. Se sabe que les gustan las criaturas revoloteantes, especialmente las verdes.",
    ["You're keen, aren't you? You'll have to wait for the countdown to the next competition to start before I can give you a hint."] = "Estás interesado, ¿no? Tendrás que esperar a que comience la cuenta regresiva para la próxima competencia antes de que pueda darte una pista.",
    ["Don't talk to me outerlander. Anything you have to say to me, you can say to the Chieftain. Goodbye."] = "No me hables, outsider. Cualquier cosa que tengas que decirme, puedes decírselo al Cacique. Adiós.",
    ["Welcome back, [brother/sister] [Fremennik name]. It has been too long since last we spoke! The fish are really biting today!"] = "Bienvenido de nuevo, [brother/sister] [Fremennik name]. ¡Ha pasado demasiado tiempo desde la última vez que hablamos! ¡Los peces realmente pican hoy!",
    ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
    ["We'll keep his stories alive, at least his legend will live forever."] = "Mantendremos vivas sus historias, al menos su leyenda vivirá para siempre.",
    ["I'll never understand how Miriam manages to meet her fishing quota while frittering away so much time at the tavern."] = "Nunca entenderé cómo Miriam logra cumplir con su cuota de pesca mientras desperdicia tanto tiempo en la taberna.",
    ["Have you been to the Burnt Lobster Tavern? You wouldn't think it based on the name, but Gefen's an excellent cook."] = "¿Has estado en Burnt Lobster Tavern? No lo creerías por el nombre, pero Gefen es un excelente cocinero.",
    ["Sorry pal, I'd love to chat, but my break ends soon and I'm behind on my quota."] = "Lo siento amigo, me encantaría conversar, pero mi descanso termina pronto y estoy atrasado en mi cuota.",
    ["The number of fish in the area has been in steady decline for a while now."] = "La cantidad de peces en el área ha estado disminuyendo constantemente desde hace un tiempo.",
    ["We're still not sure why. Maybe it's related to the rumours of monsters in the east."] = "Todavía no estamos seguros de por qué. Quizás esté relacionado con los rumores sobre monstruos en el este.",
    ["Maya's fish farm has helped us a lot. Don't know what we'd have done without her."] = "La piscifactoría de Maya nos ha ayudado mucho. No sé qué hubiéramos hecho sin ella.",
    ["You'll find all sorts of fish around the village."] = "Encontrarás todo tipo de peces en el pueblo.",
    ["There are crayfish, trout and salmon in the rivers, and shrimps, anchovies, sardine and herring on the western shore."] = "Hay cangrejos, truchas y salmones en los ríos, y camarones, anchoas, sardinas y arenques en la orilla occidental.",
    ["You can catch lobster, tuna, swordfish, mackerel, cod, bass and shark off the southern coast."] = "En la costa sur se pueden pescar langosta, atún, pez espada, caballa, bacalao, lubina y tiburón.",
    ["Old Man Jocko says there are still a few spots further inland where you can find giant crayfish, but I've never been able to catch one myself."] = "Old Man Jocko dice que todavía hay algunos lugares tierra adentro donde puedes encontrar cangrejos de río gigantes, pero yo nunca he podido pescar uno.",
    ["I'm painting my toenails... what's it look like I'm doing? Silly outsider..."] = "Me estoy pintando las uñas de los pies... ¿qué parece que estoy haciendo? Un forastero tonto...",
    ["Erm, good luck with that."] = "Erm, buena suerte con eso.",
    ["You haven't really won the hearts of the locals, if you see what I mean. At the last poll, only 25% of the population liked you."] = "Realmente no te has ganado el corazón de los lugareños, si entiendes lo que quiero decir. En la última encuesta, sólo le agradaste al 25% de la población.",
    ["Hey! This is the king's fishing spot. You'll need his approval to make use of it."] = "¡Oye! Este es el lugar de pesca del rey. Necesitará su aprobación para utilizarlo.",
    ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    ["You know very well what I'm doing, Your Royal Highness."] = "Usted sabe muy bien lo que estoy haciendo, Su Alteza Real.",
    ["Just teasing!"] = "¡Solo bromeo!",
    ["Your people are growing dissatisfied with the regime, Your Royal Highness. At the last poll, only [*x*]% of the population supported you."] = "Su gente está cada vez más insatisfecha con el régimen, Su Alteza Real. En la última encuesta, sólo el [*x*]% de la población lo apoyó.",
    ["What a catch!"] = "¡Qué captura!",
    ["You are rewarded for checking on the diver - You receive 1,940 Fishing XP."] = "Serás recompensado por controlar al buceador: recibirás 1940 Fishing XP.",
    ["You cast out your line... You attempt to catch a fish."] = "Lanzas tu línea... Intentas pescar un pez.",
    ["You catch a tropical trout."] = "Coges una trucha tropical.",
    ["You can't carry any more fish"] = "No puedes llevar más pescado.",
    ["The Sunlight Sands Beach is not active at the moment."] = "La playa Sunlight Sands no está activa en este momento.",
    ["Er, hi, so...isn't there supposed to be a theme park around here somewhere?"] = "Er, hola, entonces... ¿no se supone que hay un parque temático por aquí en alguna parte?",
    ["Ha! That old chestnut. People still fall for that?"] = "¡Ja! Ese viejo castaño. ¿La gente todavía cae en eso?",
    ["Fall for what?"] = "¿Enamorarse de qué?",
    ["Oh, nothing. Why don't you, er, join us...for dinner?"] = "Oh, nada. ¿Por qué no te unes a nosotros... para cenar?",
    ["Ooh, what's on the menu?"] = "Oh, ¿qué hay en el menú?",
    ["Dibs on the sweet meats!"] = "¡Disfruta de las carnes dulces!",
    ["You can't call dibs! We share, remember?"] = "¡No puedes pedirlo! Compartimos, ¿recuerdas?",
    ["Aww, but you KNOW I've got a sweet tooth."] = "Ah, pero SABES que soy goloso.",
    ["And you KNOW I'm a pescatarian. I'm not eating that! It could have been anywhere."] = "Y SABES que soy pescatariano. ¡No voy a comer eso! Podría haber estado en cualquier lugar.",
    ["What? What aren't you eating?"] = "¿Qué? ¿Qué no estás comiendo?",
    ["We ARE stranded, remember. Beggars can't be choosers. Unless you want to start eating each other?"] = "Estamos varados, recuerda. Los mendigos no pueden elegir. ¿A menos que quieran empezar a comerse unos a otros?",
    ["Er, yeah, that would be uncivil."] = "Er, sí, eso sería descortés.",
    ["Right, see, even our meal agrees - cannonballs don't eat other cannonballs."] = "Bien, mira, incluso nuestra comida está de acuerdo: las balas de cañón no se comen a otras balas de cañón.",
    ["How many times? It's 'cannibals'!"] = "¿Cuántas veces? ¡Son 'caníbales'!",
    ["That's what I said. You KNOW I have a speech impediment, 'Keith'."] = "Eso es lo que dije. SABES que tengo un impedimento del habla, 'Keith'.",
    ["And I've told you my name is Puddinghead! Not cool, 'Jeff'."] = "¡Y ya les dije que mi nombre es Puddinghead! No está bien, 'Jeff'.",
    ["Urgh, would you boys stop arguing for just one minute?"] = "Urgh, ¿podrían dejar de discutir por un minuto?",
    ["Wait! Stop arguing for a sec. You're cannonballs, I mean, cannibals?"] = "¡Espera! Deja de discutir por un segundo. ¿Sois balas de cañón, quiero decir, caníbales?",
    ["And a pescatarian. I'm a person too, you know. Food is so rude these days. Am I right?"] = "Y un pescatariano. Yo también soy una persona, ¿sabes? La comida es muy grosera estos días. ¿Estoy en lo cierto?",
    ["You're a pescatarian cannibal? How does that work."] = "¿Eres un caníbal pescatariano? ¿Cómo funciona eso?",
    ["Mermaids."] = "Sirenas.",
    ["Oh, that's clever. No, wait, the other thing - that's gross! What about sea orphans. Do you eat those?"] = "Oh, eso es inteligente. No, espera, la otra cosa... ¡eso es asqueroso! ¿Qué pasa con los huérfanos del mar? ¿Comes esos?",
    ["Nah, I have a very strict diet regime. Sea orphans are half-person, half-fish - more like surf 'n' turf."] = "No, tengo una dieta muy estricta. Los huérfanos del mar son mitad personas, mitad peces, más como surf y tierra.",
    ["We're getting off-topic here! Right, so, who gets the legs?"] = "¡Nos estamos saliendo del tema! Bien, entonces, ¿quién se queda con las piernas?",
    ["None of you! Not unless you want to stay stranded! I'll take you back, but NO eating me or my crew."] = "¡Ninguno de ustedes! ¡No, a menos que quieras quedarte varado! Te llevaré de regreso, pero NO me comeré a mí ni a mi tripulación.",
    ["Aww."] = "Ay.",
    ["Spoilsport."] = "Aguafiestas.",
    ["Wait, not even travel snacks?"] = "Espera, ¿ni siquiera bocadillos de viaje?",
    ["Well, I suppose we could try to not eat you if it gets us off this island. We've been stranded here since The Harbinger sank our ship."] = "Bueno, supongo que podríamos intentar no comerte si eso nos saca de esta isla. Hemos estado varados aquí desde que The Harbinger hundió nuestro barco.",
    ["Yes, not eating me would help. Now, what about your friend over there. Is she coming too?"] = "Sí, no comerme ayudaría. Ahora, ¿qué pasa con tu amigo de allí? ¿Ella también viene?",
    ["Who, Jellyhead-head? Nah, she'll be fine. I think she likes it here. Besides, she hasn't said much since she put that thing on her head."] = "¿Quién, Jellyhead-head? No, ella estará bien. Creo que a ella le gusta estar aquí. Además, no ha dicho mucho desde que se puso esa cosa en la cabeza.",
    ["I don't sell to outerlanders."] = "No vendo a extranjeros.",
    ["Only Fremenniks may purchase fish here."] = "Sólo los Fremenniks pueden comprar pescado aquí.",
    ["The fishmonger is staring at you suspiciously. You cannot steal from his stall while he distrusts you."] = "El pescadero te mira con recelo. No puedes robar en su puesto mientras él desconfíe de ti.",
    ["Hello there, [Fremennik name]. Looking for fresh fish?"] = "Hola, [Fremennik name]. ¿Buscas pescado fresco?",
    ["Have you been up to much lately?"] = "¿Has estado haciendo mucho últimamente?",
    ["I just came back from Lev's. His cakes are delicious."] = "Acabo de regresar de Lev. Sus pasteles son deliciosos.",
    ["Hello there. How are you?"] = "Hola. ¿Cómo estás?",
    ["I'm doing well, thanks. Blessings of Inanna be upon you, traveller."] = "Estoy bien, gracias. Bendiciones de Inanna sean contigo, viajero.",
    ["How's your day going?"] = "¿Cómo va tu día?",
    ["Could be better. I ran into a bear in the Highweald earlier. I managed to escape but had to leave my gear behind."] = "Podría ser mejor. Me encontré con un oso en Highweald antes. Logré escapar pero tuve que dejar mi equipo.",
    ["Stay alert if you venture into the forest. It's been dangerous lately."] = "Mantente alerta si te aventuras en el bosque. Ha sido peligroso últimamente.",
    ["I can't complain. The sun is shining, the birds are singing... What more can you ask for?"] = "No me puedo quejar. El sol brilla, los pájaros cantan... ¿Qué más se puede pedir?",
    ["Leave me be, outlander."] = "Déjame en paz, forastero.",
    ["My kids are looking forward to the lamplight festival."] = "Mis hijos esperan con ansias el festival de las lámparas.",
    ["This year's candles are the best we've ever made, if I do say so myself."] = "Las velas de este año son las mejores que hemos hecho jamás, si me permite decirlo.",
    ["Nice to meet you."] = "Encantado de conocerte.",
    ["If you want small talk, go speak to Gefen."] = "Si quieres una pequeña charla, habla con Gefen.",
    ["Our harvests, our fish, our very land... Something's not right."] = "Nuestras cosechas, nuestros peces, nuestra propia tierra... Algo no está bien.",
    ["Hopefully your arrival is a sign of brighter days ahead."] = "Esperemos que tu llegada sea una señal de que se avecinan días mejores.",
    ["So... tired... There was loud barking coming from Zeeva's all night."] = "Muy... cansado... Hubo fuertes ladridos provenientes de casa de Zeeva durante toda la noche.",
    ["She needs to teach that dog some manners."] = "Necesita enseñarle algunos modales a ese perro.",
    ["You're the new outlander, right?"] = "Eres el nuevo forastero, ¿verdad?",
    ["I am!"] = "¡Lo soy!",
    ["It's nice to meet you. I hope you're enjoying our village."] = "Es un placer conocerte. Espero que estés disfrutando de nuestro pueblo.",
    ["Greetings, Sir. Get your fresh fish here!"] = "Saludos, señor. ¡Consigue tu pescado fresco aquí!",
    ["I've heard that the Etceterian fish is stored in a cow shed."] = "He oído que el pescado etceteriano se almacena en un establo para vacas.",
    ["Greetings, Your Highness. Have some fresh fish!"] = "Saludos, Alteza. ¡Come pescado fresco!",
    ["Welcome, [Fremennik Name]. My fish is fresher than any in Miscellania."] = "Bienvenido, [Fremennik Name]. Mi pescado es más fresco que cualquiera de Miscellania.",
    ["That's an interesting title... I was the same until my pal, the Makeover Mage, helped me out."] = "Es un título interesante... Yo era el mismo hasta que mi amigo, el Makeover Mage, me ayudó.",
    ["You've unlocked the 'Cracked' colour for the 'the Egg' title!"] = "¡Has desbloqueado el color 'Agrietado' para el título 'el Huevo'!",
    ["Let me slap some new colours on that title for you, maybe they'll serve you well."] = "Déjame ponerle algunos colores nuevos a ese título, tal vez te sirvan.",
    ["Well met, Player!"] = "¡Bien conocido, Player!",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["I was overseeing the creation of some delicious statuettes - modelled after yours truly - when I was hit with a scrumptious epiphany!"] = "Estaba supervisando la creación de unas deliciosas estatuillas, inspiradas en un servidor, ¡cuando tuve una revelación deliciosa!",
    ["Cocoamancy! Animated chocolate goodies! Not just a tasty treat, but an exciting toy!"] = "¡Coamancia! ¡Delicias de chocolate animadas! ¡No sólo es un sabroso manjar, sino también un juguete emocionante!",
    ["Unfortunately I was led astray by the confidence of a peer I sought assitance from; seems he was lying a bit about his experience, and now the bunnies are loose!"] = "Desafortunadamente, la confianza de un compañero del que busqué ayuda me desvió; Parece que estaba mintiendo un poco sobre su experiencia, ¡y ahora los conejitos están sueltos!",
    ["They've started inhabiting chocolate burrows nearby, and every few minutes the rascals seem to pop up in a different place."] = "Han comenzado a habitar madrigueras de chocolate cercanas, y cada pocos minutos los sinvergüenzas parecen aparecer en un lugar diferente.",
    ["If you manage to track them down, I would be ecstatic to offer you spring tokens in exchange for any you return to me."] = "Si logras localizarlos, me encantaría ofrecerte fichas de primavera a cambio de las que me devuelvas.",
    ["I've got something for you."] = "Tengo algo para ti.",
    ["Are you pulling my leg? You don't have any rabbits! Come back when you've got something for me."] = "¿Me estás tomando el pelo? ¡No tienes conejos! Vuelve cuando tengas algo para mí.",
    ["You will not receive any Spring tokens for this. Hand in ayway?"] = "No recibirás ningún token Spring por esto. ¿Entregar de todos modos?",
    ["You have reached the Spring token soft cap of 30,000. You need to spend some tokens in Gummy's store before you can earn more."] = "Ha alcanzado el límite flexible del token Spring de 30 000. Debes gastar algunas fichas en la tienda de Gummy antes de poder ganar más.",
    ["The following has been added to your currency pouch: [number] x Spring tokens"] = "Se ha agregado lo siguiente a su bolsa de divisas: [número] x tokens Spring",
    ["Amazing work, Player! Take these as payment and get back out there, stat!"] = "¡Trabajo increíble, Player! ¡Toma esto como pago y vuelve a salir, inmediatamente!",
    ["Farewell, Fizzy."] = "Adiós, Fizzy.",
    ["Come back soon! With as many chocolate rabbits as you can hold!"] = "¡Vuelve pronto! ¡Con tantos conejos de chocolate como puedas sostener!",
    ["Warped by the depths below, Flesh-hatcher Mhekarnahz sees all."] = "Deformado por las profundidades inferiores, Flesh-hatcher Mhekarnahz lo ve todo.",
    ["Requirements"] = "Requisitos",
    ["Completion Time: [time] - New Personal Record! An improvement of [number] seconds!"] = "Tiempo de finalización: [time] - ¡Nuevo récord personal! ¡Una mejora de [número] segundos!",
    ["You have killed [number] Flesh-hatcher Mhekarnahz."] = "Has matado a [número] Flesh-hatcher Mhekarnahz.",
    ["The corpse is empty."] = "El cadáver está vacío.",
    ["If you could provide me some resources from your base camp, I could create a fletcher's hut for you to train at within this dream, and teach you something of Ilujankan fletching techniques."] = "Si pudieras proporcionarme algunos recursos de tu campamento base, podría crear una cabaña de fletcher para que entrenes dentro de este sueño y enseñarte algo sobre las técnicas de fletching de Ilujankan.",
    ["Thank you for the wood. If you keep supplying me with more, I can teach you much about ilujankan fletching techniques."] = "Gracias por la madera. Si sigues proporcionándome más, puedo enseñarte mucho sobre las técnicas de emplumado ilujankan.",
    ["I have recounted my tale to Pastkeeper Sharrigan. Thank you for all of your efforts. Perhaps you should train at one of the other stations for a time."] = "Le he contado mi historia a Pastkeeper Sharrigan. Gracias por todos sus esfuerzos. Quizás deberías entrenar en alguna de las otras estaciones por un tiempo.",
    ["Contribute [number] x wood and store [number] XP in this station?"] = "¿Contribuir [número] x madera y almacenar [número] XP en esta estación?",
    ["The fletcher's hut now has [number]/135,000 Fletching XP stored in it."] = "La cabaña del Fletcher ahora tiene [número]/135,000 Fletching XP almacenados.",
    ["You contribute to the station: [number] x wood"] = "Tú contribuyes a la estación: [número] x madera.",
    ["**CONTRIBUTE [NUMBER] X WOOD AND STORE [NUMBER] XP IN THIS STATION?**"] = "**¿CONTRIBUIR [número] X MADERA Y ALMACENAR [número] XP EN ESTA ESTACIÓN?**",
    ["The fletcher's hut now has [number]/350,000 Fletching XP stored in it."] = "La cabaña del Fletcher ahora tiene [número]/350,000 Fletching XP almacenados.",
    ["You need the following skills to start this quest: 74 Firemaking, 76 Constitution, 64 Agility."] = "Necesitas las siguientes habilidades para comenzar esta misión: 74 Firemaking, 76 Constitution, 64 Agility.",
    ["What are you all doing here?"] = "¿Qué están haciendo todos aquí?",
    ["Top secret, my friend. But perhaps when you're more experienced you could help us."] = "Alto secreto, amigo mío. Pero quizás cuando tengas más experiencia puedas ayudarnos.",
    ["I see."] = "Ya veo.",
    ["Ah, Player! Welcome, welcome!"] = "¡Ah, Player! ¡Bienvenidos, bienvenidos!",
    ["Chat to Sera and Emmett if you want to try out our activities."] = "Chatea con Sera y Emmett si quieres probar nuestras actividades.",
    ["It's all a bit too energetic for me, especially after our last adventure!"] = "¡Es todo demasiado enérgico para mí, especialmente después de nuestra última aventura!",
    ["Keep walking, mate."] = "Sigue caminando, amigo.",
    ["I don't suppose y-"] = "Supongo que no-",
    ["Can I smell fish? Give me some fish and I might 'suppose'."] = "¿Puedo oler a pescado? Dame un poco de pescado y tal vez \"supongo\".",
    ["Give raw fish to Flippers?"] = "¿Darle pescado crudo a Flippers?",
    ["Thanks. Not bad."] = "Gracias. Nada mal.",
    ["Now, will you-"] = "Ahora, ¿podrías-?",
    ["Nope."] = "No.",
    ["Oh my, what was that slice of deliciousness? I must have more!"] = "Dios mío, ¿qué fue ese trozo de delicia? ¡Debo tener más!",
    ["Now, will y-"] = "Ahora, ¿quieres?",
    ["Yes! Whatever it is, yes! If you can get me more of those, I'll do it."] = "¡Sí! Sea lo que sea, ¡sí! Si puedes conseguirme más de esos, lo haré.",
    ["You'll join my ship cr-"] = "Te unirás a mi barco cr-",
    ["I ain't swabbing nothing."] = "No estoy limpiando nada.",
    ["You could be my lookou-"] = "Podrías ser mi lookou-",
    ["Nope, on account of the cultural prejudice that is a 'crow's nest'."] = "No, por el prejuicio cultural que es un 'nido de cuervo'.",
    ["Well, what would yo-"] = "Bueno, ¿qué harías?",
    ["I'm a fixer."] = "Soy un reparador.",
    ["That's not a traditional crew pos-"] = "Esa no es una posición de equipo tradicional.",
    ["It's whatever you need it to be, Cap. Now, more fish like that. Please, I suppose."] = "Es lo que necesites, Cap. Ahora, más peces así. Por favor, supongo.",
    ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
    ["Captain."] = "Capitán.",
    ["Hey, Flippers, what are you doing?"] = "Oye, Flippers, ¿qué estás haciendo?",
    ["Ah, you know, just hanging around the fishing spots. These idiots keep just dropping fish all over the place. It's like free breakfast buffet all the time."] = "Ah, ya sabes, simplemente dando vueltas por los lugares de pesca. Estos idiotas siguen tirando peces por todos lados. Es como un desayuno buffet gratis todo el tiempo.",
    ["Coming here was a great plan, Cap! We should never leave. Fish as far as the eye can see! And the smell, oh gods, the smell &nbsp;I am in the penguin afterlife!"] = "¡Venir aquí fue un gran plan, Cap! Nunca deberíamos irnos. ¡Pesca hasta donde alcanza la vista! Y el olor, oh dioses, el olor. ¡Estoy en el más allá de los pingüinos!",
    ["Have you seen these dragon monks? They're completely nutso!"] = "¿Has visto a estos monjes dragón? ¡Están completamente locos!",
    ["I mean, I could understand if they were trying to attain the form of a penguin, but a dragon? Sheesh. Sometimes, I think I'm the only sane person left in this world."] = "Quiero decir, podría entender si estuvieran tratando de alcanzar la forma de un pingüino, pero ¿un dragón? Cielos. A veces pienso que soy la única persona cuerda que queda en este mundo.",
    ["I'm just gonna go climb these towers and jump off, see if I can fly yet."] = "Voy a escalar estas torres y saltar, para ver si todavía puedo volar.",
    ["Great, have fun!"] = "¡Genial, diviértete!",
    ["No, wait! You're a penguin! You can't fly!"] = "¡No, espera! ¡Eres un pingüino! ¡No puedes volar!",
    ["Don't tell me what I can and can't do. You're not the boss of me, er, Cap."] = "No me digas qué puedo y qué no puedo hacer. No eres mi jefe, eh, Cap.",
    ["No, I mean you literally, physically can't fly. It's not me stopping you, it's physics."] = "No, quiero decir que, literalmente, físicamente no puedes volar. No soy yo quien te detiene, es la física.",
    ["Yeah, well, physics can do one."] = "Sí, bueno, la física puede hacerlo.",
    ["Can we visit the berry bar? I've got a thirst on like you wouldn't believe. I'm one parched penguin."] = "¿Podemos visitar el bar de bayas? Tengo una sed como no lo creerías. Soy un pingüino reseco.",
    ["Boring! There's nothing here to do. Can we go yet? Can we? Huh?"] = "¡Aburrido! Aquí no hay nada que hacer. ¿Podemos irnos todavía? ¿Podemos? ¿Eh?",
    ["Not yet, Flippers."] = "Todavía no, Flippers.",
    ["Aww. You're mean."] = "Ay. Eres malo.",
    ["You are such a child, sometimes."] = "A veces eres un niño.",
    ["Brr, this place shivers my flippers. It's so quiet and spooky. Can we leave soon?"] = "Brr, este lugar me hace temblar las aletas. Es tan silencioso y espeluznante. ¿Podemos irnos pronto?",
    ["Ha-Has she gone? I'm scared!"] = "Ja-¿Se ha ido? ¡Tengo miedo!",
    ["What's wrong, Flippers?"] = "¿Qué pasa, Flippers?",
    ["M-my nemesis! She was here just before you arrived, and she won't leave me alone! K-keeps trying to... I can't even say it; it makes me feel sick even thinking about it."] = "¡M-mi némesis! ¡Estuvo aquí justo antes de que llegaras y no me dejará en paz! K-sigue intentando... Ni siquiera puedo decirlo; Me hace sentir mal incluso pensar en ello.",
    ["So spell it out."] = "Así que explícalo.",
    ["She tries to... to... to H_U_G me. Isn't that just the grossest?"] = "Ella trata de... de... ABRAZARME. ¿No es eso lo más asqueroso?",
    ["You're scared of a woman that's trying to, let me get this straight, trying to hug you?"] = "¿Tienes miedo de una mujer que intenta, déjame aclararlo, intentar abrazarte?",
    ["*blech* Don't say it or you'll make me 'feed the chicks'."] = "*blech* No lo digas o me obligarás a \"alimentar a los polluelos\".",
    ["It's not a woman either - it's a little girl."] = "Tampoco es una mujer, es una niña.",
    ["She's the cutest thing too."] = "Ella también es la cosa más linda.",
    ["She keeps calling me Sophie. I keep telling her she's got the wrong penguin. She's not getting the message, though. Children are the worst."] = "Sigue llamándome Sophie. Sigo diciéndole que se equivocó de pingüino. Sin embargo, ella no entiende el mensaje. Los niños son lo peor.",
    ["Ready to head back?"] = "¿Listo para regresar?",
    ["Yeah, I'm ready to go."] = "Sí, estoy listo para partir.",
    ["No, I'll stay a little longer."] = "No, me quedaré un poco más.",
    ["I can't complain."] = "No me puedo quejar.",
    ["Although, saying that, I wouldn't mind getting my hands on that beastie in the pool. She'd make a meal fit for a kingdom."] = "Aunque, dicho esto, no me importaría tener en mis manos a esa bestia en la piscina. Haría una comida digna de un reino.",
    ["I might need a bigger rod though!"] = "¡Quizás necesite una caña más grande!",
    ["There's great fishing to be had here. The tropical trout are frisky, but just the thing for cooking up a tasty summer treat."] = "Aquí se puede pescar muy bien. Las truchas tropicales son juguetonas, pero ideales para preparar un sabroso manjar de verano.",
    ["[Using the fishing spots gives you fishing experience. You can gain extra experience for handing the fish to Wellington or delivering them to the barbecue area.]"] = "[Usar los lugares de pesca te brinda experiencia de pesca. Puedes adquirir experiencia adicional entregando el pescado a Wellington o entregándolo en la zona de barbacoa.]",
    ["Why are there pirate ships?"] = "¿Por qué hay barcos piratas?",
    ["Those ships are feisty ones! They're looking for something to fight."] = "¡Esos barcos son luchadores! Están buscando algo con qué luchar.",
    ["If you have any battleships you can pit them against one of the pirate ships but beware, !"] = "Si tienes acorazados, puedes enfrentarlos contra uno de los barcos piratas, pero ¡cuidado, !",
    ["How are things going?"] = "¿Cómo van las cosas?",
    ["Oo, a stranger left this for you!"] = "¡Oh, un extraño te dejó esto!",
    ["You need 1 free space in your backpack to receive your clue caskets."] = "Necesitas 1 espacio libre en tu backpack para recibir tus cofres de pistas.",
    ["[You are handed a casket!]"] = "[¡Te entregan un ataúd!]",
    ["Get out of it! You'se aint commin' in 'ere to get our's blood or's our food!"] = "¡Fuera de ahí! ¡No vendrás aquí a buscar nuestra sangre ni nuestra comida!",
    ["*(Before River of Blood:)*"] = "*(Antes de Río de Sangre:)*",
    ["Hey it's the hero! Wow, you're amazing! How on earth did you manage to tackle those two juvinates and Gadderanks? And the town is lovely - you've done a great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo diablos lograste enfrentarte a esos dos juvinates y Gadderanks? Y la ciudad es preciosa. ¡Has hecho un gran trabajo!",
    ["*(After River of Blood:)*"] = "*(Después de Río de Sangre :)*",
    ["Hey it's the hero! Wow, you're amazing! How did you manage to return all the villagers? Things feel so much safer around here now too - great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo conseguiste devolver a todos los aldeanos? Ahora las cosas también se sienten mucho más seguras por aquí: ¡excelente trabajo!",
    ["You're more than welcome."] = "De nada.",
    ["Well met! My name's Florin. I do a bit of this, a bit of that. Just try to survive really, there's nothing much else we can do."] = "¡Bien conocido! Mi nombre es Florin. Hago un poco de esto, un poco de aquello. Sólo trata de sobrevivir de verdad, no hay mucho más que podamos hacer.",
    ["How do you like your town?"] = "¿Qué te parece tu ciudad?",
    ["It's just perfect, thanks so much for your efforts."] = "Es simplemente perfecto, muchas gracias por tus esfuerzos.",
    ["What's happening around here?"] = "¿Qué está pasando por aquí?",
    ["Oh, not much really, we're all still hiding from the vampyres and eking out a living from this terrible place, hopefully soon we'll be strong enough to make the journey to the temple on the Salve."] = "Oh, no mucho en realidad, todos todavía nos estamos escondiendo del vampyres y ganándonos la vida a duras penas en este terrible lugar, con suerte pronto seremos lo suficientemente fuertes para hacer el viaje al templo en la Salve.",
    ["Oh, not much really, we're all just trying to eke out a living in this place. Some of us still want to head for the Salve and into Misthalin, but honestly, it's not so bad here anymore...in spite of how it might look."] = "Oh, no mucho en realidad, todos estamos tratando de ganarnos la vida a duras penas en este lugar. Algunos de nosotros todavía queremos dirigirnos a la Salve y a Misthalin, pero, sinceramente, ya no está tan mal aquí... a pesar de cómo pueda parecer.",
    ["Is there anything I can do to help out?"] = "¿Hay algo que pueda hacer para ayudar?",
    ["Not as far as I know, we have some basic amenities now which is so very useful, we're all incredibly grateful to you. I've never really seen or known a hero before, so I have nothing to compare one to, but I suspect in most people's judgement, you would be one! I for one am very pleased to have met you."] = "No que yo sepa, ahora contamos con algunos servicios básicos que son muy útiles y todos te estamos increíblemente agradecidos. Nunca antes había visto o conocido a un héroe, así que no tengo nada con qué compararlo, pero sospecho que, a juicio de la mayoría de la gente, ¡tú serías uno! Por mi parte, estoy muy contento de haberte conocido.",
    ["Okay, thanks."] = "Está bien, gracias.",
    ["You should speak with the ruler of this isle, King Gjuki Sorvott IV."] = "Deberías hablar con el gobernante de esta isla, el rey Gjuki Sorvott IV.",
    ["Can I have a look at your stock please?"] = "¿Puedo echar un vistazo a sus existencias, por favor?",
    ["No, nothing just now thanks."] = "No, nada ahora, gracias.",
    ["Oh, hello again. Want some fish?"] = "Oh, hola de nuevo. ¿Quieres pescado?",
    ["I'll have a look."] = "Echaré un vistazo.",
    ["Not right now."] = "No en este momento.",
    ["I'm selling flowers, 15gp for three. Would you like some?"] = "Estoy vendiendo flores, 15 po por tres. ¿Quieres algunos?",
    ["Thank you! Here you go."] = "¡Gracias! Aquí tienes.",
    ["No, thank you."] = "No, gracias.",
    ["I'm selling flowers, 15gp for three. Would you like some, Your Highness?"] = "Estoy vendiendo flores, 15 po por tres. ¿Quiere un poco, alteza?",
    ["Interrupt the flowing energy?"] = "¿Interrumpir el flowing energy?",
    ["Leave?"] = "¿Irse?",
    ["Get me out of here!"] = "¡Sáquenme de aquí!",
    ["Remain here."] = "Quédate aquí.",
    ["Hello Fluffs."] = "Hola Fluffs.",
    ["Purrrrr. So, you can talk to cats now?"] = "Purrrrr. Entonces, ¿ahora puedes hablar con los gatos?",
    ["Yes, I got this amulet from a Sphinx."] = "Sí, obtuve este amuleto de un Sphinx.",
    ["Well, I should thank you for finding my kittens that time. I have a terrible time keeping track of them and I never know how many Gertrude has managed to sell."] = "Bueno, debería agradecerte por encontrar a mis gatitos esa vez. Me cuesta muchísimo seguirles la pista y nunca sé cuántos Gertrude ha logrado vender.",
    ["They're cute little creatures, aren't they?"] = "Son pequeñas criaturas lindas, ¿no?",
    ["Purrrrr!"] = "¡Prrrrr!",
    ["Fluffs looks proud."] = "Fluffs parece orgulloso.",
    ["My children have always been popular with Adventurers. They have inherited their father's adventurous spirit."] = "Mis hijos siempre han sido populares entre los aventureros. Han heredado el espíritu aventurero de su padre.",
    ["He's always travelling the world - when he can find some kind person to help him through doors."] = "Siempre está viajando por el mundo, cuando encuentra a alguna persona amable que lo ayude a cruzar las puertas.",
    ["Look after yourself, Fluffs."] = "Cuídate, Fluffs.",
    ["You too, Player."] = "Tú también, Player.",
    ["Hi, mommy!"] = "¡Hola mami!",
    ["Hello, dear!"] = "¡Hola querida!",
    ["Aww, that's sweet."] = "Oh, eso es dulce.",
    ["Is Player looking after you well?"] = "¿Player te está cuidando bien?",
    ["No complaints, mom."] = "No tengo quejas, mamá.",
    ["Good, good. That's what I like to hear."] = "Bien, bien. Eso es lo que me gusta oír.",
    ["They're cute little creatures, aren't they? I've got one in my bank."] = "Son pequeñas criaturas lindas, ¿no? Tengo uno en mi banco.",
    ["You've put one of my children in your bank?"] = "¿Has puesto a uno de mis hijos en tu banco?",
    ["It's fine in there, honest!"] = "¡Está bien ahí, sinceramente!",
    ["Hisss!"] = "¡Silbido!",
    ["Ouch!"] = "¡Ay!",
    ["Hey, aren't you Gertrude's cat?"] = "Oye, ¿no eres el gato de Gertrude?",
    ["What's it to you?"] = "¿A ti qué te importa?",
    ["Well, seeing as I've had to go off and fetch you for Gertrude already..."] = "Bueno, ya que tuve que ir a buscarte para Gertrude...",
    ["Oh would you ever quit worrying, I come down here to watch the fights all the time."] = "Oh, ¿alguna vez dejarías de preocuparte? Vengo aquí para ver las peleas todo el tiempo.",
    ["Oh yes, it's a great place for catching a bit of tail."] = "Oh, sí, es un gran lugar para coger un poco de cola.",
    ["Ummmm, ok. I'll leave you to it then."] = "Ummm, está bien. Entonces te dejo con eso.",
    ["Fluffs' mummified mouth is too tightly wrapped in bandages for her to talk, but now that she's back home with her owner and kittens, she makes mumbled noises of gratitude."] = "La boca momificada de Fluffs está demasiado envuelta en vendas para que pueda hablar, pero ahora que está de regreso en casa con su dueño y sus gatitos, murmura ruidos de gratitud.",
    ["So, what do you do?"] = "Entonces, ¿a qué te dedicas?",
    ["I count eggs for the Easter Bunny."] = "Cuento huevos para el Easter Bunny.",
    ["How many have you counted: a thousand?"] = "¿Cuántos has contado: mil?",
    ["I lost my count. I LOST MY COUNT!"] = "Perdí la cuenta. ¡PERDÍ LA CUENTA!",
    ["I'm sorry. I guess you'll have to start from 1 again."] = "Lo siento. Supongo que tendrás que empezar desde 1 otra vez.",
    ["No, wait! I was ON 1. I remembered."] = "¡No, espera! Estaba en 1. Lo recordé.",
    ["You seem a little distracted."] = "Pareces un poco distraído.",
    ["I was thinking what red would smell like."] = "Estaba pensando a qué olería el rojo.",
    ["Colours don't have a smell."] = "Los colores no tienen olor.",
    ["But if they did, what would it smell like?"] = "Pero si lo hicieran, ¿a qué olería?",
    ["I don't know."] = "No lo sé.",
    ["Thoughts like these keep me up at night."] = "Pensamientos como estos me mantienen despierto por la noche.",
    ["Hello to you too. Isn't it a wonderful day?"] = "Hola a ti también. ¿No es un día maravilloso?",
    ["It seems very nice, yes."] = "Me parece muy bonito, sí.",
    ["Not nice! It is wonderful!"] = "¡No es agradable! ¡Es maravilloso!",
    ["If you say so..."] = "Si tú lo dices...",
    ["NO! I'LL GNAW YOU GOOD! SAY THAT IT'S WONDERFUL! NOW!"] = "¡NO! ¡TE RODRÉ BIEN! ¡DIGA QUE ES MARAVILLOSO! ¡AHORA!",
    ["Okay, okay! It's a wonderful day."] = "¡Está bien, está bien! Es un día maravilloso.",
    ["Yah! Wonderful days are nice!"] = "¡Sí! ¡Los días maravillosos son agradables!",
    ["Hello. You smell nice."] = "Hola. Hueles bien.",
    ["How strange."] = "Qué extraño.",
    ["Hello. Do you want to buy or sell any maces?"] = "Hola. ¿Quieres comprar o vender alguna maza?",
    ["Well, I'll have a look, at least."] = "Bueno, al menos echaré un vistazo.",
    ["I am just a lowly follower of Sliske, here to play a game."] = "Solo soy un humilde follower of Sliske, estoy aquí para jugar.",
    ["What do you want?"] = "¿Qué quieres?",
    ["I have some golem parts, that I wish to...dispose of."] = "Tengo algunas piezas de golem de las que deseo... deshacerme.",
    ["And to do so, in honour of Sliske, I have created a little game."] = "Y para ello, en honor a Sliske, he creado un pequeño juego.",
    ["The first faction to get 20 different people to ask me for the parts will get them all."] = "La primera facción que consiga que 20 personas diferentes me pidan las piezas las obtendrá todas.",
    ["Do you want the parts for your faction?"] = "¿Quieres las piezas para tu facción?",
    ["Yes, I would like the parts."] = "Sí, me gustarían las piezas.",
    ["Thank you for playing... I have counted your vote."] = "Gracias por jugar... He contado tu voto.",
    ["No, I'm not playing your game."] = "No, no estoy jugando a tu juego.",
    ["Life is a game. Only by dying can you not play."] = "La vida es un juego. Sólo muriendo no podrás jugar.",
    ["What do you get out of this?"] = "¿Qué obtienes de esto?",
    ["For me? Why, I just want to help you continue your beautiful war."] = "¿Para mí? Vaya, sólo quiero ayudarte a continuar con tu hermosa guerra.",
    ["Do you want these golem parts for your faction?"] = "¿Quieres estas partes de golem para tu facción?",
    ["What do you want? <sub>If already voted</sub>"] = "¿Qué quieres? <sub>Si ya votó</sub>",
    ["You have done all you need do, for now."] = "Ya has hecho todo lo que necesitabas, por ahora.",
    ["I want your help. I have a little game to play."] = "Quiero tu ayuda. Tengo un pequeño juego que jugar.",
    ["I have managed to convince a Godless agent that I am a reliable source."] = "He logrado convencer a un agente de Godless de que soy una fuente confiable.",
    ["I can deceive them and make them launch one attack on [enemy faction]."] = "Puedo engañarlos y hacer que lancen un ataque contra [enemy faction].",
    ["But I need 20 followers of [player faction] to ask me before 20 followers of [enemy faction] do."] = "Pero necesito que 20 seguidores de [player faction] me lo pregunten antes de que lo hagan 20 seguidores de [enemy faction].",
    ["Do you want me to persuade the Godless to attack [enemy faction]?"] = "¿Quieres que convenza a los Godless para que ataquen a [enemy faction]?",
    ["Yes, attack my enemy."] = "Sí, ataca a mi enemigo.",
    ["Thank you. I hope you enjoy my game as much as I do."] = "Gracias. Espero que disfrutes de mi juego tanto como yo.",
    ["So, do you want me to persuade the Godless to attack your enemy?"] = "Entonces, ¿quieres que convenza a los Sin Dios para que ataquen a tu enemigo?",
    ["I have heard your voice, and will bear in mind your actions."] = "He escuchado tu voz y tendré en cuenta tus acciones.",
    ["What do you want? <sub>If 20 players from one faction have voted</sub>"] = "¿Qué quieres? <sub>Si 20 jugadores de una facción han votado</sub>",
    ["I have all the help I need. Perhaps next time we can... play."] = "Tengo toda la ayuda que necesito. Quizás la próxima vez podamos... jugar.",
    ["Hello!"] = "¡Hola!",
    ["Oh, are you addressing...me?"] = "Oh, ¿te estás dirigiendo... a mí?",
    ["Well, yes?"] = "Bueno, ¿sí?",
    ["Oh dear...This will never do."] = "Dios mío... Esto nunca servirá.",
    ["What are you talking about?"] = "¿De qué estás hablando?",
    ["I was right. This will never do. I mean...look at yourself. How, by any stretch of the imagination, am I supposed to...converse...with one such as yourself?"] = "Tenía razón. Esto nunca servirá. Quiero decir... mírate a ti mismo. ¿Cómo, por mucho que lo imagine, se supone que debo... conversar... con alguien como usted?",
    ["Well, you could flap your mouth about while making words into a sentence."] = "Bueno, podrías mover la boca mientras conviertes las palabras en una oración.",
    ["Oh...you are so lower class. I've become used to dealing with better people than you since I became fabulously wealthy. Thank goodness I have my pomander of expensive spices, your odour was beginning to make me feel light-headed."] = "Oh...eres de clase tan baja. Me he acostumbrado a tratar con mejores personas que tú desde que me hice fabulosamente rico. Gracias a Dios tengo mi pomo de especias caras, tu olor empezaba a marearme.",
    ["Hey!"] = "¡Oye!",
    ["I'm sorry, I can't hear it when poor people are upset. Toodle-pip."] = "Lo siento, no puedo oír cuando la gente pobre está molesta. Toodle-pip.",
    ["Ruined! I'm ruined!"] = "¡Arruinado! ¡Estoy arruinado!",
    ["What's the matter?"] = "¿Qué pasa?",
    ["Don't interrupt my woe!"] = "¡No interrumpas mi aflicción!",
    ["Ahem... Ruined! Oh woe is me!"] = "Ejem... ¡Arruinado! ¡Ay de mí!",
    ["First I lose my spices, and then that blubbery whale Rolo goes and gives away all the food I could've used to buy some more!"] = "Primero pierdo mis especias, y luego esa ballena regordeta de Rolo va y regala toda la comida que podría haber usado para comprar más.",
    ["I'm going to starve in the gutter; my clothes taken by footpads and my body heaped into a pauper's grave!"] = "Voy a morir de hambre en la alcantarilla; ¡Mi ropa se la llevaron unos bandidos y mi cuerpo fue amontonado en una tumba de mendigo!",
    ["Oh come on, I'm sure things aren't that bad."] = "Oh, vamos, estoy seguro de que las cosas no están tan mal.",
    ["Hmm, now you mention it."] = "Hmm, ahora lo mencionas.",
    ["I know, I'll just stop paying my workers so much, and drop the quality of the goods I sell."] = "Lo sé, dejaré de pagarles tanto a mis trabajadores y reduciré la calidad de los productos que vendo.",
    ["If I keep firing people and charging through the roof for my wares I'll soon be back to normal!"] = "Si sigo despidiendo gente y cargando hasta las nubes por mis productos, ¡pronto volveré a la normalidad!",
    ["Uh..."] = "Eh...",
    ["Thank you, uneducated and filthy stranger. You may have saved my life!"] = "Gracias, extraño inculto y asqueroso. ¡Quizás me hayas salvado la vida!",
    ["You're... welcome."] = "De nada.",
    ["Welcome to my new rebuildathon!"] = "¡Bienvenido a mi nuevo maratón de reconstrucción!",
    ["What do I need to do here?"] = "¿Qué necesito hacer aquí?",
    ["Simple really. Choose a sandcastle you want to help build and start working on it."] = "Realmente simple. Elige un castillo de arena que quieras ayudar a construir y empieza a trabajar en él.",
    ["I've got some visiting dignitaries mind so it's worth trying to impress them while they're here to get a better reward."] = "Tengo en mente a algunos dignatarios visitantes, así que vale la pena intentar impresionarlos mientras están aquí para obtener una mejor recompensa.",
    ["It's hot work mind, so if you get too hot you might want to find yourself an ice cream to cool off."] = "Es un trabajo muy caliente, así que si tienes demasiado calor quizás quieras buscar un helado para refrescarte.",
    ["What do I get for helping?"] = "¿Qué obtengo por ayudar?",
    ["Straight down to business, eh?"] = "Directamente al grano, ¿eh?",
    ["Help me build these sandcastles and you'll get some Construction XP. If you take note of the visiting dignitary then you'll get a greater reward for impressing them with your work."] = "Ayúdame a construir estos castillos de arena y obtendrás algo de XP Construction. Si toma nota del dignatario visitante, obtendrá una recompensa mayor por impresionarlo con su trabajo.",
    ["My name's George, and I'm the foreman of this project."] = "Mi nombre es George y soy el capataz de este proyecto.",
    ["Bit of a change from my previous work - helping to rebuild Lumbridge after the battle - but this looks to be just as challenging."] = "Un pequeño cambio con respecto a mi trabajo anterior: ayudar a reconstruir Lumbridge después de la batalla, pero esto parece ser igual de desafiante.",
    ["Really? They just look like sandcastles - how hard can they be to build?"] = "¿En serio? Parecen castillos de arena. ¿Qué tan difícil puede ser construirlos?",
    ["Are you questioning my building abilities?"] = "¿Estás cuestionando mis habilidades de construcción?",
    ["Let's just say they're more advanced than your regular sandcastle - I've got the blueprints, you just focus on the building."] = "Digamos que son más avanzados que un castillo de arena normal. Yo tengo los planos, tú solo concéntrate en el edificio.",
    ["We'll speak later."] = "Hablaremos más tarde.",
    ["Someone left this for you in one of the sand sculptures."] = "Alguien te dejó esto en una de las esculturas de arena.",
    ["Get to work! There's a blockage in channel [blocked channel]."] = "¡Ponte a trabajar! Hay un bloqueo en el canal [blocked channel].",
    ["Choose an option"] = "Elige una opción",
    ["What do I have to do here?"] = "¿Qué tengo que hacer aquí?",
    ["The lava here is only just above the rock's melting point. In order to keep the lava flowing, we have to constantly mine the crust that forms on the edges of the channels. You can mine anywhere you like, but there's usually a blockage in some segment or other, and you'll get experience more quickly from mining that segment. You can find the blockage using the flow gauges. The lava flows more slowly near the blockages. There are a few...distractions that pop up from time to time. You might want to keep an eye out for them. Any questions?"] = "La lava aquí está apenas por encima del punto de fusión de la roca. Para que la lava siga fluyendo, tenemos que extraer constantemente la costra que se forma en los bordes de los canales. Puedes minar en cualquier lugar que quieras, pero generalmente hay un bloqueo en algún segmento u otro, y obtendrás experiencia más rápidamente al minar ese segmento. Puede encontrar el bloqueo utilizando los medidores de flujo. La lava fluye más lentamente cerca de los bloqueos. Hay algunas... distracciones que surgen de vez en cuando. Quizás quieras estar atento a ellos. ¿Alguna pregunta?",
    ["What do I get out of this?"] = "¿Qué gano con esto?",
    ["You get experience in mining! It's a great way to practise your pickaxe skills without having to carry an inconvenient load of rocks away afterwards."] = "¡Obtienes experiencia en minería! Es una excelente manera de practicar tus habilidades con el pico sin tener que cargar una carga incómoda de piedras después.",
    ["*(Shows other options)*"] = "*(Muestra otras opciones)*",
    ["What do you mean...distractions?"] = "¿Qué quieres decir con... distracciones?",
    ["Firstly, ever since the latest chaos dwarf attack, the boilers have been playing up. If you spot one that's broken you can repair it with a hammer. You might find it gives you Smithing experience. Secondly, there's the Liquid Gold Nymph. She's harmless; she just wants to dress everyone in new clothes. If she gives you a gold pickaxe, I can remove the gold again if you decide you don't like it. Thirdly, the mine is...haunted. Sometimes an ancestor spirit will grab someone's pickaxe. If you defeat the possessed pickaxe, it'll give you a boost to Mining experience in the mine for ten minutes. Finally, watch out for a TzHaar hero and lava monster. I still don't know what the monster did, but if you can delay it enough for the hero to catch it, everyone in the area will find more gems when mining here for ten minutes."] = "En primer lugar, desde el último ataque de los enanos del caos, las calderas han estado funcionando mal. Si ves alguno roto puedes repararlo con un martillo. Es posible que descubra que le brinda la experiencia Smithing. En segundo lugar, está el Liquid Gold Nymph. Ella es inofensiva; ella sólo quiere vestir a todos con ropa nueva. Si te da un pico de oro, puedo quitarle el oro nuevamente si decides que no te gusta. En tercer lugar, la mina está... embrujada. A veces, un espíritu ancestral agarrará el pico de alguien. Si derrotas el pico poseído, aumentarás tu experiencia Mining en la mina durante diez minutos. Por último, ten cuidado con el héroe TzHaar y el monstruo de lava. Todavía no sé qué hizo el monstruo, pero si puedes retrasarlo lo suficiente para que el héroe lo atrape, todos en el área encontrarán más gemas al extraer aquí durante diez minutos.",
    ["What's all this for, anyway?"] = "¿Para qué es todo esto?",
    ["This, my friend, is the power supply for the great city of Keldagrim! Heat from the lava flows boils water in the pipes, and the power is transferred to all of the city's machinery. It's a marvel of the modern age! Just...marvellous!"] = "¡Esto, amigo mío, es la fuente de alimentación de la gran ciudad de Keldagrim! El calor de los flujos de lava hierve el agua en las tuberías y la energía se transfiere a toda la maquinaria de la ciudad. ¡Es una maravilla de la era moderna! Simplemente... ¡maravilloso!",
    ["How can I stand so close to the lava without being burned?"] = "¿Cómo puedo estar tan cerca de la lava sin quemarme?",
    ["It's brilliant, isn't it? Just...brilliant! Logically, convection should make the air in this chamber hotter than an oven, and we'd all roast alive. But for some reason that doesn't happen!"] = "Es brillante, ¿no? Simplemente... ¡brillante! Lógicamente, la convección debería hacer que el aire en esta cámara esté más caliente que un horno, y todos nos asaríamos vivos. ¡Pero por alguna razón eso no sucede!",
    ["*If you have a glided pickaxe on you:*"] = "*Si tienes un pico deslizado:*",
    ["Can you remove the gold from a pickaxe?"] = "¿Puedes quitar el oro de un pico?",
    ["You think it's tacky as well, eh? Sure. Just give me the pickaxe you want cleaned up."] = "También crees que es de mal gusto, ¿eh? Seguro. Sólo dame el pico que quieres limpiar.",
    ["Use a gold-plated pickaxe on Foreman Jaak to have him remove the gold."] = "Usa un pico chapado en oro en Foreman Jaak para que retire el oro.",
    ["Do you want me to remove the gold from that pickaxe?"] = "¿Quieres que le quite el oro a ese pico?",
    ["Foreman Jaak removes the gold from the pickaxe."] = "Foreman Jaak quita el oro del pico.",
    ["There you go. Now you can mine without hurting everyone's eyes."] = "Ahí lo tienes. Ahora puedes minar sin lastimar la vista de todos.",
    ["Well, keep that thing away from me, then. I can't stand the...tackiness."] = "Bueno, entonces mantén esa cosa alejada de mí. No soporto la... vulgaridad.",
    ["He doesn't seem interested in talking to you."] = "No parece interesado en hablar contigo.",
    ["Hey! You can't come through here! This is private land!"] = "¡Oye! ¡No puedes pasar por aquí! ¡Este es un terreno privado!",
    ["You will need to find another way in."] = "Tendrás que encontrar otra forma de entrar.",
    ["There might be a gap in the fence somewhere where he wouldn't see you sneak in. You should look around."] = "Puede que haya un hueco en la valla en algún lugar por donde no te vea entrar. Deberías mirar a tu alrededor.",
    ["How dare you make such a mockery!"] = "¡Cómo te atreves a hacer semejante burla!",
    ["Is this your idea of humour?"] = "¿Es esta tu idea del humor?",
    ["This conversation can continue after you remove that ridiculous outfit."] = "Esta conversación puede continuar después de que te quites ese ridículo atuendo.",
    ["What do you want, young'un?"] = "¿Qué quieres, jovencito?",
    ["Ask about moonstones."] = "Pregunta por las piedras lunares.",
    ["I've found this gem."] = "He encontrado esta joya.",
    ["I'm afraid if you want to talk shop, you're going to need a brown apron."] = "Me temo que si quieres hablar de negocios, necesitarás un delantal marrón.",
    ["What sense does that make?"] = "¿Qué sentido tiene eso?",
    ["I have to wear an apron just to talk to you?"] = "¿Tengo que usar un delantal solo para hablar contigo?",
    ["Not even the Crafting Guild makes you wear an apron anymore."] = "Ya ni siquiera el Gremio Crafting te obliga a usar delantal.",
    ["Sounds like the place has lost its integrity since I left."] = "Parece que el lugar ha perdido su integridad desde que me fui.",
    ["Rules are rules: no apron, no crafting help."] = "Las reglas son reglas: sin delantal, sin ayuda para hacer manualidades.",
    ["The master crafter returns to what he was doing."] = "El master crafter vuelve a lo que estaba haciendo.",
    ["I'm wearing a brown apron?"] = "¿Llevo un delantal marrón?",
    ["The master crafter glances at what you're wearing."] = "El master crafter mira lo que llevas puesto.",
    ["Doesn't look like it to me."] = "No me lo parece.",
    ["If you want to talk about crafting, you're gonna need a brown apron."] = "Si quieres hablar sobre manualidades, necesitarás un delantal marrón.",
    ["Alright, let me have a look."] = "Muy bien, déjame echar un vistazo.",
    ["[You show the master crafter the moonstone.]"] = "[Le muestras al master crafter la piedra lunar.]",
    ["Hmm..."] = "Mmm...",
    ["Hmm?"] = "¿Mmm?",
    ["It's moonstone alright - the good stuff too."] = "Es piedra lunar, lo bueno también.",
    ["I was hoping you might know how to turn it into jewellery? I get the feeling gold or silver isn't going to work here."] = "Esperaba que supieras cómo convertirlo en joyería. Tengo la sensación de que el oro o la plata no van a funcionar aquí.",
    ["Yep, you'd be right."] = "Sí, tendrías razón.",
    ["Never worked with it myself, but I've got a book around here somewhere."] = "Nunca he trabajado con eso, pero tengo un libro por aquí.",
    ["Bear with..."] = "Oso con...",
    ["Just a moment..."] = "Un momento...",
    ["Aha! 'Mighty Minerals Volume Two'. I'm afraid it's a bit mangled."] = "¡Ajá! \"Mighty Minerals Volumen dos\". Me temo que está un poco destrozado.",
    ["Let me just find the page..."] = "Déjame buscar la página...",
    ["Moonstone...moonstone..."] = "Piedra lunar...piedra lunar...",
    ["What colour was it again?"] = "¿De qué color era?",
    ["Like a bluey-green."] = "Como un verde azulado.",
    ["Blood moonstone...? Nope."] = "¿Piedra lunar de sangre...? No.",
    ["Snow moonstone...? Ha, you wish!"] = "¿Piedra lunar de nieve...? ¡Ja, lo deseas!",
    ["Ah, here we are. Plain old boring moonstone."] = "Ah, aquí estamos. Piedra lunar vieja y aburrida.",
    ["Ensouling...transmutation...yada, yada, yada."] = "Animación...transmutación...yada, yada, yada.",
    ["Anything?"] = "¿Algo?",
    ["Right. So. It's a simple process, really."] = "Correcto. Entonces. Es un proceso simple, de verdad.",
    ["Turns out you can cast it just like any other gemstone."] = "Resulta que puedes lanzarla como cualquier otra piedra preciosa.",
    ["Okay, do I need any special materials?"] = "Bien, ¿necesito algún material especial?",
    ["The book implies it'll reject 'normal' materials, so you're going to want to cast in an ensouled metal alloy."] = "El libro implica que rechazará materiales \"normales\", por lo que querrás fundir una aleación de metal con alma.",
    ["Great, anything else?"] = "Genial, ¿algo más?",
    ["Looks like it'll respond to enchantment in a similar fashion to dragonstone."] = "Parece que responderá al encantamiento de manera similar a la piedra dragón.",
    ["Thanks for your time, I think I can work with that!"] = "Gracias por tu tiempo. ¡Creo que puedo trabajar con eso!",
    ["Congratulations! You have completed: 'Mystical Moonstone' - Learn how to craft moonstone jewellery."] = "¡Felicitaciones! Has completado: 'Piedra lunar mística': aprende a fabricar joyas con piedra lunar.",
    ["Very good, I'll get back to making my potion golem."] = "Muy bien, volveré a hacer mi gólem de poción.",
    ["Bye!"] = "¡Adiós!",
    ["I need to obtain a moonstone imbued with the power of the underworld. Do you know of such a practice?"] = "Necesito obtener una piedra lunar imbuida del poder del inframundo. ¿Conoces tal práctica?",
    ["Hmm...rings a bell. I'll consult the manual."] = "Mmm... me suena. Consultaré el manual.",
    ["[The former master crafter once again produces 'Mighty Minerals Volume Two' from a hiding place best left unexplored.]"] = "[El former master crafter produce una vez más 'Mighty Minerals Volume Two' desde un escondite que es mejor dejar inexplorado.]",
    ["[He flips through the mangled pages, mouthing the words as he reads.]"] = "[Hojea las páginas destrozadas y articula las palabras mientras lee.]",
    ["It says here you'll first need to ensoul a moonstone by doing a ritual with it as the focus object, then use the ensouled moonstone to somehow capture the appropriate spirits of nature."] = "Aquí dice que primero necesitarás animar una piedra lunar haciendo un ritual con ella como objeto de enfoque, luego usar la piedra lunar animada para capturar de alguna manera los espíritus apropiados de la naturaleza.",
    ["Maybe I need to carry an ensouled moonstone while mining with stone spirits?"] = "¿Tal vez necesito llevar una piedra lunar con alma mientras extraigo con espíritus de piedra?",
    ["Exactly. Then when the moonstone's hunger for stone spirits is sated, you'll need to mine all the toughest rocks you can with a powerful pickaxe until it attunes to the moonstone."] = "Exactamente. Luego, cuando el hambre de la piedra lunar por los espíritus de piedra esté saciada, tendrás que extraer todas las rocas más duras que puedas con un pico poderoso hasta que sintonice con la piedra lunar.",
    ["First things first. How do I get an ensouled moonstone?"] = "Lo primero es lo primero. ¿Cómo consigo una piedra lunar con alma?",
    ["Aha! There's a ritual here to ensoul a moonstone. Take a look at this diagram..."] = "¡Ajá! Aquí hay un ritual para animar una piedra lunar. Echa un vistazo a este diagrama...",
    ["[You memorise the 'ensoul moonstone' ritual. The ritual requires a cut moonstone as a focus.]"] = "[Memorizas el ritual de la 'piedra lunar del alma'. El ritual requiere una piedra lunar tallada como foco.]",
    ["I'm...uh...I'm the master crafter! Renowned distributer of the Crafting skillcape!"] = "Yo soy... uh... ¡Soy el master crafter! ¡Reconocido distribuidor de Crafting skillcape!",
    ["Though I seem to have forgotten my name."] = "Aunque parece que he olvidado mi nombre.",
    ["Wow, that's a cool skillcape!"] = "¡Guau, ese es un skillcape genial!",
    ["It's all white and ghostly!"] = "¡Es todo blanco y fantasmal!",
    ["I suppose it is."] = "Supongo que sí.",
    ["Now, was there anything else? I should really get back to my project."] = "Ahora, ¿había algo más? Realmente debería volver a mi proyecto.",
    ["Thanks so much for saving me from being a vampyre. Here, take this certificate, I'm sorry but it's all I can offer as a reward."] = "Muchas gracias por salvarme de ser vampyre. Toma, toma este certificado, lo siento pero es todo lo que puedo ofrecer como recompensa.",
    ["[The rescued vampyre gratefully hands you a reward.]"] = "[El vampyre rescatado te entrega con gratitud una recompensa.]",
    ["What's up, boss?"] = "¿Qué pasa, jefe?",
    ["You were a Dark Warrior?"] = "¿Eras un guerrero oscuro?",
    ["DARK WARRIORS RULE!"] = "¡REGLA DE LOS GUERREROS OSCUROS!",
    ["So I hear. Tell me more about them."] = "Eso he oído. Cuéntame más sobre ellos.",
    ["We're the strongest gang in the Wilderness!"] = "¡Somos la pandilla más fuerte de Wilderness!",
    ["Still?"] = "¿Aún así?",
    ["I guess not. We were though."] = "Supongo que no. Pero lo estábamos.",
    ["Are there a lot of bandit gangs in the Wilderness?"] = "¿Hay muchas bandas de bandidos en Wilderness?",
    ["A few, yeah. You got your Orphans, Rogues, your Furies, the Destroyers and uh... Gladiators."] = "Algunos, sí. Tienes a tus Huérfanos, Pícaros, Furias, Destructores y... Gladiadores.",
    ["Most of them are dead now, or working for the Zammies. Better dead than red!"] = "La mayoría de ellos ya están muertos o trabajan para los Zammies. ¡Mejor muerto que rojo!",
    ["What happened to the Dark Warriors then?"] = "¿Qué pasó entonces con los Guerreros Oscuros?",
    ["We weren't gonna fight in no demon war. Our leader Cyrus said no, so they killed him."] = "No íbamos a pelear en ninguna guerra de demonios. Nuestro líder Ciro dijo que no y lo mataron.",
    ["We been trying to get out of the Wildy ever since."] = "Hemos estado intentando salir del Wildy desde entonces.",
    ["Why?"] = "¿Por qué?",
    ["Have you seen it out there? Demons, dragons, even mammoths have been moving down from the far north."] = "¿Lo has visto por ahí? Demonios, dragones e incluso mamuts han estado descendiendo desde el extremo norte.",
    ["Demons I can handle, but those things? They scare me."] = "Demonios que puedo manejar, pero ¿esas cosas? Me asustan.",
    ["I hear you."] = "Te escucho.",
    ["I guess we're in the Duchy of Forinthry gang now, though. Back on the rise!"] = "Aunque supongo que ahora estamos en la pandilla del Ducado de Forinthry. ¡De nuevo en ascenso!",
    ["That's right! Keep up the good work."] = "¡Así es! Sigan con el buen trabajo.",
    ["Right, boss."] = "Bien, jefe.",
    ["All clear on the walls?"] = "¿Todo despejado en las paredes?",
    ["Looks it for now. If we see any Zammies on the move we'll come running."] = "Eso parece por ahora. Si vemos algún Zammies en movimiento, iremos corriendo.",
    ["Good job."] = "Buen trabajo.",
    ["As you were."] = "Como eras tú.",
    ["Hey! You can't come in here! This is a high security military installation."] = "¡Oye! ¡No puedes entrar aquí! Esta es una instalación militar de alta seguridad.",
    ["Oh, but I work here!"] = "¡Ah, pero trabajo aquí!",
    ["I might be new here, but I certainly don't recognise you."] = "Puede que sea nuevo aquí, pero ciertamente no te reconozco.",
    ["You're not even wearing proper guards' uniform!"] = "¡Ni siquiera estás usando el uniforme de guardia adecuado!",
    ["So what is this uniform?"] = "Entonces, ¿qué es este uniforme?",
    ["Well, you can see me wearing it. It's an iron chainbody and a bronze helmet."] = "Bueno, puedes verme usándolo. Es un cuerpo de cadena de hierro y un casco de bronce.",
    ["Of course, the officers have elite black plate armour, but that's not something we grunts can dream of..."] = "Por supuesto, los oficiales tienen una armadura de placas negras de élite, pero eso no es algo con lo que nosotros, los gruñidos, podamos soñar...",
    ["Hmm, I wonder if I can make that or get some in the local towns..."] = "Hmm, me pregunto si puedo hacer eso o conseguir algunos en las ciudades locales...",
    ["What was that you just muttered?"] = "¿Qué fue eso que acabas de murmurar?",
    ["Oh, nothing important."] = "Oh, nada importante.",
    ["Oh, please let me in!"] = "¡Oh, por favor déjame entrar!",
    ["Go away. You're getting annoying."] = "Vete. Te estás volviendo molesto.",
    ["I don't suppose you're open to a bribe."] = "Supongo que no estás dispuesto a aceptar un soborno.",
    ["If I had a penny for every well-meaning adventurer who tried to bribe their way into this fortress..."] = "Si tuviera un centavo por cada aventurero bien intencionado que intentó sobornar para entrar en esta fortaleza...",
    ["I could hang up my uniform and retire!"] = "¡Podría colgar mi uniforme y retirarme!",
    ["Who does this fortress belong to?"] = "¿A quién pertenece esta fortaleza?",
    ["This fortress belongs to the Black Knights, also known as the Kinshra."] = "Esta fortaleza pertenece al Black Knights, también conocido como Kinshra.",
    ["*Fortress Guard may say any one of the following at random:*"] = "*Fortress Guard puede decir cualquiera de las siguientes palabras al azar:*",
    ["*Dialogue 1:*"] = "*Diálogo 1:*",
    ["Be careful walking the corridors. The Black Knights are all on edge after that package got delivered."] = "Tenga cuidado al caminar por los pasillos. Los Black Knights están nerviosos después de que se entregó el paquete.",
    ["What package?"] = "¿Qué paquete?",
    ["We weren't told, but it must be important if it's got them all excited like this."] = "No nos lo dijeron, pero debe ser importante si los tiene a todos tan emocionados.",
    ["*Dialogue 2:*"] = "*Diálogo 2:*",
    ["What's the connection between the Black Kni- I mean us and King Arthur?"] = "¿Cuál es la conexión entre Black Kni, quiero decir nosotros, y King Arthur?",
    ["We of the Black Knight order oppose all supporters of the White Knights..."] = "Nosotros, los de la orden Black Knight, nos oponemos a todos los partidarios de los Caballeros Blancos...",
    ["But it is said that King Arthur sent one of his knights to find the Holy Grail."] = "Pero se dice que King Arthur envió a uno de sus caballeros a encontrar el Santo Grial.",
    ["So?"] = "¿Y entonces?",
    ["Well, the knight killed our Black Knight titan."] = "Bueno, el caballero mató a nuestro titán Black Knight.",
    ["He was our mightiest warrior and Lord Daquarius sent him to prevent King Arthur from retrieving such a powerful relic."] = "Era nuestro guerrero más poderoso y Lord Daquarius lo envió para evitar que King Arthur recuperara una reliquia tan poderosa.",
    ["*Dialogue 3:*"] = "*Diálogo 3:*",
    ["I heard something happened to King Arthur and that Lord Daquarius was behind it."] = "Escuché que algo le pasó a King Arthur y que Lord Daquarius estaba detrás de esto.",
    ["Really? Where is King Arthur now?"] = "¿En serio? ¿Dónde está King Arthur ahora?",
    ["I've no idea, but it's a great victory for Lord Daquarius."] = "No tengo idea, pero es una gran victoria para Lord Daquarius.",
    ["To take down such a mighty supporter of the White Knights down... Truly brilliant."] = "Derribar a un partidario tan poderoso de los Caballeros Blancos... Realmente brillante.",
    ["*Fortress guard may say any one of the following at random:*"] = "*Fortress guard puede decir cualquiera de las siguientes palabras al azar:*",
    ["My [lord/lady], I hear the covert operation went well. Only one of those foolish Seers' Village guards suspects any foul play."] = "Mi [lord/lady], escuché que la operación encubierta salió bien. Sólo uno de esos tontos guardias de Seers' Village sospecha que se ha cometido un delito.",
    ["Really? I heard a very brave and courageous adventurer was on to us."] = "¿En serio? Escuché que un aventurero muy valiente y valiente nos estaba siguiendo.",
    ["Pfft, nah. [She/He] couldn't possibly be brave enough to work out our part in the plan."] = "Pfft, no. [She/He] no podríamos ser lo suficientemente valientes para cumplir nuestra parte en el plan.",
    ["I beg your pardon, [my lord/lady]. What does Lord Daquarius plan to do with his newly acquired statue?"] = "Le pido perdón, [my lord/lady]. ¿Qué planea hacer Lord Daquarius con su estatua recién adquirida?",
    ["Display it prominently, no doubt. All evil geniuses do that."] = "Muéstralo de forma destacada, sin duda. Todos los genios malvados hacen eso.",
    ["Truly? But it's so well hidden in the dungeon."] = "¿De verdad? Pero está muy bien escondido en el calabozo.",
    ["I doubt we would ever get to see it."] = "Dudo que alguna vez lleguemos a verlo.",
    ["Good day, brave knight. Congratulations on your victory against King Arthur."] = "Buenos días, valiente caballero. Felicitaciones por su victoria contra King Arthur.",
    ["Er, thanks. Why don't you tell me - in your own words - how glorious you thought our victory was?"] = "Er, gracias. ¿Por qué no me dices, con tus propias palabras, lo gloriosa que pensaste que fue nuestra victoria?",
    ["Of course. It was so clever of Lord Daquarius to lend our men to Morgan Le Faye in exchange for our prize."] = "Por supuesto. Fue muy inteligente por parte de Lord Daquarius prestar nuestros hombres a Morgan Le Faye a cambio de nuestro premio.",
    ["We got the better end of the deal, no doubt."] = "Obtuvimos la mejor parte del trato, sin duda.",
    ["The guard regards you with silent fear."] = "El guardia te mira con miedo silencioso.",
    ["I'm sorry ,sir, but I'm under strict orders not to chat while on duty."] = "Lo siento, señor, pero tengo órdenes estrictas de no charlar mientras estoy de servicio.",
    ["Your orders, actually."] = "Tus órdenes, en realidad.",
    ["Get lost. This is private property."] = "Piérdete. Esta es propiedad privada.",
    ["Yes, what are you selling?"] = "Sí, ¿qué estás vendiendo?",
    ["Talk about Rag and Bone Man."] = "Hablando de Rag and Bone Man.",
    ["Oh, you've come back."] = "Oh, has vuelto.",
    ["Please, I haven't got any more vinegar. Give me some time, I beg you."] = "Por favor, no tengo más vinagre. Dame un poco de tiempo, te lo ruego.",
    ["I wasn't after vinegar today."] = "Hoy no buscaba vinagre.",
    ["Oh, wonderful."] = "Oh, maravilloso.",
    ["I will have some in soon if 'he' needs it."] = "Pronto tendré algunos si 'él' los necesita.",
    ["In the meantime, can I interest you in anything else?"] = "Mientras tanto, ¿puedo interesarte en algo más?",
    ["Well, I'll put something special to one side for you."] = "Bueno, dejaré algo especial a un lado para ti.",
    ["Wine merchant, huh?"] = "Comerciante de vinos, ¿eh?",
    ["Yes, indeed. The finest wines in Misthalin."] = "Sí, efectivamente. Los mejores vinos de Misthalin.",
    ["Care to take a look at my wares?"] = "¿Te importaría echar un vistazo a mis productos?",
    ["Not at the moment."] = "No por el momento.",
    ["Can you tell me about Draynor Village?"] = "¿Puedes hablarme de Draynor Village?",
    ["The village is quite old, but the market is a rather recent addition. We were doing quite good business up until recently."] = "El pueblo es bastante antiguo, pero el mercado es una incorporación bastante reciente. Hasta hace poco estábamos haciendo bastante buen negocio.",
    ["What happened?"] = "¿Qué pasó?",
    ["Mysterious attacks began happening to villagers. Some say it's a vampyre, but I'm not convinced."] = "Los aldeanos comenzaron a sufrir ataques misteriosos. Algunos dicen que es un vampyre, pero a mí no me convence.",
    ["Talk about Vampyre Slayer."] = "Habla de Vampyre Slayer.",
    ["Well done killing that vampyre. Business has certainly improved since the attacks have stopped."] = "Bien hecho matando a ese vampyre. Sin duda, el negocio ha mejorado desde que cesaron los ataques.",
    ["Happy to help."] = "Encantado de poder ayudar.",
    ["Then move along, you filthy ragamuffin, I have customers to serve!"] = "Entonces sigue adelante, asqueroso canalla, ¡tengo clientes a quienes atender!",
    ["Ah! I buy wine bottles back if you want to hand them all over."] = "¡Ah! Compro botellas de vino si quieres entregármelas todas.",
    ["Saradomin and Zamorak have decided to have a huge fight just nearby! It's terrible for business!"] = "¡Saradomin y Zamorak han decidido tener una gran pelea cerca! ¡Es terrible para los negocios!",
    ["Well, not long ago there was a battle right outside Draynor, between Saradomin and Zamorak! You can still see the battlefield."] = "Bueno, no hace mucho hubo una batalla justo afuera de Draynor, ¡entre Saradomin y Zamorak! Todavía puedes ver el campo de batalla.",
    ["Besides that, mysterious attacks began happening to villagers. Some say it's a vampyre, but I'm not convinced."] = "Además de eso, comenzaron a ocurrir ataques misteriosos a los aldeanos. Algunos dicen que es un vampyre, pero a mí no me convence.",
    ["You add that to the vampyre you killed, and it doesn't make for happy sales figures!"] = "Si sumas eso al vampyre que eliminaste, ¡no obtendrás cifras de ventas felices!",
    ["Perhaps I can interest you in some wine?"] = "¿Quizás pueda interesarte un poco de vino?",
    ["A raw bass? You should know that is not a worthy offering, outlander."] = "¿Un bajo crudo? Debes saber que esa no es una ofrenda digna, forastero.",
    ["*If you are not wearing a Ring of charos (a)*"] = "*Si no llevas puesto un Ring of charos (a)*",
    ["Yes, you're right - I'll find something more worthy of you."] = "Sí, tienes razón: encontraré algo más digno de ti.",
    ["*If you are wearing a Ring of charos (a)*"] = "*Si llevas puesto un Ring of charos (a)*",
    ["*(Same as above)*"] = "*(Igual que arriba)*",
    ["[Charm] That's not a bass, it's just a very small shark."] = "[Charm] Eso no es una lubina, es sólo un tiburón muy pequeño.",
    ["That's not a bass, it's just a very small shark."] = "Eso no es una lubina, es solo un tiburón muy pequeño.",
    ["That is a very small shark indeed, outlander. Small, but worthy."] = "Ese es un tiburón muy pequeño, forastero. Pequeño, pero digno.",
    ["Your lyre is now enchanted. You can use it to teleport to Rellekka. When the enchantment wears off you will need to re-enchant it."] = "Tu lira ahora está encantada. Puedes usarlo para teletransportarte a Rellekka. Cuando el encantamiento desaparezca, tendrás que volver a encantarlo.",
    ["I offer you this enchantment for your worthy offering."] = "Te ofrezco este encantamiento por tu digna ofrenda.",
    ["This... here... home."] = "Esta... aquí... casa.",
    ["This... here... home. Pests take over... No sleep... Big bangs..."] = "Esto... aquí... casa. Las plagas se apoderan... Sin dormir... Big bangs...",
    ["This... here... home. Pests take over... No sleep... Big bangs... Giants... not know... how to catch?"] = "Esto... aquí... casa. Las plagas se apoderan... Sin dormir... Big bangs... Gigantes... no saben... ¿cómo atrapar?",
    ["Giants try..."] = "Los gigantes lo intentan...",
    ["Giants try... Giants lose..."] = "Los gigantes lo intentan... Los gigantes pierden...",
    ["Giants try... Giants lose... Giants sad..."] = "Los gigantes lo intentan... Los gigantes pierden... Los gigantes están tristes...",
    ["You friend of giant then help catch pests..."] = "Amigo del gigante, entonces ayuda a atrapar plagas...",
    ["Human help? Will... human be friend?"] = "¿Ayuda humana? ¿Será... el humano amigo?",
    ["You're all friendly, happy to help!"] = "¡Sois todos amables y encantados de ayudar!",
    ["How does it work?"] = "¿Cómo funciona?",
    ["We try trap."] = "Probamos con trampa.",
    ["We try trap. Not work."] = "Probamos trap. No funciona.",
    ["We try trap. Not work. Food for pests in home."] = "Probamos trampa. No funciona. Alimento para plagas en casa.",
    ["You take food."] = "Toma comida.",
    ["You take food. You catch their food."] = "Tomas comida. Atrapas su comida.",
    ["You take food. You catch their food. Build trap and catch."] = "Tomas comida. Atrapas su comida. Construye trampa y atrapa.",
    ["Don't get... catch?"] = "No entiendes... ¿capturas?",
    ["Don't get... catch? Caught!"] = "No te... ¿captas? ¡Atrapado!",
    ["Don't get... catch? Caught! Or they eat your bones and you be bones for Ivar."] = "No te... ¿captas? ¡Atrapado! O se comen tus huesos y tú serás huesos para Ivar.",
    ["If you catch..."] = "Si atrapas...",
    ["If you catch... We let you..."] = "Si atrapas... Te dejamos...",
    ["If you catch... We let you... Use giants trap stash."] = "Si atrapas... Te permitimos... Usar alijo de trampas gigantes.",
    ["You catch!"] = "¡Lo atrapas!",
    ["You catch! You much power!"] = "¡Captas! ¡Tienes mucho poder!",
    ["You catch! You much power! Use giants trap stash anytime."] = "¡Lo atrapas! ¡Tienes mucho poder! Usa la trampa de gigantes en cualquier momento.",
    ["Tell me about giants."] = "Háblame de gigantes.",
    ["Can you tell me anything about giant culture?"] = "¿Puedes contarme algo sobre la cultura de los gigantes?",
    ["Culture...?"] = "¿Cultura...?",
    ["Culture...? What this... culture?"] = "¿Cultura...? ¿Qué es esta... cultura?",
    ["History! Where did you come from?"] = "¡Historia! ¿De dónde vienes?",
    ["We try... To remember."] = "Intentamos... Recordar.",
    ["We try... To remember. Most giants forget."] = "Intentamos... Recordar. La mayoría de los gigantes olvidan.",
    ["We try... To remember. Most giants forget. Giants once..."] = "Intentamos... Recordar. La mayoría de los gigantes olvidan. Los gigantes alguna vez...",
    ["What the word? Sm... Smar..."] = "¿Cuál es la palabra? Pequeño... Inteligente...",
    ["Smart?"] = "¿Inteligente?",
    ["Smart! Yes! Giants once smart!"] = "¡Inteligente! ¡Sí! ¡Los gigantes alguna vez fueron inteligentes!",
    ["Stories of giant builders..."] = "Historias de constructores gigantes...",
    ["And giants once have king and queen!"] = "¡Y los gigantes alguna vez tuvieron rey y reina!",
    ["Ivar false king..."] = "Ivar falso rey...",
    ["Like Ivar?"] = "¿Te gusta Ivar?",
    ["No... Ivar mean... Ivar punch and kill if..."] = "No... Ivar quiere decir... Ivar golpea y mata si...",
    ["No... Ivar mean... Ivar punch and kill if... we speak... or ask..."] = "No... Ivar quiere decir... Ivar golpea y mata si... hablamos... o preguntamos...",
    ["Ivar just..."] = "Ivar simplemente...",
    ["One day."] = "Un día.",
    ["One day. Maybe human help us learn."] = "Un día. Quizás los humanos nos ayuden a aprender.",
    ["One day. Maybe human help us learn. They give favour."] = "Un día. Quizás los humanos nos ayuden a aprender. Ellos nos dan favor.",
    ["One Giant favour."] = "Un favor gigante.",
    ["But first pests."] = "Pero primero las plagas.",
    ["What's your name?"] = "¿Cómo te llamas?",
    ["Fox."] = "Zorro.",
    ["Fox. What your name?"] = "Fox. ¿Cómo te llamas?",
    ["I'm Player."] = "Soy Player.",
    ["Player?"] = "¿Player?",
    ["Player? Your name bit stupid..."] = "Player? Tu nombre es un poco estúpido...",
    ["Player? Your name bit stupid... Not remember that."] = "Player? Tu nombre es un poco estúpido... No recuerdo eso.",
    ["I call... you... Small friendly human."] = "Yo te llamo... a ti... Pequeño humano amigable.",
    ["Oh okay."] = "Oh, está bien.",
    ["Nothing, thanks."] = "Nada, gracias.",
    ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
    ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
    ["He is ignoring you."] = "Él te está ignorando.",
    ["Apparently you aren't as stupid as you look."] = "Aparentemente no eres tan estúpido como pareces.",
    ["Hi there!"] = "¡Hola!",
    ["Am I dead? What's going on here?"] = "¿Estoy muerto? ¿Qué está pasando aquí?",
    ["Luckily for you, not at all! I've brought you here because - well - Death needs your help!"] = "¡Afortunadamente para ti, para nada! Te he traído aquí porque... bueno, ¡la muerte necesita tu ayuda!",
    ["I'm standing in for him while he's absent, but I'm sure you know the guy. The Grim Reaper, the Collector of Souls... Whatever you like to call him. He retrieves souls from dying creatures, mainly."] = "Lo sustituiré mientras esté ausente, pero estoy seguro de que conoces al tipo. La Parca, el Coleccionista de Almas... Como quieras llamarlo. Recupera almas de criaturas moribundas, principalmente.",
    ["So what does he need me for?"] = "Entonces, ¿para qué me necesita?",
    ["Well his instructions in case of absence aren't too clear. Not sure he ever expected to be gone, but I'm doing my best. It looks like there's an imbalance in the harmony of life and death. Too much life, as far as I can tell."] = "Bueno, sus instrucciones en caso de ausencia no son muy claras. No estoy seguro de que alguna vez esperara irse, pero estoy haciendo lo mejor que puedo. Parece que hay un desequilibrio en la armonía entre la vida y la muerte. Demasiada vida, hasta donde yo sé.",
    ["This seems like something you should probably be more sure of..."] = "Esto parece algo de lo que probablemente deberías estar más seguro...",
    ["Oh, it'll be fine."] = "Oh, todo estará bien.",
    ["Anyway, Death's noticed you're a bit of a killing machine. Putting it simply, he wants you to kill some things."] = "De todos modos, la Muerte se ha dado cuenta de que eres una especie de máquina de matar. En pocas palabras, quiere que mates algunas cosas.",
    ["I can do that! When do I start?"] = "¡Puedo hacer eso! ¿Cuándo empiezo?",
    ["Straight away! First, let me give you this gem. It'll let you contact me or Death remotely, in case you need help or another assignment."] = "¡Inmediatamente! Primero, déjame darte esta joya. Te permitirá comunicarte conmigo o con Muerte de forma remota, en caso de que necesites ayuda u otra tarea.",
    ["You receive a grim gem."] = "Recibes una joya sombría.",
    ["Before I give you your first assignment, I also need to know whether you're happy to team up with other adventurers. Don't worry, you can change your mind later."] = "Antes de darte tu primera tarea, también necesito saber si estás feliz de formar equipo con otros aventureros. No te preocupes, puedes cambiar de opinión más tarde.",
    ["Now for your first assignment."] = "Ahora, tu primera tarea.",
    ["Let's see what we've got. Right! We need X souls from the following battle: *monster name*. How does that sound?"] = "Veamos qué tenemos. ¡Bien! Necesitamos X almas de la siguiente batalla: *nombre del monstruo*. ¿Cómo suena eso?",
    ["*(Dialogue from after dying and losing items occurs.)*"] = "*(Se produce un diálogo después de morir y perder objetos.)*",
    ["*(If you don't have an old Soul Reaper task active:)*"] = "*(Si no tienes una antigua tarea de Soul Reaper activa:)*",
    ["Hello! My names Frank, I'm filling in for Death while he's missing. What can I do for you?"] = "¡Hola! Mi nombre es Frank, estoy reemplazando a la Muerte mientras él está desaparecido. ¿Qué puedo hacer por ti?",
    ["*(If you have an old Soul Reaper task active:)*"] = "*(Si tienes una antigua tarea de Soul Reaper activa:)*",
    ["You've been on the same task for a little while now. Would you like a new one?"] = "Has estado en la misma tarea desde hace un tiempo. ¿Quieres uno nuevo?",
    ["If you choose to reset your assignment this will be treated as a brand new task, with fresh rerolls. There is no guarantee the new assignment will be different to your current one. If you wish to reroll your current task instead, use your grim gem."] = "Si elige restablecer su tarea, esta será tratada como una tarea completamente nueva, con nuevas repeticiones. No hay garantía de que la nueva asignación sea diferente a la actual. Si deseas volver a realizar tu tarea actual, usa tu gema sombría.",
    ["*(Only without an active assignment:)*"] = "*(Sólo sin una tarea activa:)*",
    ["I need an assignment."] = "Necesito una tarea.",
    ["*(With daily assignment available:)*"] = "*(Con tarea diaria disponible :)*",
    ["Let's see what we've got. Right! We need [number] souls from the following battle: [monster name]. How does that sound?"] = "Veamos qué tenemos. ¡Bien! Necesitamos almas [número] de la siguiente batalla: [monster name]. ¿Cómo suena eso?",
    ["Great, thanks!"] = "¡Genial, gracias!",
    ["You have a new reaper assignment: [number] x [boss name]."] = "Tienes una nueva tarea de reaper: [número] x [boss name].",
    ["I'd like a different assignment."] = "Me gustaría una tarea diferente.",
    ["*(Dialogue from rerolling tasks occurs.)*"] = "*(Se produce un diálogo entre las tareas que se repiten).*",
    ["I need some hints about my assignment."] = "Necesito algunas pistas sobre mi tarea.",
    ["*(An assignment hint is shown.)*"] = "*(Se muestra una pista de tarea.)*",
    ["*(Without daily assignment available:)*"] = "*(Sin asignación diaria disponible :)*",
    ["It looks like you're done for today. Great job! I should have some more work for you tomorrow."] = "Parece que ya terminaste por hoy. ¡Buen trabajo! Debería tener más trabajo para ti mañana.",
    ["*(Only with an active assignment:)*"] = "*(Solo con una tarea activa:)*",
    ["*(Only on first time:)*"] = "*(Sólo la primera vez:)*",
    ["I'd like another grim gem."] = "Me gustaría otra joya sombría.",
    ["Are there any rewards for this?"] = "¿Hay alguna recompensa por esto?",
    ["*Rewards interface opens*"] = "*Se abre la interfaz de recompensas*",
    ["*(Assignment hint is shown.)*"] = "*(Se muestra la pista de la tarea.)*",
    ["Am I dead? What do you want from me?"] = "¿Estoy muerto? ¿Qué quieres de mí?",
    ["Straight away! You've already got an assignment - [amount] souls remaining from the following battle: [boss name]."] = "¡Inmediatamente! Ya tienes una tarea: [amount] almas restantes de la siguiente batalla: [boss name].",
    ["*(Only if a grim gem has been requested.)*"] = "*(Solo si se ha solicitado una gema sombría.)*",
    ["Hello! My name's Frank, I'm filling in for Death while he's missing. What can I do for you?"] = "¡Hola! Mi nombre es Frank, estoy reemplazando a Muerte mientras él está desaparecido. ¿Qué puedo hacer por ti?",
    ["How am I doing so far?"] = "¿Cómo me va hasta ahora?",
    ["*(With an active assignment:)*"] = "*(Con una tarea activa:)*",
    ["You're currently collecting souls from the following: *boss name*. You need to collect X more before you're done!"] = "Actualmente estás recolectando almas de lo siguiente: *nombre del jefe*. ¡Necesitas recolectar X más antes de terminar!",
    ["*(Without an active assignment:)*"] = "*(Sin una tarea activa:)*",
    ["It looks like you've completed your current assignment."] = "Parece que has completado tu tarea actual.",
    ["Can you give me any hints?"] = "¿Puedes darme alguna pista?",
    ["It doesn't look like you've got an assignment at the moment."] = "No parece que tengas ninguna tarea en este momento.",
    ["What do you want from me?"] = "¿Qué quieres de mí?",
    ["Straight away! You've already got an assignment - X souls remaining from the following battle: *boss name*."] = "¡Inmediatamente! Ya tienes una tarea: quedan X almas de la siguiente batalla: *nombre del jefe*.",
    ["Where are you?"] = "¿Dónde estás?",
    ["I'm in Death's office. Take the portal south of Draynor Manor to find it!"] = "Estoy en la oficina de la Muerte. ¡Toma el portal al sur de Draynor Manor para encontrarlo!",
    ["That's fine - I can give you a new assignment with no penalty! Do you want me to assign you something new?"] = "Está bien. ¡Puedo darte una nueva tarea sin penalización! ¿Quieres que te asigne algo nuevo?",
    ["Yes, remove my current assignment and give me a new one."] = "Sí, elimina mi asignación actual y dame una nueva.",
    ["Let's see what we've got. Right! We need [number] sould from the following battle: [boss name]. How does that sound?"] = "Veamos qué tenemos. ¡Bien! Necesitamos el alma [número] de la siguiente batalla: [boss name]. ¿Cómo suena eso?",
    ["*(Next section's dialogue occurs.)*"] = "*(Se produce el diálogo de la siguiente sección.)*",
    ["No, I've changed my mind. Leave my assignment."] = "No, he cambiado de opinión. Deja mi tarea.",
    ["If you request a different assignment today you'll only receive 75% of the reaper points for completion, I'm afraid. You'll still get the full amount of experience, though."] = "Si solicitas una tarea diferente hoy, me temo que solo recibirás el 75% de los puntos Reaper por completarla. Sin embargo, seguirás obteniendo toda la experiencia.",
    ["I understand, remove my current assignment and give me a new one."] = "Entiendo, elimina mi asignación actual y dame una nueva.",
    ["*(As on first reroll.)*"] = "*(Como en la primera repetición.)*",
    ["If you request a different assignment today you'll only receive 50% of the reaper points for completion, I'm afraid. You'll still get the full amount of experience, though."] = "Si solicitas una tarea diferente hoy, me temo que solo recibirás el 50% de los puntos Reaper por completarla. Sin embargo, seguirás obteniendo toda la experiencia.",
    ["*(As on second reroll.)*"] = "*(Como en la segunda repetición.)*",
    ["If you request a different assignment today you'll only receive 25% of the reaper points for completion, I'm afraid. You'll still get the full amount of experience, though."] = "Si solicitas una tarea diferente hoy, me temo que solo recibirás el 25% de los puntos Reaper por completarla. Sin embargo, seguirás obteniendo toda la experiencia.",
    ["If you request a different assignment again I can't give you any reaper points, I'm afraid. You'll still get the full amount of experience, though."] = "Si vuelves a solicitar una tarea diferente, me temo que no puedo darte ningún punto Reaper. Sin embargo, seguirás obteniendo toda la experiencia.",
    ["I understand. Remove my current assignment and give me a new one."] = "Lo entiendo. Elimina mi tarea actual y dame una nueva.",
    ["I've changed my mind. Leave my task."] = "He cambiado de opinión. Deja mi tarea.",
    ["I'm afraid I can't offer you any more alternatives today. Even in Death's absence I need to enforce his rules."] = "Me temo que hoy no puedo ofrecerte más alternativas. Incluso en ausencia de la Muerte necesito hacer cumplir sus reglas.",
    ["Hi there! Let's see. Player, was it? I don't think you were on one of the lists... Just bear with me. Hmmm, no. It doesn't seem like you have items to reclaim."] = "¡Hola! Vamos a ver. Player, ¿verdad? No creo que estuvieras en una de las listas... Solo ten paciencia. Mmmm, no. No parece que tengas artículos para reclamar.",
    ["*(Death Item Reclaiming interface opens.)*"] = "*(Se abre la interfaz de recuperación de objetos muertos.)*",
    ["Hi there! Let's see. Player, was it? Yes, you were on one of the lists... Just bear with me - ah here it is! It seems you have items to reclaim."] = "¡Hola! Vamos a ver. Player, ¿verdad? Sí, estabas en una de las listas... Sólo ten paciencia, ¡ah, aquí está! Parece que tienes elementos para reclamar.",
    ["Reclaim your items?"] = "¿Recuperar tus artículos?",
    ["Ask about something else."] = "Pregunta por otra cosa.",
    ["*(Proceeds with normal dialogue.)*"] = "*(Continúa con el diálogo normal.)*",
    ["Ah, it's Player! Death told me you'd be visiting the city. Welcome!"] = "¡Ah, es Player! La muerte me dijo que visitarías la ciudad. ¡Bienvenido!",
    ["I'm Frank. You could say I'm Death's own apprentice, ha. Sorry if we've met before, I see a lot of faces and skulls. It's hard to keep track."] = "Soy Frank. Se podría decir que soy el propio aprendiz de la Muerte, ja. Perdón si nos conocemos antes, veo muchas caras y calaveras. Es difícil seguir la pista.",
    ["Hi! What do you do here, Frank?"] = "¡Hola! ¿Qué haces aquí, Frank?",
    ["I'm the here. I do my best to take care of our residents' every need. Have to do all I can to help their peace be restful; they've earned it!"] = "Soy el aquí. Hago lo mejor que puedo para atender todas las necesidades de nuestros residentes. Tengo que hacer todo lo que pueda para ayudar a que su paz sea reparadora; ¡Se lo han ganado!",
    ["I also take a census every now and then, and log all the changes to the city, so we know what amenities we have available at any given time."] = "También realizo un censo de vez en cuando y registro todos los cambios en la ciudad, para saber qué servicios tenemos disponibles en un momento dado.",
    ["Speaking of which, we've just had a boat-load of new arrivals. They're all over at the pub for their welcome drinks."] = "Hablando de eso, acabamos de recibir un montón de recién llegados. Están todos en el pub para tomar sus bebidas de bienvenida.",
    ["2 souls fly over to power the vessel."] = "2 almas vuelan para impulsar el barco.",
    ["You should stop in and introduce yourself, if you haven't already. Might be some fresh recruits to our mutual cause."] = "Deberías pasar y presentarte, si aún no lo has hecho. Podrían haber nuevos reclutas para nuestra causa mutua.",
    ["Hello again!"] = "¡Hola de nuevo!",
    ["Show me the medium Underworld tasks I can do."] = "Muéstrame las tareas medianas de Underworld que puedo hacer.",
    ["You cannot do that right now."] = "No puedes hacer eso ahora mismo.",
    ["Can I claim any rewards from you?"] = "¿Puedo reclamar alguna recompensa de usted?",
    ["You don't have any rewards to claim!"] = "¡No tienes ninguna recompensa que reclamar!",
    ["I've completed all the tasks in the medium Underworld task set."] = "He completado todas las tareas del conjunto de tareas mediano de Underworld.",
    ["Well done Player, I've kept some rewards aside for you."] = "Bien hecho Player, he reservado algunas recompensas para ti.",
    ["Lupe has also agreed to provide you with a daily supply of baby dragon bones, regular ghostly ink and regular ritual candles in recognition of your efforts."] = "Lupe también acordó proporcionarte un suministro diario de huesos de dragón bebé, tinta fantasmal regular y velas rituales regulares en reconocimiento a tus esfuerzos.",
    ["I'm afraid you don't have enough backpack space to claim all your rewards. Speak to me again when you have 2 spaces."] = "Me temo que no tienes suficiente espacio backpack para reclamar todas tus recompensas. Hablame de nuevo cuando tengas 2 espacios.",
    ["[You are given some rewards for completing the medium Underworld task set!]"] = "[¡Recibirás algunas recompensas por completar el conjunto de tareas mediano de Underworld!]",
    ["There you go, looks like that's everything."] = "Ahí lo tienes, parece que eso es todo.",
    ["I lost the Underworld Grimoire 2 you have me..."] = "Perdí el Underworld Grimoire 2, me tienes...",
    ["You don't seem to have any room for a new one, come back to me when you do."] = "Parece que no tienes espacio para uno nuevo, vuelve conmigo cuando lo tengas.",
    ["Lucky for you I have a spare. Take better care of this one."] = "Por suerte para ti, tengo uno de repuesto. Cuida mejor este.",
    ["[You're handed another Underworld Grimoire 2.]"] = "[Te entregan otro Underworld Grimoire 2.]",
    ["Looks like I have an extra lamp for you. Here you go!"] = "Parece que tengo una lámpara extra para ti. ¡Aquí tienes!",
    ["Ask about the Task System."] = "Pregunta por el Sistema de Tareas.",
    ["Tell me about the Task System."] = "Cuéntame sobre el sistema de tareas.",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
    ["For completing the Underworld set, you are presented with the Underworld Grimoire."] = "Por completar el conjunto Underworld, se te presenta el Grimorio de Underworld.",
    ["This book will become increasingly useful with each difficulty level of the set that you complete."] = "Este libro será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
    ["When you are presented with your rewards, you will be told of its uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its corresponding Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su conjunto de logros correspondiente en la interfaz de Logros.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
    ["You need to complete all of the Tasks in a set of a particular difficulty, then you can claim your reward. Some of the Underworld Tasks are straightforward, some will require skill levels, and some might require quests to be started or completed."] = "Debes completar todas las tareas de un conjunto de una dificultad particular y luego podrás reclamar tu recompensa. Algunas de las tareas del inframundo son sencillas, algunas requerirán skill levels y otras pueden requerir que se inicien o completen misiones.",
    ["To claim the Underworld set reward, speak to Icthlarin or myself."] = "Para reclamar la recompensa del conjunto Underworld, habla con Icthlarin o conmigo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Underworld Grimoire 1"] = "Grimorio del inframundo 1",
    ["Underworld Grimoire 1? Yes, but I'm afraid it would cost you 5,000 coins."] = "¿Grimorio del inframundo 1? Sí, pero me temo que te costaría 5.000 coins.",
    ["Purchase another for 5,000 coins?"] = "¿Comprar otro por 5.000 coins?",
    ["[You're handed another Underworld Grimoire 1.]"] = "[Te entregan otro Grimorio 1 de Underworld.]",
    ["Underworld Grimoire 2"] = "Grimorio del inframundo 2",
    ["Underworld Grimoire 2? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Grimorio del inframundo 2? Sí, pero me temo que te costaría 10.000 coins.",
    ["Purchase another for 10,000 coins?"] = "¿Comprar otro por 10.000 coins?",
    ["Underworld Grimoire 3"] = "Grimorio del inframundo 3",
    ["You'll need space in your inventory."] = "Necesitarás espacio en tu inventario.",
    ["Underworld Grimoire 3? Yes, but I'm afraid it would cost you 25,000 coins."] = "¿Grimorio del inframundo 3? Sí, pero me temo que te costaría 25.000 coins.",
    ["Purchase another for 25,000 coins?"] = "¿Comprar otro por 25.000 coins?",
    ["It doesn't look like you can afford it right now, though. Come back to me when you can."] = "Sin embargo, no parece que puedas permitírtelo en este momento. Vuelve conmigo cuando puedas.",
    ["[You're handed another Underworld Grimoire 3.]"] = "[Te entregan otro Underworld Grimoire 3.]",
    ["Underworld Grimoire 4"] = "Grimorio del inframundo 4",
    ["Underworld Grimoire 4? Yes, but I'm afraid it would cost you 50,000 coins."] = "¿Grimorio del inframundo 4? Sí, pero me temo que te costaría 50.000 coins.",
    ["Purchase another for 50,000 coins?"] = "¿Comprar otro por 50.000 coins?",
    ["[You're handed another Underworld Grimoire 4.]"] = "[Te entregan otro Underworld Grimoire 4.]",
    ["Take care!"] = "¡Cuídate!",
    ["Hello again, Player."] = "Hola de nuevo, Player.",
    ["Hello. How's the repair work going?"] = "Hola. ¿Cómo va el trabajo de reparación?",
    ["I'm working on it. I can always do with more iron sheets, so if you've got any more, I'll give you 20 gp per sheet."] = "Estoy trabajando en ello. Siempre me vendrían bien más láminas de hierro, así que si tienes más, te daré 20 po por lámina.",
    ["Thanks, I'll remember that."] = "Gracias, lo recordaré.",
    ["Hello again, Player. Were you wanting to sell me that iron sheet? I'd give you 20 gp for it."] = "Hola de nuevo, Player. ¿Querías venderme esa chapa de hierro? Te daría 20 po por ello.",
    ["Hello again, Player. Were you wanting to sell me those iron sheets? I'd give you [amount] gp."] = "Hola de nuevo, Player. ¿Querías venderme esas láminas de hierro? Te daría [amount] gp.",
    ["Yes, that'll do nicely."] = "Sí, eso funcionará muy bien.",
    ["No, I'd rather not."] = "No, preferiría no hacerlo.",
    ["That's ok."] = "Está bien.",
    ["Go away, human. Can't you see me busy here?"] = "Vete, humano. ¿No me ves ocupado aquí?",
    ["Oh, well, excuse me! My mistake entirely! Why would I ever think that someone standing behind a cash register might be interested in helping me?"] = "Oh, bueno, ¡disculpe! ¡Error completamente mío! ¿Por qué habría de pensar que alguien detrás de una caja registradora podría estar interesado en ayudarme?",
    ["Go away, human. We not open yet!"] = "Vete, humano. ¡Aún no abrimos!",
    ["Well, excuse me!"] = "Bueno, ¡disculpe!",
    ["What you want, human?"] = "¿Qué quieres, humano?",
    ["So what do you have for sale, then?"] = "Entonces, ¿qué tienes a la venta?",
    ["You a bit annoying, human; you know that?"] = "Eres un poco molesto, humano; ¿sabes eso?",
    ["Thanks. I try."] = "Gracias. Lo intento.",
    ["Do you work here?"] = "¿Trabajas aquí?",
    ["Yes, I work as a forester for the McGrubors! Let me guess: the lederhosen gave me away, right?"] = "¡Sí, trabajo como guardabosques para los McGrubors! Déjame adivinar: los pantalones de cuero me delataron, ¿verdad?",
    ["Something like that. What does your job entail?"] = "Algo así. ¿Qué implica tu trabajo?",
    ["What? Where? How many tails?"] = "¿Qué? ¿Dónde? ¿Cuántas colas?",
    ["Excuse me? No, I mean what do you do here?"] = "¿Perdón? No, quiero decir ¿qué haces aquí?",
    ["Oh! Er...sorry. I look after the place - plant and fell trees, check them for disease, look after the local wildlife...and hold back the tide of the pheasant incursion."] = "¡Oh! Er... lo siento. Cuido el lugar: planto y talo árboles, reviso si hay enfermedades, cuido la vida silvestre local... y detengo la marea de incursiones de faisanes.",
    ["Sounds simple enou-"] = "Suena bastante sencillo.",
    ["Wait - run that last one by me again."] = "Espera, vuelve a ejecutar ese último.",
    ["Pheasants! I kill them - they're pests, see."] = "¡Faisanes! Yo los mato, son plagas, ¿ven?",
    ["Pests? Really? Are you sure you're not thinking of pigeons?"] = "¿Plagas? ¿En realidad? ¿Estás seguro de que no estás pensando en palomas?",
    ["Pigeons, pheasants - what's the difference?"] = "Palomas, faisanes: ¿cuál es la diferencia?",
    ["Actually, there's a very big diff-"] = "En realidad, hay una diferencia muy grande.",
    ["Exactly! They're as bad as each other...plus these ones are mutating."] = "¡Exactamente! Son tan malos como los demás... además estos están mutando.",
    ["Mutating?"] = "¿Mutando?",
    ["Some have got more tail feathers than others."] = "Algunos tienen más plumas en la cola que otros.",
    ["Maybe some have just lost a few fea-"] = "Quizás algunos hayan perdido algunas características.",
    ["Giant mutated pheasants from the Void, planning the destruction of my lovely forest!"] = "¡Faisanes gigantes mutados del Vacío, planeando la destrucción de mi hermoso bosque!",
    ["But they're tiny! You're...you're just a bit mad aren't you?"] = "¡Pero son pequeños! Estás... estás un poco enojado, ¿no?",
    ["Mad? No. 'Freaky', maybe, but not mad!"] = "¿Enojado? No. 'Freaky', tal vez, ¡pero no loco!",
    ["Hey there pal, anything I can help you with?"] = "Hola amigo, ¿puedo ayudarte en algo?",
    ["Ah you must be talking about all the fish flying through the air!"] = "¡Ah, debes estar hablando de todos los peces volando por el aire!",
    ["There's a lot of action in the water on this side of the hub as these fish are crazy little things. You cast out and they'll bite straight way, but getting them out of the water isn't so easy, and that's when before you know it they're flying through the air!"] = "Hay mucha acción en el agua de este lado del centro, ya que estos peces son pequeños y locos. Los lanzas y te muerden de inmediato, pero sacarlos del agua no es tan fácil, y es entonces cuando, antes de que te des cuenta, ¡están volando por el aire!",
    ["I'm not entirely sure what it is that makes these fish so special, but they're in high demand so we'll take any help we can get."] = "No estoy del todo seguro de qué es lo que hace que estos peces sean tan especiales, pero tienen una gran demanda, por lo que aceptaremos cualquier ayuda que podamos conseguir.",
    ["We like to have a bit of fun here, so we keep track of how many we catch in quick succession."] = "Nos gusta divertirnos un poco aquí, por eso hacemos un seguimiento de cuántos capturamos en rápida sucesión.",
    ["The higher your streak, the more rewarding it is, so if you fancy helping us out, put your all in and I'll make sure you're being rewarded for it."] = "Cuanto mayor sea tu racha, más gratificante será, así que si te apetece ayudarnos, ponlo todo de tu parte y me aseguraré de que recibas una recompensa por ello.",
    ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
    ["What are you doing?"] = "¿Qué estás haciendo?",
    ["Me? I'm making sure we're on track for our order of course!"] = "¿Yo? ¡Me estoy asegurando de que estemos bien encaminados para nuestro pedido, por supuesto!",
    ["It's my job to make sure that everything is in order and we're keeping on top of the craziness that's going on in the water over there."] = "Mi trabajo es asegurarme de que todo esté en orden y que estemos al tanto de la locura que sucede en el agua de allí.",
    ["Hey you! You there! Have some free rope!"] = "¡Hola, tú! ¡Tú allí! ¡Ten un poco de cuerda gratis!",
    ["Who are you, and why are you giving away free rope?"] = "¿Quién eres y por qué regalas cuerda?",
    ["I could get into a lot of trouble if I told you that."] = "Podría meterme en muchos problemas si te dijera eso.",
    ["Uh... All right?"] = "Eh... ¿Está bien?",
    ["Hey you! Yes you! How would you like... Oh, you already have some..."] = "¡Hola, tú! ¡Sí tú! ¿Cómo te gustaría...? Oh, ya tienes algunos...",
    ["Sorry, what?"] = "Lo siento, ¿qué?",
    ["I was going to give you some rope, but it looks like you have plenty."] = "Iba a darte un poco de cuerda, pero parece que tienes suficiente.",
    ["What are you doing on my land?"] = "¿Qué haces en mi tierra?",
    ["I'm looking for something to kill."] = "Estoy buscando algo para matar.",
    ["What, on my land? Leave my livestock alone!"] = "¿Qué, en mi tierra? ¡Deja en paz a mi ganado!",
    ["I'm lost."] = "Estoy perdido.",
    ["How can you be lost? Just follow the road east and south. You'll end up in Lumbridge fairly quickly."] = "¿Cómo puedes estar perdido? Simplemente siga la carretera hacia el este y el sur. Terminarás en Lumbridge bastante rápido.",
    ["I'm looking for work."] = "Estoy buscando trabajo.",
    ["Fred! Fred! I've seen 'The Thing'!"] = "¡Fred! ¡Fred! ¡He visto 'La Cosa'!",
    ["You... you actually saw it? Run for the hills! Player, grab as many chickens as you can! We have to..."] = "Tú... ¿realmente lo viste? ¡Corre hacia las colinas! Player, ¡agarra tantas gallinas como puedas! Tenemos que...",
    ["Fred!"] = "¡Fred!",
    ["...flee! Oh, woe is me! The shape-shifter is coming! We're all..."] = "...¡huye! ¡Ay de mí! ¡El cambiaformas ya viene! Todos somos...",
    ["FRED!"] = "¡FRED!",
    ["...doomed. What?"] = "...condenado. ¿Qué?",
    ["It's not a shape-shifter or any other kind of monster."] = "No es un cambiaformas ni ningún otro tipo de monstruo.",
    ["Well, what is it, [boy/girl]?"] = "Bueno, ¿qué pasa, [boy/girl]?",
    ["Well, it's just two penguins... disguised as a sheep."] = "Bueno, son solo dos pingüinos... disfrazados de oveja.",
    ["Have you been out in the sun too long?"] = "¿Has estado demasiado tiempo al sol?",
    ["Hello again."] = "Hola de nuevo.",
    ["What are you doing on my..."] = "¿Qué estás haciendo en mi...?",
    ["Ah, it's the sheep shearer! That wool you gave me sold exceptionally well. Please accept this as an extra thanks."] = "¡Ah, es el esquilador de ovejas! Esa lana que me diste se vendió excepcionalmente bien. Acepte esto como un agradecimiento adicional.",
    ["[The farmer hands over 1,940 coins.]"] = "[El agricultor entrega 1.940 coins.]",
    ["Thank you!"] = "¡Gracias!",
    ["What are you doing on my land? You're not the one who keeps leaving all my gates open and letting out all my chickens are you?"] = "¿Qué haces en mi tierra? No eres tú quien sigue dejando todas mis puertas abiertas y dejando salir a todas mis gallinas, ¿verdad?",
    ["Hmph. Yes, a great big portal appears not far from my farm and Saradomin and Zamorak come traipsing over my land, happy as you please."] = "Hmph. Sí, aparece un gran portal no muy lejos de mi granja y Saradomin y Zamorak vienen recorriendo mi tierra, felices como quieran.",
    ["Bloomin' soldiers everywhere, spooking my chickens and telling everyone they should join up with some army of other."] = "Soldados florecientes por todas partes, asustando a mis gallinas y diciéndoles a todos que deberían unirse a algún ejército de otros.",
    ["Then, without a warning, Saradomin himself plonks a war camp on top of my house. Well, I was angry, I'll tell you."] = "Entonces, sin previo aviso, el propio Saradomin instala un campamento de guerra en lo alto de mi casa. Bueno, estaba enojado, te lo diré.",
    ["So, I left a sternly written letter with the duke, and built a new house here, bringing my sheep with me."] = "Entonces, dejé una carta escrita con severidad al duque y construí una nueva casa aquí, trayendo mis ovejas conmigo.",
    ["And you know what... the THING followed..."] = "Y sabes qué... la COSA siguió...",
    ["The battle destroyed some other peoples houses, too, and there's a rebuilding effort going on right now to help them."] = "La batalla también destruyó las casas de otras personas, y ahora mismo se están realizando esfuerzos de reconstrucción para ayudarlos.",
    ["Not that I needed help moving my house! Hank and Explorer Jack are too soft, in my opinion, accepting help from passing adventurers like that."] = "¡No es que necesitara ayuda para mudar mi casa! Hank y Explorer Jack son demasiado blandos, en mi opinión, al aceptar ayuda de aventureros que pasan como ese.",
    ["At least they're not fighting any more though."] = "Al menos ya no pelean.",
    ["But don't expect me to just hand you more jobs! Find your own work!"] = "¡Pero no esperes que te dé más trabajos! ¡Encuentra tu propio trabajo!",
    ["They're still fighting it out now, over to the west. As for you, maybe you should stop lumbering about in my house and do something useful!"] = "Todavía están peleando, hacia el oeste. En cuanto a ti, ¡tal vez deberías dejar de andar pesadamente por mi casa y hacer algo útil!",
    ["Well hello there! My, you're a cheerful one! How can I help you?"] = "Bueno, ¡hola! ¡Dios mío, eres alegre! ¿Le puedo ayudar en algo?",
    ["I'm Freda, welcome to my humble home!"] = "Soy Freda, ¡bienvenido a mi humilde hogar!",
    ["My husband, Sabbot, and I came here to start a trading post. You know, selling dwarven arms to the Guard."] = "Mi esposo, Sabbot, y yo vinimos aquí para iniciar un puesto comercial. Ya sabes, vender armas enanas a la Guardia.",
    ["Then the trolls came and took over the plateau before we could get established, so I came to live here."] = "Luego vinieron los trolls y se apoderaron de la meseta antes de que pudiéramos establecernos, así que vine a vivir aquí.",
    ["What about your husband?"] = "¿Qué pasa con tu marido?",
    ["That stubborn old mule won't leave the cave we were in! He'd rather die than let the trolls win."] = "¡Esa vieja mula testaruda no sale de la cueva en la que estábamos! Preferiría morir antes que dejar que los trolls ganen.",
    ["I send him soup and letters now and then, and those nice men in town make sure he's okay."] = "Le envío sopa y cartas de vez en cuando, y esos buenos hombres de la ciudad se aseguran de que esté bien.",
    ["Is there anything else you want?"] = "¿Hay algo más que quieras?",
    ["Aren't you afraid of the trolls up here?"] = "¿No les tienes miedo a los trolls de aquí?",
    ["Not at all. There used to be a few around here, but I soon dealt with them."] = "Para nada. Solía ​​haber algunos por aquí, pero pronto me ocupé de ellos.",
    ["How? Aren't trolls really fierce in combat?"] = "¿Cómo? ¿No son los trolls realmente feroces en combate?",
    ["Yes, but I'm fiercer!"] = "Sí, ¡pero soy más feroz!",
    ["I'll have you know I've not been a trader all my life. I do know which end of an axe will do the most damage to a troll."] = "Debes saber que no he sido comerciante en toda mi vida. Sé qué extremo de un hacha le hará más daño a un troll.",
    ["Besides, some of those nice young men from town give me a hand if the trolls come in numbers. But after the last time the trolls seem to have got the hint."] = "Además, algunos de esos jóvenes simpáticos del pueblo me echan una mano si los trolls vienen en gran número. Pero después de la última vez, los trolls parecen haber captado la indirecta.",
    ["It's astonishing what waving an axe at groin height will do to break the will of even the biggest troll!"] = "¡Es sorprendente lo que puede hacer agitar un hacha a la altura de la ingle para romper la voluntad incluso del troll más grande!",
    ["So why don't you live with your husband then?"] = "Entonces, ¿por qué no vives con tu marido?",
    ["Well, I can take on the occasional wandering troll, but a whole horde of them is something else entirely."] = "Bueno, puedo enfrentarme a algún troll errante ocasional, pero una horda entera de ellos es algo completamente distinto.",
    ["This place may not be that safe, but at least it's not the middle of a warzone."] = "Puede que este lugar no sea tan seguro, pero al menos no está en medio de una zona de guerra.",
    ["Anything else I can help you with?"] = "¿Puedo ayudarte con algo más?",
    ["Oh? Well you take care on your way back."] = "¿Ah? Bueno, cuídate en el camino de regreso.",
    ["Hello, Freda."] = "Hola, Freda.",
    ["Hello there. I heard from some of the boys in town that you really gave those trolls a thrashing!"] = "Hola. ¡Escuché de algunos de los chicos de la ciudad que realmente les diste una paliza a esos trolls!",
    ["You keep it up. Every little helps."] = "Sigue así. Todo ayuda.",
    ["I will!"] = "¡Lo haré!",
    ["Anything else you need?"] = "¿Necesitas algo más?",
    ["Can I buy some Climbing boots?"] = "¿Puedo comprar unas botas de escalada?",
    ["I don't see why not. Let me see what I've got in your size."] = "No veo por qué no. Déjame ver lo que tengo en tu talla.",
    ["Buy standard boots for 12gp."] = "Compra botas estándar por 12 po.",
    ["Sorry, you don't have anywhere to put these."] = "Lo sentimos, no tienes ningún lugar donde colocarlos.",
    ["Oops, it looks like you're a little short there. That's 12 gold you need to buy these boots."] = "Vaya, parece que te falta un poco. Son 12 de oro lo que necesitas para comprar estas botas.",
    ["[You purchase the climbing boots.]"] = "[Compras las botas de montaña.]",
    ["See full range of stock."] = "Ver gama completa de stock.",
    ["*If any magic golem outfit piece is not owned:*"] = "*Si alguna pieza del traje de golem mágico no es de tu propiedad:*",
    ["*If inventory is full:*"] = "*Si el inventario está lleno:*",
    ["To receive a piece of the magic golem outfit, you need a free space in your backpack."] = "Para recibir una pieza del traje de golem mágico, necesitas un espacio libre en tu backpack.",
    ["I'm a placeholder NPC so players can quickly get free items in the mining and smithing beta."] = "Soy un NPC marcador de posición para que los jugadores puedan obtener rápidamente elementos gratis en la versión beta de minería y herrería.",
    ["*If inventory is not full:*"] = "*Si el inventario no está lleno:*",
    ["You have been given a piece of the magic golem set."] = "Te han dado una pieza del conjunto de golem mágico.",
    ["*A random unowned sapphire, emerald, or ruby golem outfit piece is placed in the inventory.*"] = "*Se coloca en el inventario una pieza aleatoria de traje de golem de zafiro, esmeralda o rubí sin dueño.*",
    ["*If all magic golem outfit pieces are owned:*"] = "*Si tienes todas las piezas del traje de golem mágico:*",
    ["I cannot speak to you outerlander! Talk to Brundt, the Chieftain!"] = "¡No puedo hablar contigo, extranjero! ¡Habla con Brundt, el cacique!",
    ["They are too suspicious of you for you to get close enough to steal from them."] = "Sospechan demasiado de ti como para que te acerques lo suficiente como para robarles.",
    ["*When speaking to Freidir in Rellekka.*"] = "*Al hablar con Freidir en Rellekka.*",
    ["*Freidir may greet you with any of the following at random:*"] = "*Freidir puede saludarte con cualquiera de los siguientes al azar:*",
    ["How are you, [Fremennik name]? I hope all fares well with you this day!"] = "¿Cómo estás, [Fremennik name]? ¡Espero que a todos les vaya bien este día!",
    ["I'm fine, thanks, how are you?"] = "Estoy bien, gracias, ¿cómo estás?",
    ["All is well with me also!"] = "¡Todo está bien para mí también!",
    ["Hello again, [sister/brother] [Fremennik name]. What need you of me this day? You can always rely on my assistance!"] = "Hola de nuevo, [sister/brother] [Fremennik name]. ¿Qué necesitas de mí este día? ¡Siempre puedes confiar en mi ayuda!",
    ["Hello. Did you want something, [Fremennik name]?"] = "Hola. ¿Querías algo, [Fremennik name]?",
    ["[Fremennik name], it has been too long since last we met!"] = "[Fremennik name], ¡ha pasado demasiado tiempo desde la última vez que nos vimos!",
    ["Welcome back, [sister/brother] [Fremennik name]. It is always a pleasure to see you here!"] = "Bienvenido de nuevo, [sister/brother] [Fremennik name]. ¡Siempre es un placer verte por aquí!",
    ["Hello to you, too!"] = "¡Hola a ti también!",
    ["Always good to see you, [sister/brother] [Fremennik name]."] = "Siempre es un placer verte, [sister/brother] [Fremennik name].",
    ["Select an option (all greetings continue with dialogue below)"] = "Seleccione una opción (todos los saludos continúan con el diálogo a continuación)",
    ["*Freidir may reply to you with any of the following at random:*"] = "*Freidir puede responderle con cualquiera de los siguientes mensajes al azar:*",
    ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
    ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
    ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
    ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
    ["*(Will open your bank.)*"] = "*(Abrirá su banco.)*",
    ["*(Will open you bank pin settings.)*"] = "*(Abrirá la configuración del PIN del banco.)*",
    ["*(Will open you collection box.)*"] = "*(Abrirá su caja de colección.)*",
    ["This is a branch of the Bank of Runescape. We have branches in many towns."] = "Esta es una sucursal del Banco de Runescape. Disponemos de sucursales en muchas localidades.",
    ["Yes we did, but people kept coming into our branches outside of Varrock and telling us that our signs were wrong. They acted as if we didn't know what town we were in or something."] = "Sí, lo hicimos, pero la gente seguía entrando a nuestras sucursales fuera de Varrock y diciéndonos que nuestros carteles estaban equivocados. Actuaron como si no supiéramos en qué ciudad estábamos o algo así.",
    ["Greetings, adventurer! Braving the dangers of the terrible dungeons, I see."] = "¡Saludos, aventurero! Ya veo, desafiando los peligros de las terribles mazmorras.",
    ["What are you doing here?"] = "¿Qué estás haciendo aquí?",
    ["I'm setting up another base for adventurers to use. It's hard and dangerous work, I can tell you."] = "Estoy preparando otra base para que la utilicen los aventureros. Es un trabajo duro y peligroso, te lo aseguro.",
    ["Can I help?"] = "¿Puedo ayudar?",
    ["Certainly! I have lots to do, so feel free to dig in."] = "¡Por supuesto! Tengo mucho que hacer, así que siéntete libre de profundizar.",
    ["**Fremennik scout:** If you look around the room, you should find some crates containing raw fish, logs, and metal bars. I need the fish cooked, the logs turned into bows, and the bars turned into battleaxes. If you take care of this for me, I'll make sure you can continue."] = "**Fremennik scout:** Si miras alrededor de la habitación, deberías encontrar algunas cajas que contienen pescado crudo, logs y barras de metal. Necesito el pescado cocido, los logs convertidos en arcos y las barras convertidas en hachas de batalla. Si te encargas de esto por mí, me aseguraré de que puedas continuar.",
    ["Do you have a knife I can use?"] = "¿Tienes un cuchillo que pueda usar?",
    ["You already have a knife, so what do you need mine for?"] = "Ya tienes un cuchillo, entonces, ¿para qué necesitas el mío?",
    ["Could you remind me what I have to do?"] = "¿Podrías recordarme qué tengo que hacer?",
    ["Do you have a hammer I can use?"] = "¿Tienes un martillo que pueda usar?",
    ["I'll get back to work now."] = "Volveré a trabajar ahora.",
    ["You already have a hammer, so what do you need mine for?"] = "Ya tienes un martillo, entonces, ¿para qué necesitas el mío?",
    ["Consider it done!"] = "¡Considérelo hecho!",
    ["Can you unlock the door?"] = "¿Puedes desbloquear la puerta?",
    ["Thank you."] = "Gracias.",
    ["*First time choosing this option:*"] = "*Primera vez que elijo esta opción:*",
    ["Can you unlock the door for me?"] = "¿Puedes abrirme la puerta?",
    ["Well, I could, but I'd need something in return from you. If you help me out, I will unlock it for you."] = "Bueno, podría, pero necesitaría algo a cambio de tu parte. Si me ayudas, lo desbloquearé.",
    ["Okay, I can help."] = "Está bien, puedo ayudar.",
    ["That's great! Let me just give you some instructions."] = "¡Eso es genial! Déjame darte algunas instrucciones.",
    ["I don't want to help."] = "No quiero ayudar.",
    ["I guess you won't be continuing, then."] = "Entonces supongo que no continuarás.",
    ["Fine!"] = "¡Bien!",
    ["Fine."] = "Bien.",
    ["*Subsequent times:*"] = "*Tiempos posteriores:*",
    ["I've already told you: if you want the door unlocked, you need to help me out."] = "Ya te lo dije: si quieres que la puerta esté abierta, debes ayudarme.",
    ["I sure am!"] = "¡Claro que sí!",
    ["That's the spirit! Keep up the hard work."] = "¡Ese es el espíritu! Sigan con el trabajo duro.",
    ["Hey there! How is the work coming?"] = "¡Hola! ¿Cómo va el trabajo?",
    ["It's going great!"] = "¡Va genial!",
    ["Wonderful! Keep up the good work."] = "¡Maravilloso! Sigan con el buen trabajo.",
    ["It's not going too well, I'm afraid."] = "Me temo que no va muy bien.",
    ["What kind of attitude is that? You need to work harder, that's all."] = "¿Qué tipo de actitud es esa? Necesitas trabajar más duro, eso es todo.",
    ["Hey! Those aren't for you."] = "¡Oye! Esos no son para ti.",
    ["Wonderful! That was the last of them. As promised, I'll unlock the door for you."] = "¡Maravilloso! Ese fue el último de ellos. Como prometí, te abriré la puerta.",
    ["Hello again. Shouldn't you be slaying terrors of untold magnitude?"] = "Hola de nuevo. ¿No deberías estar matando terrores de magnitud incalculable?",
    ["Not until I've managed to dig out a knife."] = "No hasta que haya logrado sacar un cuchillo.",
    ["That was put on hold until I could find a hammer."] = "Eso quedó en espera hasta que pudiera encontrar un martillo.",
    ["Oh yeah, I should."] = "Oh, sí, debería hacerlo.",
    ["Do you want to set sail?"] = "¿Quieres zarpar?",
    ["Select An Option"] = "Selecciona una opción",
    ["Yes, please (Al Kharid)."] = "Sí, por favor (Al Kharid).",
    ["All aboard, then."] = "Entonces, todos a bordo.",
    ["Yes, please (Taverley)."] = "Sí, por favor (Taverley).",
    ["Yes, please (Shadow Reef)."] = "Sí, por favor (Shadow Reef).",
    ["You must be on a members' world to visit the Shadow Reef."] = "Debes estar en un mundo de miembros para visitar Shadow Reef.",
    ["Would You Like To Enter The Shadow Reef?"] = "¿Te gustaría entrar en Shadow Reef?",
    ["Normal mode"] = "modo normal",
    ["Story mode"] = "modo historia",
    ["Not now"] = "Ahora no",
    ["Suit yourself. I'll be here soaking up the atmosphere if you change your mind."] = "Haz lo que quieras. Estaré aquí absorbiendo el ambiente si cambias de opinión.",
    ["Not right now, thanks."] = "Ahora no, gracias.",
    ["You look happy."] = "Te ves feliz.",
    ["Indeed, [brother/sister]! I simply can't get enough of this place."] = "¡Efectivamente, [brother/sister]! Simplemente no puedo tener suficiente de este lugar.",
    ["The brisk sea air, the refreshing chill. It really gets the blood pumping."] = "El fresco aire del mar, el refrescante frío. Realmente hace que la sangre bombee.",
    ["Anyway, listen to me ramble. Are we to set sail?"] = "De todos modos, escúchame divagar. ¿Vamos a zarpar?",
    ["You want passage to Daemonheim?"] = "¿Quieres pasar a Daemonheim?",
    ["Well, don't stand around. Get on board."] = "Bueno, no te quedes ahí parado. Sube a bordo.",
    ["Well, be on your way then. Leave me in peace!"] = "Bueno, entonces sigue tu camino. ¡Déjame en paz!",
    ["Yes, the icy peninsula far to the north of here."] = "Sí, la península helada muy al norte de aquí.",
    ["Ice, snow, harsh winds..."] = "Hielo, nieve, fuertes vientos...",
    ["...and no sand or swamp sludge, clogging up every orifice."] = "...y sin arena ni lodo de pantano que obstruyan todos los orificios.",
    ["Are you done with questions? Can we go now?"] = "¿Terminaste con las preguntas? ¿Podemos irnos ahora?",
    ["Why are you so grumpy?"] = "¿Por qué estás tan gruñón?",
    ["Grumpy? I should kill you where you stand!"] = "¿Gruñón? ¡Debería matarte donde estás!",
    ["But that wouldn't help with this damned humidity."] = "Pero eso no ayudaría con esta maldita humedad.",
    ["I need the snow in my boots, the sea wind stinging my face..."] = "Necesito la nieve en mis botas, el viento del mar picando mi cara...",
    ["That's why I want to leave. Are you ready to go to Daemonheim?"] = "Por eso quiero irme. ¿Estás listo para ir a Daemonheim?",
    ["You! You look like a capable adventurer. We need your help."] = "¡Tú! Pareces un aventurero capaz. Necesitamos tu ayuda.",
    ["My Fremennik clansmen and I have embarked on a test of skill and combat in the far north."] = "Los miembros de mi clan Fremennik y yo nos hemos embarcado en una prueba de habilidad y combate en el extremo norte.",
    ["Unfortunately, it's proving more of a challenge than we had anticipated."] = "Desafortunadamente, está resultando ser un desafío mayor de lo que habíamos previsto.",
    ["They need reinforcements to explore the dungeons there: to fight, or, if not, to provide support to those who do."] = "Necesitan refuerzos para explorar las mazmorras que hay allí: para luchar, o en su defecto, para dar apoyo a quienes lo hagan.",
    ["Why do you need me?"] = "¿Por qué me necesitas?",
    ["How dangerous is this?"] = "¿Qué tan peligroso es esto?",
    ["There are challenges for adventurers of all skill-levels."] = "Hay desafíos para aventureros de todos los niveles.",
    ["My clansmen can explain more when you arrive."] = "Los miembros de mi clan pueden explicarte más cuando llegues.",
    ["Sounds good!"] = "¡Suena bien!",
    ["Sorry, I'm too busy."] = "Lo siento, estoy demasiado ocupado.",
    ["You seem like a [man/woman] with fire in [his/her] heart."] = "Pareces un [man/woman] con fuego en el corazón de [his/her].",
    ["A thirst for adventure, am I wrong?"] = "Sed de aventuras, ¿me equivoco?",
    ["Excellent! Just look for the jetty nearby. There, a boat will take you to your destination."] = "¡Excelente! Basta con buscar el embarcadero cercano. Allí, un barco os llevará a vuestro destino.",
    ["Suit yourself. We'll be here if you change your mind."] = "Haz lo que quieras. Estaremos aquí si cambias de opinión.",
    ["Would you like to buy some Cooking equipment?"] = "¿Te gustaría comprar algún equipo Cooking?",
    ["Sorry, I don't need your help right now."] = "Lo siento, no necesito tu ayuda en este momento.",
    ["You currently do not qualify to start this quest. You need Level 67 Smithing, level 60 Divination, level 62 Slayer and level 67 Mining. You must also have completed the Lunar Diplomacy and Tai Bwo Wannai Trio quests and mastered Barbarian Skilling."] = "Actualmente no calificas para comenzar esta misión. Necesitas Nivel 67 Smithing, nivel 60 Divination, nivel 62 Slayer y nivel 67 Mining. También debes haber completado las misiones Lunar Diplomacy y Tai Bwo Wannai Trio y dominar las habilidades bárbaras.",
    ["Hello again, [brother/sister] [Fremennik name]. What need you of me this day? You can always rely on my assistance!"] = "Hola de nuevo, [brother/sister] [Fremennik name]. ¿Qué necesitas de mí este día? ¡Siempre puedes confiar en mi ayuda!",
    ["Welcome back, [brother/sister] [Fremennik name]. It is always a pleasure to see you here!"] = "Bienvenido de nuevo, [brother/sister] [Fremennik name]. ¡Siempre es un placer verte por aquí!",
    ["Always good to see you, [brother/sister] [Fremennik name]."] = "Siempre es un placer verte, [brother/sister] [Fremennik name].",
    ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
    ["*Dialogue 1*"] = "*Diálogo 1*",
    ["How's the King treating you then?"] = "¿Cómo te trata el Rey entonces?",
    ["Like serfs."] = "Como siervos.",
    ["Serf?"] = "¿Siervo?",
    ["Yes, you know - peons, plebs, the downtrodden. He treats us like his own personal possessions."] = "Sí, ya sabes: peones, plebeyos, los oprimidos. Nos trata como a sus posesiones personales.",
    ["You should leave this place."] = "Deberías abandonar este lugar.",
    ["I keep trying to save up enough to leave, but the King keeps taxing us! We have no money left."] = "Sigo intentando ahorrar lo suficiente para irme, ¡pero el Rey sigue cobrando impuestos! No nos queda dinero.",
    ["Oh dear."] = "Dios mío.",
    ["*Dialogue 2*"] = "*Diálogo 2*",
    ["It's a bit grey round here, isn't it?"] = "Está un poco gris por aquí, ¿no?",
    ["It gets you down after a while, you know. There are 273 shades of grey, you know, and we have them all."] = "Te deprime después de un tiempo, ¿sabes? Hay 273 tonos de gris, ya sabes, y los tenemos todos.",
    ["That's grey-t."] = "Eso es gris-t.",
    ["That attempt at humour merely made me more depressed. Leave me alone."] = "Ese intento de humor simplemente me deprimió más. Déjame en paz.",
    ["*Dialogue 3*"] = "*Diálogo 3*",
    ["How are you today?"] = "¿Cómo estás hoy?",
    ["**sigh**"] = "**suspiro**",
    ["That good? Everyone around here seems a little depressed."] = "¿Tan bueno? Todos por aquí parecen un poco deprimidos.",
    ["And not particularly talkative."] = "Y no es particularmente hablador.",
    ["I'll leave you to your sighing. It looks like you have plenty to do."] = "Te dejo con tus suspiros. Parece que tienes mucho que hacer.",
    ["*Dialogue 4*"] = "*Diálogo 4*",
    ["Cheer up! It's not the end of the world."] = "¡Anímate! No es el fin del mundo.",
    ["I'd prefer that, if it meant I didn't have to talk to people as insanely happy as you."] = "Preferiría eso, si eso significara no tener que hablar con personas tan increíblemente felices como tú.",
    ["Whoa! I think you need to get out more."] = "¡Vaya! Creo que necesitas salir más.",
    ["Talk about Nial."] = "Habla de Nial.",
    ["How are you?"] = "¿Cómo estás?",
    ["I'm quite busy, getting ready for the move."] = "Estoy bastante ocupado preparándome para la mudanza.",
    ["Talk about life on Jatizso."] = "Habla sobre la vida en Jatizso.",
    ["I'm surprised to see you still here."] = "Me sorprende verte todavía aquí.",
    ["Well, I went to visit Mawnis a couple of times, but I'm just used to the atmosphere here. It's home."] = "Bueno, fui a visitar Mawnis un par de veces, pero ya estoy acostumbrado al ambiente de aquí. Es el hogar.",
    ["I have good news. I've been to the afterlife - long story - and Nial was there, safe and sound."] = "Tengo buenas noticias. Estuve en el más allá (una larga historia) y Nial estaba allí, sano y salvo.",
    ["Oh, that's wonderful news! Thank you so much!"] = "¡Oh, qué maravillosa noticia! ¡Muchas gracias!",
    ["Shhh! I'm waiting for the show!"] = "¡Shhh! ¡Estoy esperando el espectáculo!",
    ["What's on the bill?"] = "¿Qué hay en la factura?",
    ["Nothing an outerlander would enjoy!"] = "¡Nada que un extranjero disfrutaría!",
    ["There's a performance of an epic from olden times tonight! The epic of Bukalla!"] = "¡Esta noche hay una presentación de una epopeya de tiempos antiguos! ¡The epic of Bukalla!",
    ["Bukalla?"] = "¿Bukalla?",
    ["He was a famed slayer of daggermouths in olden times. It's a very inspirational song."] = "Era un famoso cazador de bocas de daga en la antigüedad. Es una canción muy inspiradora.",
    ["Sounds interesting! Maybe I'll stick around."] = "¡Suena interesante! Quizás me quede por aquí.",
    ["The Epic of Bukalla is a live recorded poem, roughly five minutes in length. We suggest that you turn your sound on in order to get the most out of it."] = "The Epic of Bukalla es un poema grabado en vivo, de aproximadamente cinco minutos de duración. Le sugerimos que active el sonido para aprovecharlo al máximo.",
    ["I'm ready to hear it!"] = "¡Estoy listo para escucharlo!",
    ["Wait a second!"] = "¡Espera un segundo!",
    ["Sounds boring"] = "Suena aburrido",
    ["Sounds boring."] = "Suena aburrido.",
    ["Well, you're missing out on a glorious piece of history."] = "Bueno, te estás perdiendo una gloriosa parte de la historia.",
    ["Welcome to NovtumberFest! Look at that fancy tent!"] = "¡Bienvenido a NovtumberFest! ¡Mira esa elegante tienda!",
    ["*(Only if not asked last:)*"] = "*(Solo si no se preguntó al final:)*",
    ["Hello! I am Friedrich, I'm in charge of the archery range."] = "¡Hola! Soy Friedrich, estoy a cargo del campo de tiro con arco.",
    ["First of all just line up with one of the targets behind me."] = "Primero que nada, alinéate con uno de los objetivos detrás de mí.",
    ["Then pull back your bowstring and let your arrows fly!"] = "¡Entonces tira hacia atrás la cuerda del arco y deja volar tus flechas!",
    ["You will receive Ranged XP for taking part in the archery range."] = "Recibirás Ranged XP por participar en el campo de tiro con arco.",
    ["How's it going?"] = "¿Cómo te va?",
    ["I'm great and you know what? I believe that you're going to be great on the range!"] = "Estoy genial y ¿sabes qué? ¡Creo que vas a estar genial en el campo!",
    ["All you have to do is..."] = "Todo lo que tienes que hacer es...",
    ["BOW-LIEVE!"] = "¡ARCO-LIEVE!",
    ["Keep your aim true."] = "Mantén tu puntería fiel.",
    ["H-hello."] = "H-hola.",
    ["Hello, young lady. What's the problem?"] = "Hola, señorita. ¿Cuál es el problema?",
    ["Don't send me to Lumbridge!"] = "¡No me envíes a Lumbridge!",
    ["Why would I do that?"] = "¿Por qué haría eso?",
    ["My mum says that if I don't behave she'll send me to Lumbridge! I don't wanna go there. Even Saradomin is scary now."] = "¡Mi mamá dice que si no me porto bien me enviará a Lumbridge! No quiero ir allí. Incluso Saradomin da miedo ahora.",
    ["I'm sure she wouldn't do that!"] = "¡Estoy seguro de que ella no haría eso!",
    ["You don't know my mum!"] = "¡No conoces a mi mamá!",
    ["Will we be safe here?"] = "¿Estaremos a salvo aquí?",
    ["I'm tired!"] = "¡Estoy cansado!",
    ["I'm scared, mum!"] = "¡Tengo miedo, mamá!",
    ["Zamorak won't come here will he?"] = "Zamorak no vendrá aquí ¿verdad?",
    ["Hello; how can I help you?"] = "Hola; ¿Le puedo ayudar en algo?",
    ["What are you selling?"] = "¿Qué estás vendiendo?",
    ["You can't; I'm beyond help."] = "No puedes; No tengo ayuda.",
    ["I'm okay, thank you."] = "Estoy bien, gracias.",
    ["Hello. I'm Frito."] = "Hola. Soy Frito.",
    ["Hi there! I'm Player."] = "¡Hola! Soy Player.",
    ["Good afternoon, Player. What can I do for you?"] = "Buenas tardes, Player. ¿Qué puedo hacer por ti?",
    ["Hold on a second..."] = "Espera un segundo...",
    ["Darling, what are those?"] = "Cariño, ¿qué son esos?",
    ["Oh, uh, these things on my feet? They're only the most fashionable shoe around! Gators!"] = "Oh, eh, ¿estas cosas en mis pies? ¡Son sólo los zapatos más de moda que existen! ¡Caimanes!",
    ["Aren't they just? Look at them!"] = "¿No son justos? ¡Míralos!",
    ["Some might consider them distasteful, but I think they're absolutely fabulous!"] = "Algunos podrían considerarlos desagradables, ¡pero yo creo que son absolutamente fabulosos!",
    ["Well, thank you. I'm glad someone appreciates fashion around here."] = "Bueno, gracias. Me alegra que alguien aprecie la moda por aquí.",
    ["Indeed. If you want to make a fashion statement you have to be bold, and that is exactly what you've done here."] = "De hecho. Si quieres hacer una declaración de moda tienes que ser audaz, y eso es exactamente lo que has hecho aquí.",
    ["Ignore what anyone else says. THOSE are the shoes of the next generation."] = "Ignora lo que digan los demás. ESOS son los zapatos de la próxima generación.",
    ["Fabulous."] = "Fabuloso.",
    ["That's it? Nothing about what a wonderful place this is and how much you're enjoying it?"] = "¿Eso es todo? ¿Nada sobre lo maravilloso que es este lugar y cuánto lo estás disfrutando?",
    ["Nope. Now, if you have nothing better to ask, you're blocking the sunlight."] = "No. Ahora, si no tienes nada mejor que preguntar, estás bloqueando la luz del sol.",
    ["Why haven't you eaten me?"] = "¿Por qué no me has comido?",
    ["Oh please. There are much better-tasting foods out there than human. Take fruit, for example. Fruit pies, salads, smoothies, and more! Juicy, healthy, and absolutely delicious."] = "Ah, por favor. Existen alimentos con mucho mejor sabor que los humanos. Tomemos como ejemplo la fruta. ¡Tartas de frutas, ensaladas, batidos y más! Jugoso, saludable y absolutamente delicioso.",
    ["I guess not all crocodiles are uncivilised beasts."] = "Supongo que no todos los cocodrilos son bestias incivilizadas.",
    ["Indeed, some of us have good taste. I think my kind are gradually opening up to the possibility of other diets."] = "De hecho, algunos de nosotros tenemos buen gusto. Creo que los de mi especie se están abriendo gradualmente a la posibilidad de otras dietas.",
    ["Do you know Chito and Dundee?"] = "¿Conoces Chito y Dundee?",
    ["Yes, they invited me here. I was having a rather splendid time down by Menaphos, but Chito is my cousin, so how could I say no?"] = "Sí, me invitaron aquí. Me lo estaba pasando bastante bien con Menaphos, pero Chito es mi primo, así que ¿cómo podría decir que no?",
    ["That explains it - I thought you guys looked similar."] = "Eso lo explica. Pensé que ustedes se parecían.",
    ["I don't see it."] = "No lo veo.",
    ["Really? If you guys stood side-by-side, I wouldn't be able to tell who's who!"] = "¿En serio? ¡Si estuvieran uno al lado del otro, no podría decir quién es quién!",
    ["You really must get your eyes tested, Player."] = "Realmente debes hacerte una prueba de la vista, Player.",
    ["You look dazzling! (Only appears if the golden crocodile cosmetic upgrade is applied)"] = "¡Te ves deslumbrante! (Solo aparece si se aplica la mejora cosmética del cocodrilo dorado)",
    ["You look dazzling!"] = "¡Te ves deslumbrante!",
    ["I do, don't I? Much better than my boring old green look."] = "Sí, ¿no? Mucho mejor que mi viejo y aburrido look verde.",
    ["Dundee made it for you!"] = "¡Dundee lo hizo para ti!",
    ["Oh? That's surprising."] = "¿Ah? Eso es sorprendente.",
    ["How so?"] = "¿Cómo es eso?",
    ["He's not exactly the most fashionable person around here."] = "No es exactamente la persona más elegante por aquí.",
    ["I can't say I disagree..."] = "No puedo decir que no esté de acuerdo...",
    ["Ah, I know that look!"] = "¡Ah, conozco esa mirada!",
    ["You want scratches!"] = "¡Quieres rasguños!",
    ["I've got just the spot, right behind the ears..."] = "Tengo el lugar justo, justo detrás de las orejas...",
    ["You inch closer, and extend your arm out to the crocodile."] = "Te acercas un poco más y extiendes tu brazo hacia el cocodrilo.",
    ["The crocodile snaps at you."] = "El cocodrilo te muerde.",
    ["I guess I should have expected that."] = "Supongo que debería haberlo esperado.",
    ["Hiya!"] = "¡Hola!",
    ["I'm in the middle of grabbing a snack, Player. Talk to me after I'm done."] = "Estoy a punto de tomar un refrigerio, Player. Habla conmigo cuando termine.",
    ["RRRGGGGGGG"] = "RRRGGGGGGGG",
    ["COCONUT! Fruit from Crondis herself!"] = "¡COCO! ¡Fruta de la propia Crondis!",
    ["Frito eats the coconut whole, cracking the shell cleanly in one big munch."] = "Frito se come el coco entero, rompiendo la cáscara limpiamente de un gran bocado.",
    ["You know, I wasn't sure about you, Player. But that was a really kind gesture."] = "Sabes, no estaba seguro de ti, Player. Pero ese fue un gesto realmente amable.",
    ["Ah, it was nothing really. Enjoy!"] = "Ah, en realidad no fue nada. ¡Disfrutar!",
    ["Congratulations! You have completed: 'Fruit Glorious Fruit' - Feed Frito her favourite fruit."] = "¡Felicitaciones! Has completado: 'Fruit Glorious Fruit' - Dale a Frito su fruta favorita.",
    ["Fruit! Delicious fruit!"] = "¡Fruta! ¡Fruta deliciosa!",
    ["Frito gobbles the fruit down before you have a chance to react."] = "Frito devora la fruta antes de que tengas la oportunidad de reaccionar.",
    ["That wasn't for... uh, nevermind."] = "Eso no fue para... eh, no importa.",
    ["Oh. Well. I appreciate the gesture, but I've gone off the texture of meat. Fruit, on the other hand..."] = "Ah. Bien. Agradezco el gesto, pero se me ha ido la textura de la carne. La fruta, en cambio...",
    ["Interesting..."] = "Interesante...",
    ["Congratulations! You have completed: 'Vegan Unfriendly' - Feed all the crocodiles some steak."] = "¡Felicitaciones! Has completado: 'Vegan Unfriendly': alimenta a todos los cocodrilos con un poco de filete.",
    ["You have unlocked the title: |color=#00FF00}}"] = "Has desbloqueado el título: |color=#00FF00}}",
    ["You can activate this via the 'Titles' tab in the 'Customisations' interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz 'Personalizaciones'.",
    ["There's a reason I drop off the shells for you when we're hunting. They're not particularly nice."] = "Hay una razón por la que te dejo los caparazones cuando estamos cazando. No son particularmente agradables.",
    ["Hello adventurer, welcome to the Entrana furnace."] = "Hola aventurero, bienvenido al horno Entrana.",
    ["Would you like me to explain my craft to you?"] = "¿Quieres que te explique mi oficio?",
    ["Yes please. I'd be fascinated to hear what you do."] = "Sí, por favor. Me fascinaría escuchar lo que haces.",
    ["I'm extremely pleased to hear that! I've always wanted an apprentice. Let me talk you through the secrets of glassblowing."] = "¡Me alegra muchísimo escuchar eso! Siempre quise un aprendiz. Déjame explicarte los secretos del soplado de vidrio.",
    ["**Fritz the Glassblower:** Glass is made from soda ash and silica. We get our soda ash by collecting seaweed from the rocks - the prevailing currents make the north-east and south-west corners of the island the best place to find it, it can also be found in"] = "**Fritz the Glassblower:** El vidrio está hecho de carbonato de sodio y sílice. Obtenemos nuestra carbonato de sodio recolectando algas de las rocas; las corrientes predominantes hacen que los rincones noreste y suroeste de la isla sean el mejor lugar para encontrarla; también se puede encontrar en",
    ["your nets sometimes when you're fishing, on Karamja island or at the Piscatoris Fishing Colony in the nets there. To turn seaweed into soda ash, all you need to do is burn it on a fire. Feel free to use the range in my house for"] = "tus redes a veces cuando estás pescando, en la isla Karamja o en la colonia Piscatoris Fishing en las redes de allí. Para convertir las algas en carbonato de sodio, todo lo que necesitas hacer es quemarlas al fuego. Siéntete libre de usar la estufa de mi casa para",
    ["that; it's the one directly west of here. Next we collect sand from the sandpit that you'll also find just west of here, there are others located in Yanille and Shilo Village."] = "eso; es el que está directamente al oeste de aquí. A continuación recogemos arena del arenero que también encontrarás justo al oeste de aquí, hay otros ubicados en Yanille y Shilo Village.",
    ["I see you already have a bucket that you can use for carrying it in."] = "Veo que ya tienes un cubo que puedes usar para transportarlo.",
    ["You'll need a bucket to carry it in. Tell you what, you can have this old one of mine."] = "Necesitarás un balde para transportarlo. Te diré una cosa, puedes quedarte con este viejo mío.",
    ["You can use the bucket I gave you earlier."] = "Puedes usar el cubo que te di antes.",
    ["I'm afraid I don't have that bucket with me. Could you give me another one, please?"] = "Me temo que no tengo ese cubo conmigo. ¿Podrías darme otro, por favor?",
    ["Do I look like I'm made of buckets? You'll just have to buy another from a general store."] = "¿Parece que estoy hecho de cubos? Sólo tendrás que comprar otro de un general store.",
    ["And don't interrupt me when I'm speaking - it's rude. Anyway, as I was saying ..."] = "Y no me interrumpas cuando hablo, es de mala educación. De todos modos, como decía...",
    ["**Fritz the Glassblower:** Bring the sand and the soda ash back here and melt them together in the furnace, and there you have it - molten glass!"] = "**Fritz the Glassblower:** Trae la arena y el carbonato de sodio aquí y derrítelos en el horno, y ahí lo tienes: ¡vidrio fundido!",
    ["There are many things you can use the molten glass for once you have made it. Depending on how talented you are, you could try turning it into something, like a fishbowl, for example. If you'd like to try your hand at the"] = "Hay muchas cosas para las que puedes usar el vidrio fundido una vez que lo hayas hecho. Dependiendo de tu talento, puedes intentar convertirlo en algo, como una pecera, por ejemplo. Si quieres probar suerte en el",
    ["fine art of glassblowing you can use my spare glassblowing pipe. I think I left it on the chest of drawers in my house this morning."] = "el fino arte del soplado de vidrio, puedes usar mi pipa de soplado de vidrio de repuesto. Creo que lo dejé en la cómoda de mi casa esta mañana.",
    ["Alternatively I am always happy to buy the molten glass from you, saves me running about making it for myself."] = "Alternativamente, siempre estaré feliz de comprarte el vidrio fundido, así me ahorro tener que tener que hacerlo yo mismo.",
    ["That sounds good. How much will you pay me?"] = "Eso suena bien. ¿Cuánto me pagarás?",
    ["Tell you what, because you've been interested in my art, I'll pay you the premium price of 20 gold pieces for each piece of molten glass you bring me."] = "Te diré una cosa, como te has interesado en mi arte, te pagaré el precio premium de 20 piezas de oro por cada pieza de vidrio fundido que me traigas.",
    ["No thanks, I doubt I'll ever turn my hand to glassblowing."] = "No, gracias, dudo que algún día me dedique al soplado de vidrio.",
    ["Ok, suit yourself. Nobody seems to be interested in the skilled crafts these days."] = "Ok, haz lo que quieras. Hoy en día nadie parece estar interesado en los oficios especializados.",
    ["If you should change your mind, come back and talk to me."] = "Si cambias de opinión, vuelve y habla conmigo.",
    ["Ah Player, have you come to sell me some molten glass?"] = "Ah Player, ¿has venido a venderme un poco de vidrio fundido?",
    ["Umm, not much point me trying to pay you for glass you don't have, is there?"] = "Umm, no tiene mucho sentido que intente pagarte por un vaso que no tienes, ¿verdad?",
    ["Well, actually, if you don't mind..."] = "Bueno, en realidad, si no te importa...",
    ["I guess you've never heard of a rhetorical question then. I'll make it simple for you. You bring glass, me pay shiny gold coins."] = "Supongo que nunca has oído hablar de una pregunta retórica. Te lo haré sencillo. Tú traes vidrio, yo pago brillante gold coins.",
    ["Fantastic! Let's see, for that much glass I could pay you ... ... <number> gold pieces!"] = "¡Fantástico! A ver, por tanto vaso te podría pagar... ... ¡<number> piezas de oro!",
    ["Are you mad? I've run all over the island to make this glass."] = "¿Estás enojado? He corrido por toda la isla para hacer este vaso.",
    ["Pity. Well you can find me here if you change your mind."] = "Lástima. Bueno, puedes encontrarme aquí si cambias de opinión.",
    ["Sure, that sounds like a fair price."] = "Claro, parece un precio justo.",
    ["Here you are then."] = "Aquí estás entonces.",
    ["Thanks very much, Player. I'll buy any more that you bring."] = "Muchas gracias, Player. Compraré más que traigas.",
    ["Oh."] = "Ah.",
    ["...errr, well should you get any I'm quite happy to pay for it. Remember, I'll pay you 20 gold pieces for each piece of molten glass you get for me."] = "...errr, bueno, si consigues alguno, estaré encantado de pagarlo. Recuerda, te pagaré 20 piezas de oro por cada trozo de vidrio fundido que me consigas.",
    ["So what did you want to talk to me about then?"] = "Entonces, ¿de qué querías hablarme?",
    ["Could you tell me how to make molten glass again, please?"] = "¿Podrías decirme cómo volver a hacer vidrio fundido, por favor?",
    ["Well, I am very busy at the moment, but I guess I can take 5 minutes off for my favourite student."] = "Bueno, estoy muy ocupado en este momento, pero supongo que puedo tomarme 5 minutos libres para mi estudiante favorito.",
    ["I just thought I'd drop in and say hello."] = "Sólo pensé en pasar a saludar.",
    ["Hello then. I'm afraid I don't have any time to chat though. The druids of Taverley have placed a huge order for glass vials, so I'm very busy."] = "Hola, entonces. Pero me temo que no tengo tiempo para charlar. Los druidas de Taverley han hecho un pedido enorme de viales de vidrio, así que estoy muy ocupado.",
    ["You don't have a sapling planted in that patch. Plant one and I might agree to look after it for you."] = "No tienes ni un retoño plantado en esa parcela. Plante uno y tal vez acepte cuidarlo por usted.",
    ["Alright, but it's not going to be cheap! I want [3/5] monkey nuts, a monkey bar and a ground-up Suqah tooth."] = "Muy bien, ¡pero no será barato! Quiero nueces de mono [3/5], una barra y un diente de Suqah molido.",
    ["You don't have a sapling planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes ni un retoño plantado en esa parcela. Planta algo y tal vez acepte cuidarlo por ti.",
    ["First, I want [3/5] monkey nuts, a monkey bar and a ground up suqah tooth."] = "Primero, quiero nueces de mono [3/5], una barra de mono y un diente de suqah molido.",
    ["Where can I get all that stuff?"] = "¿Dónde puedo conseguir todo eso?",
    ["You can get a Suqah tooth from a Suqah's mouth, of course. Then you grind it up with a pestle and mortar. As for the monkey bar and nuts, try looking somewhere where there are lots of monkeys!"] = "Puedes obtener un diente de Suqah de la boca de una Suqah, por supuesto. Luego lo mueles con un mortero. En cuanto a la barra de monos y las nueces, ¡intenta buscar en algún lugar donde haya muchos monos!",
    ["Alright, I'll pay."] = "Muy bien, pagaré.",
    ["What the heck do you want with THAT?"] = "¿Qué diablos quieres con ESO?",
    ["They're for eating, silly! What else can you do with a monkey bar?"] = "¡Son para comer, tonto! ¿Qué más puedes hacer con una barra de mono?",
    ["And the Suqah tooth?"] = "¿Y el diente de Suqah?",
    ["Lots of gnomes like a bit of ground-up Suqah tooth, just don't tell anyone about this, okay?"] = "A muchos gnomos les gusta un poco de diente de Suqah molido, pero no le cuentes a nadie sobre esto, ¿de acuerdo?",
    ["Forget I asked."] = "Olvida que pregunté.",
    ["Maybe some other time."] = "Quizás en otro momento.",
    ["His and Her Royal Frogness just think of me as a toady."] = "Él y ella Royal Frogness simplemente piensan en mí como un adulador.",
    ["No one thinks to give me a kiss. I'm all alone..."] = "A nadie se le ocurre darme un beso. Estoy completamente solo...",
    ["I'll never get to be a [prince/princess]. *sigh*"] = "Nunca llegaré a ser un [prince/princess]. *suspiro*",
    ["Okay, so what happens now?"] = "Bien, ¿qué pasa ahora?",
    ["Ooh, hubby look - a visitor!"] = "Oh, mira mi esposo, ¡un visitante!",
    ["I see him, sweetie. Welcome to the Enchanted Valley!"] = "Lo veo, cariño. ¡Bienvenidos al Valle Encantado!",
    ["Are you two royalty?"] = "¿Ustedes dos son miembros de la realeza?",
    ["Yes, we're His..."] = "Sí, somos suyos...",
    ["...and Her..."] = "...y ella...",
    ["...Royal Frogness..."] = "...Rana Real...",
    ["...and Frogness-ess. No, that doesn't sound right. Frogness-ess, maybe?"] = "...y Frogness-ess. No, eso no suena bien. ¿Rana, tal vez?",
    ["I think 'Frogness' covers us both, darling."] = "Creo que 'Frogness' nos cubre a ambos, cariño.",
    ["Of course it does, sorry, my mind got ribbited away there."] = "Por supuesto que sí, lo siento, mi mente se burló allí.",
    ["Is the Enchanted Valley your kingdom?"] = "¿Es el Valle Encantado tu reino?",
    ["Oh no, silly. We rule over the Land of the Frogs."] = "Oh no, tonto. Gobernamos la Tierra de las Ranas.",
    ["We're on our froggymoon!"] = "¡Estamos en nuestra luna de ranas!",
    ["We just got married, see?"] = "Nos acabamos de casar, ¿ves?",
    ["As human and frog..."] = "Como humano y rana...",
    ["...until one of us croaks!"] = "...¡hasta que uno de nosotros croa!",
    ["Don't you need to keep kissing people to lift your amphibian curse?"] = "¿No necesitas seguir besando a la gente para levantar tu maldición anfibia?",
    ["All the time! So why not just tie the knot instead of abducting random adventurers to do the honours?"] = "¡Todo el tiempo! Entonces, ¿por qué no simplemente casarse en lugar de secuestrar a aventureros al azar para que hagan los honores?",
    ["Oh, you make it sound so romantic."] = "Oh, lo haces sonar muy romántico.",
    ["You know you're the only frog for me."] = "Sabes que eres la única rana para mí.",
    ["*If the player talks to Frog Prince during his transformation:*"] = "*Si el player habla con Frog Prince durante su transformación:*",
    ["Ah - er - this is embarrassing."] = "Ah, ejem, esto es vergonzoso.",
    ["*If the player kisses the Frog Prince during his transformation:*"] = "*Si el player besa a Frog Prince durante su transformación:*",
    ["Hey! Lips off my froggy hubby!"] = "¡Oye! ¡Labios de mi marido ranita!",
    ["*If the player talks to Frog Princess during her transformation:*"] = "*Si el player habla con Frog Princess durante su transformación:*",
    ["Argh! Please - don't look at me when I'm like this."] = "¡Argh! Por favor, no me mires cuando estoy así.",
    ["*If the player kisses the Frog Princess during her transformation:*"] = "*Si el player besa a Frog Princess durante su transformación:*",
    ["You'd better not be trying to kiss my wife, you toad!"] = "¡Será mejor que no intentes besar a mi esposa, sapo!",
    ["...and Frogness-ess. No, that doesn't sound right. Frogness-ees, maybe?"] = "...y Frogness-ess. No, eso no suena bien. ¿Ranas, tal vez?",
    ["*(End of dialogue)*"] = "*(Fin del diálogo)*",
    ["One day I'm going to meet our Big High War God."] = "Un día conoceré a nuestro Gran Dios War.",
    ["We've heard all sorts of stories over the years."] = "Hemos escuchado todo tipo de historias a lo largo de los años.",
    ["We like how good he is to us goblinkind."] = "Nos gusta lo bueno que es con nosotros, los duendes.",
    ["Pretty Trees!"] = "¡Bonitos árboles!",
    ["Having fun?"] = "¿Te estás divirtiendo?",
    ["I'm just looking at the magic trees. I think they're cool."] = "Solo estoy mirando los árboles mágicos. Creo que son geniales.",
    ["Well, they are magical. Valuable as well..."] = "Bueno, son mágicos. Valioso también...",
    ["When I grow up I want to chop down trees and make magic bows. Then I'd be rich."] = "Cuando sea mayor quiero talar árboles y hacer arcos mágicos. Entonces sería rico.",
    ["Well, that does seem to be a common career around here."] = "Bueno, esa parece ser una carrera común por aquí.",
    ["Good day, [sir/madam]."] = "Buenos días, [sir/madam].",
    ["I'm working on the digging, of course."] = "Estoy trabajando en la excavación, por supuesto.",
    ["It's a small excavation, so only two of us can work on it at a time."] = "Es una excavación pequeña, por lo que solo dos de nosotros podemos trabajar en ella a la vez.",
    ["Good day."] = "Buenos días.",
    ["Would you like to trade in fur?"] = "¿Le gustaría comerciar con pieles?",
    ["These hides are very soft. Did you trap these yourself?"] = "Estas pieles son muy suaves. ¿Los atrapaste tú mismo?",
    ["Hunt... skin..."] = "Cazar... piel...",
    ["Fur keep cold out... wind bite less."] = "Las pieles mantienen el frío afuera... el viento muerde menos.",
    ["They look heavy."] = "Se ven pesados.",
    ["Heavy... means warm."] = "Pesado... significa cálido.",
    ["This fur... death in snow."] = "Esta piel... muerte en la nieve.",
    ["Only Fremenniks may purchase furs here."] = "Sólo los Fremenniks pueden comprar pieles aquí.",
    ["The fur trader is staring at you suspiciously. You cannot steal from his stall while he distrusts you."] = "El comerciante de pieles te mira con recelo. No puedes robar en su puesto mientras él desconfíe de ti.",
    ["*When speaking to Fur trader in Rellekka.*"] = "*Al hablar con un comerciante de pieles en Rellekka.*",
    ["Welcome back, [Fremennik name]! Have you seen the furs I have today?"] = "¡Bienvenido de nuevo, [Fremennik name]! ¿Has visto las pieles que tengo hoy?",
    ["*Fur trader may reply to you with any of the following at random:*"] = "*El comerciante de pieles puede responderle con cualquiera de los siguientes mensajes al azar:*",
    ["Let me see your wares."] = "Déjame ver tus productos.",
    ["Welcome, mortal."] = "Bienvenido, mortal.",
    ["That's an interesting Anima crystal you have there. Would you be willing to donate it?"] = "El cristal de Anima que tienes ahí es interesante. ¿Estarías dispuesto a donarlo?",
    ["Hand in your Anima crystal?"] = "¿Entregar tu cristal de Anima?",
    ["Yes. (Gain 500 reputation with Zamorak)"] = "Sí. (Gana 500 de reputación con Zamorak)",
    ["You have gained 500 reputation with the Zamorakian forces!"] = "¡Has ganado 500 puntos de reputación con las fuerzas zamorakianas!",
    ["Thank you for your help."] = "Gracias por tu ayuda.",
    ["I notice you have a stock of seals from around the Heart. Would you be interested in donating them?"] = "Noté que tienes un stock de sellos de todo el Corazón. ¿Estarías interesado en donarlos?",
    ["**EXCHANGE SEALS FOR REPUTATION WITH THE ZAMORAKIANS?**"] = "**¿CAMBIAR SELLOS POR REPUTACIÓN CON LOS ZAMORAKIANOS?**",
    ["Hand in Seren seals."] = "Entregue los sellos Seren.",
    ["Your Seals of the Cywir were worth [number] reputation with the Zamorakian forces!"] = "¡Tus Sellos de Cywir valían [número] reputación ante las fuerzas zamorakianas!",
    ["Hand in Sliske seals."] = "Entregue los sellos Sliske.",
    ["Your Seals of the faceless were worth [number] reputation with the Zamorakian forces!"] = "¡Tus Sellos de los sin rostro valían [número] reputación ante las fuerzas zamorakianas!",
    ["Hand in Zaros seals"] = "Entrega de sellos de Zaros",
    ["Your Seals of the Dragon riders were worth [number] reputation with the Zamorakian forces!"] = "¡Tus jinetes de los Sellos del Dragón valían [número] reputación con las fuerzas zamorakianas!",
    ["Hand in all seals."] = "Entregue todos los sellos.",
    ["No thank you."] = "No, gracias.",
    ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
    ["You find yourself in the Heart of Gielinor, adventurer. Hear the cries and relish the chaos of the battlefield as the forces of Zamorak do battle with the vile minions of Zaros, Sliske and Seren! Leading us into battle are the ferocious Twin Furies: Avaryss the unceasing and Nymora the vengeful."] = "Te encuentras en el Corazón de Gielinor, aventurero. ¡Escucha los gritos y disfruta del caos del campo de batalla mientras las fuerzas de Zamorak luchan contra los viles secuaces de Zaros, Sliske y Seren! Liderándonos a la batalla están las feroces Furias Gemelas: Avaryss la incesante y Nymora la vengativa.",
    ["Why are you all just stood here? Shouldn't you be fighting?"] = "¿Por qué están todos aquí parados? ¿No deberías estar peleando?",
    ["We are not all savages. Upon this platform a truce has been established, allowing us - the envoys of each faction - to use words rather than violence to sway fresh recruits. For below the battle rages on, so we must do what we can to persuade the mercenaries that join the fray to fight for our cause. Take a look at what I have to offer. I assure you, I'll make it worth your while to fight for Zamorak."] = "No todos somos salvajes. Sobre esta plataforma se ha establecido una tregua que nos permite a nosotros, los enviados de cada facción, utilizar palabras en lugar de violencia para influir en nuevos reclutas. Porque abajo la batalla continúa, por lo que debemos hacer lo que podamos para persuadir a los mercenarios que se unen a la refriega para que luchen por nuestra causa. Echa un vistazo a lo que tengo para ofrecerte. Te lo aseguro, haré que valga la pena luchar por Zamorak.",
    ["What is your opinion of me?"] = "¿Cuál es tu opinión sobre mí?",
    ["How can I improve my reputation?"] = "¿Cómo puedo mejorar mi reputación?",
    ["There are a few ways you can improve your standing. The easiest thing you can do is defeat our enemies, and use Ingression fragments to call in reinforcements for us. The bounty master over there, Feng, can also help you improve your standing by offering you bounties. Speak to him if you'd like to know more. Oh, and I'm sure if you could somehow find a way to defeat the other factions' generals that would certainly earn you a lot of favour."] = "Hay algunas formas de mejorar tu posición. Lo más fácil que puedes hacer es derrotar a nuestros enemigos y usar fragmentos de Ingresión para pedir refuerzos para nosotros. El maestro de recompensas de allí, Feng, también puede ayudarte a mejorar tu posición ofreciéndote recompensas. Habla con él si quieres saber más. Ah, y estoy seguro de que si de alguna manera pudieras encontrar una manera de derrotar a los generales de las otras facciones, eso sin duda te haría ganar mucho favor.",
    ["Where can I get armour like that?"] = "¿Dónde puedo conseguir una armadura así?",
    ["You can collect armour shards and crests around the Heart which can then be combined to make armour similar to my own. If you prove your worth to me, I can show you how to improve it further and unlock its true potential."] = "Puedes recolectar fragmentos de armadura y crestas alrededor del Corazón que luego se pueden combinar para crear una armadura similar a la mía. Si me demuestras tu valía, puedo mostrarte cómo mejorarlo aún más y desbloquear su verdadero potencial.",
    ["I'd like to reclaim my rewards."] = "Me gustaría reclamar mis recompensas.",
    ["There's nothing I can give you."] = "No hay nada que pueda darte.",
    ["I'd like to reclaim my insignia."] = "Me gustaría reclamar mi insignia.",
    ["Furies' Chosen hands you a Zamorak insignia."] = "Furies' Chosen te entrega una insignia de Zamorak.",
    ["You can now discover the blueprint for Avernic components if you have at least 89 Invention."] = "Ahora puede descubrir el plano de los componentes de Avernic si tiene al menos 89 Invention.",
    ["You have unlocked the Fury Wings cosmetic override."] = "Has desbloqueado la anulación cosmética Fury Wings.",
    ["[You can't gain any more reputation with that faction.]"] = "[No puedes ganar más reputación con esa facción.]",
    ["You's better talk to Dad, We not talk to wierdly 'umans."] = "Será mejor que hables con Dad. No hablamos con humanos extraños.",
    ["Thanks for da chompy, it was deloverly!"] = "Gracias por el chompy, ¡estuvo delicioso!",
    ["Human done good!"] = "¡Humano hecho bien!",
    ["[Fycie has given you another clue scroll!]"] = "[¡Fycie te ha dado otro pergamino de pistas!]",
    ["Excellent job adventurer, the wolves have been repelled once more."] = "Excelente trabajo aventurero, los lobos han sido repelidos una vez más.",
    ["There is no time to rest, The End of Things approaches."] = "No hay tiempo para descansar, El Fin de las Cosas se acerca.",
}

return dialogues
